delete from public.world_quest_steps where quest_id = 'cq110_bat_1' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_1', 1, '울지 않는 도깨비', '울지 않는 도깨비', '{"at": ["red_plain"]}'::jsonb, '[{"s": null, "t": "적사 황무지 어귀의 주막 평상에 머리에 뿔이 하나 난 아이가 엎드려 있었다. 어깨가 들썩일 때마다 코 훌쩍이는 소리가 났다."}, {"s": "q:sx_kkotnim", "t": "어서 오게, 조사원. 마침 잘 왔네. 저 녀석 좀 보게. 아침부터 저러고 있어."}, {"s": "q:sx_bangul", "t": "안 울어! 모래가 눈에 들어간 거야!"}, {"s": "q:sx_kkotnim", "t": "그래, 모래가 한 바가지는 들어갔겠다. 이 녀석은 방울이라고, 이 근방 꼬마 도깨비야. 할아버지 도깨비한테 물려받은 방망이를 잃어버렸다지 뭔가."}, {"s": "q:sx_bangul", "t": "잃어버린 거 아니야. 뚝딱이가 잠깐 마실 간 거야."}, {"s": null, "t": "나는 방망이를 어디서 마지막으로 보았느냐고 물었다."}, {"s": "q:sx_bangul", "t": "어제 황무지 한가운데서 「금 나와라 뚝딱」 했거든. 근데 모래만 잔뜩 나와서, 화가 나서 베고 잤어. 일어나 보니까 없어."}, {"s": "q:sx_kkotnim", "t": "금 대신 모래가 나왔으니 방망이도 체면이 상했겠지. 조사원, 이 녀석이 잔 자리 근처를 좀 둘러봐 주게. 나 혼자 보내면 또 길을 잃어."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_1', 2, '끌려간 자국', '적사 황무지을(를) 살핀다', '{"at": ["red_plain"], "tasks": [{"t": "search", "r": ["red_plain"], "n": 3}]}'::jsonb, '[{"s": null, "t": "모래 언덕 아래에 아이 하나가 웅크려 잔 듯한 자국이 있었다. 그 옆으로 무언가 길쭉한 것이 끌려간 줄이 바위틈까지 이어졌다."}, {"s": null, "t": "끌린 자국 양옆으로는 가느다란 발자국이 수십 개 찍혀 있었다."}, {"s": "q:sx_bangul", "t": "이거 전갈 발자국이잖아! 흥, 전갈쯤이야. 내가 뿔로 한 번 들이받으면……."}, {"s": null, "t": "바위틈에서 붉은 꼬리가 하나 쑥 올라왔다. 방울은 말을 끝내기도 전에 내 등 뒤로 숨었다."}, {"s": "q:sx_bangul", "t": "……조사원이 먼저 해. 나는 뒤를 지킬게. 뒤가 제일 위험한 거야."}, {"s": "q:sx_kkotnim", "t": "뒤를 지킨다는 놈이 왜 조사원 옷자락을 쥐고 있냐."}, {"s": "q:sx_kkotnim", "t": "저것들이 반짝이는 걸 굴로 끌어가는 버릇이 있다더라. 붉은 전갈부터 쫓아 주게."}]'::jsonb, '{"xp": 137}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_1', 3, '붉은 돌만 남은 굴', '붉은 전갈을(를) 물리친다', '{"at": ["red_plain"], "tasks": [{"t": "win", "m": ["g_red_plain"], "n": 3}]}'::jsonb, '[{"s": null, "t": "전갈 굴 안에는 방망이가 없었다. 끌린 자국은 굴 앞에서 끊겨 있었고, 대신 사람의 짚신 자국이 찍혀 있었다."}, {"s": "q:sx_bangul", "t": "없어……. 뚝딱이 없어……."}, {"s": "q:sx_kkotnim", "t": "울지 말고 들어 봐라. 오늘 새벽에 주사 캐는 광부 하나가 우리 주막에 들렀거든. 「쇠테 두른 나무 몽둥이로 바위를 쳤더니 붉은 돌이 쏟아지더라」고 떠벌리면서 외상술을 먹고 갔어."}, {"s": "q:sx_bangul", "t": "그거 뚝딱이야! 그 사람이 뚝딱이로 「주사 나와라」 한 거야!"}, {"s": "q:sx_kkotnim", "t": "그 광부가 두드려 낸 돌이 황무지 바위틈에 아직 굴러다닐 게다. 도깨비는 제 방망이 냄새를 맡는다지?"}, {"s": "q:sx_bangul", "t": "당연하지. 나는 코가 제일 좋은 도깨비야."}, {"s": "q:sx_kkotnim", "t": "그럼 조사원, 바위틈에서 주사 광물 세 덩이만 주워다 주게. 이 녀석 코에 대 보자."}]'::jsonb, '{"xp": 137}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_1', 4, '물 냄새', '주사 광물을(를) 모은다', '{"at": ["red_plain"], "tasks": [{"t": "gather", "items": ["cinnabar"], "r": ["red_plain"], "n": 3}]}'::jsonb, '[{"s": null, "t": "방울은 주사 광물을 하나씩 코에 대고 킁킁거렸다. 세 번째 덩이에서 눈이 동그래졌다."}, {"s": "q:sx_bangul", "t": "이거다! 뚝딱이 냄새! 그리고…… 물 냄새가 나."}, {"s": "q:sx_kkotnim", "t": "물 냄새라. 이 근방에서 물 냄새 나는 곳이면 수경루밖에 없지. 그 광부가 외상값 갚으러 수경루 장에 돌 팔러 간다고 했어."}, {"s": "q:sx_bangul", "t": "내 뚝딱이로 캔 돌을 판다고? 나쁜 놈! 쫓아가자!"}, {"s": "q:sx_kkotnim", "t": "너 혼자 가면 수경루가 아니라 황무지 끝에서 울고 있을 게다. 나도 가마."}, {"s": null, "t": "나는 주막은 어떻게 하느냐고 물었다."}, {"s": "q:sx_kkotnim", "t": "주막이야 솥 하나 수레에 얹으면 그만이지. 수경루에 가면 외상값 받을 사람도 하나 있고. 조사원, 거기서 만나세."}]'::jsonb, '{"xp": 137, "gil": 29, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
