values ('cq110_bat_2', 'side', '연계·도깨비 방망이 분실 사건', '물에 비친 방망이', '수경루 물거울에 방망이가 비친다', 'mirror_pavilion', 9, '{cq110_bat_1}'::text[], null, 1101, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'cq110_bat_2' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_2', 1, '방망이가 백 개', '방망이가 백 개', '{"at": ["mirror_pavilion"]}'::jsonb, '[{"s": null, "t": "수경루 물가에 꽃님의 수레가 서 있었다. 솥에서 국밥 냄새가 올라왔고, 방울은 물가에 쪼그려 앉아 있었다."}, {"s": "q:sx_kkotnim", "t": "왔나, 조사원. 황무지에서 주사 냄새를 따라온 건 맞았네. 그런데 와 보니 이 꼴이야."}, {"s": "q:sx_bangul", "t": "조사원! 저기 봐! 뚝딱이가 백 개야!"}, {"s": null, "t": "물 위 여기저기에 쇠테 두른 방망이가 비쳐 있었다. 그런데 물가 어디에도 방망이는 없었다."}, {"s": "q:sx_kkotnim", "t": "물거울 요정이란 것들이 비친 걸 흉내 내서 노는 거라더라. 어느 게 진짜 그림자인지 알 수가 없어."}, {"s": "q:sx_bangul", "t": "내가 다 건져 볼게. 하나는 진짜겠지."}, {"s": null, "t": "방울은 물에 손을 쑥 넣었다가 그대로 고꾸라져 물에 빠졌다. 내가 건져 내자 방울은 콧물을 줄줄 흘리며 덜덜 떨었다."}, {"s": "q:sx_bangul", "t": "안 울어……. 물이 눈에서 나오는 거야……."}, {"s": "q:sx_kkotnim", "t": "조사원, 저 요정들부터 쫓아 주게. 그래야 물이 가라앉아서 진짜 그림자가 보일 게다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_2', 2, '갈대숲의 코골이', '물거울 요정을(를) 물리친다', '{"at": ["mirror_pavilion"], "tasks": [{"t": "win", "m": ["g_mirror_pavilion"], "n": 3}]}'::jsonb, '[{"s": null, "t": "요정들이 흩어지자 물 위의 방망이 그림자도 하나둘 사라졌다. 마지막 하나는 물가 갈대숲 쪽으로 길게 비쳐 있었다."}, {"s": "q:sx_bangul", "t": "저기야! 갈대숲에서 뚝딱이 그림자가 나와!"}, {"s": null, "t": "갈대숲 안쪽에서 드르렁, 하고 코 고는 소리가 났다. 갈대가 너무 빽빽해서 안이 보이지 않았다."}, {"s": "q:sx_kkotnim", "t": "저 코골이는 내가 알지. 사흘 외상 진 놈 코골이야."}, {"s": "q:sx_bangul", "t": "{직업:호위=조사원 칼로 다 베어 버려!/월궁=조사원 화살로 다 쏴 버려!/퇴마=조사원 방울로 갈대를 쫓아 버려!/의무=조사원 부채로 다 쓸어 버려!/봉인=조사원 부적으로 갈대를 묶어 버려!/암영=조사원 단도로 다 베어 버려!/*=조사원이 다 치워 버려!}"}, {"s": "q:sx_kkotnim", "t": "갈대는 함부로 꺾으면 수향 사람들이 싫어해. 길만 내게, 길만. 수향 갈대 네 단만 베어 길을 터 주게. 벤 건 내가 솥 불쏘시개로 쓰마."}]'::jsonb, '{"xp": 249}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_2', 3, '금 나와라, 술 나와라', '수향 갈대을(를) 모은다', '{"at": ["mirror_pavilion"], "tasks": [{"t": "gather", "items": ["river_reed"], "r": ["mirror_pavilion"], "n": 4}]}'::jsonb, '[{"s": null, "t": "갈대를 베어 낸 자리에 광부 하나가 대자로 누워 있었다. 눈을 반쯤 뜬 채로 허공에 대고 무언가를 두드리는 시늉을 했다."}, {"s": "q:sx_jusul", "t": "금 나와라, 뚝딱……. 술 나와라, 뚝딱……."}, {"s": "q:sx_bangul", "t": "이 사람이야! 내 뚝딱이 내놔!"}, {"s": null, "t": "방울이 광부의 품을 뒤졌지만 나온 것은 빈 술병과 주사 몇 덩이뿐이었다."}, {"s": "q:sx_kkotnim", "t": "눈동자가 물빛으로 흐려졌구먼. 물거울 요정한테 홀린 게야. 이 상태로는 제 이름도 못 댈 게다."}, {"s": "q:sx_bangul", "t": "그럼 뚝딱이가 어디 있는지도 모르잖아!"}, {"s": "q:sx_kkotnim", "t": "정화 부적 한 장이면 정신이 돌아온다지. 조사원, 한 장만 지어 주게. 외상값도 받아야 하니 멀쩡하게 깨워야 해."}]'::jsonb, '{"xp": 249}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_2', 4, '사슴이 물고 갔다', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["mirror_pavilion"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 1}], "give": {"ward_talisman": 1}}'::jsonb, '[{"s": null, "t": "부적을 이마에 붙이자 광부가 벌떡 일어나 앉았다. 눈빛이 맑아지더니 꽃님을 보고 얼굴이 하얘졌다."}, {"s": "q:sx_jusul", "t": "꼬, 꽃님이. 외상값은 내가 꼭……."}, {"s": "q:sx_kkotnim", "t": "외상값은 나중이고. 황무지에서 주운 방망이 어쨌냐."}, {"s": "q:sx_jusul", "t": "아, 그거. 여기서 「술 나와라」 했더니 물만 콸콸 나오더라고. 그래서 내던졌지. 그랬더니 웬 붉은 뿔 사슴이 와서 덥석 물고 혈엽림 쪽으로 뛰어가던데."}, {"s": "q:sx_bangul", "t": "사슴? 사슴이 뚝딱이로 뭐 하게!"}, {"s": "q:sx_jusul", "t": "나야 모르지. 사슴이 금이 필요하겠나, 술이 필요하겠나."}, {"s": null, "t": "방울은 젖은 옷을 짜며 혈엽림 쪽을 노려보았다. 꽃님은 광부의 외상 장부에 줄을 하나 더 그었다."}, {"s": "q:sx_kkotnim", "t": "이걸로 외상 나흘째다. 조사원, 혈엽림은 붉은 잎이 무성해서 길 잃기 쉬운 곳이야. 이번엔 내가 먼저 가서 자리를 잡아 두마."}]'::jsonb, '{"xp": 249, "gil": 41, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
