on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'cq110_bat_3' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_3', 1, '뿔에 걸린 것', '뿔에 걸린 것', '{"at": ["red_forest"]}'::jsonb, '[{"s": null, "t": "혈엽림 어귀 큰 나무 아래에 꽃님의 수레가 서 있었다. 방울은 꽃님의 치맛자락 뒤에 숨어 숲속을 힐끔거렸다."}, {"s": "q:sx_kkotnim", "t": "수경루에서 고생했네. 광부 말대로 붉은 뿔 사슴이 이 숲에 있더라. 나무꾼들 말로는 요새 뿔에 쇠테 두른 몽둥이를 매단 놈이 돌아다닌대."}, {"s": "q:sx_bangul", "t": "뚝딱이를 뿔에 매달았다고? 내 뚝딱이가 사슴 장신구가 됐다고?"}, {"s": "q:sx_kkotnim", "t": "그놈이 머리를 흔들 때마다 「뚝딱」 소리가 나고, 그때마다 붉은 잎이 우수수 쏟아진다더라. 「잎 나와라」인 셈이지."}, {"s": "q:sx_bangul", "t": "흥, 사슴 따위. 내가 뿔 대 뿔로 붙어 줄게."}, {"s": null, "t": "숲속에서 붉은 눈이 여럿 번뜩였다. 방울은 다시 꽃님 뒤로 들어갔다."}, {"s": "q:sx_bangul", "t": "……저건 뿔이 너무 많잖아. 반칙이야."}, {"s": "q:sx_kkotnim", "t": "조사원, 핏빛 사슴귀부터 쫓아 주게. 그 무리 속에 방망이 매단 놈이 있을 게다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_3', 2, '나무가 삼킨 방망이', '핏빛 사슴귀을(를) 물리친다', '{"at": ["red_forest"], "tasks": [{"t": "win", "m": ["g_red_forest"], "n": 3}]}'::jsonb, '[{"s": null, "t": "사슴귀 무리가 흩어지는 사이, 뿔에 무언가를 매단 한 마리가 숲 안쪽으로 내달렸다. 쫓아가 보니 사슴은 늙은 나무에 뿔을 비비고 있었다."}, {"s": null, "t": "사슴이 달아난 뒤, 나무껍질 틈에 쇠테 두른 방망이 끝이 조금 삐져나와 있었다. 나무가 방망이를 반쯤 삼킨 채였다."}, {"s": "q:sx_bangul", "t": "뚝딱이! 뚝딱아! 내가 왔어!"}, {"s": null, "t": "방울이 방망이 끝을 잡고 힘껏 당겼다. 방망이는 꿈쩍도 하지 않았고, 방울만 엉덩방아를 찧었다."}, {"s": "q:sx_kkotnim", "t": "영맥이 흐르는 나무라 껍질이 질기다더라. 억지로 빼다간 방망이가 부러져."}, {"s": "q:sx_kkotnim", "t": "둘레 껍질을 조금씩 벗겨 내면 저절로 빠질 게다. 조사원, 영맥 수피 세 장만 벗겨 주게. 벗긴 껍질은 약재로 쓰니 버리지 말고."}]'::jsonb, '{"xp": 390}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_3', 3, '너무 기뻐서 잠이 안 와', '영맥 수피을(를) 모은다', '{"at": ["red_forest"], "tasks": [{"t": "gather", "items": ["spirit_bark"], "r": ["red_forest"], "n": 3}]}'::jsonb, '[{"s": null, "t": "마지막 껍질이 벗겨지자 방망이가 툭 떨어졌다. 방울은 방망이를 끌어안고 한참 동안 얼굴을 묻었다."}, {"s": "q:sx_bangul", "t": "안 울어. 이건…… 나무 진이 눈에 튄 거야."}, {"s": "q:sx_kkotnim", "t": "그래그래. 진이 아주 콸콸 튀는구나."}, {"s": null, "t": "그날 밤, 방울은 방망이를 안고 누웠지만 잠들지 못했다. 바스락 소리만 나도 벌떡 일어나 방망이를 휘둘렀다."}, {"s": "q:sx_bangul", "t": "누구야! 또 뚝딱이 가져가려는 거지!"}, {"s": "q:sx_kkotnim", "t": "바람이다, 이 녀석아. 벌써 열 번째야. 너 때문에 나도 한숨도 못 잤어."}, {"s": "q:sx_kkotnim", "t": "조사원, 안신탕 두 그릇만 끓여 주게. 하나는 이 녀석, 하나는 나. 이대로 가면 날이 새기 전에 내가 먼저 도깨비가 되겠어."}]'::jsonb, '{"xp": 390}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_3', 4, '장작 값', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["red_forest"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 2}], "give": {"calm_brew": 2}}'::jsonb, '[{"s": null, "t": "안신탕을 마신 방울은 방망이를 꼭 안은 채 곯아떨어졌다. 꽃님도 평상에 기대어 꾸벅꾸벅 졸았다."}, {"s": null, "t": "이튿날 아침, 방울의 비명이 숲을 울렸다. 품 안의 방망이가 사라지고 없었다."}, {"s": "q:sx_bangul", "t": "뚝딱이 또 없어! 이번엔 누구야!"}, {"s": "q:sx_kkotnim", "t": "……아이고. 그거 혹시 나 아닌가 모르겠다."}, {"s": "q:sx_kkotnim", "t": "새벽에 웬 장사치가 와서 「벼락 맞은 나무 사러 다닌다」면서 저 몽둥이 얼마냐고 묻길래, 졸린 김에 장작인 줄 알고 서 푼에 넘겼지 뭐야."}, {"s": "q:sx_bangul", "t": "서 푼? 할아버지 뚝딱이가 서 푼이라고?"}, {"s": "q:sx_kkotnim", "t": "내가 잘못했다, 잘못했어. 그 장사치가 뇌명봉으로 간다더라. 벼락 맞은 나무가 거기서 제일 값나간다고."}, {"s": null, "t": "방울은 입술을 삐죽 내밀고 꽃님을 노려보다가, 그래도 꽃님의 소매를 놓지 않았다. 나는 뇌명봉으로 가는 길을 짚어 보았다."}]'::jsonb, '{"xp": 390, "gil": 53, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
