insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('sq110_ice_letter', 'side', '채집·빙혼곡', '얼음 속 편지', '해마다 얼음을 깨는 할미가 스무 해 전 남편의 편지 상자를 찾는다', 'frost_valley', 12, '{}'::text[], null, 1103, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_ice_letter' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_ice_letter', 1, '해마다 깨는 얼음', '해마다 깨는 얼음', '{"at": ["frost_valley"]}'::jsonb, '[{"s": null, "t": "빙혼곡 어귀에서 허리가 굽은 할미가 얼음을 깨고 있었다. 정으로 한 번 칠 때마다 손이 떨렸다."}, {"s": "q:sx_seodeok", "t": "거기 젊은이. 이 늙은이 좀 거들어 주려나."}, {"s": "q:sx_seodeok", "t": "스무 해 전 이맘때, 우리 영감이 이 골짜기에 들어가서 안 나왔어. 나갈 때 편지 상자를 품에 넣고 갔는데, 그게 이 얼음 밑 어디에 있을 게야."}, {"s": "q:sx_seodeok", "t": "해마다 깨 봤는데, 얼음이 해마다 두꺼워져."}, {"s": null, "t": "나는 얼음을 녹일 방법이 있느냐고 물었다."}, {"s": "q:sx_seodeok", "t": "빙정염을 뿌리면 얼음이 무르게 된다더라. 골짜기 바위틈에 하얗게 앉은 소금 말이야. 다섯 줌만 모아다 주게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_ice_letter', 2, '얼음 밑의 숨', '빙정염을(를) 모은다', '{"at": ["frost_valley"], "tasks": [{"t": "gather", "items": ["frost_salt"], "r": ["frost_valley"], "n": 5}]}'::jsonb, '[{"s": null, "t": "빙정염을 뿌리자 얼음이 쩍쩍 소리를 내며 갈라졌다. 갈라진 틈에서 하얀 김이 올라왔다."}, {"s": null, "t": "김 너머로 늑대 울음이 들렸다. 골짜기 위에서 눈빛이 몇 개 번뜩였다."}, {"s": "q:sx_seodeok", "t": "얼음 깨는 소리를 듣고 왔구먼. 저것들은 해마다 이맘때 내려와."}, {"s": "q:sx_seodeok", "t": "저것들 좀 쫓아 주면, 그동안 나는 틈을 넓혀 보겠네."}]'::jsonb, '{"xp": 390}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_ice_letter', 3, '언 상자', '설원 늑대을(를) 물리친다', '{"at": ["frost_valley"], "tasks": [{"t": "win", "m": ["g_frost_valley"], "n": 3}]}'::jsonb, '[{"s": null, "t": "늑대를 쫓고 돌아오니, 할미가 얼음 틈 앞에 주저앉아 있었다. 틈 아래로 나무 상자의 귀퉁이가 보였다."}, {"s": "q:sx_seodeok", "t": "……있네. 정말 있었어."}, {"s": null, "t": "상자는 얼음과 한 덩어리로 얼어 있었다. 억지로 떼면 안에 든 종이까지 부서질 것 같았다."}, {"s": "q:sx_seodeok", "t": "불로 녹이면 젖어서 글씨가 번져. 부적목 수지를 태우면 연기가 따뜻하기만 하고 불은 안 붙는다지. 그 연기로 천천히 녹여 보세."}, {"s": "q:sx_seodeok", "t": "골짜기 나무에서 수지 세 덩이만 따다 주게."}]'::jsonb, '{"xp": 390}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_ice_letter', 4, '봄에만 불러 다오', '부적목 수지을(를) 모은다', '{"at": ["frost_valley"], "tasks": [{"t": "gather", "items": ["resin"], "r": ["frost_valley"], "n": 3}]}'::jsonb, '[{"s": null, "t": "수지 연기가 얼음을 감싸자 상자가 천천히 떨어져 나왔다. 상자 안에는 접힌 편지 한 장이 마른 채로 들어 있었다."}, {"s": null, "t": "할미는 편지를 펴지 못하고 나에게 내밀었다. 눈이 어두워 글씨가 안 보인다고 했다. 나는 편지를 읽어 주었다."}, {"s": null, "t": "「길을 잃었소. 날이 차서 오래 못 버틸 것 같소. 당신이 내 이름을 불러 주면 나는 춥지 않을 거요.」"}, {"s": "q:sx_seodeok", "t": "……."}, {"s": "q:sx_seodeok", "t": "그래서 그랬구먼. 해마다 얼음을 깨면서 그 양반 이름을 불렀는데, 골짜기에 바람이 한 번씩 지나갔어. 나는 그게 대답인 줄은 몰랐네."}, {"s": null, "t": "편지 끝에 한 줄이 더 있었다. 얼어서 반쯤 번진 글씨였다."}, {"s": null, "t": "「그래도 겨울에는 부르지 마오. 당신 손이 시리니. 봄에 부르오.」"}, {"s": "q:sx_seodeok", "t": "이 양반이 끝까지 잔소리야."}, {"s": null, "t": "할미는 웃으면서 울었다. 그리고 정을 내려놓았다. 올해는 더 얼음을 깨지 않겠다고 했다."}, {"s": null, "t": "골짜기를 떠날 때 등 뒤로 바람이 한 번 지나갔다. 춥지 않은 바람이었다."}]'::jsonb, '{"xp": 390, "gil": 53, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
