values ('sq110_singing_pick', 'side', '채집·주혈 광산', '노래하는 곡괭이', '밤마다 연장 창고의 곡괭이가 노래를 부른다', 'crimson_mine', 13, '{}'::text[], null, 1104, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_singing_pick' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_singing_pick', 1, '밤에 우는 연장', '밤에 우는 연장', '{"at": ["crimson_mine"]}'::jsonb, '[{"s": "q:sx_deolsu", "t": "야행국에서 왔다고? 마침 잘 왔네. 우리 연장 창고 좀 봐 주게."}, {"s": "q:sx_deolsu", "t": "밤만 되면 곡괭이가 노래를 불러. 그것도 꼭 자정에, 꺾이는 가락으로."}, {"s": null, "t": "나는 곡괭이가 어떤 노래를 부르느냐고 물었다."}, {"s": "q:sx_deolsu", "t": "내가 그걸 알면 이러고 있겠나! 듣자마자 다들 갱도를 뛰쳐나가는데."}, {"s": "q:sx_deolsu", "t": "사흘째 일을 못 했어. 광산 안을 한번 훑어보고, 그 소리가 어디서 나는지 찾아 주게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_singing_pick', 2, '자루 속의 가수', '주혈 광산을(를) 살핀다', '{"at": ["crimson_mine"], "tasks": [{"t": "search", "r": ["crimson_mine"], "n": 3}]}'::jsonb, '[{"s": null, "t": "소리는 연장 창고에서 났다. 벽에 세워 둔 곡괭이 자루마다 작은 구멍이 나 있었고, 구멍 안에서 무언가 꼼지락거렸다."}, {"s": null, "t": "등불을 들이대자 박쥐 한 마리가 찍 소리를 내며 날아올랐다. 그 뒤를 따라 수십 마리가 쏟아져 나왔다."}, {"s": "q:sx_deolsu", "t": "……박쥐? 박쥐란 말이야? 나는 사흘 동안 원혼이 붙은 줄 알고 부적까지 붙였는데!"}, {"s": null, "t": "창고 구석에서 막내 광부가 조심스럽게 고개를 내밀었다."}, {"s": "q:sx_kongdol", "t": "저, 영감님. 다 쫓으시면 안 돼요……."}, {"s": "q:sx_deolsu", "t": "너 거기서 뭐 하냐?"}, {"s": "q:sx_kongdol", "t": "아, 아무것도요!"}, {"s": "q:sx_deolsu", "t": "일단 갱도에 들어앉은 박쥐 떼부터 치워 주게. 저것들이 자루를 다 파먹었으니 곡괭이를 새로 맞춰야겠어."}]'::jsonb, '{"xp": 443}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_singing_pick', 3, '꾀꼬리', '갱도 박쥐 떼을(를) 물리친다', '{"at": ["crimson_mine"], "tasks": [{"t": "win", "m": ["g_crimson_mine"], "n": 4}]}'::jsonb, '[{"s": null, "t": "갱도가 조용해졌다. 그런데 창고에서 또 노래가 들렸다. 이번에는 한 마리 목소리였다."}, {"s": null, "t": "콩돌이 쓰고 있던 안전모를 벗자, 그 안에 새끼 박쥐 한 마리가 웅크리고 있었다."}, {"s": "q:sx_kongdol", "t": "꾀꼬리예요. 날개를 다쳐서 제가 밥을 줬어요. 밤에 배가 고프면 저렇게 울어요."}, {"s": "q:sx_deolsu", "t": "박쥐한테 꾀꼬리라고 이름을 붙였어?"}, {"s": "q:sx_kongdol", "t": "노래를 잘하잖아요."}, {"s": null, "t": "덜수는 한참 콩돌을 노려보다가, 머리를 긁적이며 고개를 돌렸다."}, {"s": "q:sx_deolsu", "t": "……창고에서만 키워라. 갱도 안에는 들이지 말고."}, {"s": "q:sx_deolsu", "t": "조사원, 곡괭이 자루를 쇠로 새로 박아야겠네. 월철 광석을 캐다가 강철 주괴로 두 덩이만 뽑아 주게. 이번엔 구멍이 안 나게."}]'::jsonb, '{"xp": 443}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_singing_pick', 4, '자정의 합창', '월철 광석을(를) 모은다, 강철 주괴을(를) 만든다, 강철 주괴을(를) 넘긴다', '{"at": ["crimson_mine"], "tasks": [{"t": "gather", "items": ["ore"], "r": ["crimson_mine"], "n": 6}, {"t": "craft", "items": ["steel_ingot"], "n": 2}], "give": {"steel_ingot": 2}}'::jsonb, '[{"s": null, "t": "쇠 자루를 박은 곡괭이는 무거웠지만 단단했다. 덜수는 새 곡괭이로 바위를 몇 번 내려찍어 보고는 만족스럽게 웃었다."}, {"s": "q:sx_deolsu", "t": "됐네. 이제 밤에 노래할 놈은 없겠지."}, {"s": null, "t": "그날 자정, 창고에서 다시 노래가 들렸다. 꺾이는 가락이었다."}, {"s": null, "t": "들여다보니 덜수가 새 곡괭이를 닦으며 흥얼거리고 있었고, 꾀꼬리가 그 어깨에 매달려 따라 울고 있었다."}, {"s": "q:sx_kongdol", "t": "영감님, 그 노래 꾀꼬리한테 배우셨죠."}, {"s": "q:sx_deolsu", "t": "시끄러워. 너도 따라 불러."}]'::jsonb, '{"xp": 443, "gil": 57, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
