values ('cq110_pack_1', 'side', '연계·아버지의 등짐', '아버지의 등짐', '외상 장부를 멘 등짐장수 오누이가 꺼진 등대를 찾아온다', 'nine_lighthouse', 14, '{mq_frost_seal}'::text[], null, 1105, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'cq110_pack_1' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_1', 1, '외상 받으러 온 오누이', '외상 받으러 온 오누이', '{"at": ["nine_lighthouse"]}'::jsonb, '[{"s": null, "t": "구등대 군도 나루에 저보다 큰 등짐을 멘 오누이가 서 있었다. 누나는 장부를 펴 들었고, 동생은 바닷바람에 날리는 장부 귀퉁이를 붙잡고 있었다."}, {"s": "q:sx_dodam", "t": "누나, 저 사람 야행국 사람이에요! 허리에 야행국 패가 달렸어요."}, {"s": "q:sx_haesol", "t": "손가락질하지 마. ……실례했어요. 저희는 등짐장수 해솔, 도담이에요. 아버지가 놓은 외상값을 받으러 다녀요."}, {"s": "q:sx_haesol", "t": "이 군도 끝 작은 섬에 등대지기 반돌이라는 분이 있는데, 장부에 「등잔 기름 열 동이」가 적혀 있어요. 그런데 와 보니 등대가 꺼져 있고 사람도 안 보여요."}, {"s": "q:sx_dodam", "t": "빚 받으러 온 걸 알고 숨은 거예요. 틀림없어요. 제가 아까 「반돌 아저씨!」 하고 세 번이나 불렀거든요."}, {"s": "q:sx_haesol", "t": "그러니까 숨었지."}, {"s": null, "t": "나는 등대가 꺼진 까닭부터 찾아보자고 했다."}, {"s": "q:sx_haesol", "t": "고마워요. 섬 안을 같이 좀 돌아봐 주세요. 등대지기든 등대 불이든, 하나라도 찾으면 돼요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_1', 2, '기름 항아리 속의 등대지기', '구등대 군도을(를) 살핀다', '{"at": ["nine_lighthouse"], "tasks": [{"t": "search", "r": ["nine_lighthouse"], "n": 3}]}'::jsonb, '[{"s": null, "t": "세 번째로 바위 그늘을 살폈을 때, 빈 기름 항아리 하나가 혼자 덜컹거렸다. 뚜껑을 열자 수염이 덥수룩한 사내가 무릎을 끌어안고 들어앉아 있었다."}, {"s": "q:sx_bandol", "t": "없다! 나 여기 없어!"}, {"s": "q:sx_dodam", "t": "있잖아요."}, {"s": "q:sx_bandol", "t": "……외상값 받으러 왔지? 열 동이를 무슨 수로 갚아! 등대 기름이 몽땅 없어졌는데!"}, {"s": "q:sx_haesol", "t": "없어졌다고요?"}, {"s": "q:sx_bandol", "t": "밤마다 무언가 기름을 핥아 먹어. 등잔 심지까지 씹어 먹고, 불이 꺼지면 깔깔 웃어. 이 섬 사람들은 그걸 등대식귀라 부르지."}, {"s": "q:sx_bandol", "t": "나 혼자서는 무서워서…… 아니, 바빠서 못 쫓았네. 그것들만 쫓아 주면 내 빚 얘기는 그다음에 하세."}, {"s": "q:sx_dodam", "t": "누나, 저 아저씨 방금 무섭다고 했어요."}]'::jsonb, '{"xp": 500}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_1', 3, '장부에 적힌 갚는 법', '등대식귀을(를) 물리친다', '{"at": ["nine_lighthouse"], "tasks": [{"t": "win", "m": ["m_24"], "n": 3}]}'::jsonb, '[{"s": null, "t": "등대식귀가 흩어지자 등대 둘레에는 기름 냄새만 남았다. 반돌은 항아리에서 나와 땅바닥에 넙죽 엎드렸다."}, {"s": "q:sx_bandol", "t": "자, 이제 받아 가시오. 가진 건 그물 두 벌하고 마른 미역뿐이지만."}, {"s": null, "t": "해솔은 장부를 다시 넘기다가 그 줄 아래에 작게 적힌 글씨를 손가락으로 짚었다."}, {"s": "q:sx_haesol", "t": "「등잔 기름 열 동이. 갚는 법: 밤마다 불을 끄지 말 것.」 ……아저씨, 끝까지 안 읽으셨죠?"}, {"s": "q:sx_bandol", "t": "나는 글을 못 읽네. 그 양반이 뭐라고 적는지 몰랐지."}, {"s": "q:sx_dodam", "t": "그럼 아저씨는 기름값 대신 불만 켜 두면 됐던 거예요? 그런데 숨었어요? 항아리에?"}, {"s": "q:sx_bandol", "t": "……그 얘긴 그만하세."}, {"s": "q:sx_haesol", "t": "아버지는 밤배가 이 섬을 지날 때 등대가 꺼지는 게 싫었나 봐요. 그럼 빚을 갚게 해 드려야죠."}, {"s": "q:sx_haesol", "t": "조사원, 어유 등잔 두 개만 만들어 주세요. 기름이 다시 모일 때까지 그걸로 불을 이어 가면 돼요."}]'::jsonb, '{"xp": 500}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_1', 4, '다시 켜진 불', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["nine_lighthouse"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 2}], "give": {"fish_oil_lamp": 2}}'::jsonb, '[{"s": null, "t": "어유 등잔 두 개를 등대 꼭대기에 올리자 불빛이 바다 위로 멀리 퍼졌다. 지나가던 고깃배 한 척이 노를 두 번 들어 보였다."}, {"s": "q:sx_bandol", "t": "갚았네. 이제 갚은 거지?"}, {"s": "q:sx_haesol", "t": "오늘 밤 몫은요. 내일 밤도, 모레 밤도 갚으셔야 해요."}, {"s": "q:sx_bandol", "t": "평생 갚으란 말이구먼."}, {"s": "q:sx_dodam", "t": "그래도 기름값보다 싸요."}, {"s": null, "t": "해솔은 장부의 그 줄 옆에 작은 점을 하나 찍었다. 받았다는 표시라고 했다."}, {"s": "q:sx_haesol", "t": "저는 아버지가 셈을 못 하는 줄 알았어요. 외상을 이렇게 놓으면 남는 게 없잖아요."}, {"s": "q:sx_haesol", "t": "그런데 이 줄은 남는 게 있네요. 도담아, 다음 줄 읽어 봐."}, {"s": "q:sx_dodam", "t": "「옛 의금부 옥사. 칠복. 주먹밥……」 누나, 옥사가 어디예요?"}, {"s": null, "t": "해솔의 얼굴이 조금 굳었다. 해솔은 대답 대신 장부를 덮어 등짐 깊숙이 넣었다."}]'::jsonb, '{"xp": 500, "gil": 61, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
