values ('sq110_backward_clock', 'side', '제작·물시계 터', '거꾸로 가는 물시계', '하루에 한 번 물시계가 거꾸로 돈다', 'water_clock', 14, '{}'::text[], null, 1106, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_backward_clock' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_backward_clock', 1, '하루 한 번 거슬러 흐르는 물', '하루 한 번 거슬러 흐르는 물', '{"at": ["water_clock"]}'::jsonb, '[{"s": null, "t": "물시계 터 한가운데에 사람 키 세 배쯤 되는 물시계가 서 있었다. 항아리에서 항아리로 물이 떨어지는 소리가 고르게 이어졌다."}, {"s": "q:sx_okryeon", "t": "야행국 분이세요? 잘 오셨어요. 저는 여기 시각지기 옥련이에요."}, {"s": "q:sx_okryeon", "t": "이 물시계가 하루에 한 번, 꼭 해시 이각에 거꾸로 흘러요. 아래 항아리의 물이 위로 올라가요."}, {"s": null, "t": "나는 그게 정말이냐고 물었다."}, {"s": "q:sx_okryeon", "t": "저도 처음엔 제 눈을 의심했어요. 그런데 그 일각 동안은 잣대도 거꾸로 올라가고, 종 치는 인형이 같은 시각을 몇 번이고 다시 쳐요."}, {"s": "q:sx_okryeon", "t": "일단 고칠 수 있는 데부터 고쳐 보려고요. 물이 지나는 유리관에 금이 잔뜩 갔어요. 이 터 바위틈에서 나는 영유리 네 덩이만 구해 주세요. 영기가 든 유리라야 거슬러 오르는 물에도 안 깨진대요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_backward_clock', 2, '기다리는 인형', '영유리을(를) 모은다', '{"at": ["water_clock"], "tasks": [{"t": "gather", "items": ["spirit_glass"], "r": ["water_clock"], "n": 4}]}'::jsonb, '[{"s": null, "t": "새 유리관을 끼우자 물소리가 맑아졌다. 그날 밤 해시 이각, 물은 또 거꾸로 올라갔다."}, {"s": null, "t": "물시계 꼭대기의 작은 문이 열리고, 색이 바랜 나무 인형 둘이 나와 종을 쳤다. 땡, 하고 한 번 친 뒤 물이 다시 올라가자 인형들이 같은 자리로 돌아가 또 종을 쳤다."}, {"s": "q:sx_inhyeong", "t": "왔어? 왔어?"}, {"s": "q:sx_inhyeong", "t": "아직이야. 다시."}, {"s": null, "t": "옥련의 얼굴이 하얗게 질렸다. 옥련은 인형들을 한참 올려다보다가 겨우 입을 열었다."}, {"s": "q:sx_okryeon", "t": "……저 인형, 제가 만든 거예요. 일곱 살 때요. 할아버지가 이 물시계의 시각지기셨거든요."}, {"s": "q:sx_okryeon", "t": "할아버지는 늘 해시 이각에 일을 마치고 집에 오셨어요. 그래서 인형한테 일렀어요. 할아버지가 오시면 종을 쳐서 알려 달라고요. 그런데 그날 밤 할아버지는 안 오셨어요."}, {"s": "q:sx_okryeon", "t": "인형이 여태 그 시각을 되감고 있었던 거예요. 저렇게 계속 되감다간 물시계가 버티지 못해요. 불쌍하지만 둘 다 멈춰 주세요. 부수지는 말고요."}]'::jsonb, '{"xp": 500}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_backward_clock', 3, '사기 등잔 하나', '종 치는 인형귀을(를) 물리친다', '{"at": ["water_clock"], "tasks": [{"t": "win", "m": ["r71_clock_3"], "n": 2}]}'::jsonb, '[{"s": null, "t": "인형 둘은 종채를 떨어뜨리고 제자리에 앉았다. 눈에 남은 희미한 불빛이 아직 꺼지지 않았다."}, {"s": "q:sx_inhyeong", "t": "안 왔어. 아직 안 왔어."}, {"s": "q:sx_okryeon", "t": "미안해. 할아버지는 이제 못 오셔."}, {"s": null, "t": "옥련은 인형의 등을 쓸어 주다가 문득 손을 멈추었다."}, {"s": "q:sx_okryeon", "t": "할아버지는 밤길에 늘 사기 등잔을 들고 오셨어요. 하얀 갓을 씌운 작은 등잔이요. 인형은 그 불빛을 보고 종을 치게 되어 있었어요."}, {"s": "q:sx_okryeon", "t": "할아버지 등잔은 그날 밤 할아버지랑 같이 없어졌어요. 하나만 새로 만들어 주시겠어요? 그 시각에 문 앞에 켜 두고 싶어요."}]'::jsonb, '{"xp": 500}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_backward_clock', 4, '해시 이각의 종', '사기 등잔을(를) 만든다, 사기 등잔을(를) 넘긴다', '{"at": ["water_clock"], "tasks": [{"t": "craft", "items": ["hf_surf_lamp"], "n": 1}], "give": {"hf_surf_lamp": 1}}'::jsonb, '[{"s": null, "t": "해시 이각이 가까워지자 옥련은 사기 등잔에 불을 붙여 물시계 문 앞에 놓았다."}, {"s": null, "t": "물이 거꾸로 오르려다 멈칫했다. 꼭대기 문이 삐걱 열리고, 인형 둘이 고개를 내밀어 등잔 불빛을 내려다보았다."}, {"s": "q:sx_inhyeong", "t": "왔다."}, {"s": "q:sx_inhyeong", "t": "할아버지 왔다."}, {"s": null, "t": "땡. 종소리는 단 한 번이었다. 인형들은 문 안으로 들어갔고, 물은 다시 아래로 떨어지기 시작했다."}, {"s": "q:sx_okryeon", "t": "……할아버지, 다녀오셨어요."}, {"s": null, "t": "옥련은 아무도 없는 문 쪽에 대고 할아버지를 불렀다. 그때 등잔 불꽃이 바람도 없이 문 쪽으로 기울었다. 누군가 곁을 지나간 것처럼."}, {"s": "q:sx_okryeon", "t": "봤어요? 방금 봤죠?"}, {"s": null, "t": "나는 고개를 끄덕였다. 그날 밤부터 물시계는 더는 거꾸로 흐르지 않았다. 다만 해시 이각이면 사기 등잔의 불꽃이 늘 문 쪽으로 한 번 기운다고 했다."}]'::jsonb, '{"xp": 500, "gil": 61, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
