values ('cq110_bat_4', 'side', '연계·도깨비 방망이 분실 사건', '벼락 맞은 금 나와라', '뇌명봉에 금이 비처럼 쏟아졌다는 소문', 'thunder_peak', 16, '{cq110_bat_3}'::text[], null, 1107, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'cq110_bat_4' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_4', 1, '산꼭대기의 피뢰침', '산꼭대기의 피뢰침', '{"at": ["thunder_peak"]}'::jsonb, '[{"s": null, "t": "뇌명봉 아래 바위 그늘에서 꽃님이 장사치 하나의 멱살을 잡고 있었다. 방울은 그 옆에서 팔짱을 끼고 콧김을 뿜었다."}, {"s": "q:sx_kkotnim", "t": "조사원, 왔나. 혈엽림에서 내가 서 푼에 넘긴 그 방망이, 이 양반이 사 갔다네."}, {"s": "q:sx_gamdol", "t": "아이고, 주모. 서 푼에 산 걸 두 냥 받고 돌려드린다니까 그러시네."}, {"s": "q:sx_bangul", "t": "두 냥? 원래 내 거야!"}, {"s": "q:sx_gamdol", "t": "그게 말일세, 그냥 몽둥이로는 값이 안 나가. 벼락을 맞아야 값이 붙지. 그래서 산꼭대기 바위틈에 꽂아 두고 벼락 칠 날을 기다리는 중이었네."}, {"s": null, "t": "나는 산꼭대기에 무엇이 있느냐고 물었다."}, {"s": "q:sx_gamdol", "t": "그게 문제야. 꽂아 두고 내려오는 길에 벼락 지네들이 몰려들었거든. 쇠테에 벼락 기운이 모이니 그놈들이 좋아라 하고 감겨 붙었어."}, {"s": "q:sx_kkotnim", "t": "조사원, 지네부터 치워 주게. 이 양반은 내가 붙들고 있으마. 값은 그다음에 따지자고."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_4', 2, '벼락 맞은 머리', '벼락 지네을(를) 물리친다', '{"at": ["thunder_peak"], "tasks": [{"t": "win", "m": ["x_thunder_peak_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "지네를 쫓고 꼭대기에 오르자, 바위틈에 방망이가 꽂혀 있었다. 쇠테가 시퍼렇게 달아올라 지지직 소리를 냈다."}, {"s": "q:sx_bangul", "t": "뚝딱아! 이번엔 진짜 안 놓칠 거야!"}, {"s": null, "t": "방울이 방망이를 붙잡고 외쳤다. 「금 나와라, 뚝딱!」"}, {"s": null, "t": "하늘에서 번쩍 하고 벼락이 떨어졌다. 연기가 걷히자 방울의 머리카락이 밤송이처럼 곤두서 있었다."}, {"s": "q:sx_bangul", "t": "……금 대신 벼락이 나왔어."}, {"s": "q:sx_kkotnim", "t": "아이고, 내 새끼. 머리가 아주 성게가 됐구나."}, {"s": "q:sx_gamdol", "t": "그것 보게. 벼락을 맞으니 영험이 붙었잖나. 이제 열 냥은 받겠어."}, {"s": null, "t": "방울이 다시 당겨 보았지만 방망이는 빠지지 않았다. 벼락 열기에 녹은 쇠가 바위와 들러붙어 있었다."}, {"s": "q:sx_kkotnim", "t": "둘레 바위를 쪼아 내야겠다. 조사원, 방망이에 들러붙은 뇌철 광석 네 덩이만 떼어 주게. 조심해, 아직 따끔따끔할 게다."}]'::jsonb, '{"xp": 623}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_4', 3, '하나 남은 소원', '뇌철 광석을(를) 모은다', '{"at": ["thunder_peak"], "tasks": [{"t": "gather", "items": ["thunder_ore"], "r": ["thunder_peak"], "n": 4}]}'::jsonb, '[{"s": null, "t": "뇌철을 떼어 내자 방망이가 빠져나왔다. 그런데 방망이를 두르던 쇠테가 녹아서 흘러내리고 없었다."}, {"s": "q:sx_bangul", "t": "쇠테가 없어……. 할아버지가 직접 두른 쇠테인데……."}, {"s": null, "t": "방울은 방망이를 끌어안고 처음으로 울지 않는다는 말을 하지 않았다. 그냥 울었다."}, {"s": "q:sx_kkotnim", "t": "쇠테야 새로 두르면 되지. 울기는."}, {"s": "q:sx_bangul", "t": "그게 아니야. 할아버지가 그랬어. 뚝딱이는 소원을 딱 하나만 더 들어준대. 할아버지가 다 쓰고 하나 남겨 준 거래. 쇠테가 없으면 그 하나도 새 나간대."}, {"s": "q:sx_gamdol", "t": "……하나 남은 걸 내가 벼락 맞히려 했던 게로군."}, {"s": null, "t": "감돌이는 한참 손을 비비다가 돈주머니를 도로 품에 넣었다."}, {"s": "q:sx_gamdol", "t": "두 냥은 됐네. 조사원, 강철 주괴 두 덩이만 뽑아 주게. 쇠테 두르는 일은 내가 할 줄 알아. 장사치가 되기 전엔 대장간 풀무꾼이었거든."}]'::jsonb, '{"xp": 623}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_4', 4, '할아버지 함자', '강철 주괴을(를) 만든다, 강철 주괴을(를) 넘긴다', '{"at": ["thunder_peak"], "tasks": [{"t": "craft", "items": ["steel_ingot"], "n": 2}], "give": {"steel_ingot": 2}}'::jsonb, '[{"s": null, "t": "감돌이는 바위 위에 풀무를 걸고 강철을 달구어 방망이에 새 쇠테를 둘렀다. 망치 소리가 산꼭대기에 울렸다."}, {"s": "q:sx_gamdol", "t": "됐네. 이제 벼락 맞을 일은 없을 게야. 대신 값도 안 나가겠지만."}, {"s": "q:sx_bangul", "t": "흥. 원래 값 같은 거 없어."}, {"s": "q:sx_kkotnim", "t": "그래, 그 하나 남은 소원으로 뭘 빌 거냐? 금 나와라? 내 주막에 기와지붕이나 올려 주라."}, {"s": "q:sx_bangul", "t": "금 빌 거야. 산만 한 금. 꽃님이 지붕도 올려 주고, 감돌이 두 냥도 주고. 할아버지가 하늘에서 제일 가까운 데서 빌어야 잘 들어준다고 했어."}, {"s": "q:sx_kkotnim", "t": "하늘에서 제일 가까운 데라면 백옥 천문탑이지. 그런데 너, 할아버지 함자는 뭐였냐? 빌 때 할아버지 이름 대고 빌어야 하는 거 아니냐."}, {"s": "q:sx_bangul", "t": "할아버지는 할아버지지! 이름은……. 이름은 왕……."}, {"s": null, "t": "방울은 말끝을 흐리고 방망이를 내려다보았다. 한참 있다가 방울은 대답 대신 먼저 산을 내려가 버렸다."}, {"s": "q:sx_kkotnim", "t": "……조사원, 천문탑에서 보세. 저 녀석, 오늘은 내가 업고 가야겠어."}]'::jsonb, '{"xp": 623, "gil": 69, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
