values ('sq110_struck_jujube', 'side', '채집·뇌명봉', '벼락 맞은 대추나무', '벼락 맞은 나무로 도장을 파겠다는 노인의 주문 백 개', 'thunder_peak', 16, '{}'::text[], null, 1108, '[]'::jsonb, true, null, null)
