delete from public.world_quest_steps where quest_id = 'sq110_struck_jujube' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_struck_jujube', 1, '주문 백 개', '주문 백 개', '{"at": ["thunder_peak"]}'::jsonb, '[{"s": null, "t": "뇌명봉 기슭의 작은 공방 앞에 대추나무 한 그루가 서 있었다. 그 아래에서 영감 하나가 하늘만 올려다보고 있었다."}, {"s": "q:sx_samchul", "t": "왔구먼! 조사원이 오면 하늘도 도와준다더니. 이보게, 벼락 맞은 대추나무 알지? 그걸로 판 도장은 액을 막는다네."}, {"s": "q:sx_samchul", "t": "내가 그 도장을 백 개 팔기로 했어. 값도 미리 받았지. 그런데 나무가 없어."}, {"s": "q:sx_bunyi", "t": "할아버지가 나무도 없는데 돈부터 받았대요."}, {"s": "q:sx_samchul", "t": "나무는 있다! 저기 있잖아. 벼락만 안 맞았을 뿐이지."}, {"s": null, "t": "나는 벼락이 언제 칠 줄 알고 기다리느냐고 물었다."}, {"s": "q:sx_samchul", "t": "그러니까 부르는 거야. 부적목은 벼락을 끈다더라. 이 산 부적목 여섯 단만 베어 오게. 대추나무 가지마다 묶어 두면 벼락이 알아서 찾아오겠지."}, {"s": "q:sx_bunyi", "t": "그거 할아버지가 지어낸 말이죠?"}, {"s": "q:sx_samchul", "t": "어른 말에 토 달지 마라."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_struck_jujube', 2, '벼락보다 먼저 온 손님', '부적목을(를) 모은다', '{"at": ["thunder_peak"], "tasks": [{"t": "gather", "items": ["wood"], "r": ["thunder_peak"], "n": 6}]}'::jsonb, '[{"s": null, "t": "부적목을 가지마다 묶자 대추나무가 털 난 짐승처럼 부풀어 보였다. 삼출은 흐뭇하게 팔짱을 꼈다."}, {"s": null, "t": "그런데 산등성이에서 먼저 내려온 것은 벼락이 아니라 등에 퍼런 불꽃을 두른 지네들이었다. 부적목에 서린 기운을 맡고 꼬여 든 모양이었다."}, {"s": "q:sx_samchul", "t": "오, 저것 봐라! 벌써 기운이 모이지 않느냐!"}, {"s": "q:sx_bunyi", "t": "할아버지, 저거 벼락 지네예요. 물리면 사흘 동안 머리카락이 서요."}, {"s": "q:sx_samchul", "t": "……사흘? 그럼 안 되지. 이번 장날에 장가가는 조카 잔치에 가야 해."}, {"s": "q:sx_samchul", "t": "조사원, 저것들 좀 치워 주게. 나무에 붙기 전에!"}]'::jsonb, '{"xp": 623}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_struck_jujube', 3, '마침내 친 벼락', '벼락 지네을(를) 물리친다', '{"at": ["thunder_peak"], "tasks": [{"t": "win", "m": ["x_thunder_peak_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "지네들을 쫓고 나자 하늘이 정말로 낮게 내려앉았다. 뇌명봉 꼭대기에서 우르릉 소리가 굴러 내려왔다."}, {"s": "q:sx_samchul", "t": "온다, 온다! 다들 엎드려!"}, {"s": null, "t": "하얀 빛이 번쩍하고, 귀가 먹먹해질 만큼 큰 소리가 났다. 나는 잠깐 앞을 보지 못했다."}, {"s": null, "t": "눈을 떠 보니 대추나무는 멀쩡했다. 부적목 묶음도 그대로였다. 대신 공방 뒤쪽 어디선가 연기가 피어올랐다."}, {"s": "q:sx_bunyi", "t": "할아버지, 할아버지 갓에서도 연기 나요."}, {"s": "q:sx_samchul", "t": "내 갓은 됐고! 벼락이 어디로 떨어졌는지 찾아. 그 자리 나무를 써야 진짜야. 조사원, 연기 나는 쪽을 좀 뒤져 주게."}]'::jsonb, '{"xp": 623}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_struck_jujube', 4, '백 개의 도장', '뇌명봉을(를) 살핀다', '{"at": ["thunder_peak"], "tasks": [{"t": "search", "r": ["thunder_peak"], "n": 3}]}'::jsonb, '[{"s": null, "t": "연기를 따라가 보니 공방 뒤 바위 위에 나무 지팡이 하나가 새까맣게 그을린 채 쓰러져 있었다. 쪼개진 틈에서 아직 김이 올랐다."}, {"s": "q:sx_bunyi", "t": "저거 할아버지 지팡이잖아요. 아까 하늘 보신다고 바위에 기대 놓으셨죠."}, {"s": "q:sx_samchul", "t": "……무슨 나무로 깎았더라."}, {"s": "q:sx_bunyi", "t": "대추나무요. 할머니가 깎아 주신 거요."}, {"s": null, "t": "삼출은 그을린 지팡이를 한참 들여다보다가 무릎을 쳤다."}, {"s": "q:sx_samchul", "t": "하늘이 내 정성을 알았구먼! 벼락 맞은 대추나무, 틀림없는 진짜다!"}, {"s": "q:sx_bunyi", "t": "근데 지팡이 하나로 백 개가 나와요?"}, {"s": "q:sx_samchul", "t": "작게 파면 되지. 손톱만 하게."}, {"s": null, "t": "열흘 뒤 마을 사람들은 손톱만 한 도장을 하나씩 받았다. 찍으면 글자가 너무 작아서 아무도 읽지 못했다. 그래도 액을 막는다는 소문은 금세 퍼졌다."}, {"s": null, "t": "삼출은 새 지팡이를 짚고 다녔다. 공방 앞 대추나무 가지로 깎은 것이었다. 분이는 그 지팡이를 비 오는 날마다 집 안에 숨겨 두었다."}]'::jsonb, '{"xp": 623, "gil": 69, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
