insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_star_child', 1, '혼자 온 아이', '혼자 온 아이', '{"at": ["comet_crater"]}'::jsonb, '[{"s": null, "t": "혜성 낙하지의 유리 같은 모래밭 한가운데에 아이 하나가 쪼그려 앉아 있었다. 손에는 작은 대바구니를 들고 있었다."}, {"s": "q:sx_kkomabyeol", "t": "아저씨, 아니 언니, 아니 조사원님! 별똥 어디 있는지 알아요?"}, {"s": "q:sx_kkomabyeol", "t": "우리 엄마 생일이 모레예요. 별똥으로 노리개를 만들어 드릴 거예요. 엄마가 별을 엄청 좋아하거든요."}, {"s": null, "t": "나는 여기까지 누구와 왔느냐고 물었다."}, {"s": "q:sx_kkomabyeol", "t": "혼자 왔어요. 비밀이라서요. 엄마한테 말하면 비밀이 아니잖아요."}, {"s": null, "t": "아이의 짚신은 다 해져 있었다. 마을에서 낙하지까지는 어른 걸음으로도 반나절 길이었다."}, {"s": "q:sx_kkomabyeol", "t": "반짝반짝하는 모래요, 별모래! 그게 별똥 부스러기래요. 저는 아까부터 찾았는데 하나도 못 찾았어요. 조금만 같이 찾아 주세요. 네 개만요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_star_child', 2, '모래밭의 집게', '성진사을(를) 모은다', '{"at": ["comet_crater"], "tasks": [{"t": "gather", "items": ["star_sand"], "r": ["comet_crater"], "n": 4}]}'::jsonb, '[{"s": null, "t": "성진사를 손바닥에 올려 주자 꼬마 별은 숨도 안 쉬고 들여다보았다."}, {"s": "q:sx_kkomabyeol", "t": "우와. 진짜 별이다. 진짜 별 부스러기다."}, {"s": null, "t": "그때 아이 뒤쪽 모래가 볼록 솟았다. 유리처럼 비치는 꼬리가 모래 위로 올라왔다."}, {"s": "q:sx_kkomabyeol", "t": "저, 저거 뭐예요? 저 안 무서워요. 하나도 안 무서워요."}, {"s": null, "t": "아이는 그렇게 말하면서 내 옷자락 뒤로 쏙 들어갔다."}, {"s": "q:sx_kkomabyeol", "t": "조사원님이 무서우면 제가 바구니로 막아 줄게요. 그러니까 먼저 가세요."}]'::jsonb, '{"xp": 689}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_star_child', 3, '집에 가는 길', '유리 모래 전갈을(를) 물리친다', '{"at": ["comet_crater"], "tasks": [{"t": "win", "m": ["r71_comet_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "전갈들이 모래 밑으로 사라지자 하늘은 벌써 어두워져 있었다. 꼬마 별은 바구니를 꼭 안고 하품을 했다."}, {"s": "q:sx_kkomabyeol", "t": "이제 집에 가야 하는데…… 깜깜해요."}, {"s": "q:sx_kkomabyeol", "t": "엄마가 그랬어요. 밤길에 불 없이 다니면 이름을 잃어버린대요. 이름을 잃으면 엄마가 불러도 못 알아듣는대요."}, {"s": null, "t": "아이는 그 말을 하고 나서 입술을 꾹 깨물었다. 울지 않으려고 애쓰는 얼굴이었다."}, {"s": "q:sx_kkomabyeol", "t": "저 울려는 거 아니에요. 모래가 눈에 들어갔어요."}, {"s": null, "t": "나는 밤길에 들고 갈 등을 하나 만들어 주겠다고 했다. 기름을 오래 머금는 어유 등잔이라면 마을까지 넉넉히 갈 것이었다."}]'::jsonb, '{"xp": 689}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_star_child', 4, '마주 오는 불빛', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["comet_crater"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 1}], "give": {"fish_oil_lamp": 1}}'::jsonb, '[{"s": null, "t": "어유 등잔을 들려 주자 꼬마 별은 금세 기운을 차리고 앞장서 걸었다."}, {"s": "q:sx_kkomabyeol", "t": "제가 길 비춰 줄게요. 조사원님은 따라오기만 하세요."}, {"s": null, "t": "낙하지를 반쯤 벗어났을 때, 맞은편 언덕에서 작은 불빛 하나가 흔들리며 다가왔다. 불빛이 우리 쪽으로 달려오기 시작했다."}, {"s": "q:sx_hwaseon", "t": "별아! 별아!"}, {"s": "q:sx_kkomabyeol", "t": "……엄마?"}, {"s": null, "t": "여인은 등을 내던지듯 내려놓고 아이를 끌어안았다. 아이 이름을 몇 번이고 불렀다."}, {"s": "q:sx_hwaseon", "t": "어디 갔었어. 엄마가 얼마나 찾았는지 알아?"}, {"s": "q:sx_kkomabyeol", "t": "비밀이었는데. 엄마, 생일 축하해요. 이틀 일찍요."}, {"s": null, "t": "아이가 내민 바구니 안에서 성진사 네 알이 반짝였다. 화선은 그것을 보다가 웃음인지 울음인지 모를 소리를 냈다."}, {"s": "q:sx_hwaseon", "t": "너 태어나던 밤에도 엄마가 여기 와서 별모래를 주웠단다. 네 돌 노리개에 달아 준 게 바로 그거야. 그래서 네 이름이 별이고."}, {"s": "q:sx_kkomabyeol", "t": "그럼 엄마도 혼자 왔었어요?"}, {"s": "q:sx_hwaseon", "t": "……응. 그래서 혼낼 수가 없네."}, {"s": null, "t": "두 사람은 등 두 개를 나란히 들고 언덕을 넘어갔다. 멀리서 보니 별 두 개가 땅 위를 걸어가는 것 같았다."}]'::jsonb, '{"xp": 689, "gil": 73, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
