insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_analyst', 1, '깜빡이는 등', '깜빡이는 등', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "등롱 가게 천장에 매달린 수백 개의 등 가운데 하나가 꺼질 듯 깜빡이고 있었다. 내 등 바로 옆이었다."}, {"s": "q:dh_ilsu", "t": "왔구나. 저거 보여? 서린이라는 암영 등이야. 너보다 몇 해 먼저 들어온 놈이지."}, {"s": "q:dh_ilsu", "t": "열흘 전에 월식성에 들어간다고 했어. 그런데 사흘째 저렇게 깜빡여. 등이 깜빡이면 그 사람이 돌아올 길을 잃어 가고 있다는 뜻이야."}, {"s": "q:dh_ilsu", "t": "꺼지기 전에 데려와. 다만 거긴 적월교 땅이야. 칼 뽑고 들어가면 성 전체가 깨."}, {"s": "q:dh_ilsu", "t": "그림자 속으로 다녀. 너희 암영이 제일 잘하는 거잖아. 성 안을 조용히 훑어서 서린의 흔적부터 찾아."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_analyst', 2, '벽에 남은 칼자국', '적월교 월식성을(를) 살핀다', '{"at": ["red_moon_fort"], "tasks": [{"t": "search", "r": ["red_moon_fort"], "n": 3}]}'::jsonb, '[{"s": null, "t": "성 뒷담 그늘에 단도로 그은 짧은 칼자국이 이어져 있었다. 암영끼리 쓰는 표시였다. 따라오라는 뜻이었다."}, {"s": null, "t": "칼자국을 따라가자 처마 밑에서 박쥐들이 한꺼번에 눈을 떴다. 저것들이 울면 교도들이 몰려올 터였다."}, {"s": null, "t": "나는 숨을 죽이고 그림자 쪽으로 몸을 붙였다. 울기 전에, 하나씩 조용히 떨어뜨려야 했다."}, {"s": null, "t": "성벽 위로 붉은 등을 든 교도들이 지나갔다. 나는 그들의 발소리가 멀어질 때까지 움직이지 않았다."}, {"s": null, "t": "박쥐 떼 너머 칼자국은 성 안쪽 망루 아래로 꺾여 들어가 있었다."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_analyst', 3, '그림자 속의 선배', '월식 박쥐 떼을(를) 물리친다', '{"at": ["red_moon_fort"], "tasks": [{"t": "win", "m": ["x_red_moon_fort_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "망루 아래 빛이 닿지 않는 틈에 한 사내가 웅크리고 있었다. 옆구리에 감은 천이 피로 검게 젖어 있었다."}, {"s": "q:sx_seorin", "t": "…마일수가 보냈군."}, {"s": "q:sx_seorin", "t": "사흘째 여기 있었다. 나가는 길목에 혈월 무사 둘이 서 있어. 혼자서는 못 뚫는다."}, {"s": "q:sx_seorin", "t": "그리고 등이 필요해. 빛이 새지 않는 작은 등. 어둠 속에선 발밑만 보이면 된다."}, {"s": null, "t": "나는 어유 등잔을 지어 오겠다고 했다. 등잔 둘레를 천으로 가리면 발밑만 비출 수 있었다."}, {"s": "q:sx_seorin", "t": "길목 놈들부터 치워. 소리 없이."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_analyst', 4, '등 앞에 서는 일', '혈월 무사을(를) 물리친다, 어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "win", "m": ["x_red_moon_fort_2"], "n": 2}, {"t": "craft", "items": ["fish_oil_lamp"], "n": 1}], "give": {"fish_oil_lamp": 1}}'::jsonb, '[{"s": null, "t": "서린은 천을 두른 등잔 불빛만 보고 성을 빠져나왔다. 야시장에 닿을 때까지 한마디도 하지 않았다."}, {"s": null, "t": "등롱 가게에 들어서자 깜빡이던 등이 환하게 밝아졌다. 서린은 제 등 앞에 오래 서 있었다. 등불이 그의 그림자를 바닥에 길게 드리웠다."}, {"s": "q:dh_ilsu", "t": "그래, 그거야. 그게 그림자 값이야."}, {"s": null, "t": "나는 그림자 값이 무엇이냐고 물었다."}, {"s": "q:dh_ilsu", "t": "너희는 그림자를 빌려 쓰고 다니잖아. 빌린 건 갚아야지. 살아서 돌아와서, 제 등 앞에 서서 그림자를 다시 드리우는 거. 그게 값이야."}, {"s": "q:sx_seorin", "t": "…갚았다."}, {"s": null, "t": "서린은 내 등을 한 번 올려다보고, 고개를 짧게 숙이고 나갔다."}, {"s": "q:dh_ilsu", "t": "저놈이 고맙다고 할 때 저렇게 해. 네 등도 오늘 좀 밝아졌네."}]'::jsonb, '{"xp": 758, "gil": 77, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
