insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_artificer', 1, '서문에서 온 부탁', '서문에서 온 부탁', '{"at": ["west_gate"]}'::jsonb, '[{"s": null, "t": "서문 폐성 성벽 아래에서 탁대근이 구겨진 편지 한 장을 펴 들고 있었다."}, {"s": "q:dh_daegeun", "t": "왔군. 자네 칼집 매듭은 여전하네. 그사이 많이 맞아 본 얼굴이야."}, {"s": "q:dh_daegeun", "t": "뇌명봉에서 편지가 왔네. 서문이 무너진 밤에 내가 지키지 못한 부적쟁이가 있다고 했지. 그 사람 딸일세."}, {"s": "q:dh_daegeun", "t": "벼락 맞은 부적목을 깎는다더군. 벼락이 친 자리에서 깎아야 힘이 든다고. 그런데 깎는 동안 앞에 서 줄 사람이 없다는 게야."}, {"s": "q:dh_daegeun", "t": "내가 가야 마땅한데, 이 다리로는 산길 반도 못 오르네."}, {"s": null, "t": "나는 대신 가서 앞에 서겠다고 했다."}, {"s": "q:dh_daegeun", "t": "고맙네. 그 아이는 봉우리마다 옮겨 다니며 깎는다니, 뇌명봉을 몇 번 훑어서 작업터부터 찾게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_artificer', 2, '벼락 친 자리', '뇌명봉을(를) 살핀다', '{"at": ["thunder_peak"], "tasks": [{"t": "search", "r": ["thunder_peak"], "n": 3}]}'::jsonb, '[{"s": null, "t": "불에 그은 바위 위에서 한 여인이 칼로 나무를 깎고 있었다. 나무 둥치에는 아직 벼락 맞은 자국이 시커멓게 남아 있었다."}, {"s": "q:sx_geumi", "t": "탁 아저씨가 보낸 분이에요? 늦게 오셨네요. 아니, 오신 것만도 고맙지요."}, {"s": "q:sx_geumi", "t": "벼락 친 나무는 따뜻할 때 깎아야 해요. 식으면 힘이 다 빠져요. 그런데 그 온기를 벼락 지네들이 맡고 몰려와요."}, {"s": null, "t": "바위틈에서 다리가 수십 개 달린 것들이 푸른 불꽃을 튀기며 기어 나왔다."}, {"s": "q:sx_geumi", "t": "저는 칼에서 눈을 못 떼요. 뒤는 안 볼 테니까, 앞에서만 막아 주세요."}, {"s": null, "t": "나는 금이와 지네들 사이에 섰다."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_artificer', 3, '아버지가 남긴 말', '벼락 지네을(를) 물리친다', '{"at": ["thunder_peak"], "tasks": [{"t": "win", "m": ["x_thunder_peak_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "지네들이 흩어지는 동안 금이는 한 번도 고개를 들지 않았다. 깎은 부적목에서 아직 김이 올랐다."}, {"s": "q:sx_geumi", "t": "정말 한 걸음도 안 물러나셨네요. 발자국이 바위에 그대로 찍혔어요."}, {"s": "q:sx_geumi", "t": "아버지가 마지막으로 보낸 편지에 그런 말이 있었어요. 「뒤는 보지 마라. 앞에 선 사람이 물러서지 않는다.」 그게 탁 아저씨였대요."}, {"s": "q:sx_geumi", "t": "아저씨는 자기가 아버지를 못 지켰다고만 해요. 아버지는 끝까지 붓을 놓지 않았는데 말이에요."}, {"s": null, "t": "산 아래에서 쇳소리가 났다. 돌 껍데기를 두른 것들이 무리 지어 올라오고 있었다."}, {"s": "q:sx_geumi", "t": "뇌석 갑귀예요. 밀어붙이는 놈들이라 버티는 수밖에 없어요. 그동안 저는 부적목을 몇 토막만 더 거둘게요. 남는 손이 있으면 같이 거둬 주세요."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_artificer', 4, '교대', '뇌석 갑귀을(를) 물리친다, 부적목을(를) 모은다, 부적목을(를) 넘긴다', '{"at": ["west_gate"], "tasks": [{"t": "win", "m": ["x_thunder_peak_2"], "n": 3}, {"t": "gather", "items": ["wood"], "r": ["thunder_peak"], "n": 5}], "give": {"wood": 3}}'::jsonb, '[{"s": null, "t": "금이가 깎은 부적목으로 부적 한 장을 지어 내게 맡겼다. 탁대근에게 꼭 전해 달라고 했다."}, {"s": null, "t": "나는 서문 폐성으로 돌아와 부적을 건넸다. 부적 뒷면에는 금이의 글씨로 아버지의 이름이 적혀 있었다."}, {"s": "q:dh_daegeun", "t": "…이 녀석, 이름을 적어 보냈구먼."}, {"s": null, "t": "나는 금이가 전한 말을 그대로 옮겼다. 앞에 선 사람이 물러서지 않았기에 아버지가 끝까지 붓을 그었다고."}, {"s": "q:dh_daegeun", "t": "나는 스무 해 동안 그 밤에 진 줄만 알았네."}, {"s": "q:dh_daegeun", "t": "지킨다는 건 다 살려 내는 게 아니라, 뒤에 선 사람이 제 일을 끝까지 하게 해 주는 걸세. 그걸 그 녀석 딸한테 배우는구먼."}, {"s": null, "t": "탁대근은 부적을 성벽 틈에 꽂고 녹슨 창을 바로 세웠다. 그리고 오랜만에 두 다리로 똑바로 섰다."}, {"s": "q:dh_daegeun", "t": "자네 발자국이 뇌명봉에 찍혔다지. 그럼 그 봉우리도 이제 우리 호위대 땅일세."}]'::jsonb, '{"xp": 758, "gil": 77, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
