insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_exorcist', 1, '방울이 안 우는 곳', '방울이 안 우는 곳', '{"at": ["shrine_ruins"]}'::jsonb, '[{"s": null, "t": "폐쇄 사당 촛대에 불이 몇 개 더 늘어 있었다. 가을이 제 방울을 흔들며 마중을 나왔다."}, {"s": "q:dh_gaeul", "t": "퇴마관님! 저 이제 촛대 다섯 개까지 켤 수 있어요."}, {"s": "q:dh_gaeul", "t": "그런데요, 지나가던 영들이 그러는데, 퇴마관 방울이 하나도 안 우는 데가 있대요. 무명 고도래요."}, {"s": "q:dh_gaeul", "t": "방울은 이름을 부를 때 우는 거잖아요. 거기는 성 이름도, 사람 이름도 다 없어졌대요. 부를 게 없으니까 방울도 가만히 있대요."}, {"s": "q:dh_gaeul", "t": "그 성에 남은 것들은 아무도 안 불러 줘서 계속 거기서 돌기만 한대요. 저처럼요. 아니, 저보다 오래요."}, {"s": null, "t": "나는 무명 고도에 가 보겠다고 했다. 가을이 방울끈 한 가닥을 풀어 내 방울에 매 주었다."}, {"s": "q:dh_gaeul", "t": "이거 매면 제 방울 소리가 조금 섞여요. 무서우면 흔들어요. 먼저 성 안을 돌면서 이름이 남은 데가 있나 찾아봐요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_exorcist', 2, '지워진 문패', '무명 고도을(를) 살핀다', '{"at": ["forgotten_city"], "tasks": [{"t": "search", "r": ["forgotten_city"], "n": 3}]}'::jsonb, '[{"s": null, "t": "무명 고도의 집집마다 문패 자리가 비어 있었다. 글자를 깎아 낸 자국만 남아 있었다. 방울을 흔들어도 소리가 나지 않았다."}, {"s": null, "t": "성문 쪽 담벼락 아래에서 겨우 글자가 남은 돌판 하나를 찾았다. 비바람에 닳아 반쯤 읽혔다. 성을 지키던 문지기들의 이름이었다."}, {"s": null, "t": "돌판을 집어 들자 성문 쪽에서 무거운 발소리가 다가왔다. 돌로 깎은 병사들이 창을 끌며 걸어왔다."}, {"s": null, "t": "내가 돌판에 남은 이름 하나를 소리 내어 읽자, 방울이 처음으로 작게 울렸다. 맨 앞의 석상 수문병이 잠깐 멈칫했다."}, {"s": null, "t": "하지만 나머지는 멈추지 않았다. 이름이 다 닳은 돌판이었다."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_exorcist', 3, '결계관의 숙제', '석상 수문병을(를) 물리친다', '{"at": ["forgotten_city"], "tasks": [{"t": "win", "m": ["g_forgotten_city"], "n": 3}]}'::jsonb, '[{"s": null, "t": "쓰러진 석상들의 등에는 저마다 이름 한 자씩이 새겨져 있었다. 이름 반쪽만 남은 것도 있었다. 나는 그 글자들을 돌판의 이름과 하나씩 맞추어 보았다."}, {"s": null, "t": "맞춘 이름을 부를 때마다 방울이 조금씩 더 크게 울렸다. 가을의 방울끈 소리가 그 위에 얹혔다."}, {"s": null, "t": "성 한가운데 결계 너머로 관복 입은 것들이 결계를 손질하고 있었다. 결계 안쪽에 성의 이름이 갇혀 있는 듯했다. 결계관들은 누구도 그 이름을 읽지 못하게 막고 있었다."}, {"s": null, "t": "결계 앞을 지날 때 가을이 매어 준 방울끈이 혼자 떨렸다. 그 안의 이름을 불러 달라는 듯했다."}, {"s": null, "t": "맞춘 이름들은 정화 부적에 옮겨 적어야 오래 남을 것 같았다. 닳아 가는 돌보다 새 종이가 나았다."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_exorcist', 4, '우는 방울', '정화 부적을(를) 만든다, 고도 결계관을(를) 물리친다, 정화 부적을(를) 넘긴다', '{"at": ["shrine_ruins"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}, {"t": "win", "m": ["x_forgotten_city_2"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "결계관이 무너진 자리에서 결계가 풀렸다. 그 안의 돌기둥에 성의 이름이 남아 있었다. 나는 부적에 적은 문지기들의 이름과 함께 성의 이름을 불렀다. 방울이 성 전체에 울렸다."}, {"s": null, "t": "성 안을 돌던 기척들이 하나씩 멈추고, 돌아보고, 흩어졌다. 무명 고도라는 이름만은 그대로 남았다. 부르는 사람이 없던 동안 붙은 이름이었다."}, {"s": null, "t": "나는 폐쇄 사당으로 돌아와 가을에게 이야기를 들려주었다."}, {"s": "q:dh_gaeul", "t": "다 돌아봤어요? 진짜로요?"}, {"s": "q:dh_gaeul", "t": "그 사람들, 오래 기다렸겠다. 누가 불러 주기만을요."}, {"s": null, "t": "가을이 제 방울을 한 번 크게 흔들었다. 촛대 하나에 불이 더 붙었다. 여섯 개째였다."}, {"s": "q:dh_gaeul", "t": "퇴마관님 방울은 이름이 있어야 울지만요, 이름이 없어도 찾으면 되잖아요. 그쵸?"}, {"s": "q:dh_gaeul", "t": "다음에 방울이 안 우는 데가 있으면 저한테 먼저 말해요. 제가 같이 흔들어 줄게요."}]'::jsonb, '{"xp": 758, "gil": 77, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
