insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_medic', 1, '둘째 권', '둘째 권', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "약방 문턱에 외상 장부가 두 권 펼쳐져 있었다. 첫째 권은 낯이 익었다. 둘째 권은 줄 그은 이름이 하나도 없었다."}, {"s": "q:dh_gopun", "t": "왔네. 첫째 권은 못 돌아온 사람들이고, 이건 둘째 권이야. 아직 갚을 사람들이지."}, {"s": "q:dh_gopun", "t": "혜성 낙하지에 성진사 캐는 패거리가 있어. 반장이 억쇠라고, 몇 해째 약값을 안 갚았어. 이번 달엔 사람을 보내오지도 않았고."}, {"s": "q:dh_gopun", "t": "그쪽에 열병이 돈다는 소문이 있어. 약값 받으러 가는 거 아니야. 약 갖다주러 가는 거야."}, {"s": "q:dh_gopun", "t": "안신탕 두 그릇만 달여 가. 열에 들뜬 사람은 잠을 못 자거든. 자야 산다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_medic', 2, '별 떨어진 자리의 열병', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["comet_crater"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 2}], "give": {"calm_brew": 2}}'::jsonb, '[{"s": null, "t": "낙하지 구덩이 가장자리에 천막 몇 채가 쳐져 있었다. 천막 안에서 사람들이 열에 들떠 앓고 있었다."}, {"s": "q:sx_eoksoe", "t": "고분 할멈이 보냈다고? 약값도 안 냈는데 약을 또 보내? 그 할멈 셈이 영 틀렸구먼."}, {"s": null, "t": "나는 안신탕을 앓는 사람들에게 먹였다. 다리마다 붉게 부은 자국이 있었다. 열병이 아니라 독이었다."}, {"s": "q:sx_eoksoe", "t": "모래 속에 유리 같은 전갈들이 숨어 있네. 성진사를 캐다 보면 꼭 손이나 발을 쏘여."}, {"s": "q:sx_eoksoe", "t": "약은 고맙네만, 더 쏘이면 소용없어. 구덩이 주위 놈들부터 좀 치워 주게."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_medic', 3, '돌아오지 않은 막내', '유리 모래 전갈을(를) 물리친다', '{"at": ["comet_crater"], "tasks": [{"t": "win", "m": ["r71_comet_2"], "n": 4}]}'::jsonb, '[{"s": null, "t": "전갈을 치우고 돌아오자 억쇠가 천막 앞을 서성이고 있었다."}, {"s": "q:sx_eoksoe", "t": "막내 한 놈이 안 보여. 열에 들떠서는 별 떨어진 자리를 더 파 보겠다고 혼자 나갔다네."}, {"s": "q:sx_eoksoe", "t": "그놈이 할멈 장부 둘째 권 맨 끝에 적힌 이름일세. 지난봄에 처음 할멈 약을 먹은 놈이야."}, {"s": null, "t": "나는 해가 지기 전에 찾아오겠다고 했다. 독이 퍼지면 밤을 넘기기 어려웠다."}, {"s": "q:sx_eoksoe", "t": "구덩이가 깊고 넓어. 낙하지를 샅샅이 훑어야 할 걸세. 부탁하네."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_medic', 4, '갚지 말라는 빚', '혜성 낙하지을(를) 살핀다', '{"at": ["lantern_market"], "tasks": [{"t": "search", "r": ["comet_crater"], "n": 4}]}'::jsonb, '[{"s": null, "t": "막내는 별 떨어진 구덩이 맨 밑바닥에 쓰러져 있었다. 성진사 한 줌을 꼭 쥐고 있었다. 나는 독을 빼고 업어서 천막까지 데려왔다. 막내는 밤을 넘겼다."}, {"s": null, "t": "억쇠가 성진사 한 자루를 내밀며 약값으로 가져가라고 했다. 나는 그 자루를 들고 야시장으로 돌아왔다."}, {"s": "q:dh_gopun", "t": "그 영감이 약값을 보냈다고? …안 받아. 도로 갖다줘."}, {"s": null, "t": "나는 왜 약값을 받지 않느냐고 물었다."}, {"s": "q:dh_gopun", "t": "빚이 남아 있어야 돌아오거든. 갚을 게 있는 사람은 어떻게든 살아서 와."}, {"s": "q:dh_gopun", "t": "그래서 둘째 권에는 줄을 안 그어. 다 갚으면 장부에서 이름이 빠지잖아. 나는 그게 싫어."}, {"s": null, "t": "할멈은 둘째 권을 펴서 막내 이름 옆에 작은 점을 하나 찍었다."}, {"s": "q:dh_gopun", "t": "이건 「한 번 살렸음」이라는 표시야. 자네가 찍은 거나 마찬가지지. 앞으로 이 점이 늘어나게 해."}]'::jsonb, '{"xp": 758, "gil": 77, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
