insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_scout', 1, '그믐', '그믐', '{"at": ["hq_training"]}'::jsonb, '[{"s": null, "t": "연무장 과녁 옆에는 잿빛 들녘에서 찾아 온 부러진 화살 세 대가 아직 꽂혀 있었다. 위소라는 활을 손질하다 말고 하늘을 올려다보았다."}, {"s": "q:dh_sora", "t": "오늘 밤이 그믐이에요. 달이 없는 밤이요."}, {"s": "q:dh_sora", "t": "백옥 천문탑에 그믐마다 별빛 박쥐가 내려온대요. 천문관들이 별을 못 본다고 쏴 줄 사람을 구해요."}, {"s": "q:dh_sora", "t": "사실 저는 그믐에 활을 안 잡아요. 그 순찰조가 돌아오지 않은 게 그믐 밤이었거든요."}, {"s": "q:dh_sora", "t": "그래도 가 볼래요. 같이 가 줘요. 쏘기 전에 먼저 봐야 하니까, 탑을 몇 번 돌면서 박쥐들이 어디서 내려오는지 읽어 와요."}, {"s": null, "t": "나는 활을 챙겨 위소라를 따라나섰다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_scout', 2, '귀로 쏘는 법', '백옥 천문탑을(를) 살핀다', '{"at": ["white_tower"], "tasks": [{"t": "search", "r": ["white_tower"], "n": 3}]}'::jsonb, '[{"s": null, "t": "탑 꼭대기 처마마다 하얀 똥 자국이 줄지어 있었다. 박쥐들은 별이 가장 밝은 쪽에서 내려왔다."}, {"s": "q:dh_sora", "t": "잘 읽었네요. 저것들은 별빛을 등지고 와요. 눈으로 보면 늘 반 박자 늦어요."}, {"s": "q:dh_sora", "t": "달 없는 밤엔 귀로 쏴요. 날갯짓이 멈추는 그때가 내려앉기 직전이에요."}, {"s": null, "t": "위소라는 시위를 반쯤 당겼다가 놓지 못하고 다시 내렸다. 손이 떨리고 있었다."}, {"s": "q:dh_sora", "t": "…먼저 쏴 줘요. 저는 보고 있을게요. 보는 것도 사수 일이니까."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_scout', 3, '거울 속 과녁', '별빛 박쥐을(를) 물리친다', '{"at": ["white_tower"], "tasks": [{"t": "win", "m": ["x_white_tower_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "박쥐들이 흩어지자 탑 안이 조용해졌다. 그때 천문 거울 속에 사람 그림자 셋이 비쳤다. 활을 멘 그림자들이었다."}, {"s": "q:dh_sora", "t": "…저 사람들이에요. 그 순찰조요."}, {"s": null, "t": "그림자들은 거울 속에서 활을 들어 우리를 겨누었다. 거울 테두리가 일그러지며 무언가가 기어 나왔다."}, {"s": "q:dh_sora", "t": "아니에요. 그 사람들은 끝까지 쏘고 갔어요. 우리를 겨눌 리가 없어요. 저건 거울이 훔쳐 간 모습이에요."}, {"s": "q:dh_sora", "t": "거울귀는 비친 것 뒤에 숨어요. 그림자 말고 거울 테를 겨눠요. 저도 이번엔 쏠게요."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_scout', 4, '별 하나', '천문 거울귀을(를) 물리친다', '{"at": ["white_tower"], "tasks": [{"t": "win", "m": ["x_white_tower_2"], "n": 2}]}'::jsonb, '[{"s": null, "t": "마지막 거울귀가 깨지는 순간, 화살 하나가 내 어깨 옆을 지나 거울 테를 꿰뚫었다. 위소라의 화살이었다."}, {"s": "q:dh_sora", "t": "…쐈네요. 그믐에."}, {"s": null, "t": "깨진 거울에는 이제 별만 비쳤다. 위소라는 빈 화살통에서 화살 한 대를 꺼내 하늘로 쏘아 올렸다. 화살은 소리 없이 어둠 속으로 사라졌다."}, {"s": "q:dh_sora", "t": "그 사람들 몫이에요. 달 없는 밤에도 누가 쏘고 있다는 거, 알면 좋겠어요."}, {"s": "q:dh_sora", "t": "사수는 눈으로 먼저 쏜다고 했죠. 그믐엔 귀로, 그것도 안 되면 마음으로 쏴요. 오늘 배웠어요."}, {"s": "q:dh_sora", "t": "다음 그믐에도 와요. 이제 제가 먼저 쏠 테니까."}]'::jsonb, '{"xp": 758, "gil": 77, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
