insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_sealmaster', 1, '맞지 않는 칸', '맞지 않는 칸', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "윤도한이 봉인 출납 장부를 펴 놓고 붓끝으로 한 칸을 거듭 짚고 있었다."}, {"s": "q:m_yun", "t": "다시 뵙습니다. 이번에도 칸이 하나 맞지 않습니다."}, {"s": "q:m_yun", "t": "옛 의금부 옥사에 걸어 둔 봉인이 장부에는 모두 「묶여 있음」으로 적혀 있습니다. 그런데 옥사에서 쇠사슬 소리가 난다는 보고가 들어왔습니다."}, {"s": "q:m_yun", "t": "장부와 현장이 다르면 어느 한쪽이 틀린 것이지요. 저는 장부를 믿고 싶습니다만, 현장을 보지 않고 믿을 수는 없습니다."}, {"s": "q:m_yun", "t": "옥사를 돌며 봉인 하나하나가 어떤지 살펴 주십시오. 풀린 것이 있으면 몇 개인지 세어 주십시오."}]'::jsonb, '{}'::jsonb)
