insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_sealmaster', 2, '풀린 사슬', '옛 의금부 옥사을(를) 살핀다', '{"at": ["old_prison"], "tasks": [{"t": "search", "r": ["old_prison"], "n": 3}]}'::jsonb, '[{"s": null, "t": "옥사 칸마다 걸린 봉인 부적 가운데 셋이 찢겨 있었다. 부적이 묶어 두던 쇠사슬이 바닥에 풀려 늘어져 있었다."}, {"s": null, "t": "풀린 사슬을 끌고 다니는 옥졸들이 복도를 돌았다. 몸은 없고 사슬과 옥졸 갓만 허공에 떠 있었다."}, {"s": null, "t": "봉인을 다시 묶으려면 먼저 사슬을 끄는 것들을 치워야 했다. 묶는 쪽은 언제나 푸는 쪽보다 오래 걸린다는 윤도한의 말이 떠올랐다."}, {"s": null, "t": "옥졸 갓 아래에서 쇠사슬이 철컥거리며 이쪽으로 고개를 돌렸다. 풀려난 것은 사슬만이 아니었다."}, {"s": null, "t": "나는 풀린 봉인 셋의 자리를 장부 한쪽에 적고, 복도로 나섰다."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_sealmaster', 3, '다시 묶을 먹', '쇠사슬 옥졸을(를) 물리친다', '{"at": ["old_prison"], "tasks": [{"t": "win", "m": ["r71_prison_4"], "n": 3}]}'::jsonb, '[{"s": null, "t": "옥졸들이 흩어지자 사슬이 바닥에 조용히 가라앉았다. 찢긴 부적 자리에 새 부적을 붙여야 했다."}, {"s": null, "t": "옥사 봉인은 보통 먹으로는 오래 가지 않았다. 옥사 안 형방 터에 옛 봉인 먹이 굳은 채 남아 있었고, 부적을 동여맬 부적실도 서고에 남아 있었다."}, {"s": null, "t": "나는 굳은 먹을 풀어 쓰기로 했다. 옥사에서 쓰던 먹이면 옥사 사슬을 가장 잘 알 터였다."}, {"s": null, "t": "형방 터 서고 앞에는 옥사 쥐 떼가 갉아 먹은 장부 부스러기가 수북했다. 먹과 실만은 쥐들도 건드리지 않았다."}, {"s": null, "t": "윤도한에게 장부를 맞춰 줄 몫도 남겨 두어야 했다. 묶은 증거를 함께 가져가야 장부에 적을 수 있었다."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq2_sealmaster', 4, '묶은 사람의 이름', '봉인 먹을(를) 모은다, 부적실을(를) 모은다, 봉인 먹을(를) 넘긴다', '{"at": ["hq_yard"], "tasks": [{"t": "gather", "items": ["sealing_ink"], "r": ["old_prison"], "n": 3}, {"t": "gather", "items": ["talisman_thread"], "r": ["old_prison"], "n": 2}], "give": {"sealing_ink": 1}}'::jsonb, '[{"s": null, "t": "나는 옥사의 풀린 봉인 셋을 새 먹과 부적실로 다시 묶고 정청으로 돌아왔다. 윤도한에게 남겨 온 봉인 먹을 건넸다."}, {"s": "q:m_yun", "t": "셋이었군요. 장부에는 하나도 없었는데 말입니다."}, {"s": "q:m_yun", "t": "풀린 것은 누가 언제 풀었는지 장부에 남지 않습니다. 묶은 것만 남지요. 그래서 묶은 분의 이름은 꼭 적어야 합니다."}, {"s": null, "t": "윤도한은 세 칸에 「다시 묶음」이라고 적고, 그 옆에 붓을 멈추었다."}, {"s": "q:m_yun", "t": "봉인술사 {이름}. …이렇게 적으면 되겠습니까."}, {"s": null, "t": "나는 그렇게 적어 달라고 했다. 윤도한은 또박또박 끝까지 눌러 적었다."}, {"s": "q:m_yun", "t": "이제 칸이 맞습니다. 다음에 또 맞지 않는 칸이 생기면, 이 이름부터 찾겠습니다."}]'::jsonb, '{"xp": 758, "gil": 77, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
