insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_north', 1, '맹약지의 마지막 등불', '맹약지의 마지막 등불', '{"at": ["thunder_peak"]}'::jsonb, '[{"s": null, "t": "뇌명봉 산마루의 작은 초막 앞에서 설백이 무릎을 꿇고 있었다. 초막 안에는 하얀 수염의 노인이 반듯하게 누워 있었다."}, {"s": "q:rn_seolbaek", "t": "서강 어르신이십니다. 얼음 인장 앞에서 처음 맹약을 맺은 일곱 분 가운데 마지막 분이셨어요."}, {"s": "q:rn_seolbaek", "t": "어젯밤 주무시듯 가셨습니다. 그런데 같은 밤에 벼락이 초막 위에 떨어져 맹약 패가 갈라졌어요."}, {"s": "q:rn_seolbaek", "t": "맹약은 처음 맺은 분이 계시는 동안 그분이 지니고, 마지막 분이 가시면 누군가 새 패를 지어 이어받는 게 법도입니다."}, {"s": null, "t": "나는 맹주가 이어받는 것이냐고 물었다."}, {"s": "q:rn_seolbaek", "t": "맹주는 맹을 이끄는 분이고, 맹약은 맹주 뒤에 서는 사람이 지킵니다. 그래서 따로 둬요. 맹주님은 저더러 지키라 하셨습니다."}, {"s": null, "t": "초막 둘레의 바위들이 들썩였다. 벼락을 머금은 바위 껍질들이 패 조각 쪽으로 기어 오고 있었다."}, {"s": "q:rn_seolbaek", "t": "벼락 냄새를 따라온 놈들이에요. 어르신 곁을 시끄럽게 하게 둘 순 없어요. 좀 도와주세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_north', 2, '갈라진 패', '뇌석 갑귀을(를) 물리친다', '{"at": ["thunder_peak"], "tasks": [{"t": "win", "m": ["x_thunder_peak_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "갑귀가 물러나자 설백이 갈라진 패 조각을 주워 모았다. 패에는 일곱 이름이 새겨져 있었고, 이름마다 얼음 같은 금이 가 있었다."}, {"s": "q:rn_seolbaek", "t": "새 패는 이 산의 뇌철로 지어야 한답니다. 벼락을 맞아도 갈라지지 않게요."}, {"s": "q:rn_seolbaek", "t": "그런데 저는 자격이 있을까요. 맹주님 형님이 얼음 속에서 문을 두드릴 때도 저는 몰랐습니다. 지키는 사람이라면서요."}, {"s": null, "t": "나는 그 두드림을 끝까지 잊지 않고 찾아낸 사람이 설백이라고 했다."}, {"s": "q:rn_seolbaek", "t": "……그건 잊지 못해서였어요. 잘해서가 아니라요."}, {"s": "q:rn_seolbaek", "t": "일단 뇌철부터 캐 주세요. 네 덩이면 패 한 장이 나옵니다."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_north', 3, '잊지 못하는 사람', '뇌철 광석을(를) 모은다', '{"at": ["thunder_peak"], "tasks": [{"t": "gather", "items": ["thunder_ore"], "r": ["thunder_peak"], "n": 4}]}'::jsonb, '[{"s": null, "t": "뇌철 광석을 초막 앞에 내려놓자 광석 틈에서 푸른 불빛이 일었다. 그 빛 속에 하얀 수염의 노인이 앉아 있었다."}, {"s": "q:sx_seogang", "t": "허허, 아직 내 이름을 부르는 사람이 있으니 바로 못 가겠구먼."}, {"s": "q:rn_seolbaek", "t": "어르신."}, {"s": "q:sx_seogang", "t": "얼음 인장 앞에서 밤새 서 있던 계집아이. 자네를 기억하네. 자네가 패를 이을 줄 알았지."}, {"s": "q:rn_seolbaek", "t": "저는 지키지 못한 게 많습니다."}, {"s": "q:sx_seogang", "t": "우리 일곱도 그랬네. 맹약은 잘 지킨 사람이 잇는 게 아니야. 못 지킨 걸 잊지 않는 사람이 잇는 거지."}, {"s": "q:sx_seogang", "t": "뇌철만 부으면 벼락에는 버텨도 추위에 깨지네. 조사원, 강철 주괴 두 덩이를 섞어 주게. 우리 패도 그렇게 지었네."}]'::jsonb, '{"xp": 758}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_north', 4, '여덟째 이름', '강철 주괴을(를) 만든다, 강철 주괴을(를) 넘긴다', '{"at": ["thunder_peak"], "tasks": [{"t": "craft", "items": ["steel_ingot"], "n": 2}], "give": {"steel_ingot": 2}}'::jsonb, '[{"s": null, "t": "설백은 뇌철과 강철을 섞어 부은 새 패에 일곱 이름을 하나씩 옮겨 새겼다. 마지막 자리에서 끌이 멈췄다."}, {"s": "q:sx_seogang", "t": "망설이지 말게. 자네 이름을 새기는 자리일세."}, {"s": null, "t": "설백이 제 이름을 새기는 동안 산 아래에서 누군가 올라왔다. 백발이 성성한 노무인이었다."}, {"s": "north_league:seok", "t": "……늦었군. 서강 형님께 술 한 잔 못 올렸다."}, {"s": "q:sx_seogang", "t": "진악이. 이제 자네 뒤에 설 사람이 생겼네. 눈 좀 붙이고 살게."}, {"s": "north_league:seok", "t": "눈을 감는 자는 뒤에 선 사람을 못 지킵니다. 형님이 가르치신 말 아닙니까."}, {"s": "q:sx_seogang", "t": "그러니까 뒤에 선 사람을 믿고 감으란 말일세."}, {"s": null, "t": "푸른 빛이 천천히 가라앉았다. 패에 새긴 여덟 이름 위로 서리가 얇게 앉았다가 녹았다."}, {"s": "q:rn_seolbaek", "t": "맹주님, 이번 겨울은 제가 산마루를 지키겠습니다."}, {"s": "north_league:seok", "t": "그래라. 그리고 조사원, 이것도 갚지 않겠다."}]'::jsonb, '{"xp": 758, "gil": 77, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
