values ('cq110_pack_2', 'side', '연계·아버지의 등짐', '옥에 갇힌 외상값', '외상을 진 사람이 옥사에서 옥귀가 되어 있다', 'old_prison', 19, '{cq110_pack_1}'::text[], null, 1117, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'cq110_pack_2' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_2', 1, '옥사 앞의 거간', '옥사 앞의 거간', '{"at": ["old_prison"]}'::jsonb, '[{"s": null, "t": "옛 의금부 옥사는 낮에도 어두웠다. 무너진 담장 너머에서 쇠사슬 끄는 소리가 났다가 멎었다."}, {"s": "q:sx_haesol", "t": "반돌 아저씨네 등대는 아직 잘 켜져 있대요. 오는 길에 만난 뱃사람이 그랬어요."}, {"s": "q:sx_haesol", "t": "이번 줄은 이 옥사예요. 「칠복. 주먹밥 백열 개. 나오면 갚을 것.」 그런데 옥사 근처 사람들 말이, 칠복이라는 죄수는 여기서 나오지 못하고 죽었대요."}, {"s": null, "t": "그때 담장 그늘에서 비단 두루마기를 입은 사내가 걸어 나왔다."}, {"s": "q:sx_mogap", "t": "죽은 사람한테 외상값을 받으러 왔소? 장사 수완이 아비를 닮았구려."}, {"s": "q:sx_mogap", "t": "나는 빚 거간 모갑이오. 그 장부, 내가 사 주리다. 사람 이름이 이렇게 빼곡히 적힌 장부는 값이 꽤 나가오."}, {"s": "q:sx_haesol", "t": "안 팔아요."}, {"s": "q:sx_dodam", "t": "누나, 저 아저씨는 아까부터 장부만 봐요."}, {"s": "q:sx_mogap", "t": "그럼 어디 받아 보시오. 옥사 안에는 쇠사슬 옥졸들이 아직도 순번을 돈다오."}, {"s": null, "t": "나는 옥졸들부터 치우고 들어가자고 했다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_2', 2, '족쇄 찬 그림자', '쇠사슬 옥졸을(를) 물리친다', '{"at": ["old_prison"], "tasks": [{"t": "win", "m": ["r71_prison_4"], "n": 3}]}'::jsonb, '[{"s": null, "t": "마지막 옥졸이 쓰러지자 사슬이 저절로 풀려 바닥에 똬리를 틀었다. 가장 안쪽 옥방에서 무언가 창살을 두드렸다."}, {"s": "q:sx_oesang_okgwi", "t": "왔냐. 받으러 왔냐."}, {"s": null, "t": "창살 너머에 발목에 족쇄를 찬 그림자가 앉아 있었다. 족쇄에서 뻗은 쇠사슬이 옥졸들이 쓰러진 쪽으로 이어져 있었고, 얼굴이 있어야 할 자리는 먹물처럼 번져 있었다."}, {"s": "q:sx_oesang_okgwi", "t": "받으러 왔냐. 받으러 왔냐. 나는 줄 게 없다."}, {"s": "q:sx_dodam", "t": "누, 누나. 저거 대답해야 돼요?"}, {"s": "q:sx_haesol", "t": "내 뒤에 있어."}, {"s": null, "t": "해솔은 떨리는 손으로 장부를 펴고 그 줄을 소리 내어 읽었다. 칠복이라는 이름이 나오자 그림자가 고개를 홱 들었다."}, {"s": "q:sx_oesang_okgwi", "t": "……그 이름. 누가 부르냐. 아무도 안 부르는 이름을."}, {"s": "q:sx_haesol", "t": "장부에 이름이 남아 있어서 영으로 남으신 거예요. 그런데 외상이 걸려 있어서 이 옥방을 못 떠나시는 거고요."}, {"s": "q:sx_haesol", "t": "조사원, 이 줄을 지우면 이름까지 지워져요. 「갚음」이라고 적어 드려야 해요. 옥사 안에 봉인 먹이 굳은 채 남아 있대요. 세 개만 찾아 주세요. 보통 먹으로 쓴 글씨는 영이 읽지 못한대요."}]'::jsonb, '{"xp": 831}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_2', 3, '갚음 두 글자', '봉인 먹을(를) 모은다', '{"at": ["old_prison"], "tasks": [{"t": "gather", "items": ["sealing_ink"], "r": ["old_prison"], "n": 3}]}'::jsonb, '[{"s": null, "t": "봉인 먹을 갈자 옥방 안의 공기가 차가워졌다. 해솔은 칠복의 줄 끝에 또박또박 「갚음」 두 글자를 적었다."}, {"s": "q:sx_oesang_okgwi", "t": "갚았냐. 내가 갚았냐."}, {"s": "q:sx_haesol", "t": "네. 다 갚으셨어요."}, {"s": "q:sx_oesang_okgwi", "t": "주먹밥. 그 사람이 주먹밥을 주면서 외상이라고 했다. 공짜로 받으면 내가 고개를 못 든다고. 나가서 갚으라고."}, {"s": "q:sx_oesang_okgwi", "t": "나는 못 나갔다. 그래서 여기 있었다."}, {"s": "q:sx_dodam", "t": "아버지가 옥사에 주먹밥을 날랐어요? 백열 번이나요?"}, {"s": null, "t": "그때 등 뒤에서 손뼉 소리가 났다. 모갑이 옥방 문턱에 기대어 서 있었다."}, {"s": "q:sx_mogap", "t": "눈물겹구려. 그런데 그 장부, 그렇게 함부로 쓰다가는 언젠가 탈이 나오. 마음이 바뀌면 부르시오."}, {"s": null, "t": "모갑이 떠나자 족쇄 찬 그림자가 다시 창살을 두드리기 시작했다. 이번에는 조금 느렸다."}, {"s": "q:sx_haesol", "t": "족쇄와 사슬에 아직 원한이 엉켜 있어요. 조사원, 정화 부적 두 장만 만들어 주세요. 하나는 족쇄에, 하나는 사슬에 붙여 드릴게요."}]'::jsonb, '{"xp": 831}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_2', 4, '열린 옥문', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["old_prison"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "정화 부적을 붙이자 족쇄가 두 쪽으로 갈라져 발목에서 떨어졌다. 사슬은 녹슨 쇳가루가 되어 흘러내렸다."}, {"s": null, "t": "그림자가 처음으로 일어섰다. 번져 있던 얼굴에 눈과 입이 희미하게 돌아왔다."}, {"s": "q:sx_oesang_okgwi", "t": "이제 나가도 되냐."}, {"s": "q:sx_haesol", "t": "네. 칠복 아저씨, 나가셔도 돼요."}, {"s": "q:sx_oesang_okgwi", "t": "그 사람한테 전해라. 주먹밥이 짰다고. 소금을 너무 쳤다고."}, {"s": null, "t": "그림자는 열린 옥문을 지나 담장 너머로 사라졌다. 쇠사슬 소리는 다시 나지 않았다."}, {"s": "q:sx_dodam", "t": "아버지 주먹밥은 원래 짜요. 누나도 알잖아요."}, {"s": "q:sx_haesol", "t": "……알아."}, {"s": null, "t": "나는 그 사람한테 전하라는 말이 마음에 걸린다고 했다. 해솔은 대답하지 않았다."}, {"s": null, "t": "옥사를 나서며 해솔은 장부를 품 안쪽으로 깊이 넣었다. 담장 그늘에 모갑의 두루마기 자락이 언뜻 보였다가 사라졌다."}]'::jsonb, '{"xp": 831, "gil": 81, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
