values ('sq110_cangue_ghost', 'side', '전투·옛 의금부 옥사', '칼 쓴 옥귀의 상소', '칼을 쓴 채 죽은 죄수가 밤마다 상소문을 읊는다', 'old_prison', 19, '{}'::text[], null, 1118, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_cangue_ghost' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_cangue_ghost', 1, '밤마다 들리는 상소', '밤마다 들리는 상소', '{"at": ["old_prison"]}'::jsonb, '[{"s": null, "t": "옛 의금부 옥사는 지붕이 반쯤 내려앉아 있었다. 무너진 문틈으로 누군가 글을 읽는 소리가 새어 나왔다."}, {"s": "q:sx_okgwi", "t": "신은 죄가 없사옵니다. 신은 죄가 없사옵니다. 장부를 다시 보아 주시옵소서."}, {"s": null, "t": "옥 안쪽 어둠 속에 목에 무거운 칼을 쓴 사람의 형체가 앉아 있었다. 칼 위로 숙인 얼굴은 보이지 않았다."}, {"s": "q:sx_okgwi", "t": "거기 누구시오. 산 사람의 발소리로구려."}, {"s": "q:sx_okgwi", "t": "나는 이 옥에서 칼을 쓴 채 죽었소. 죄명은 국고를 훔친 것이라 하였소. 그러나 나는 그 곳간 열쇠를 만져 본 적도 없소."}, {"s": null, "t": "나는 무엇을 도와주면 되느냐고 물었다."}, {"s": "q:sx_okgwi", "t": "그날의 형리 장부가 아직 이 옥사 어딘가에 있소. 그것만 찾으면 진짜 도둑의 이름이 적혀 있을 것이오. 부디 옥사를 뒤져 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_cangue_ghost', 2, '저절로 쓰이는 장부', '옛 의금부 옥사을(를) 살핀다', '{"at": ["old_prison"], "tasks": [{"t": "search", "r": ["old_prison"], "n": 3}]}'::jsonb, '[{"s": null, "t": "장부는 형방 자리 아래 마루 밑에서 나왔다. 종이는 누렇게 삭았는데 먹빛만은 이상하게 새것처럼 젖어 있었다."}, {"s": null, "t": "펼쳐 든 순간, 죄인 칸의 글자가 꿈틀거렸다. 먹이 벌레처럼 기어 다니며 획을 지우고 다시 썼다."}, {"s": null, "t": "나는 새로 써지는 글자를 읽었다. 내 이름이었다."}, {"s": "q:sx_okgwi", "t": "보았소? 그자가 아직 여기 있소. 죽어서도 밤마다 장부를 고치오. 오늘 밤은 당신을 죄인 칸에 넣으려는 모양이오."}, {"s": null, "t": "어디선가 낮게 웃는 소리가 들렸다. 등 뒤의 어둠이 한 뼘쯤 가까워진 것 같았다."}, {"s": "q:sx_okgwi", "t": "먹이 움직이지 못하게 해야 하오. 봉인 먹으로 그 위에 덧쓰면 다시는 고칠 수 없다 들었소. 이 옥사 어딘가에 옛 봉인관들이 쓰던 봉인 먹이 남아 있을 것이오. 세 자루만 찾아 주시오."}]'::jsonb, '{"xp": 831}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_cangue_ghost', 3, '고쳐 쓴 자', '봉인 먹을(를) 모은다', '{"at": ["old_prison"], "tasks": [{"t": "gather", "items": ["sealing_ink"], "r": ["old_prison"], "n": 3}]}'::jsonb, '[{"s": null, "t": "봉인 먹을 갈아 장부 위에 대자 기어 다니던 글자들이 멈추었다. 내 이름이 지워지고, 그 밑에 감춰져 있던 진짜 글자가 떠올랐다."}, {"s": null, "t": "국고를 훔친 자의 자리에 적힌 이름은 그날 이 장부를 쓴 형리 자신의 이름이었다."}, {"s": "q:sx_hyeongri", "t": "거, 남의 장부를 함부로 읽으면 쓰나."}, {"s": null, "t": "옥사 기둥 그늘에서 붓을 쥔 형리의 귀신이 걸어 나왔다. 손가락 끝이 모두 먹물로 시커멓게 젖어 있었다."}, {"s": "q:sx_hyeongri", "t": "장부란 쓰는 사람 것이라네. 내가 쓴 대로 저자는 죄인이 되었고, 나는 깨끗한 형리로 남았지. 자네도 내 장부에 한 줄 들어가 주게나."}, {"s": "q:sx_okgwi", "t": "저자요. 저자가 내 목에 칼을 씌웠소."}, {"s": null, "t": "형리귀 뒤로 똑같이 붓을 쥔 그림자가 하나 더 일어섰다. {직업:호위=나는 옥귀 앞을 막아서며 무기를 고쳐 잡았다./월궁=나는 기둥 뒤로 물러서며 화살을 메겼다./퇴마=나는 방울을 꺼내 들고 진언의 첫 구절을 외웠다./의무=나는 옥귀를 등 뒤로 감추고 약낭을 단단히 묶었다./봉인=나는 봉인 먹을 묻힌 부적을 손가락 사이에 끼웠다./암영=나는 숨을 죽이고 그림자 쪽으로 한 걸음 미끄러져 들어갔다.}"}]'::jsonb, '{"xp": 831}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_cangue_ghost', 4, '옮겨 간 칼', '의금부 형리귀을(를) 물리친다', '{"at": ["old_prison"], "tasks": [{"t": "win", "m": ["r71_prison_5"], "n": 2}]}'::jsonb, '[{"s": null, "t": "형리귀의 붓이 부러지자 옥사 안의 먹 냄새가 한꺼번에 걷혔다."}, {"s": null, "t": "쓰러진 형리귀가 몸을 일으키려 할 때, 옥귀의 목에 걸려 있던 칼이 저절로 풀렸다. 칼은 마루를 미끄러져 가더니 형리귀의 목에 철컥 채워졌다."}, {"s": "q:sx_hyeongri", "t": "이, 이게 무슨……. 이건 내 것이 아니야. 장부를 다시 보게!"}, {"s": null, "t": "나는 봉인 먹으로 굳힌 장부를 펼쳐 형리귀 앞에 내밀었다. 장부 속 글자는 이제 한 획도 움직이지 않았다."}, {"s": null, "t": "형리귀는 칼을 쓴 채 옥 안쪽으로 끌려 들어갔다. 그 칼 위로 숙인 얼굴은 더는 웃지 않았다."}, {"s": "q:sx_okgwi", "t": "……칼이 없으니 목이 가볍구려. 마흔 해 만이오."}, {"s": null, "t": "나는 장부의 억울한 죄인 칸에 적혀 있던 옥귀의 이름을 소리 내어 읽었다. 그는 처음으로 고개를 들었다. 생각보다 젊은 얼굴이었다."}, {"s": "q:sx_okgwi", "t": "그 이름을 불러 준 사람이 마흔 해 동안 아무도 없었소. 고맙소."}, {"s": null, "t": "그날 밤부터 옥사에서 상소 읽는 소리는 그쳤다. 대신 옥 깊은 곳에서 가끔 장부를 넘기는 소리가 났다. 형리귀가 칼을 쓴 채 자기 이름을 지우려 애쓰는 소리라고 했다. 봉인 먹으로 적은 글자는 지워지지 않았다."}]'::jsonb, '{"xp": 831, "gil": 81, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
