delete from public.world_quest_steps where quest_id = 'sq110_s_cheolbu' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_cheolbu', 1, '열두 해 묵은 내일', '열두 해 묵은 내일', '{"at": ["comet_crater"]}'::jsonb, '[{"s": null, "t": "혜성 낙하지의 유리 모래밭에 낯익은 풀무 가방이 놓여 있었다. 머리가 하얗게 센 대장장이가 그 옆에 앉아 망치 자루를 손질하고 있었다."}, {"s": "q:rn_cheolbu", "t": "왔소? 회산 관문에서 쇠를 캐 주던 그 조사원 맞지. 얼굴은 늙었는데 걸음은 그대로구먼."}, {"s": null, "t": "나는 화구 아래에서 생 월철을 캐던 날을 떠올렸다. 그게 벌써 열두 해 전이었다."}, {"s": "q:rn_cheolbu", "t": "그때 하나 더 부탁할 게 있다고 했잖소. 내일 말하겠다고. 이튿날 호송대 장비 얘기를 꺼냈지만, 그건 둘러댄 거였소."}, {"s": "q:sx_bulttong", "t": "그 「내일」이 열두 해 갔어요. 저는 그 말을 열두 해 동안 들었고요. 스승님은 그 얘기만 나오면 「내일」 하세요."}, {"s": "q:rn_cheolbu", "t": "시끄럽다. 오늘은 말할 거다. ……여기까지 온 김에, 먼저 쇠부터 찾고."}, {"s": "q:sx_bulttong", "t": "봐요, 또 미루시잖아요."}, {"s": "q:rn_cheolbu", "t": "이 모래밭 어딘가에 별에서 떨어진 쇠가 박혀 있다 하오. 별쇠라 부르지. 함께 좀 훑어봐 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_cheolbu', 2, '별쇠 둥지', '혜성 낙하지을(를) 살핀다', '{"at": ["comet_crater"], "tasks": [{"t": "search", "r": ["comet_crater"], "n": 3}]}'::jsonb, '[{"s": null, "t": "녹아 굳은 유리 모래 사이에 검푸른 쇳덩이 하나가 반쯤 묻혀 있었다. 손을 대니 아직도 미지근했다."}, {"s": "q:rn_cheolbu", "t": "이거요. 이 빛깔이면 틀림없소."}, {"s": null, "t": "쇳덩이를 들어 올리려는 순간, 모래가 들썩이더니 하늘빛 꼬리 끝이 여럿 솟았다. 별쇠 밑이 전갈 둥지였다."}, {"s": "q:sx_bulttong", "t": "스승님, 손 빼세요! 꼬리에 쏘이면 망치를 사흘은 못 드신대요."}, {"s": "q:rn_cheolbu", "t": "사흘이면 내 평생 처음 쉬어 보는 거구먼."}, {"s": "q:sx_bulttong", "t": "그런 말씀 마시고 물러나세요. 조사원님, 저 전갈들 좀 부탁드려요."}]'::jsonb, '{"xp": 831}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_cheolbu', 3, '섞어 부을 쇠', '유리 모래 전갈을(를) 물리친다', '{"at": ["comet_crater"], "tasks": [{"t": "win", "m": ["r71_comet_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "전갈을 쫓고 나자 철부가 별쇠를 품에 안듯 들어 올렸다. 그러고는 한참 쇳덩이만 내려다보았다."}, {"s": "q:rn_cheolbu", "t": "별쇠는 혼자 부으면 쉽게 갈라지오. 강철을 섞어야 단단해지지."}, {"s": "q:sx_bulttong", "t": "그건 제가 녹일게요. 스승님 손은 요즘 떨리시잖아요."}, {"s": "q:rn_cheolbu", "t": "아니. 이건 네가 하면 안 된다."}, {"s": null, "t": "불똥이 입을 삐죽 내밀었다. 철부는 모른 척하고 나를 돌아보았다."}, {"s": "q:rn_cheolbu", "t": "조사원, 강철 주괴 두 덩이만 뽑아 주시오. 그때 수리 도구 이음매를 곱게 붙이던 그 손이면 되오."}, {"s": null, "t": "나는 그 부탁이 이것이냐고 물었다. 철부는 고개를 저었다."}, {"s": "q:rn_cheolbu", "t": "이건 부탁 축에도 안 드오. 부탁은…… 쇠가 다 되면 하리다."}]'::jsonb, '{"xp": 831}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_cheolbu', 4, '오늘 하는 말', '강철 주괴을(를) 만든다, 강철 주괴을(를) 넘긴다', '{"at": ["comet_crater"], "tasks": [{"t": "craft", "items": ["steel_ingot"], "n": 2}], "give": {"steel_ingot": 2}}'::jsonb, '[{"s": null, "t": "철부는 별쇠에 강철 주괴를 섞어 밤새 두드렸다. 새벽녘, 모래 위에 검푸른 망치 하나가 놓였다."}, {"s": "q:rn_cheolbu", "t": "열두 해 전에 하려던 부탁은 이랬소. 「내 제자가 되어 주시오.」"}, {"s": null, "t": "나는 그만 웃고 말았다. 철부는 귀까지 붉어졌다."}, {"s": "q:rn_cheolbu", "t": "이튿날 말하려 했는데 막상 얼굴을 보니 입이 안 떨어져 장비 얘기만 했소. 그러고 나니 그대는 길을 떠났지. 그래서 저 녀석을 들였소."}, {"s": "q:sx_bulttong", "t": "저요? 저를 꿩 대신 닭으로 들이신 거예요?"}, {"s": "q:rn_cheolbu", "t": "닭이 꿩보다 낫더라. 그 말을 열두 해 못 했다."}, {"s": null, "t": "철부는 새 망치를 불똥에게 내밀지 못하고 내 손에 쥐여 주었다. 대신 건네 달라는 것이었다."}, {"s": null, "t": "내가 망치를 건네자 불똥은 망치를 받아 들고 한참 아무 말도 하지 않았다."}, {"s": "q:sx_bulttong", "t": "……스승님, 이것도 내일 말하려다 만 거예요?"}, {"s": "q:rn_cheolbu", "t": "그래. 그러니 오늘 받아라. 내일은 또 미룰 테니."}]'::jsonb, '{"xp": 831, "gil": 81, "items": {"tonic": 2, "travel_ration": 1}}'::jsonb)
