insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_5', 1, '하늘에서 제일 가까운 데', '하늘에서 제일 가까운 데', '{"at": ["white_tower"]}'::jsonb, '[{"s": null, "t": "백옥 천문탑 아래에 꽃님의 수레가 서 있었다. 방울은 새 쇠테를 두른 방망이를 등에 메고 탑 꼭대기를 올려다보았다."}, {"s": "q:sx_kkotnim", "t": "뇌명봉에서 내려와서 이 녀석이 한마디도 안 했어. 밥은 세 그릇 먹었지만."}, {"s": "q:sx_bangul", "t": "생각하느라 그랬어. 소원은 신중하게 비는 거야."}, {"s": "q:sx_kkotnim", "t": "이 탑이 하늘에서 제일 가깝다지만, 꼭대기로 가는 계단이 중간에 무너져 있대. 천문관들도 꼭대기엔 요새 안 올라간다더라."}, {"s": "q:sx_bangul", "t": "날아가면 되지. 나는 도깨비니까."}, {"s": "q:sx_kkotnim", "t": "날 줄 알면 진작 날아서 방망이 찾았겠지."}, {"s": "q:sx_bangul", "t": "……오늘은 날개가 쉬는 날이야."}, {"s": "q:sx_kkotnim", "t": "조사원, 꼭대기로 오를 길을 좀 찾아 주게. 이 녀석 날개가 안 쉬는 날은 내 평생 안 올 테니."}]'::jsonb, '{}'::jsonb)
