insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_5', 2, '반짝이를 좋아하는 것들', '백옥 천문탑을(를) 살핀다', '{"at": ["white_tower"], "tasks": [{"t": "search", "r": ["white_tower"], "n": 2}]}'::jsonb, '[{"s": null, "t": "무너진 계단 옆 벽에 별자리가 새겨진 돌판이 있었고, 그것을 밟고 오르니 꼭대기로 이어지는 좁은 길이 나왔다."}, {"s": null, "t": "꼭대기에 다다르자 방울 등의 방망이가 희미하게 빛났다. 그 빛을 보고 어둠 속에서 날개 소리가 몰려왔다."}, {"s": "q:sx_bangul", "t": "박쥐! 박쥐가 뚝딱이 노려!"}, {"s": "q:sx_bangul", "t": "이번엔 안 숨어. 이번엔 진짜 내가 지킬 거야."}, {"s": null, "t": "방울은 방망이를 꼭 끌어안고 두 눈을 질끈 감은 채 그 자리에 버티고 섰다. 다리가 후들후들 떨렸다."}, {"s": "q:sx_kkotnim", "t": "아이고, 장하다. 눈은 뜨고 버텨라."}, {"s": "q:sx_kkotnim", "t": "조사원, 별빛 박쥐들 좀 쫓아 주게. 저 녀석 다리가 꺾이기 전에."}]'::jsonb, '{"xp": 906}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_5', 3, '생각이 안 나', '별빛 박쥐을(를) 물리친다', '{"at": ["white_tower"], "tasks": [{"t": "win", "m": ["x_white_tower_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "박쥐가 흩어지자 탑 꼭대기에 별빛만 가득 내려앉았다. 방울은 방망이를 높이 들었다가, 천천히 도로 내렸다."}, {"s": "q:sx_kkotnim", "t": "왜 그러냐. 산만 한 금 빈다며."}, {"s": "q:sx_bangul", "t": "……꽃님, 나 할아버지 이름이 생각이 안 나."}, {"s": "q:sx_bangul", "t": "뚝딱이 잃어버린 날부터 그래. 할아버지 얼굴은 생각나는데, 이름을 부르려고 하면 입이 막혀. 할아버지 이름 아는 도깨비는 이제 나밖에 없는데."}, {"s": "q:sx_bangul", "t": "나까지 까먹으면, 할아버지는 이제 아무 데도 없는 거잖아."}, {"s": null, "t": "방울은 이번에도 안 운다는 말을 하지 않았다. 꽃님이 방울을 끌어안았다. 꽃님도 울고 있었다."}, {"s": "q:sx_kkotnim", "t": "이 녀석아, 그걸 왜 이제 말해. 소원은 맑은 정신으로 비는 거다. 이렇게 엉엉 울면서 빌면 방망이도 못 알아들어."}, {"s": "q:sx_kkotnim", "t": "조사원, 청심환 둘만 지어 주게. 하나는 이 녀석, 하나는 나. 나도 지금 정신이 하나도 없어."}]'::jsonb, '{"xp": 906}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_bat_5', 4, '금 나와라 대신', '청심환을(를) 만든다, 청심환을(를) 넘긴다', '{"at": ["white_tower"], "tasks": [{"t": "craft", "items": ["tonic"], "n": 2}], "give": {"tonic": 2}}'::jsonb, '[{"s": null, "t": "청심환을 삼킨 방울은 코를 한 번 훔치고 방망이를 두 손으로 쥐었다. 꽃님과 나는 한 걸음 물러섰다."}, {"s": "q:sx_bangul", "t": "뚝딱아, 금은 됐어. 꽃님이 지붕은 내가 나중에 올려 줄게."}, {"s": "q:sx_bangul", "t": "할아버지 이름, 딱 한 번만 다시 불러 보게 해 줘. 뚝딱!"}, {"s": null, "t": "방망이가 별빛 아래서 한 번 크게 울렸다. 그리고 방울의 입에서 이름 하나가 굴러 나왔다."}, {"s": "q:sx_bangul", "t": "……왕방울. 우리 할아버지 왕방울! 나 방울이는 왕방울 할아버지 이름 따서 지은 거야!"}, {"s": null, "t": "그 순간 탑 꼭대기에 바람이 한 번 불었다. 허허, 하고 웃는 소리 같은 바람이었다. 방망이의 빛은 꺼졌고, 이제는 그냥 쇠테 두른 나무 몽둥이였다."}, {"s": "q:sx_kkotnim", "t": "됐다. 이번엔 잊어버리지 않게 해 두자."}, {"s": null, "t": "꽃님은 품에서 숯 막대를 꺼내 방망이 자루에 또박또박 글씨를 적었다. 「왕방울 할아범. 방울이 할아버지.」"}, {"s": "q:sx_kkotnim", "t": "내 주막 기둥에도 적어 두마. 손님들이 물으면 다 말해 줄 게다. 나는 원래 말이 많으니까."}, {"s": "q:sx_bangul", "t": "꽃님이 까먹으면 내가 불러 줄게. 내가 까먹으면 꽃님이 불러 줘."}, {"s": null, "t": "방울은 빈 방망이를 메고 계단을 내려갔다. 이따금 혼잣말처럼 할아버지 이름을 불렀고, 그때마다 등 뒤로 바람이 한 번씩 따라왔다."}]'::jsonb, '{"xp": 906, "gil": 85, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
