delete from public.world_quest_steps where quest_id = 'sq110_f_south' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_south', 1, '처음 본 바다', '처음 본 바다', '{"at": ["nine_lighthouse"]}'::jsonb, '[{"s": null, "t": "구등대 군도 나루에서 아랑이 불씨 항아리를 끌어안고 앉아 있었다. 얼굴이 하얗게 질려 있었다."}, {"s": "q:r71_arang", "t": "바다가 이렇게 출렁이는 줄 몰랐어요. 배를 타고 오는 내내 속이 뒤집혔어요."}, {"s": "q:r71_arang", "t": "노장 어르신이 고개 봉화를 보시고 그러셨어요. 바다에도 남녘 불이 있어야 한다고요. 아직 배에서 사는 남명 사람들이 밤바다에서 길을 잃지 않게요."}, {"s": null, "t": "곁에서 그물을 손질하던 늙은 뱃사람이 혀를 찼다."}, {"s": "q:sx_pungdeok", "t": "바깥 섬 끝에 옛 남명 등대가 있소. 나라 무너진 뒤로 불이 들어간 적이 없지라."}, {"s": "q:sx_pungdeok", "t": "근데 거기 안개 갈매기가 둥지를 틀었소. 불티만 보면 물어 가는 놈들이오. 항아리 들고 갔다간 불씨 다 뺏기오."}, {"s": "q:r71_arang", "t": "할머니의 할머니가 안고 온 불이에요. 한 톨도 못 줘요. 같이 가 줄래요?"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_south', 2, '소금바람', '안개 갈매기을(를) 물리친다', '{"at": ["nine_lighthouse"], "tasks": [{"t": "win", "m": ["g_nine_lighthouse"], "n": 3}]}'::jsonb, '[{"s": null, "t": "갈매기를 쫓고 등대 꼭대기에 오르자 소금바람이 얼굴을 때렸다. 아랑이 항아리 뚜껑을 열자마자 불씨가 바람에 납작 엎드렸다."}, {"s": "q:r71_arang", "t": "안 돼요, 꺼지겠어요!"}, {"s": "q:sx_pungdeok", "t": "고개 바람하고 바다 바람은 다르오. 바다 바람은 쉬지를 않지라."}, {"s": "q:sx_pungdeok", "t": "옛날엔 등대 둘레에 결계를 쳐서 바람을 막았소. 그 결계가 다 부서져서 이 섬 바위틈에 조각으로 굴러다니오."}, {"s": null, "t": "나는 결계 조각을 모아다 불 둘레에 바람막이를 세우겠다고 했다."}, {"s": "q:r71_arang", "t": "그동안 저는 불씨를 품에 안고 있을게요. 피난 오던 밤에도 다들 그랬대요."}]'::jsonb, '{"xp": 906}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_south', 3, '불은 먹는 걸 가리지 않는다', '결계 파편을(를) 모은다', '{"at": ["nine_lighthouse"], "tasks": [{"t": "gather", "items": ["ward_fragment"], "r": ["nine_lighthouse"], "n": 3}]}'::jsonb, '[{"s": null, "t": "결계 조각으로 둘러친 바람막이 안에서 불씨가 다시 일어섰다. 그러나 불빛은 낮고 붉어서 바다 너머까지 닿지 않았다."}, {"s": "q:sx_pungdeok", "t": "이 불은 고개 불이오. 산에서 사람 손 녹이는 불이지, 바다 건너 보이는 불이 아니오."}, {"s": "q:sx_pungdeok", "t": "바닷불은 어유를 먹여야 하오. 등잔에 어유를 채워서 그 심지에 불씨를 옮기면 멀리 가지라."}, {"s": "q:r71_arang", "t": "물고기 기름이요? 그럼 남녘 불이 아니게 되는 거 아니에요?"}, {"s": "q:sx_pungdeok", "t": "불은 먹는 걸 가리지 않소. 사람도 그렇고. 나도 남녘 쌀 못 먹은 지 쉰 해요. 그래도 남명 사람이지라."}, {"s": null, "t": "아랑은 한참 항아리를 내려다보다가 고개를 끄덕였다. 나에게 어유 등잔 두 개를 지어 달라고 했다."}]'::jsonb, '{"xp": 906}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_south', 4, '바다를 보고 선 불', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["nine_lighthouse"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 2}], "give": {"fish_oil_lamp": 2}}'::jsonb, '[{"s": null, "t": "아랑이 불씨를 어유 등잔 심지에 옮겼다. 붉던 불이 하얗게 피어오르더니 바다 위로 길게 빛을 뻗었다."}, {"s": null, "t": "한참 뒤, 먼 바다에서 작은 불빛 하나가 세 번 깜빡였다."}, {"s": "q:sx_pungdeok", "t": "……남녘 신호요. 「여기 있다」. 저걸 다시 볼 줄은 몰랐소."}, {"s": null, "t": "풍덕은 그물을 내려놓고 고개를 돌렸다. 어깨가 떨리고 있었다."}, {"s": "q:r71_arang", "t": "할머니의 할머니는 바다를 등지고 고개를 넘어왔대요. 이제 이 불은 바다를 보고 서 있네요."}, {"s": "q:r71_arang", "t": "고개에도 불이 있고 바다에도 불이 있으면, 그 사이에서는 아무도 길을 잃지 않겠죠."}, {"s": "q:sx_pungdeok", "t": "등잔 기름은 내가 대겠소. 이 늙은이가 잡는 고기로."}]'::jsonb, '{"xp": 906, "gil": 85, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
