insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_bomi', 1, '구름에 걸린 종이학', '구름에 걸린 종이학', '{"at": ["cloud_corridor"]}'::jsonb, '[{"s": null, "t": "구름 위 회랑의 난간마다 하얀 것이 걸려 있었다. 가까이 가 보니 젖은 종이학이었다. 수백 마리가 구름에 날개가 붙어 꼼짝도 못 하고 있었다."}, {"s": null, "t": "난간 끝에 아이 하나가 걸터앉아 발을 흔들고 있었다. 여덟 해 전 백지교 난간에서 보던 그 얼굴 그대로였다. 키도 한 뼘 자라지 않았다."}, {"s": "q:dh_bomi", "t": "어, 그때 종이 구해 주신 분이다! 저 기억하세요? 보미요."}, {"s": "q:dh_bomi", "t": "천 번째 학이 날아가서 따라왔어요. 다른 학들도 다 같이 따라왔고요. 그런데 여기까지 오니까 구름이 너무 축축해요."}, {"s": null, "t": "나는 그동안 어디 있었느냐고 물었다. 보미는 고개를 갸웃했다."}, {"s": "q:dh_bomi", "t": "음…… 다리에 있었어요. 계속요. 그런데 이상하죠, 아무도 저한테 말을 안 걸었어요. 조사원님만 걸어요."}, {"s": null, "t": "그때 회랑 위로 번쩍이는 날개가 지나갔다. 번개 머금은 학이 난간에 걸린 종이학을 부리로 낚아채 삼켰다."}, {"s": "q:dh_bomi", "t": "안 돼! 쟤네가 제 학을 먹어요. 진짜 학이면서 종이학을 먹는 건 반칙이에요. 세 마리만 쫓아 주세요, 네?"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_bomi', 2, '젖은 날개', '번개 머금은 학을(를) 물리친다', '{"at": ["cloud_corridor"], "tasks": [{"t": "win", "m": ["r71_cloud_4"], "n": 3}]}'::jsonb, '[{"s": null, "t": "번개 학이 흩어지자 보미가 난간을 따라 뛰어다니며 종이학을 하나씩 떼어 냈다. 떼어 낸 학은 날개가 축 처져 있었다."}, {"s": "q:dh_bomi", "t": "다들 감기 걸렸어요. 이러면 못 날아요."}, {"s": "q:dh_bomi", "t": "이 회랑에는 구름이 뭉쳐서 솜이 된 게 있대요. 운면이요. 아까 등불 든 아줌마가 그걸로 등 심지를 싸는 걸 봤어요."}, {"s": null, "t": "나는 그 아주머니가 누구냐고 물었다."}, {"s": "q:dh_bomi", "t": "몰라요. 회랑 끝에서 등을 켜는 아줌마요. 저를 못 봐요. 바로 옆을 지나가도요."}, {"s": "q:dh_bomi", "t": "운면으로 감싸 주면 학이 마를 거예요. 세 뭉치만 걷어 와 주세요. 폭신한 걸로요."}]'::jsonb, '{"xp": 906}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_bomi', 3, '등을 켜는 사람', '운면을(를) 모은다', '{"at": ["cloud_corridor"], "tasks": [{"t": "gather", "items": ["cloud_cotton"], "r": ["cloud_corridor"], "n": 3}]}'::jsonb, '[{"s": null, "t": "운면으로 감싸 주자 종이학들이 하나둘 날개를 폈다. 보미는 손뼉을 치다가 갑자기 손을 멈췄다."}, {"s": "q:dh_bomi", "t": "근데 천 번째 학이 없어요. 제일 예쁘게 접은 거였는데."}, {"s": null, "t": "회랑 끝에서 등불 하나가 다가왔다. 머리가 하얗게 센 아낙이 등에 불을 붙이며 난간을 따라 걸었다."}, {"s": "q:sx_yeonbun", "t": "조사원이신가 봐요. 이 위까지 사람이 오는 일은 드문데요."}, {"s": "q:sx_yeonbun", "t": "요즘 회랑에 종이 소리가 많이 나요. 바스락바스락. 바람 소리는 아닌 것 같아서, 밤마다 등을 하나씩 더 켜고 있어요."}, {"s": null, "t": "보미가 아낙의 치맛자락 바로 옆에 서서 얼굴을 올려다보았다. 아낙은 보미 쪽을 한 번도 보지 않았다."}, {"s": "q:dh_bomi", "t": "……조사원님. 이 아줌마, 우리 엄마 냄새가 나요. 근데 우리 엄마는 머리가 까매요."}, {"s": "q:sx_yeonbun", "t": "혹시 지나다 하얀 종이학 한 마리를 보시면 알려 주세요. 해마다 한 마리씩 이 회랑에 내려앉거든요. 올해 것은 아직 못 찾았어요."}]'::jsonb, '{"xp": 906}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_bomi', 4, '천한 번째', '구름 위 회랑을(를) 살핀다', '{"at": ["cloud_corridor"], "tasks": [{"t": "search", "r": ["cloud_corridor"], "n": 2}]}'::jsonb, '[{"s": null, "t": "천 번째 학은 회랑 맨 끝, 오래된 등 기둥 아래에 앉아 있었다. 기둥에는 종이학 그림이 칼끝으로 잔뜩 새겨져 있었고, 그 옆에 같은 글자가 줄지어 있었다. 「보미야.」"}, {"s": "q:sx_yeonbun", "t": "우리 딸이 백지교를 건너다 길을 잃었어요. 저는 높은 데 올라가면 보일까 해서 여기까지 왔고요. 그게 벌써 여덟 해예요."}, {"s": "q:sx_yeonbun", "t": "이름을 안 부르면 잊힌다잖아요. 그래서 등을 켤 때마다 한 번씩 새겼어요. 그랬더니 해마다 종이학이 한 마리씩 날아와요."}, {"s": "q:dh_bomi", "t": "엄마, 머리가 하얘졌네. 내가 늦게 접어서 그래."}, {"s": null, "t": "나는 아이가 바로 옆에 있다고 말했다. 연분은 한참 숨을 고르더니 고개를 끄덕였다."}, {"s": "q:sx_yeonbun", "t": "알아요. 아는 것 같았어요. 종이 소리가 꼭 걔 웃음소리 같았거든요."}, {"s": null, "t": "보미가 천 번째 학을 두 손으로 들어 연분의 손바닥 위에 올려 두었다. 연분의 눈에는 학이 혼자 날아와 앉은 것처럼 보였을 것이다."}, {"s": "q:dh_bomi", "t": "소원 이뤄졌다. 엄마가 나 찾았어."}, {"s": "q:sx_yeonbun", "t": "……천 번째구나. 그럼 내일부터는 내가 접을게. 천한 번째부터."}, {"s": null, "t": "그날 밤 회랑의 등이 하나 더 켜졌다. 등불 아래에서 아낙이 종이를 접고, 그 옆에서 아이가 접는 법을 하나하나 가르쳐 주고 있었다."}]'::jsonb, '{"xp": 906, "gil": 85, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
