values ('sq110_s_yeonsu', 'side', '전투·천엽 연화늪', '삼십 년 계약의 끝', '연근식귀와 맺은 삼십 년 계약의 마지막 해', 'lotus_marsh', 20, '{sq_lotus_marsh_2}'::text[], null, 1123, '[]'::jsonb, true, null, null)
