delete from public.world_quest_steps where quest_id = 'sq110_s_yeonsu' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeonsu', 1, '돌아온 빚쟁이', '돌아온 빚쟁이', '{"at": ["lotus_marsh"]}'::jsonb, '[{"s": null, "t": "천엽 연화늪의 연밭은 몰라보게 맑아져 있었다. 연잎 사이에서 연수가 허리를 펴고 손을 흔들었다. 볕에 그을린 얼굴이 이제 어엿한 연밭 주인이었다."}, {"s": "q:sn_yeonsu", "t": "조사원님! 그 독두꺼비 쓰러뜨려 주신 뒤로 다섯 해째예요. 흉년도 한 번 있었는데, 정말 아버지랑 같이 굶었어요. 그래도 괜찮았어요."}, {"s": "q:sn_yeonsu", "t": "그런데 지난달에 웬 부적 장수가 찾아왔어요. 아버지한테 삼십 년 전에 부적을 판 사람이래요."}, {"s": "q:sx_galpil", "t": "아, 마침 증인이 오셨구려. 이 계약서 좀 보시오. 연밭지기 봉구, 똑똑히 적혀 있지 않소."}, {"s": "q:sx_galpil", "t": "「흉년 없는 삼십 년을 판다. 값은 삼십 년이 다 찬 해에 거둔다. 못 치르면 연밭과 이 이름을 거둔다.」 다섯 해를 기다려 드렸으니 이자도 쳐야지."}, {"s": "q:sn_bonggu", "t": "……내 글씨가 맞소. 그때는 흉년이 하도 무서워서 읽지도 않고 눌렀지."}, {"s": null, "t": "나는 이름을 거두면 어찌 되느냐고 물었다. 갈필은 대답 대신 웃기만 했다."}, {"s": "q:sn_yeonsu", "t": "이상한 건, 저 사람이 오고 나서부터 연근식귀가 다시 나와요. 다 사라졌던 것들이요. 세 마리만 잡아서 배 속 좀 봐 주세요. 저번처럼 뭐가 나올지도 몰라요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeonsu', 2, '먹물 든 배', '연근식귀을(를) 물리친다', '{"at": ["lotus_marsh"], "tasks": [{"t": "win", "m": ["m_17"], "n": 3}]}'::jsonb, '[{"s": null, "t": "쓰러진 연근식귀의 배 속에는 부적 대신 검은 덩어리가 들어 있었다. 손으로 누르자 먹물이 배어 나왔다. 늪 냄새가 아니라 먹 냄새였다."}, {"s": "q:sn_yeonsu", "t": "이거 독이에요. 그냥 먹이 아니에요. 늪 독이 먹에 섞여서 굳은 거예요."}, {"s": "q:sn_bonggu", "t": "그 부적들도 먹 냄새가 유난했소. 던질 때마다 손끝이 저렸지."}, {"s": "q:sn_yeonsu", "t": "아버지, 그때 독에 쏘이신 게 아니라 부적에 손이 상하셨던 거 아니에요?"}, {"s": null, "t": "나는 연수에게, 독이 정말 부적 먹에서 나왔는지 맞대 볼 수 있느냐고 물었다."}, {"s": "q:sn_yeonsu", "t": "해 볼 수 있어요. 늪 약초밭 덤불에 독성 요괴 독이 굳은 독낭이 걸려요. 늪에서 나온 독낭이랑, 저 사람 계약서 먹을 나란히 녹여 보면 같은 독인지 알 수 있어요."}, {"s": "q:sn_yeonsu", "t": "독낭 세 개만 모아다 주세요. 저 사람이 눈치 못 채게요."}]'::jsonb, '{"xp": 906}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeonsu', 3, '같은 독', '독낭을(를) 모은다', '{"at": ["lotus_marsh"], "tasks": [{"t": "gather", "items": ["venom_gland"], "r": ["lotus_marsh"], "n": 3}]}'::jsonb, '[{"s": null, "t": "연수가 독낭 세 개와 계약서 귀퉁이에서 긁어낸 먹을 각각 다른 그릇에 녹였다. 두 그릇 모두 똑같이 검푸르게 끓어올랐다."}, {"s": "q:sn_yeonsu", "t": "같아요. 부적 먹이 늪을 독하게 만든 거예요. 흉년을 거둔 게 아니라, 흉년이 올까 봐 무섭게 만든 거였어요."}, {"s": "q:sn_bonggu", "t": "그럼 독두꺼비도, 연근식귀도……"}, {"s": "q:sn_yeonsu", "t": "저 사람이 판 먹을 먹고 자란 거예요. 계약서도 같은 먹으로 썼으니, 아버지 이름이 그 먹에 묶여 있는 거고요."}, {"s": null, "t": "나는 그 먹을 풀면 이름도 풀려나느냐고 물었다."}, {"s": "q:sn_yeonsu", "t": "요기 서린 먹은 정화 부적으로 태우면 풀린대요. 이번엔 저 사람 부적 말고, 조사원님이 직접 그린 걸로요. 두 장만 만들어 주세요. 하나는 계약서에, 하나는 늪에 쓸게요."}]'::jsonb, '{"xp": 906}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeonsu', 4, '거둔 값', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["lotus_marsh"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": "q:sx_galpil", "t": "자, 보름이 찼소. 연밭을 내놓든 이름을 내놓든, 둘 중 하나는 받아 가야겠소."}, {"s": null, "t": "연수가 계약서 위에 정화 부적을 얹었다. 부적에 불이 옮겨붙자 글자가 하나씩 떨어져 나왔다. 「연밭지기 봉구」 다섯 글자가 맨 마지막에 떨어져 나와 봉구의 발치에 내려앉았다."}, {"s": "q:sn_bonggu", "t": "……몸이 가볍소. 삼십 년 동안 누가 어깨를 누르고 있었던 것 같구려."}, {"s": null, "t": "떨어져 나온 먹은 그대로 흩어지지 않았다. 검은 연기가 되어 계약서를 쓴 사람에게로 돌아갔다. 갈필의 손끝이 손목까지 검게 물들었다."}, {"s": "q:sx_galpil", "t": "이, 이게 무슨……! 내 손이, 손이 저리오!"}, {"s": "q:sn_yeonsu", "t": "아버지가 삼십 년 동안 저리던 손이에요. 그거 늪에 던진 부적 값이에요. 이자까지요."}, {"s": null, "t": "나머지 한 장은 늪 한가운데에 띄웠다. 부적이 가라앉은 자리부터 물빛이 맑아졌다. 갈필은 저린 손을 끌어안고 늪 바깥으로 달아났다."}, {"s": "q:sn_bonggu", "t": "연수야, 올해 연밥도 네가 따거라."}, {"s": "q:sn_yeonsu", "t": "아니요. 올해는 같이 따요. 아버지 손도 이제 안 저리시잖아요."}]'::jsonb, '{"xp": 906, "gil": 85, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
