insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_sleepy_astronomer', 1, '아흔아홉에서 멈추는 밤', '아흔아홉에서 멈추는 밤', '{"at": ["white_tower"]}'::jsonb, '[{"s": null, "t": "백옥 천문탑 아래에서 앳된 관측생 하나가 두꺼운 성도를 끌어안고 한숨을 쉬고 있었다."}, {"s": "q:sx_soli", "t": "조사원님이세요? 다행이다. 저희 천문관님 좀 깨워 주세요. 아니, 깨어 있게 해 주세요."}, {"s": "q:sx_soli", "t": "천문관님은 밤마다 별을 세세요. 그런데 꼭 아흔아홉에서 잠이 드세요. 하나, 둘, 하다가 아흔아홉, 하고 쿨."}, {"s": "q:sx_jamyeong", "t": "그건 모함이오. 나는 아흔아홉까지 세고 잠시 눈을 쉬는 것뿐이오."}, {"s": "q:sx_soli", "t": "그러고 아침에 일어나세요."}, {"s": "q:sx_jamyeong", "t": "……그러니까 잠시 쉬는 것이오."}, {"s": null, "t": "나는 백 번째 별에 무엇이 있느냐고 물었다."}, {"s": "q:sx_jamyeong", "t": "그걸 아무도 모르오. 스승님도, 스승님의 스승님도 백 번째 별은 못 보셨소. 이번엔 꼭 보고 싶소. 청심환을 먹으면 정신이 맑아진다니, 세 알만 지어 주시오. 한 알은 내 몫, 한 알은 솔이 몫, 한 알은 혹시 몰라서."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_sleepy_astronomer', 2, '별이 아닌 별', '청심환을(를) 만든다, 청심환을(를) 넘긴다', '{"at": ["white_tower"], "tasks": [{"t": "craft", "items": ["tonic"], "n": 3}], "give": {"tonic": 3}}'::jsonb, '[{"s": null, "t": "청심환을 삼킨 자명은 눈을 부릅뜨고 탑 난간에 섰다. 솔이는 그 옆에서 붓을 들었다."}, {"s": "q:sx_jamyeong", "t": "하나, 둘, 셋…… 쉰…… 여든…… 아흔."}, {"s": null, "t": "숫자가 아흔을 넘자 자명의 고개가 앞으로 꾸벅 떨어졌다. 그러다 화들짝 다시 들었다."}, {"s": "q:sx_jamyeong", "t": "안 잤소. 안 잤소. 그런데 별이 왜 이렇게 많아졌소? 방금 셌는데 또 새로 생겼소."}, {"s": "q:sx_soli", "t": "천문관님, 저건 별이 아니에요. 박쥐 눈이에요."}, {"s": null, "t": "탑 지붕 처마마다 별빛을 머금은 박쥐들이 거꾸로 매달려 있었다. 눈을 깜박일 때마다 하늘에 별이 생겼다 없어지는 것처럼 보였다."}, {"s": "q:sx_jamyeong", "t": "그럼 내가 여태 센 아흔아홉 개 중에……"}, {"s": "q:sx_soli", "t": "몇 개는 박쥐였겠죠."}, {"s": "q:sx_jamyeong", "t": "이러니 백까지 갈 수가 없지! 조사원, 저 가짜 별들을 좀 쫓아 주시오. 진짜 하늘만 남게."}]'::jsonb, '{"xp": 906}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_sleepy_astronomer', 3, '남은 한 알', '별빛 박쥐을(를) 물리친다', '{"at": ["white_tower"], "tasks": [{"t": "win", "m": ["x_white_tower_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "박쥐들이 흩어지자 하늘이 한결 맑아졌다. 그런데 돌아와 보니 자명은 혼천의에 기대어 코를 골고 있었다."}, {"s": "q:sx_soli", "t": "박쥐 쫓는 소리가 자장가처럼 들리셨대요."}, {"s": null, "t": "솔이는 남은 청심환 한 알을 꺼내 자명의 입에 밀어 넣었다. 자명은 쓴맛에 펄쩍 뛰며 일어났다."}, {"s": "q:sx_jamyeong", "t": "이건 혹시 몰라서 남긴 것 아니었소!"}, {"s": "q:sx_soli", "t": "지금이 그 혹시예요."}, {"s": "q:sx_jamyeong", "t": "……맞는 말이오. 오늘은 탑 꼭대기, 가장 높은 데서 세겠소. 조사원도 같이 올라가 주시오. 내가 아흔아홉에서 졸면 꼭대기를 둘러보며 백 번째를 대신 찾아 주시오."}]'::jsonb, '{"xp": 906}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_sleepy_astronomer', 4, '백 번째 별', '백옥 천문탑을(를) 살핀다', '{"at": ["white_tower"], "tasks": [{"t": "search", "r": ["white_tower"], "n": 2}]}'::jsonb, '[{"s": null, "t": "탑 꼭대기에서 자명은 다시 별을 셌다. 이번에는 목소리가 또렷했다."}, {"s": "q:sx_jamyeong", "t": "……아흔여덟. 아흔아홉."}, {"s": null, "t": "자명은 숨을 들이켰다. 그리고 하늘을 아무리 둘러봐도 다음 별을 찾지 못했다. 그때 나는 난간 아래 처마 끝에서 무언가 반짝이는 것을 보았다."}, {"s": null, "t": "쫓겨 가지 않은 박쥐 한 마리가 거꾸로 매달린 채 우리를 올려다보고 있었다. 박쥐는 한쪽 눈만 깜박였다."}, {"s": "q:sx_soli", "t": "저거…… 아까 그 박쥐 중 하나예요."}, {"s": "q:sx_jamyeong", "t": "백!"}, {"s": "q:sx_soli", "t": "네? 박쥐인데요?"}, {"s": "q:sx_jamyeong", "t": "하늘에서 반짝이면 별이오. 이름은 깜박이별로 하겠소. 성도에 적으시오, 솔이."}, {"s": null, "t": "솔이가 한숨을 쉬며 성도에 「깜박이별」이라고 적는 동안, 자명은 난간에 기대어 그대로 잠이 들었다. 다 셌으니 이제 자도 된다는 얼굴이었다."}, {"s": "q:sx_soli", "t": "스승님의 스승님도 혹시 박쥐 때문에 못 세신 건 아닐까요."}, {"s": null, "t": "그 뒤로 천문탑 성도에는 밤마다 자리가 조금씩 바뀌는 별이 하나 적혀 있다. 처마 끝에 걸린 깜박이별은 지금도 해 질 녘이면 한쪽 눈을 깜박인다고 했다."}]'::jsonb, '{"xp": 906, "gil": 85, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
