values ('sq110_root_folk', 'side', '전투·지맥의 뿌리', '뿌리 아래 사는 사람들', '이름을 맡긴 광부 가족에게 지맥포식자가 다가온다', 'under_root', 21, '{}'::text[], null, 1125, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_root_folk' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_root_folk', 1, '이름 없는 집', '이름 없는 집', '{"at": ["under_root"]}'::jsonb, '[{"s": null, "t": "지맥의 뿌리 깊은 곳, 굵은 나무뿌리가 천장처럼 얽힌 틈에 작은 움막 하나가 있었다. 문 대신 거적이 걸려 있었다."}, {"s": "q:sx_yeodeol", "t": "정청 사람이오? 돌아가시오. 우리는 부를 사람이 아니오."}, {"s": null, "t": "거적 너머에서 여자아이가 얼굴을 반쯤 내밀었다. 사내가 손짓하자 아이는 얼른 숨었다."}, {"s": "q:sx_yeodeol", "t": "나는 흑련회 굴꾼이오. 여기서는 여덟째라 불리오. 광산 빚을 지면서 이름을 회에 맡겼소. 내 안사람도 그랬소."}, {"s": "q:sx_yeodeol", "t": "이름을 맡긴다는 건 남이 내 이름을 들고 있다는 말이오. 그 이름으로 불려도 나는 대답을 못 하오. 정청 구조대는 이름을 적어야 사람을 찾으니, 우리는 구조대 장부에 들어갈 칸이 없소."}, {"s": null, "t": "나는 왜 이렇게 깊은 곳에 숨어 사느냐고 물었다."}, {"s": "q:sx_yeodeol", "t": "지맥포식자가 다가오고 있소. 뿌리를 먹고 땅을 무너뜨리는 놈이오. 위로 올라가면 빚쟁이가 있고, 여기 있으면 그놈이 있소. 그 앞잡이로 뿌리 지네들이 벌써 움막 근처까지 내려왔소. 돕겠다면 그것들부터 치워 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_root_folk', 2, '아이의 그림', '뿌리 지네을(를) 물리친다', '{"at": ["under_root"], "tasks": [{"t": "win", "m": ["g_under_root"], "n": 4}]}'::jsonb, '[{"s": null, "t": "지네들을 치우고 돌아오자 아이가 거적 밖에 나와 앉아 있었다. 아이는 숯 조각으로 뿌리 벽에 무언가를 그리고 있었다."}, {"s": "q:sx_darae", "t": "이거 엄마예요."}, {"s": null, "t": "벽에는 사람 셋이 손을 잡고 서 있었다. 가운데가 아이였고, 오른쪽 사람에게는 얼굴이 그려져 있지 않았다."}, {"s": "q:sx_darae", "t": "엄마 얼굴은 생각이 안 나요. 엄마는 작년에 뿌리 밑으로 일하러 갔다가 안 왔어요. 아빠가 엄마를 불러 보래서 불렀는데, 엄마 이름은 회에 맡겨 놔서 불러도 소용없대요."}, {"s": "q:sx_yeodeol", "t": "……다래야, 들어가 있거라."}, {"s": null, "t": "아이가 움막으로 들어가자 사내는 오래 말이 없었다. 그러다 땅바닥을 보며 입을 열었다."}, {"s": "q:sx_yeodeol", "t": "지맥포식자를 상대하려면 뿌리를 다시 굳혀야 하오. 놈이 파먹은 자리에 응축 영핵을 박으면 땅이 버틴다 들었소. 이 아래 지맥 줄기에서 두 알만 캐다 주시오. 내가 캐러 가면 저 아이 혼자 남소."}]'::jsonb, '{"xp": 985}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_root_folk', 3, '땅 밑의 숨소리', '응축 영핵을(를) 모은다', '{"at": ["under_root"], "tasks": [{"t": "gather", "items": ["spirit_core"], "r": ["under_root"], "n": 2}]}'::jsonb, '[{"s": null, "t": "응축 영핵을 무너진 뿌리 틈에 박아 넣자 흔들리던 천장이 조금 잠잠해졌다."}, {"s": null, "t": "그러나 곧 발밑 깊은 데서 숨소리 같은 울림이 올라왔다. 뿌리들이 한꺼번에 떨었고, 벽에 그린 아이의 그림 위로 흙이 쏟아졌다."}, {"s": "q:sx_darae", "t": "아빠, 엄마 그림이……"}, {"s": "q:sx_yeodeol", "t": "놈이 왔소. 굳힌 땅을 알아채고 그쪽부터 먹으러 온 거요."}, {"s": null, "t": "여덟째는 곡괭이를 쥐고 아이 앞을 막아섰다. 손이 떨리고 있었다."}, {"s": "q:sx_yeodeol", "t": "나는 회에 이름을 맡긴 몸이라, 여기서 죽으면 영으로 남을지도 모르겠소. 그런데 이 아이는 어떻게 되는 거요. 조사원, 부탁하오. 놈을 막아 주시오."}]'::jsonb, '{"xp": 985}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_root_folk', 4, '맡기지 않은 이름 하나', '지맥포식자을(를) 물리친다', '{"at": ["under_root"], "tasks": [{"t": "win", "m": ["m_26"], "n": 1}]}'::jsonb, '[{"s": null, "t": "지맥포식자가 쓰러지자 땅속 숨소리도 멎었다. 무너진 뿌리 사이로 처음 보는 맑은 바람이 한 줄기 들어왔다."}, {"s": "q:sx_yeodeol", "t": "……끝났소?"}, {"s": null, "t": "나는 고개를 끄덕였다. 여덟째는 곡괭이를 내려놓고 털썩 주저앉았다."}, {"s": "q:sx_yeodeol", "t": "고맙소. 갚을 것이 없소. 이름도 없는 놈이 무엇으로 갚겠소."}, {"s": null, "t": "사내는 잠시 망설이다가 품에서 접은 종이 한 장을 꺼냈다. 종이에는 서툰 글씨로 두 글자가 적혀 있었다."}, {"s": "q:sx_yeodeol", "t": "이 아이 이름은 회에 맡기지 않았소. 안사람이 그건 안 된다고 했소. 빚을 다 갚지 못해도 이것 하나는 우리 것으로 두자고."}, {"s": "q:sx_yeodeol", "t": "그런데 이 굴 밑에서는 이 이름을 불러 줄 사람이 우리 둘뿐이오. 바깥사람이 한 번만 불러 주시오. 그러면 이 아이 이름은 위에도 하나 남는 거니까."}, {"s": null, "t": "나는 아이 이름을 불렀다. 다래가 움막에서 나와 나를 올려다보았다. 그리고 대답했다."}, {"s": "q:sx_darae", "t": "네."}, {"s": null, "t": "여덟째는 그 대답을 듣고 고개를 돌렸다. 뿌리 벽의 그림에서 흙을 털어 내니, 얼굴 없는 사람의 손은 여전히 아이의 손을 잡고 있었다."}, {"s": "q:sx_darae", "t": "엄마는 이름이 없어도 내 이름은 알 거예요. 엄마가 지어 줬으니까요."}]'::jsonb, '{"xp": 985, "gil": 89, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
