insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_cheongun', 1, '둘째 마디', '둘째 마디', '{"at": ["red_forest"]}'::jsonb, '[{"s": null, "t": "혈엽림 어귀에서 누군가 노래를 부르고 있었다. 목이 다 쉰 소리였다. 가까이 가 보니 도끼를 멘 사내가 붉은 잎을 헤치며 걷고 있었다."}, {"s": "q:dh_cheongun", "t": "아, 귀죽림에서 독사녀를 쓰러뜨려 주신 분이죠? 저 청운이에요. 그새 열 해가 지났네요."}, {"s": "q:dh_cheongun", "t": "그날부터 숲마다 다니면서 누이 노래를 불렀어요. 길 잃은 사람이 듣고 따라 나오라고요. 그렇게 나온 사람이 꽤 돼요."}, {"s": "q:dh_cheongun", "t": "그런데 지난달에 이 숲에서 나온 아이가 그 노래를 흥얼거렸어요. 제가 부르는 것보다 한 마디가 더 있었어요."}, {"s": null, "t": "나는 그 한 마디가 무엇이 이상하냐고 물었다."}, {"s": "q:dh_cheongun", "t": "그건 누이가 지어서 혼자만 부르던 둘째 마디예요. 가르쳐 준다고 해 놓고 안 돌아왔으니까, 저는 끝내 못 배웠어요."}, {"s": "q:dh_cheongun", "t": "아이 말로는 단풍이 제일 짙은 고목에서 소리가 났대요. 그런데 그 고목에 단풍 독거미가 거미줄을 쳤어요."}, {"s": "q:dh_cheongun", "t": "또 흉내 내는 요괴일지도 몰라요. 알아요. 그래도 확인은 해야겠어요. 저 거미 좀 걷어 내 주세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_cheongun', 2, '갈라진 껍질', '단풍 독거미을(를) 물리친다', '{"at": ["red_forest"], "tasks": [{"t": "win", "m": ["regional_red_forest_guardian"], "n": 1}]}'::jsonb, '[{"s": null, "t": "독거미가 쓰러지고 거미줄이 걷히자 고목이 드러났다. 껍질이 여기저기 갈라져 있었고, 갈라진 틈에서 바람 같은 소리가 새어 나왔다."}, {"s": null, "t": "바람이 아니었다. 노래였다. 청운이 부르던 첫 마디가 지나가고, 처음 듣는 둘째 마디가 이어졌다."}, {"s": "q:dh_cheongun", "t": "……."}, {"s": "q:dh_cheongun", "t": "거미가 쓰러졌는데도 노래가 안 끊겨요. 그럼 흉내가 아닌 거죠? 그렇죠?"}, {"s": "q:sx_cheonga", "t": "청운아. 목이 왜 그렇게 쉬었니."}, {"s": null, "t": "청운은 도끼를 떨어뜨렸다. 줍지도 못하고 고목에 이마를 댔다."}, {"s": "q:sx_cheonga", "t": "네가 숲마다 내 노래를 부르니까 나도 따라다녔어. 숲이 그 노래를 배우더라. 여기가 제일 잘 배워서 여기 있었어."}, {"s": "q:sx_cheonga", "t": "그런데 붉은 잎 요기가 나무를 자꾸 갈라. 틈이 벌어지면 내 소리가 새 나가서 흩어져."}, {"s": "q:dh_cheongun", "t": "껍질을 덧대면 돼요. 나무꾼이 그것도 모를까 봐요. 조사원님, 이 숲에서 영맥 수피 세 장만 벗겨다 주세요. 쓰러진 고목에서요. 산 나무는 다치지 않게요."}]'::jsonb, '{"xp": 985}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_cheongun', 3, '쉰 목', '영맥 수피을(를) 모은다', '{"at": ["red_forest"], "tasks": [{"t": "gather", "items": ["spirit_bark"], "r": ["red_forest"], "n": 3}]}'::jsonb, '[{"s": null, "t": "청운이 영맥 수피를 고목의 갈라진 자리에 대고 칡으로 단단히 묶었다. 틈이 메워지자 노랫소리가 훨씬 또렷해졌다."}, {"s": "q:sx_cheonga", "t": "이제 좀 살겠다. 숨이 덜 새."}, {"s": "q:dh_cheongun", "t": "누이. 둘째 마디 가르쳐 줘요. 이번엔 꼭요."}, {"s": "q:sx_cheonga", "t": "그 전에 너부터 쉬어. 열 해 동안 목을 그렇게 쓰고. 밤에 잠은 자니?"}, {"s": null, "t": "청운은 대답하지 못했다. 나는 그가 밤마다 숲가에서 잠들지 못하고 노래만 불렀으리라 짐작했다."}, {"s": "q:sx_cheonga", "t": "조사원, 우리 청운이 좀 재워 줘. 이 애 마음이 너무 오래 서 있었어. 흔들린 마음 가라앉히는 탕약이 있지? 그걸로 두 그릇만."}, {"s": "q:dh_cheongun", "t": "저 괜찮아요."}, {"s": "q:sx_cheonga", "t": "안 괜찮아. 누나 말 들어."}]'::jsonb, '{"xp": 985}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_cheongun', 4, '함께 부르는 노래', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["red_forest"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 2}], "give": {"calm_brew": 2}}'::jsonb, '[{"s": null, "t": "청운은 안신탕 한 그릇을 비우고 고목 뿌리에 기대앉았다. 다른 한 그릇은 고목 아래 부어 주었다. 누이 몫이라고 했다."}, {"s": null, "t": "고목에서 노래가 흘러나왔다. 둘째 마디였다. 「붉은 잎 따라 깊이 오지 마라. 물소리 따라 아래로 가라. 거기 내 동생이 기다린다.」"}, {"s": "q:dh_cheongun", "t": "……저였네요. 둘째 마디에 나오는 동생이."}, {"s": "q:sx_cheonga", "t": "그날 너 기다릴까 봐 서둘러 내려가다가 길을 잘못 들었어. 그러니까 네 탓 아니야."}, {"s": null, "t": "청운은 고개를 무릎에 묻고 한참을 울다가 그대로 잠들었다. 고목은 그가 깰 때까지 같은 노래를 낮게 불렀다."}, {"s": "q:dh_cheongun", "t": "이제 이 숲에 살래요. 제가 첫 마디를 부르면 누이가 둘째 마디를 부르고요. 그러면 길 잃은 사람이 두 배로 잘 들을 거예요."}, {"s": "q:sx_cheonga", "t": "대신 하루에 한 번만 불러. 목 아끼고."}, {"s": "q:dh_cheongun", "t": "두 번요."}, {"s": "q:sx_cheonga", "t": "……고집은."}, {"s": null, "t": "숲을 나서는 길에 등 뒤에서 두 목소리가 번갈아 노래했다. 하나는 쉬었고, 하나는 맑았다. 붉은 잎이 그 소리를 따라 흔들렸다."}]'::jsonb, '{"xp": 985, "gil": 89, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
