insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_dalgu', 1, '갚으러 온 사람', '갚으러 온 사람', '{"at": ["comet_crater"]}'::jsonb, '[{"s": null, "t": "혜성 낙하지 한복판에 수레 몇 대가 뒤집혀 있었다. 그 옆에서 수염이 희끗한 사내가 활을 끌어안고 하늘을 노려보고 있었다."}, {"s": "q:rn_dalgu", "t": "이보시오, 야행국 양반! 백골 장터에서 화살 깎아 주던 그 양반 맞지? 열네 해 만이구먼. 내가 그 빚 갚으러 왔소."}, {"s": null, "t": "나는 어떻게 알고 여기까지 찾아왔느냐고 물었다."}, {"s": "q:rn_dalgu", "t": "야행국 조사원이 낙하지에 있다는 소리를 듣고 상단 길을 이리로 틀었지. 갚을 건 갚아야 하니까."}, {"s": "q:sx_malsun", "t": "그래서 이 화상 때문에 지름길 놔두고 혜성 구덩이로 들어왔다가 수레가 이 꼴이 됐지."}, {"s": "q:rn_dalgu", "t": "그건 매 탓이오, 행수. 하늘 깃 매가 짐을 채 갔단 말이오."}, {"s": "q:sx_malsun", "t": "매가 짐을 채 가는 동안 호위는 뭘 했는데?"}, {"s": "q:rn_dalgu", "t": "……화살이 떨어졌소."}, {"s": "q:rn_dalgu", "t": "아무튼 저 매들부터 좀 쫓아 주시오. 갚으러 와서 부탁부터 하니 면목이 없구먼."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_dalgu', 2, '흩어진 봇짐', '하늘 깃 매을(를) 물리친다', '{"at": ["comet_crater"], "tasks": [{"t": "win", "m": ["r71_comet_3"], "n": 3}]}'::jsonb, '[{"s": null, "t": "매가 흩어지자 하늘빛 깃털이 눈처럼 내려앉았다. 매가 채 간 봇짐들이 구덩이 곳곳에 떨어져 있었다."}, {"s": "q:rn_dalgu", "t": "하하, 역시 야행국 양반이구먼! 이제 빚 얘기를 합시다."}, {"s": "q:rn_dalgu", "t": "그때 화살 세 대를 깎아 줬지. 그래서 나도 화살로 갚을 생각이오. 그런데 보통 화살은 성에 안 차고, 하늘 깃 매 깃털로 깃을 달아야겠소."}, {"s": "q:sx_malsun", "t": "깃털은 매를 쫓은 사람이 주웠는데, 그걸로 그 사람한테 갚겠다고? 이 화상 셈법 좀 봐."}, {"s": "q:rn_dalgu", "t": "깃을 다는 건 내 솜씨요, 행수!"}, {"s": null, "t": "나는 웃음을 참으며 깃털을 어디서 모으면 되느냐고 물었다."}, {"s": "q:rn_dalgu", "t": "흩어진 봇짐이랑 짐 꾸러미 사이에 매 깃이 박혀 있을 거요. 천공 깃털로 세 개만 골라 주시오. 곧고 하늘빛이 짙은 걸로."}]'::jsonb, '{"xp": 985}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_dalgu', 3, '또 생긴 빚', '천공 깃털을(를) 모은다', '{"at": ["comet_crater"], "tasks": [{"t": "gather", "items": ["sky_feather"], "r": ["comet_crater"], "n": 3}]}'::jsonb, '[{"s": null, "t": "달구는 깃털을 받아 들자 수레 바퀴에 걸터앉아 화살대를 다듬기 시작했다. 술을 좋아하던 손이라고는 믿기지 않을 만큼 손끝이 꼼꼼했다."}, {"s": "q:rn_dalgu", "t": "그날 이후로 화살은 내가 직접 깎소. 남한테 빌리면 또 갚아야 하니까."}, {"s": "q:sx_malsun", "t": "그 말을 열네 해 동안 했지. 그래 놓고 지금 우리 건량이 하나도 안 남은 건 알지?"}, {"s": "q:rn_dalgu", "t": "그것도 매 탓이오."}, {"s": "q:sx_malsun", "t": "매가 건량 자루를 채 갈 때도 화살이 없었지?"}, {"s": "q:rn_dalgu", "t": "……."}, {"s": "q:rn_dalgu", "t": "야행국 양반, 미안하오. 돌아가는 길이 사흘인데 먹을 게 없소. 노정 건량 세 봉지만 만들어 주시겠소? 이건 새 빚으로 달아 두고."}, {"s": "q:sx_malsun", "t": "갚으러 와서 빚을 하나 더 지는 사람은 내 평생 처음 본다."}]'::jsonb, '{"xp": 985}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_dalgu', 4, '열네 해 묵은 술', '노정 건량을(를) 만든다, 노정 건량을(를) 넘긴다', '{"at": ["comet_crater"], "tasks": [{"t": "craft", "items": ["travel_ration"], "n": 3}], "give": {"travel_ration": 3}}'::jsonb, '[{"s": null, "t": "건량을 받아 든 달구가 수레 밑에서 작은 술독 하나를 꺼냈다. 뚜껑에 「야행국 양반 몫」이라고 삐뚤빼뚤 적혀 있었다. 봉한 끈은 한 번도 풀린 적이 없었다."}, {"s": "q:rn_dalgu", "t": "그때 술값으로 갚겠다고 했다가 혼날 뻔했지. 그래서 이번엔 진짜 술값을 모았소. 이 독 하나 채울 만큼."}, {"s": "q:sx_malsun", "t": "이 화상이 열네 해 동안 이 독을 끌고 다니면서 한 번을 안 따더라. 상단 사람들이 다 알아."}, {"s": "q:rn_dalgu", "t": "그리고 이건 화살이오. 세 대 받았으니 세 대. 이자로 깃은 하늘 깃 매 걸로."}, {"s": null, "t": "{직업:월궁=나는 화살 하나를 시위에 걸어 보았다. 하늘빛 깃이 바람을 먼저 읽었다/*=나는 화살을 받아 들었다. 활을 쏘지 않아도 깃이 곱다는 것은 알 수 있었다}."}, {"s": null, "t": "나는 술독과 화살을 받고, 건량 값은 어떻게 할 거냐고 물었다."}, {"s": "q:rn_dalgu", "t": "하하, 그건 다음에 갚겠소. 그래야 또 야행국 양반을 만나지 않겠소."}, {"s": "q:sx_malsun", "t": "내 그럴 줄 알았다."}, {"s": null, "t": "상단이 낙하지를 빠져나가는 동안 달구의 노랫소리가 한참 들렸다. 술은 한 모금도 마시지 않았는데 꼭 취한 사람 같은 가락이었다."}]'::jsonb, '{"xp": 985, "gil": 89, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
