insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_maenggu', 1, '더 깊은 데서', '더 깊은 데서', '{"at": ["under_root"]}'::jsonb, '[{"s": null, "t": "지맥의 뿌리 어귀에서 맹구가 곡괭이를 짚고 서 있었다. 주혈 광산에서 열한 몫을 나눈 지 세 해가 지났는데, 손은 그때보다 더 떨렸다."}, {"s": "q:sn_maenggu", "t": "조사원. 또 당신을 부를 줄은 몰랐소."}, {"s": "q:sn_maenggu", "t": "막장은 조용해졌소. 그런데 요즘 잠을 자면 땅 밑에서 누가 내 이름을 부르오. 「맹구야」 하고."}, {"s": "q:sn_maenggu", "t": "주혈 광산 밑으로 지맥이 뻗어 있소. 그 뿌리 끝이 여기요. 소리가 여기서 올라오는 것 같소."}, {"s": null, "t": "나는 그 목소리가 누구 목소리 같으냐고 물었다."}, {"s": "q:sn_maenggu", "t": "……그날 내 등 뒤에서 부르던 목소리요. 부반장 돌개."}, {"s": null, "t": "뿌리 틈 사이로 무언가 사각사각 기어 오르는 소리가 났다."}, {"s": "q:sn_maenggu", "t": "안쪽으로 가는 길에 뿌리 지네가 들끓소. 그날처럼 길부터 터 주시오. 이번에는 내가 뒤에서 도망가지 않겠소."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_maenggu', 2, '이름을 흉내 내는 소리', '뿌리 지네을(를) 물리친다', '{"at": ["under_root"], "tasks": [{"t": "win", "m": ["g_under_root"], "n": 4}]}'::jsonb, '[{"s": null, "t": "지네를 걷어 내고 뿌리 안쪽으로 들어가자, 어둠 저편에서 정말로 목소리가 들렸다."}, {"s": null, "t": "「맹구야.」 이어서 다른 쪽에서도 들렸다. 「맹구야.」 「맹구야.」 목소리가 사방에서 하나씩 늘어났다."}, {"s": "q:sn_maenggu", "t": "돌개 목소리가…… 왜 이렇게 많소."}, {"s": null, "t": "나는 맹구의 어깨를 붙잡았다. 목소리가 부르는 쪽마다 뿌리가 꿈틀거렸다. 무언가 땅 밑에서 이름을 미끼로 쓰고 있었다."}, {"s": "q:sn_maenggu", "t": "돌아보면 끌려가는 거요? 그날 안 돌아본 게 잘한 일이었소?"}, {"s": null, "t": "나는 대답하지 못했다. 바위 벽에는 손톱으로 긁은 글자가 여럿 남아 있었다. 다 이름이었는데, 하나같이 반쯤 갉혀 나가 있었다."}, {"s": "q:sn_maenggu", "t": "우리 조 이름이오. 소이가 노래로 부르던 이름들. 저것까지 먹히면 노래도 끊기겠소."}, {"s": "q:sn_maenggu", "t": "뿌리 밑 돌틈에 먹정이 맺힌다 하오. 그걸로 이름을 다시 진하게 적어 두겠소. 세 덩이만 구해 주시오."}]'::jsonb, '{"xp": 985}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_maenggu', 3, '먹으로 적은 열한 줄', '먹정을(를) 모은다', '{"at": ["under_root"], "tasks": [{"t": "gather", "items": ["inkstone"], "r": ["under_root"], "n": 3}]}'::jsonb, '[{"s": null, "t": "맹구는 먹정을 갈아 손가락으로 벽에 이름을 적었다. 열한 줄이었다. 글씨는 여전히 삐뚤었지만 손은 떨리지 않았다."}, {"s": null, "t": "마지막 줄을 적자 사방의 목소리가 뚝 그쳤다. 그리고 발밑 깊은 곳에서 무언가 땅을 씹는 소리가 났다."}, {"s": "q:sn_maenggu", "t": "그날 막장이 흔들릴 때도 저 소리가 났소. 광맥왕 짓인 줄 알았는데…… 더 밑에 뭐가 있었구먼."}, {"s": null, "t": "뿌리 사이 바닥이 둥글게 꺼지며 거대한 아가리가 드러났다. 지맥을 씹어 먹는 짐승이었다. 그 입 안에서 아까의 목소리들이 웅얼웅얼 새어 나왔다."}, {"s": "q:sn_maenggu", "t": "저놈이 이름을 삼켜 놓고 흉내를 낸 거요. 돌개 목소리로 사람을 끌어내리려고."}, {"s": "q:sn_maenggu", "t": "이번엔 돌아보겠소. 저놈을 쓰러뜨려 주시오. 그 안에 돌개가 아직 남아 있다면 내가 대답해야 하오."}]'::jsonb, '{"xp": 985}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_maenggu', 4, '그날 부른 말', '지맥포식자을(를) 물리친다', '{"at": ["under_root"], "tasks": [{"t": "win", "m": ["m_26"], "n": 1}]}'::jsonb, '[{"s": null, "t": "지맥포식자가 쓰러지자 땅을 씹던 소리가 멎었다. 무너진 아가리 속에서 흐릿한 목소리 하나가 천천히 떠올랐다. 이번에는 하나뿐이었다."}, {"s": "q:sx_dolgae", "t": "맹구야. 뛰어. 돌아보지 말고 뛰어."}, {"s": null, "t": "맹구가 그 자리에 무릎을 꿇었다. 목소리는 몇 번이고 같은 말만 했다. 그날 막장에서 하던 말이었다."}, {"s": "q:sn_maenggu", "t": "……살려 달라는 소리인 줄 알았소. 아홉 해를 그렇게 알았소."}, {"s": "q:sn_maenggu", "t": "뛰라는 소리였구먼. 나만이라도 나가라는."}, {"s": null, "t": "맹구는 처음으로 뒤를 돌아보았다. 그리고 어둠을 향해 대답했다."}, {"s": "q:sn_maenggu", "t": "그래, 나 나왔다, 돌개야. 네 이름은 벽에 적어 놨다. 노래에도 있다."}, {"s": null, "t": "목소리는 더 들리지 않았다. 벽에 적힌 열한 줄 가운데 맨 윗줄만 먹이 마르지 않은 것처럼 오래 반짝였다."}]'::jsonb, '{"xp": 985, "gil": 89, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
