delete from public.world_quest_steps where quest_id = 'sq110_f_lotus' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_lotus', 1, '빠져나가는 기억', '빠져나가는 기억', '{"at": ["under_root"]}'::jsonb, '[{"s": null, "t": "갱 입구에서 반석이 등잔 심지를 돋우고 있었다. 나를 보고도 한참 이름을 떠올리지 못하는 눈치였다."}, {"s": "q:bl_banseok", "t": "아, 그 조사원. 미안하오. 요즘 이렇소."}, {"s": "q:bl_banseok", "t": "반석은 회에서 받은 호칭이오. 내 이름은 회원 장부에 맡겨 두었지. 흑련회 사람은 다 그렇소."}, {"s": "q:bl_banseok", "t": "맡긴 이름에도 이자가 붙소. 해마다 기억 하나씩을 장부에 얹어 내는 거요. 올해 치는 봄에 이미 냈소."}, {"s": "q:bl_banseok", "t": "그런데 달마다 더 빠져나가오. 지난달엔 어머니가 입던 치마 빛깔이 사라졌소. 서른 해를 기억하던 빛깔이오."}, {"s": null, "t": "나는 장부 쪽에서 이자를 더 떼는 것이냐고 물었다."}, {"s": "q:bl_banseok", "t": "회를 의심하고 싶지는 않소. 하나 짚이는 게 있소. 갱 안에서 뿌리 덩굴손에 발목을 잡힌 날마다 하나씩 빠졌소."}, {"s": "q:bl_banseok", "t": "덩굴손 몇 가닥만 끊어 주시오. 끊긴 데서 무엇이 나오는지 보고 싶소."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_lotus', 2, '덩굴손 속의 콧노래', '뿌리 덩굴손을(를) 물리친다', '{"at": ["under_root"], "tasks": [{"t": "win", "m": ["x_under_root_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "끊긴 덩굴손 끝에서 묽은 진이 흘렀다. 손을 대자 귓가에 여자의 콧노래가 아주 작게 들렸다."}, {"s": null, "t": "내가 들은 가락을 흥얼거리자 반석의 얼굴이 굳었다."}, {"s": "q:bl_banseok", "t": "……그건 우리 어머니가 빨래하며 부르던 노래요. 그걸 어떻게 아오."}, {"s": "q:bl_banseok", "t": "뿌리가 기운만 마시는 게 아니었소. 사람의 기억까지 마셨던 거요."}, {"s": null, "t": "나는 왜 흑련회 사람들만 기억을 잃느냐고 물었다."}, {"s": "q:bl_banseok", "t": "이름이 몸에 없으니 명줄 끝이 헐겁소. 헐거운 끝은 잡아당기기 쉽겠지."}, {"s": "q:bl_banseok", "t": "지난번에 영핵이 뿌리의 심장 소리를 기억한다고 했지요. 마신 것들이 모이는 곳도 영핵일 거요."}, {"s": "q:bl_banseok", "t": "응축 영핵을 두 덩이만 캐다 주시오. 그 안에 내 것이 들었는지 들어 봐야겠소."}]'::jsonb, '{"xp": 1067}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_lotus', 3, '장부는 거짓말을 안 한다', '응축 영핵을(를) 모은다', '{"at": ["under_root"], "tasks": [{"t": "gather", "items": ["spirit_core"], "r": ["under_root"], "n": 2}]}'::jsonb, '[{"s": null, "t": "영핵을 귀에 대자 여러 사람의 소리가 겹쳐 들렸다. 웃음소리, 망치 소리, 이름 없는 아이를 어르는 소리."}, {"s": null, "t": "그때 갱도 안쪽에서 주판알 튕기는 소리가 났다. 장부를 품에 안은 여인이 걸어 나왔다."}, {"s": "black_lotus:guseul", "t": "딱, 딱, 딱. 감독님, 장부를 의심하셨다면서요. 들고 왔어요."}, {"s": "black_lotus:guseul", "t": "감독님 줄 올해 이자. 「처음 갱에 들어간 날 아침」. 받은 건 그거 하나예요. 받은 건 다 적어요. 장부에 없는 건 안 받아요."}, {"s": "q:bl_banseok", "t": "그럼 치마 빛깔은."}, {"s": "black_lotus:guseul", "t": "우리 장부엔 없네요. 뿌리가 훔쳐 간 거죠."}, {"s": null, "t": "나는 흑련회가 왜 이자를 기억으로 받느냐고 물었다."}, {"s": "black_lotus:guseul", "t": "먹으로 적은 글자만으로는 이름이 오래 못 버텨요. 그 사람이 누구였는지 곁에 얹어 둬야 글자가 사람으로 남거든요. 이름을 되찾아 가면 이자도 한꺼번에 돌려드려요."}, {"s": "black_lotus:guseul", "t": "영핵에 든 걸 꺼내려면 머리가 맑아야 해요. 청심환 두 알이면 되겠네요."}]'::jsonb, '{"xp": 1067}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_lotus', 4, '이자 없음', '청심환을(를) 만든다, 청심환을(를) 넘긴다', '{"at": ["under_root"], "tasks": [{"t": "craft", "items": ["tonic"], "n": 2}], "give": {"tonic": 2}}'::jsonb, '[{"s": null, "t": "반석은 청심환을 삼키고 영핵을 두 손으로 감쌌다. 한참 눈을 감고 있다가 낮게 말했다."}, {"s": "q:bl_banseok", "t": "쪽빛이었소. 빨아서 널면 바람에 하늘처럼 펄럭이던."}, {"s": "black_lotus:guseul", "t": "딱. 「되찾음. 이자 없음.」 이건 회 몫이 아니니까요."}, {"s": null, "t": "나는 반석에게 이참에 이름도 되찾지 않겠느냐고 물었다."}, {"s": "q:bl_banseok", "t": "이름은 장부에 두겠소. 갚을 게 아직 남았소. 하지만 오늘 되찾은 이 빛깔은 내 것이오."}, {"s": "q:bl_banseok", "t": "구슬, 회원들한테 일러 주시오. 갱에 들 때는 발목을 감싸고, 서로 호칭이라도 한 번씩 불러 주라고."}, {"s": "black_lotus:guseul", "t": "적어 둘게요. 그런데 뿌리가 마신 건 다 어디로 가는 걸까요."}, {"s": null, "t": "반석은 대답 대신 갱 바닥에 귀를 댔다. 아주 깊은 곳에서 무언가가 느리게 한 번 숨을 쉬었다."}]'::jsonb, '{"xp": 1067, "gil": 93, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
