insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_false_oracle', 1, '달의 말씀', '달의 말씀', '{"at": ["crimson_altar"]}'::jsonb, '[{"s": null, "t": "적월 제단터 붉은 돌계단 위에서 사제 하나가 두 팔을 벌리고 있었다. 계단 아래에는 마을 사람들이 쌀자루와 피륙을 내려놓고 엎드려 있었다."}, {"s": "q:sx_gudam", "t": "달께서 말씀하셨소! 이번 그믐까지 공물이 모자라면 마을에 붉은 비가 내릴 것이라고!"}, {"s": null, "t": "공물 자루를 내려놓던 아낙 하나가 나를 보고 다가왔다. 등에는 아직 내려놓지 못한 쌀자루가 하나 더 있었다."}, {"s": "q:sx_jeomrye", "t": "조사원님, 저 신탁이 진짜일까요? 벌써 석 달째 쌀을 바쳤어요. 이건 우리 아들 돌잔치에 쓰려고 모아 둔 쌀이에요."}, {"s": null, "t": "나는 신탁을 어디서 받느냐고 물었다."}, {"s": "q:sx_jeomrye", "t": "사제님이 밤마다 제단 뒤 동굴에 들어가서 듣고 나오신대요. 그런데 아무도 따라 들어가 본 사람이 없어요."}, {"s": "q:sx_jeomrye", "t": "혹시 짬이 나시면 제단 둘레를 좀 살펴봐 주세요. 진짜 달의 말씀이면 저도 군말 없이 바칠게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_false_oracle', 2, '동굴 안의 공물', '적월 제단터을(를) 살핀다', '{"at": ["crimson_altar"], "tasks": [{"t": "search", "r": ["crimson_altar"], "n": 3}]}'::jsonb, '[{"s": null, "t": "제단 뒤 동굴 안에는 신탁 대신 쌀자루가 천장까지 쌓여 있었다. 구석에는 먹다 남은 닭 뼈와 술병이 굴러다녔다."}, {"s": null, "t": "동굴 벽에는 옛 적월교 사제들이 새긴 신탁 글귀가 있었다. 구담이 밤마다 외치던 말이 그 글귀와 한 자도 다르지 않았다."}, {"s": "q:sx_gudam", "t": "아니, 거기서 뭘 하시오! 그 안은 신성한 곳이오!"}, {"s": null, "t": "구담이 헐레벌떡 뛰어들어 오다 멈칫했다. 동굴 입구로 하얀 형체들이 줄지어 들어오고 있었다. 형체들은 모두 손목이 붉은 끈으로 묶여 있었다."}, {"s": "q:sx_gudam", "t": "저, 저건 뭐요? 나는 아무것도 안 불렀소!"}, {"s": null, "t": "형체들은 대답 없이 구담만을 바라보았다. 옛날 이 제단에서 바쳐진 제물들이었다. 누군가 그 신탁 글귀를 다시 소리 내어 읽었기 때문에 깨어난 것 같았다."}, {"s": "q:sx_gudam", "t": "살려 주시오! 공물은 반, 아니 다 돌려주겠소! 저것들 좀 막아 주시오!"}]'::jsonb, '{"xp": 1067}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_false_oracle', 3, '진짜 사제', '제물 원령을(를) 물리친다', '{"at": ["crimson_altar"], "tasks": [{"t": "win", "m": ["r71_altar_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "원령들이 흩어지자 구담은 쌀자루 사이에 주저앉아 숨을 몰아쉬었다."}, {"s": "q:sx_gudam", "t": "끝났소? 끝났지? 아이고, 이제 다시는 신탁 같은 거 안 하겠소."}, {"s": null, "t": "그때 제단 위에서 쇳소리 같은 목소리가 울렸다. 붉은 달빛 아래 해진 제복을 입은 해골 사제가 서 있었다. 쥐고 있는 지팡이 끝에서 핏빛 불이 일렁였다."}, {"s": "q:sx_jeomrye", "t": "조사원님! 제단 위에 뭐가 있어요!"}, {"s": null, "t": "해골 사제는 구담을 손가락으로 가리켰다. 달의 말씀을 함부로 입에 올린 자를 제물로 받겠다는 듯했다. 구담이 내 뒤로 기어들어 왔다."}, {"s": "q:sx_gudam", "t": "나는 그냥 글귀를 베껴 읽었을 뿐이오. 저건 진짜잖소! 진짜는 반칙이오!"}, {"s": "q:sx_jeomrye", "t": "사제님, 지금 그런 말 할 때예요?"}]'::jsonb, '{"xp": 1067}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_false_oracle', 4, '집집마다', '월식 제사장귀을(를) 물리친다', '{"at": ["crimson_altar"], "tasks": [{"t": "win", "m": ["r71_altar_5"], "n": 1}]}'::jsonb, '[{"s": null, "t": "월식 제사장귀가 무너지자 붉은 달빛이 한 겹 옅어졌다. 제단 위에는 녹슨 지팡이 하나만 남았다."}, {"s": null, "t": "구담은 그제야 일어나 옷을 털었다. 그런데 몸을 돌리는 순간 그의 그림자가 이상하게 길었다. 그림자 끝에 손목이 묶인 형체 몇이 매달려 있었다."}, {"s": "q:sx_gudam", "t": "이, 이건 왜 아직 붙어 있소?"}, {"s": "q:sx_jeomrye", "t": "공물을 안 돌려주셔서 그런 거 아닐까요."}, {"s": null, "t": "구담은 쌀자루 하나를 들쳐 메고 점례의 마을 쪽으로 걸었다. 첫 번째 집 앞에 자루를 내려놓자 그림자에서 형체 하나가 떨어져 나갔다."}, {"s": "q:sx_gudam", "t": "……남은 게 몇 집이오?"}, {"s": "q:sx_jeomrye", "t": "마흔두 집이요. 두 번 바친 집도 있고요."}, {"s": null, "t": "구담은 울상이 되어 다음 자루를 멨다. 수레를 쓰려 하자 그림자가 무거워져 한 걸음도 떼지 못했다. 등에 지고 걸어야만 하는 모양이었다."}, {"s": null, "t": "점례는 돌려받은 쌀자루를 끌어안고 나에게 고개를 숙였다. 아들 돌잔치에는 이웃을 다 부르겠다고 했다. 사제님도 부르겠느냐고 묻자, 점례는 잠깐 생각하더니 웃었다."}, {"s": "q:sx_jeomrye", "t": "쌀을 다 돌려주고 나면요. 그때쯤이면 돌이 아니라 두 돌일 것 같지만요."}]'::jsonb, '{"xp": 1067, "gil": 93, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
