insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_doyun', 1, '벼락암의 빈자리', '벼락암의 빈자리', '{"at": ["iron_monastery"]}'::jsonb, '[{"s": "north_league:hyegak", "t": "허허, 오셨습니까. 잔도에서 우리 도윤이를 데려와 주신 지 벌써 열두 해가 되었군요."}, {"s": null, "t": "마당 한쪽에서 키가 훌쩍 자란 젊은 스님이 비질을 하고 있었다. 그 뒤를 꼬마 행자 하나가 졸졸 따라다녔다."}, {"s": "q:rn_doyun", "t": "조사원님! 저 이제 안 어려요. 이름표만 그대로예요."}, {"s": "q:sx_mongdol", "t": "도윤 스님은 비질을 하루에 세 번 해요. 잔소리도 세 번 해요."}, {"s": "north_league:hyegak", "t": "뇌명봉 꼭대기에 벼락암이라는 암자가 있습니다. 그 암자를 맡을 수좌 자리가 여러 해 비어 있었지요. 이번에 도윤이에게 시험을 보이려 합니다."}, {"s": "north_league:hyegak", "t": "시험은 간단합니다. 벼락 바위에 앉아 목탁을 치는 것이지요."}, {"s": "q:rn_doyun", "t": "또 목탁이에요? 저 팔이 아직도 그때 일을 기억하는데요."}, {"s": "north_league:hyegak", "t": "허허. 그런데 그 바위를 벼락 산령이 차지하고 앉았습니다. 그것부터 눕혀 주시겠습니까. 세게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_doyun', 2, '아무도 알려 주지 말 것', '벼락 산령을(를) 물리친다', '{"at": ["iron_monastery"], "tasks": [{"t": "win", "m": ["regional_thunder_peak_guardian"], "n": 1}]}'::jsonb, '[{"s": "north_league:hyegak", "t": "산령을 눕히셨다니, 이제 바위가 비었군요. 도윤이는 아침 일찍 목탁을 들고 올라갔습니다."}, {"s": "q:sx_mongdol", "t": "주먹밥을 일곱 개 싸 갔어요. 저한테는 하나도 안 줬어요."}, {"s": null, "t": "나는 시험이 언제 끝나느냐고 물었다. 혜각이 찻잔을 내려놓고 목소리를 낮췄다."}, {"s": "north_league:hyegak", "t": "그게 시험입니다. 목탁을 칠 줄은 열두 해 전에 이미 알았지요. 수좌는 멈출 때를 아는 사람이어야 합니다."}, {"s": "north_league:hyegak", "t": "언제 멈추라고는 일러 주지 않았습니다. 조사원께서도 알려 주지 마십시오."}, {"s": null, "t": "그때 산문으로 젖은 사람 하나가 뛰어 들어왔다. 뇌명봉에 약초를 캐러 간 사람 하나가 날이 저물도록 돌아오지 않았다고 했다. 산마루에는 먹구름이 끼어 있었다."}, {"s": "north_league:hyegak", "t": "허허, 하필 오늘이군요. 조사원께서 뇌명봉을 좀 살펴 주시겠습니까. 가시는 길에 도윤이가 무엇을 하는지도 봐 주시고요."}]'::jsonb, '{"xp": 1067}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_doyun', 3, '멈춘 목탁', '뇌명봉을(를) 살핀다', '{"at": ["iron_monastery"], "tasks": [{"t": "search", "r": ["thunder_peak"], "n": 3}]}'::jsonb, '[{"s": null, "t": "약초꾼은 벼락 바위 아래 비탈에서 발목을 접질린 채 쓰러져 있었다. 내가 닿았을 때는 이미 도윤이 그를 등에 업고 있었다. 바위 위에는 목탁만 덩그러니 남아 있었다."}, {"s": null, "t": "고찰로 내려오자 도윤은 약초꾼을 눕혀 놓고 마당에 털썩 주저앉았다."}, {"s": "q:rn_doyun", "t": "목탁을 멈췄어요. 사람 부르는 소리가 나서요. 저 떨어졌죠?"}, {"s": "north_league:hyegak", "t": "글쎄다."}, {"s": "q:rn_doyun", "t": "수좌님, 「글쎄다」가 제일 무서운 말인 거 아시죠."}, {"s": "q:sx_mongdol", "t": "그럼 남은 주먹밥은 제가 먹어도 돼요?"}, {"s": "north_league:hyegak", "t": "허허, 결과는 나중에 일러 주겠다. 조사원님, 저 약초꾼이 벼락 소리에 혼이 나서 숨을 제대로 못 쉽니다. 도윤이도 업고 뛰느라 기운이 다 빠졌고요. 청심환 두 알만 지어 주시겠습니까."}]'::jsonb, '{"xp": 1067}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_doyun', 4, '사흘 치', '청심환을(를) 만든다, 청심환을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "craft", "items": ["tonic"], "n": 2}], "give": {"tonic": 2}}'::jsonb, '[{"s": null, "t": "청심환을 먹은 약초꾼이 고르게 숨을 쉬었다. 도윤도 한 알을 삼키고 나서야 얼굴에 핏기가 돌았다."}, {"s": "north_league:hyegak", "t": "도윤아. 목탁을 왜 멈췄느냐."}, {"s": "q:rn_doyun", "t": "목탁 소리는 내일 쳐도 되는데, 그 사람은 내일이면 안 될 것 같았어요."}, {"s": "north_league:hyegak", "t": "그래. 그것이 시험이었다. 오늘부터 너를 벼락암 수좌로 삼는다."}, {"s": null, "t": "도윤은 한참 입만 벌리고 있다가, 벌떡 일어나 혜각에게 큰절을 했다. 너무 급히 숙이는 바람에 이마가 마루에 쿵 소리를 냈다."}, {"s": "q:sx_mongdol", "t": "와, 도윤 수좌님! 그럼 이제 저 마당 안 쓸어도 돼요?"}, {"s": "q:rn_doyun", "t": "몽돌아. 오늘 저녁 공양 전까지 마당을 쓸어라. 사흘 치."}, {"s": "q:sx_mongdol", "t": "수좌님……"}, {"s": null, "t": "도윤은 그 말을 하고서 저도 모르게 웃음을 터뜨렸다. 혜각이 찻잔 뒤로 얼굴을 가리고 따라 웃었다."}, {"s": "north_league:hyegak", "t": "허허. 조사원님, 고맙습니다. 저 아이가 웃으면 고찰이 따뜻해진다고 했지요. 이제는 벼락암도 따뜻해지겠습니다."}]'::jsonb, '{"xp": 1067, "gil": 93, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
