insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_sahwan', 1, '장부에 적힌 이름', '장부에 적힌 이름', '{"at": ["crimson_altar"]}'::jsonb, '[{"s": null, "t": "적월 제단터 들머리에 열너덧 살쯤 된 아이가 서 있었다. 내가 다가가자 부르기도 전에 아이가 먼저 돌아보았다."}, {"s": "q:sx_yeomun", "t": "조사원님! 저예요. 흑사단 폐단 계단에 앉아 있던 아이요. 이제 「여문아」 하고 부르면 바로 돌아봐요."}, {"s": null, "t": "나는 세 해 전 빈 명부의 마지막 줄을 떠올렸다. 그 줄에는 이제 여문이라는 이름이 적혀 있었다."}, {"s": "q:sx_yeomun", "t": "기록관 모가람님이 야행국 장부를 보여 주셨어요. 제 이름 옆에 흑사단 사람들 이름도 하나씩 옮겨 적어 두셨대요. 바친 이름은 못 되돌려도, 적어 두는 건 할 수 있다고요."}, {"s": "q:sx_yeomun", "t": "그런데 이상한 걸 찾았어요. 흑사단 이름이 적월교에 팔려 간 장부가 따로 있대요. 단주님이 문에 바친 게 아니라, 누가 팔아넘겼다는 거예요."}, {"s": "q:sx_yeomun", "t": "그 장부가 이 제단터 어딘가에 있대요. 같이 찾아 주세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_sahwan', 2, '제 차례를 기다리는 넋', '적월 제단터을(를) 살핀다', '{"at": ["crimson_altar"], "tasks": [{"t": "search", "r": ["crimson_altar"], "n": 3}]}'::jsonb, '[{"s": null, "t": "부서진 제기 더미 밑에서 붉은 끈으로 묶은 장부 한 권이 나왔다. 장마다 이름과 값이 나란히 적혀 있었다."}, {"s": "q:sx_yeomun", "t": "다 흑사단 사람들이에요. 이 사람은 저한테 엿을 사 주던 아저씨고, 이 사람은……"}, {"s": null, "t": "장부 끝에 판 사람의 표식이 찍혀 있었다. 흑사단 옛 문장이었다."}, {"s": null, "t": "그때 제단 위에서 희뿌연 넋들이 줄지어 일어났다. 넋들은 장부를 든 여문 쪽으로 손을 뻗었다. 아직도 제 차례를 기다리는 제물들이었다."}, {"s": "q:sx_yeomun", "t": "저 사람들이 장부를 달라는 거예요?"}, {"s": null, "t": "나는 장부에 적힌 이름을 다시 바치려는 것이라고 말했다. 넋들은 자기가 무엇이었는지 잊고, 바쳐지는 일만 기억하고 있었다."}, {"s": "q:sx_yeomun", "t": "그럼 안 돼요. 이번엔 아무도 안 바쳐요. 조사원님, 저 넋들 좀 눕혀 주세요."}]'::jsonb, '{"xp": 1067}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_sahwan', 3, '문지기의 얼굴', '제물 원령을(를) 물리친다', '{"at": ["crimson_altar"], "tasks": [{"t": "win", "m": ["r71_altar_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "원령들이 흩어지자 제단 뒤에서 늙수그레한 교도 하나가 허겁지겁 달려 나왔다."}, {"s": "q:sx_byeoksu", "t": "아이고, 소란이 났다기에 와 봤소. 그 장부는 이리 주시오. 제단 물건은 내가 맡고 있소."}, {"s": null, "t": "벽수의 손목에 흑사단 문장이 낡은 문신으로 남아 있었다. 장부 끝에 찍힌 표식과 같은 모양이었다."}, {"s": "q:sx_yeomun", "t": "……아저씨, 엿 사 주던 그 아저씨 맞죠. 아저씨 이름도 이 장부에 있어요. 값이 제일 비싸게요."}, {"s": "q:sx_byeoksu", "t": "무, 무슨 소리요. 나는 적월교 문지기요. 흑사단 따위 모르오."}, {"s": null, "t": "나는 장부를 덮었다. 벽수는 자기 이름까지 팔아 새 이름을 샀던 것이다. 그래서 지금은 누구도 그를 옛 이름으로 부르지 않았다."}, {"s": "q:sx_yeomun", "t": "저 원령들이 또 일어날 거예요. 바쳐진 사람들이 편히 쉬게 정화 부적을 써 주세요. 두 장이요. 하나는 제단에, 하나는…… 아저씨한테요."}]'::jsonb, '{"xp": 1067}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_sahwan', 4, '이름을 불러 주는 벌', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["crimson_altar"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "정화 부적을 제단에 붙이자 붉은 빛이 가라앉았다. 여문은 남은 한 장을 벽수의 손에 쥐여 주었다."}, {"s": "q:sx_byeoksu", "t": "이걸 왜 나한테 주오. 나를 벌주러 온 것 아니었소?"}, {"s": "q:sx_yeomun", "t": "벌이에요. 아저씨는 오늘부터 이 장부에 있는 이름을 날마다 하나씩 불러 주세요. 한 사람도 빼먹지 말고요."}, {"s": null, "t": "벽수의 얼굴이 하얗게 질렸다. 판 이름을 날마다 제 입으로 부르는 일이 무엇보다 무거운 벌이라는 것을 그도 알고 있었다."}, {"s": "q:sx_byeoksu", "t": "……다 부르려면 백 날이 넘게 걸리오."}, {"s": "q:sx_yeomun", "t": "그럼 백 날 넘게 하세요. 그 사람들은 아저씨 때문에 훨씬 오래 기다렸어요."}, {"s": null, "t": "그날 해 질 녘, 제단터에서 낮은 목소리가 들려왔다. 벽수가 장부 첫 장을 펴 놓고 이름 하나를 더듬더듬 부르고 있었다."}, {"s": null, "t": "나는 여문에게 장부의 이름을 야행국 장부에도 옮겨 적자고 했다. 여문은 부르기도 전에 고개를 끄덕였다."}]'::jsonb, '{"xp": 1067, "gil": 93, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
