on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_s_yeonok' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeonok', 1, '바구니를 멘 순찰대장', '바구니를 멘 순찰대장', '{"at": ["white_tower"]}'::jsonb, '[{"s": null, "t": "백옥 천문탑 아래 돌계단에 순찰대 다섯이 둘러앉아 있었다. 맨 앞에 앉은 사람만 칼 대신 커다란 구급 바구니를 등에 메고 있었다."}, {"s": "q:dh_yeonok", "t": "어, 조사원님! 잿빛 들녘에서 야령초 캐 주셨던 분 맞죠? 저 연옥이예요. 그때 바구니가 텅 비어서 쩔쩔매던 순찰 의원이요."}, {"s": "q:dh_yeonok", "t": "저 이제 순찰대장이에요. 웃기죠? 칼도 못 쥐는 사람이 대장이라니. 앞의 대장님이 다치시면서 저를 꼭 찍어 놓고 가셨어요."}, {"s": null, "t": "순찰대원들은 하나같이 눈이 풀려 있었다. 소매와 머리카락마다 반짝이는 가루가 묻어 있었다."}, {"s": "q:dh_yeonok", "t": "탑 둘레에 별빛 나비 떼가 몰려들었어요. 저 빛가루를 들이마시면 눈앞에 별이 핑핑 돌아요. 다들 반나절째 이러고 있어요."}, {"s": "q:dh_yeonok", "t": "저는 바구니로는 저것들을 못 쫓아요. 조사원님이 나비 떼 좀 흩어 주시겠어요? 그동안 저는 이분들 눈부터 씻길게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeonok', 2, '한 사람이 모자라요', '별빛 나비 떼을(를) 물리친다', '{"at": ["white_tower"], "tasks": [{"t": "win", "m": ["g_white_tower"], "n": 3}]}'::jsonb, '[{"s": null, "t": "나비 떼가 흩어지자 빛가루가 가라앉았다. 연옥이는 순찰대원들의 눈을 물로 씻기다가, 손가락을 접으며 머릿수를 셌다."}, {"s": "q:dh_yeonok", "t": "하나, 둘, 셋, 넷…… 넷이에요. 다섯이어야 하는데."}, {"s": "q:dh_yeonok", "t": "길수가 없어요. 새로 들어온 막내요. 나비 떼가 처음 몰려왔을 때 탑 안으로 뛰어 들어갔대요."}, {"s": null, "t": "계단참에 칼 한 자루가 떨어져 있었다. 칼집도 없이, 날이 아래로 엎어져 있었다."}, {"s": "q:dh_yeonok", "t": "길수 칼이에요. 칼을 버리고 도망갔다고들 하는데……"}, {"s": "q:dh_yeonok", "t": "그래도 다치진 않았는지 봐야죠. 탑 안이 넓어서 저 혼자서는 다 못 돌아요. 같이 찾아 주세요."}]'::jsonb, '{"xp": 1067}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeonok', 3, '도망친 게 아니라', '백옥 천문탑을(를) 살핀다', '{"at": ["white_tower"], "tasks": [{"t": "search", "r": ["white_tower"], "n": 2}]}'::jsonb, '[{"s": null, "t": "탑 중턱 관측실 구석에서 길수를 찾았다. 길수는 혼자가 아니었다. 빛가루를 뒤집어쓰고 쓰러진 늙은 관측관 하나를 무릎에 눕히고 있었다."}, {"s": "q:sx_gilsu", "t": "대, 대장님. 이분이 계단에서 쓰러지셨어요. 나비가 막 달려들어서, 업고 올라오는데 칼이 거치적거려서……"}, {"s": "q:sx_gilsu", "t": "칼을 내려놨어요. 다, 다들 제가 도망갔다고 하죠?"}, {"s": null, "t": "연옥이는 대답 대신 길수의 손을 잡아 들여다보았다. 관측관을 업고 오르느라 손바닥이 다 까져 있었다."}, {"s": "q:dh_yeonok", "t": "바보. 칼은 다시 주우면 되지만, 이분은 다시 못 주워요. 잘했어."}, {"s": null, "t": "관측관도 순찰대원들도 아직 숨이 가빴다. 빛가루가 가슴에 남아 열이 오르고 있었다."}, {"s": "q:dh_yeonok", "t": "조사원님, 청심환 세 알만 지어 주시겠어요? 관측관님 한 알, 가장 많이 들이마신 두 분한테 한 알씩이요. 제 바구니가 또 비었어요. 늘 이래요."}]'::jsonb, '{"xp": 1067}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeonok', 4, '두 칸짜리 순찰 일지', '청심환을(를) 만든다, 청심환을(를) 넘긴다', '{"at": ["white_tower"], "tasks": [{"t": "craft", "items": ["tonic"], "n": 3}], "give": {"tonic": 3}}'::jsonb, '[{"s": null, "t": "청심환을 먹은 이들이 하나둘 기운을 차렸다. 늙은 관측관은 길수의 손을 잡고 몇 번이나 고맙다고 했다. 길수는 귀까지 빨개졌다."}, {"s": null, "t": "연옥이는 바구니에서 순찰 일지를 꺼내 펼쳤다. 칸이 둘로 나뉘어 있었다. 한쪽에는 「쫓은 요괴」, 다른 쪽에는 「살린 사람」이라고 적혀 있었다."}, {"s": "q:dh_yeonok", "t": "대장이 되고 나서 칸을 하나 더 만들었어요. 앞의 대장님은 쫓은 요괴만 적으셨거든요."}, {"s": null, "t": "연옥이가 「살린 사람」 칸에 길수의 이름을 적었다. 한 획씩 꾹꾹 눌러서."}, {"s": "q:sx_gilsu", "t": "저, 저는 칼을 버렸는데요."}, {"s": "q:dh_yeonok", "t": "나도 그랬어. 칼을 못 쥐어서 바구니를 쥐었다고 늘 말했는데, 사실은 다친 사람 옆에서는 칼 쥘 손이 안 남더라."}, {"s": "q:dh_yeonok", "t": "그러니까 너도 칼 주워 와. 대신 다음에도 사람이 쓰러져 있으면, 또 내려놓고."}, {"s": null, "t": "길수는 계단참으로 달려 내려가 칼을 주워 왔다. 그리고 칼집이 없어 한참을 들고 서 있다가, 연옥이의 바구니 옆에 조심스럽게 꽂았다."}]'::jsonb, '{"xp": 1067, "gil": 93, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
