insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_1', 1, '비어 있는 화폭', '비어 있는 화폭', '{"at": ["under_root"]}'::jsonb, '[{"s": null, "t": "지맥의 뿌리 어귀의 바위 그늘에 화구 상자를 멘 사내와 앳된 소녀가 앉아 있었다. 사내 앞에는 빈 화폭이 하나 펼쳐져 있었다."}, {"s": "q:sx_sorim", "t": "야행국 조사원이시죠? 저는 소림이에요. 이분은 제 스승님이시고요. 사람 얼굴을 그리시는 화공이세요."}, {"s": "q:sx_damchae", "t": "……반갑소. 앉으시오."}, {"s": "q:sx_sorim", "t": "스승님은 잊혀 가는 사람의 얼굴을 그려요. 그려 두면 그 사람 이름이 그림에 남는다고 하셔서요."}, {"s": "q:sx_damchae", "t": "얼굴은 이름을 담는 그릇이오. 불러 줄 이가 없는 사람도, 얼굴이 남으면 누군가 언젠가 묻게 되오. 「이 사람은 누구요」 하고."}, {"s": null, "t": "나는 빈 화폭을 가리키며 무엇을 그린 그림이냐고 물었다."}, {"s": "q:sx_sorim", "t": "비어 있는 게 아니에요. 원래 광부 아저씨가 그려져 있었어요. 이 뿌리 밑에서 무너진 갱도에 묻힌 분이요. 그런데 어젯밤에 그림에서 나가 버렸어요."}, {"s": "q:sx_damchae", "t": "먹 발자국이 뿌리 안쪽으로 나 있소. 혼자 쫓기엔 내 다리가 늙었구려. 함께 좀 찾아 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_1', 2, '먹으로 찍힌 발자국', '지맥의 뿌리을(를) 살핀다', '{"at": ["under_root"], "tasks": [{"t": "search", "r": ["under_root"], "n": 3}]}'::jsonb, '[{"s": null, "t": "뿌리 사이 진흙 바닥에 검은 발자국이 이어져 있었다. 손끝으로 문지르자 먹이 묻어났다."}, {"s": null, "t": "발자국은 오래전에 무너진 갱도 입구에서 멈추었다. 입구는 굵은 뿌리로 막혀 있었고, 그 틈에서 무언가 꿈틀거렸다."}, {"s": "q:sx_sorim", "t": "저기 지네가……. 스승님, 물러서세요."}, {"s": "q:sx_damchae", "t": "저 안이오. 저 안에서 땅 파는 소리가 들리오. 그 사람이오."}, {"s": null, "t": "담채는 지네가 우글대는 입구로 그대로 걸어가려 했다. 소림이 소매를 붙잡았다."}, {"s": "q:sx_sorim", "t": "조사원님, 부탁드려요. 스승님은 그림 얘기만 나오면 앞뒤를 안 보세요."}]'::jsonb, '{"xp": 1153}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_1', 3, '제 몸을 찾는 사람', '뿌리 지네을(를) 물리친다', '{"at": ["under_root"], "tasks": [{"t": "win", "m": ["g_under_root"], "n": 3}]}'::jsonb, '[{"s": null, "t": "지네를 걷어 낸 갱도 안쪽에 먹빛 사람 하나가 서 있었다. 그림에서 빠져나온 광부였다. 광부는 아무 소리 없이 무너진 흙더미를 손으로 파고 있었다."}, {"s": null, "t": "광부의 몸은 한 번 흙을 팔 때마다 조금씩 옅어졌다. 손끝은 이미 회색 연기처럼 풀려 있었다."}, {"s": "q:sx_sorim", "t": "아저씨가 흐려지고 있어요. 그림에서 멀어지면 저렇게 되나 봐요."}, {"s": "q:sx_damchae", "t": "저 흙 밑에 제 몸이 있소. 그걸 찾으러 간 거요. 그러나 찾아서 무엇 하겠소. 몸은 이미 흙이 되었는데."}, {"s": "q:sx_damchae", "t": "다시 그려야겠소. 먹이 옅어졌으니 진한 먹이 있어야 하오. 이 뿌리 밑 돌틈에 맺히는 먹정이 좋소. 지맥의 기운을 먹고 굳은 먹이라 쉽게 바래지 않소. 아, 그 먹으로 그리면 눈동자가 살아나오. 광부의 눈은 늘 어둠에 익어 있으니 검은 데서 더 검게……. 세 덩이만 구해 주시오."}]'::jsonb, '{"xp": 1153}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_1', 4, '다시 그려진 얼굴', '먹정을(를) 모은다', '{"at": ["under_root"], "tasks": [{"t": "gather", "items": ["inkstone"], "r": ["under_root"], "n": 3}]}'::jsonb, '[{"s": null, "t": "담채는 먹정을 갈아 밤새 붓을 놀렸다. 붓이 지날 때마다 갱도 안의 먹빛 광부가 옅어지더니, 새벽녘에는 흔적도 없이 사라졌다."}, {"s": null, "t": "화폭에는 광부가 다시 서 있었다. 곡괭이를 메고, 어둠에 익은 눈으로 이쪽을 보고 있었다."}, {"s": "q:sx_damchae", "t": "되었소. 이제 이 사람 이름은 잊히지 않소."}, {"s": null, "t": "담채가 화구를 정리하는 사이, 소림이 나를 불러 화폭을 가리켰다."}, {"s": "q:sx_sorim", "t": "조사원님, 보세요. 아저씨 얼굴이요. 처음 그림보다 슬퍼 보여요. 그리고 발이요. 그림 속에서 자꾸 갱도 쪽을 향해 있어요."}, {"s": "q:sx_sorim", "t": "아저씨는 흙 밑으로 가고 싶었던 게 아닐까요. 그런데 스승님이 붙잡은 거고요."}, {"s": "q:sx_damchae", "t": "소림아. 가자. 그릴 얼굴이 아직 많소."}, {"s": null, "t": "소림은 대답하지 않고 화폭을 말아 들었다. 말린 화폭 안쪽에서 무언가 흙을 긁는 소리가 아주 작게 났다."}]'::jsonb, '{"xp": 1153, "gil": 97, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
