insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_redmoon', 1, '문지기가 성을 비운 밤', '문지기가 성을 비운 밤', '{"at": ["crimson_altar"]}'::jsonb, '[{"s": null, "t": "적월 제단터의 붉은 돌기둥 아래에 낯익은 사내가 서 있었다. 월식성 성문에서 나를 막아서던 문지기였다."}, {"s": "q:rn_takmu", "t": "……야행국. 또 너냐."}, {"s": "q:rn_takmu", "t": "성벽에서 네가 눕힌 혈월 무사 둘 기억하나. 그중 하나, 경파라는 녀석이 사흘 전에 성을 나갔다."}, {"s": "q:rn_takmu", "t": "대호법께서 그 녀석 이름을 외우셨다. 「언젠가 제 발로 서는 놈」이라고. 대호법께서 이름을 외운 놈은 셋도 안 된다."}, {"s": null, "t": "나는 그런 사람이 왜 성을 나갔느냐고 물었다."}, {"s": "q:rn_takmu", "t": "붉은 보름달을 너무 오래 보다 너한테 졌다. 교도들 사이에서 그런 놈은 달을 볼 자격이 없다는 말이 돈다. 그 말을 녀석이 믿어 버렸다."}, {"s": "q:rn_takmu", "t": "밤마다 제단 쪽에서 경문 외는 소리가 난다. 산 사람 목소리가 아니다. 녀석이 그 소리를 따라갔을 거다."}, {"s": "q:rn_takmu", "t": "문지기는 제단에 들어가지 않는 게 교리다. 그러니 네가 대신 제단터를 훑어 다오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_redmoon', 2, '제 이름을 태우는 사람', '적월 제단터을(를) 살핀다', '{"at": ["crimson_altar"], "tasks": [{"t": "search", "r": ["crimson_altar"], "n": 3}]}'::jsonb, '[{"s": null, "t": "가장 안쪽 제단 위에서 젊은 무사가 무릎을 꿇고 있었다. 무사는 붉은 천에 무언가를 적어 화로 위에 올려놓고 있었다."}, {"s": null, "t": "천에 적힌 것은 무사 자신의 이름이었다. 화로 둘레에서는 경문이 새겨진 혼들이 낮게 경을 외고 있었다."}, {"s": "q:sx_gyeongpa", "t": "오지 마시오. 내가 고른 일이오."}, {"s": "q:sx_gyeongpa", "t": "나는 달을 보다 정신을 잃었고, 바깥사람한테 졌소. 약한 자의 이름은 달에 바치는 게 맞소. 그러면 적어도 쓸모는 있으니."}, {"s": null, "t": "내 뒤에서 거친 발소리가 났다. 제단에 들어오지 않겠다던 탁무였다."}, {"s": "q:rn_takmu", "t": "이 멍청한 놈아. 누가 그런 걸 교리라고 가르쳤나."}, {"s": "q:sx_gyeongpa", "t": "저분들이오. 제단을 지키던 옛 교도들 말이오."}, {"s": null, "t": "경을 외던 혼들이 일제히 고개를 들었다. 경문 한 줄 한 줄이 붉은 결계가 되어 경파를 둘러쌌다."}, {"s": "q:rn_takmu", "t": "저것들은 오래전에 제 이름을 바친 광신도들의 혼이다. 외로워서 동무를 부르는 거다. 쳐라. 내가 녀석을 붙들고 있겠다."}]'::jsonb, '{"xp": 1153}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_redmoon', 3, '반쯤 탄 이름', '적월 광신 요인을(를) 물리친다', '{"at": ["crimson_altar"], "tasks": [{"t": "win", "m": ["r71_altar_3"], "n": 3}]}'::jsonb, '[{"s": null, "t": "{직업:호위=방패에 부딪힌 경문이 불티처럼 흩어지자/월궁=화살이 경문 한 줄을 꿰뚫자/퇴마=방울 소리에 경문이 한 줄씩 지워지자/의무=부채 바람에 경문이 흐트러지자/봉인=금강령 소리에 경문이 묶여 멈추자/암영=단도가 경문의 이음매를 끊자} 마지막 혼이 무너졌다. 결계가 걷혔다."}, {"s": null, "t": "탁무가 화로에서 붉은 천을 낚아챘다. 천은 반쯤 타 있었고, 이름 글자도 반쯤 그을려 있었다."}, {"s": "q:rn_takmu", "t": "경파."}, {"s": null, "t": "경파는 한참 뒤에야 고개를 돌렸다. 제 이름이 남의 이름처럼 들리는 얼굴이었다."}, {"s": "q:rn_takmu", "t": "……늦게 돌아본다. 이름이 덜 붙어 있는 거다."}, {"s": null, "t": "나는 정화 부적으로 그을린 글자를 감싸면 이름이 다시 붙을 것이라고 했다."}, {"s": "q:rn_takmu", "t": "야행국 부적을 적월 제단에 쓰라고? 그런 일은 교리 어디에도 없다."}, {"s": null, "t": "탁무는 이를 악물고 경파를 내려다보다가 고개를 끄덕였다."}, {"s": "q:rn_takmu", "t": "교리에 없는 일은 내가 지겠다. 정화 부적 두 장만 만들어 다오."}]'::jsonb, '{"xp": 1153}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_redmoon', 4, '달은 기억할 뿐이다', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["crimson_altar"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "정화 부적으로 붉은 천을 감싸자 그을린 글자가 천천히 제 빛을 되찾았다."}, {"s": "q:rn_takmu", "t": "경파."}, {"s": "q:sx_gyeongpa", "t": "……예."}, {"s": null, "t": "이번에는 바로 대답이 돌아왔다. 그때 제단 아래에서 무거운 발소리가 올라왔다. 붉은 장포를 걸친 거한이었다."}, {"s": "red_moon_cult:sama", "t": "내가 외운 이름을 누가 태우나 했더니, 제 손으로 태우고 있었구나."}, {"s": "red_moon_cult:sama", "t": "「약한 자는 들어오지 마라.」 내가 한 말이지. 약하면 버리라는 말이 아니다. 강해질 때까지 내가 이름을 외워 둔다는 말이다."}, {"s": "red_moon_cult:sama", "t": "제단 둘레의 경문 돌은 오늘 밤 모두 깨라. 남의 이름을 부르는 경은 교리가 아니다. 교주께서도 그리 말씀하셨다. 달은 원망하지 않는다. 기억할 뿐이다."}, {"s": "red_moon_cult:sama", "t": "그리고 탁무. 문지기가 제단에 들어왔다. 교리를 어겼다."}, {"s": "q:rn_takmu", "t": "예."}, {"s": "red_moon_cult:sama", "t": "잘했다. 벌은 따로 내리마."}, {"s": null, "t": "대호법은 떠나면서 나를 돌아보았다. 아직 내 이름을 외우고 있다고 했다. 이번에는 적이 될 날을 말하지 않았다."}]'::jsonb, '{"xp": 1153, "gil": 97, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
