insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_3', 1, '받지 말라는 줄', '받지 말라는 줄', '{"at": ["tide_gate"]}'::jsonb, '[{"s": null, "t": "만조의 갑문 아래로 밀물이 들어차고 있었다. 해솔은 장부를 펴 놓고 한참 아무 말도 하지 않았다."}, {"s": "q:sx_dodam", "t": "누나가 이상해요. 옥사에 다녀온 뒤로 밤마다 장부를 다시 읽어요. 셈은 안 하고 읽기만 해요."}, {"s": "q:sx_haesol", "t": "이 줄 좀 봐 주세요. 「만조의 갑문. 연지. 배 한 척 값.」 그 옆에 아버지 글씨로 「받지 말 것」이라고 적혀 있어요."}, {"s": "q:sx_haesol", "t": "다른 줄에는 다 갚는 법이 있었어요. 이 줄만 받지 말래요. 받지 않을 거면 왜 적어 두셨을까요."}, {"s": null, "t": "갑문 옆 오두막에서 백발의 아낙이 갈대를 엮고 있었다. 아낙은 오누이의 등짐을 보더니 손을 멈추었다."}, {"s": "q:sx_yeonji", "t": "그 등짐…… 이제야 왔구나."}, {"s": "q:sx_yeonji", "t": "기다렸다. 갚을 돈은 모아 뒀어. 그런데 그 전에 내가 마저 할 일이 있구나."}, {"s": "q:sx_yeonji", "t": "우리 영감 제삿날이 사흘 남았다. 해마다 수향 갈대로 제상 깔개를 엮는데, 올해는 손이 떨려서 갈대를 못 베겠어. 다섯 단만 베어다 주련."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_3', 2, '영감이 탄 배', '수향 갈대을(를) 모은다', '{"at": ["tide_gate"], "tasks": [{"t": "gather", "items": ["river_reed"], "r": ["tide_gate"], "n": 5}]}'::jsonb, '[{"s": null, "t": "연지는 갈대를 받아 무릎에 올려놓고 엮기 시작했다. 엮으면서 천천히 이야기했다."}, {"s": "q:sx_yeonji", "t": "서른 해 전에 우리 영감이 배를 사겠다고 했지. 돈이 모자랐는데, 지나가던 등짐장수가 모자란 돈을 꿔 줬어. 갚을 수 있을 때 갚으라고."}, {"s": "q:sx_yeonji", "t": "그 배를 산 지 열흘 만에 밀물에 갑문이 터졌다. 영감은 배랑 같이 물 밑으로 갔고."}, {"s": "q:sx_yeonji", "t": "그 등짐장수가 그해 겨울에 다시 왔어. 나는 갚을 게 없다고 울었지. 그 사람은 아무 말 없이 장부에 뭘 적고 갔다. 그게 그 말이었구나."}, {"s": null, "t": "갑문 쪽 물소리가 거칠어졌다. 밀물을 타고 물에 불은 손들이 갑문 턱을 짚고 올라오고 있었다."}, {"s": "q:sx_yeonji", "t": "제삿날이 다가오면 저것들이 올라와. 우리 영감은 아니다. 영감 이름은 내가 날마다 부르니까. 저건 이름을 잃고 물에 남은 것들이야."}, {"s": "q:sx_dodam", "t": "누나, 제가 할머니 옆에 있을게요. 조사원, 저것들 좀 막아 주세요."}, {"s": null, "t": "해솔은 동생을 잠깐 바라보다가 고개를 끄덕였다."}]'::jsonb, '{"xp": 1241}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_3', 3, '서른 해 모은 돈', '밀물 수귀을(를) 물리친다', '{"at": ["tide_gate"], "tasks": [{"t": "win", "m": ["r71_tide_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "수귀들이 물러가자 연지는 오두막 마루 밑에서 작은 항아리를 꺼냈다. 항아리에는 엽전이 가득 들어 있었다."}, {"s": "q:sx_yeonji", "t": "서른 해 모았다. 배 한 척 값이야. 받아 가거라."}, {"s": null, "t": "해솔은 항아리를 내려다보았다. 셈이 빠른 아이라 그게 얼마인지 단번에 알았을 것이다."}, {"s": "q:sx_haesol", "t": "이 돈이면 저희 오누이가 세 해는 등짐을 안 메도 돼요."}, {"s": "q:sx_dodam", "t": "누나."}, {"s": "q:sx_haesol", "t": "알아."}, {"s": null, "t": "해솔은 항아리 뚜껑을 도로 덮어 연지의 무릎에 올려놓았다."}, {"s": "q:sx_haesol", "t": "아버지가 받지 말라고 하셨어요. 저는 아버지 장부대로 받으러 다니는 거니까, 이 줄은 안 받아요."}, {"s": "q:sx_yeonji", "t": "……그 사람 딸이 맞구나."}, {"s": "q:sx_yeonji", "t": "그럼 하나만 해 다오. 영감은 갑문에서 낚은 고기를 제상에 꼭 두 마리 올렸어. 오늘 밤 밀물이 차면 여기서 두 번만 줄을 드리워 주련."}]'::jsonb, '{"xp": 1241}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_3', 4, '갑문 위의 발자국', '만조의 갑문에서 낚시를 한다', '{"at": ["tide_gate"], "tasks": [{"t": "fish", "r": ["tide_gate"], "n": 2}]}'::jsonb, '[{"s": null, "t": "제상 위에 갈대 깔개를 깔고 갑문에서 낚은 고기 두 마리를 올렸다. 연지는 영감의 이름을 한 번 부르고 오래 절했다."}, {"s": null, "t": "밀물 소리가 잦아들었다. 갑문 턱에 젖은 발자국 둘이 찍혔다가, 마르면서 사라졌다."}, {"s": "q:sx_yeonji", "t": "왔다 갔네. 해마다 저렇게 다녀가."}, {"s": "q:sx_yeonji", "t": "너희 아버지도 해마다 이맘때 왔다. 갑문 위에 서서 영감 이름을 같이 불러 주고 갔지. 그런데 다섯 해 전부터 안 오더구나."}, {"s": "q:sx_dodam", "t": "아버지는 다섯 해 전에 돌아가셨어요. 등짐만 집으로 돌아왔어요."}, {"s": "q:sx_yeonji", "t": "그래? ……그 사람은 등짐을 놓고 갈 사람이 아닌데."}, {"s": null, "t": "해솔은 대답하지 않고 장부의 맨 끝 쪽을 펼쳤다. 다른 쪽보다 글씨가 흐트러져 있었다."}, {"s": "q:sx_haesol", "t": "마지막 줄은 흑조 균열이에요. 다른 줄은 다 외상인데, 이 줄만 「판 것」이라고 적혀 있어요."}, {"s": "q:sx_haesol", "t": "도담아, 거기까지 가 보자. 아버지가 마지막으로 뭘 파셨는지 알아야겠어."}]'::jsonb, '{"xp": 1241, "gil": 101, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
