values ('sq110_f_north2', 'side', '세력·뇌명봉', '맹약지의 겨울잠', '맹세를 이은 뒤 맞는 북령의 첫겨울', 'thunder_peak', 24, '{sq110_f_north}'::text[], null, 1137, '[]'::jsonb, true, null, null)
