delete from public.world_quest_steps where quest_id = 'sq110_f_north2' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_north2', 1, '겨울잠 드는 사람들', '겨울잠 드는 사람들', '{"at": ["thunder_peak"]}'::jsonb, '[{"s": null, "t": "뇌명봉 산마루의 맹약지 초막 둘레에 눈집 여러 채가 새로 서 있었다. 지팡이를 짚은 노병들이 하나둘 눈집 안으로 들어가고 있었다."}, {"s": "q:rn_seolbaek", "t": "오셨어요. 북령맹에는 옛 풍습이 있어요. 싸움터에서 물러난 맹우들이 겨울이면 맹약지에 모여 봄까지 함께 자요. 겨울잠이라고 불러요."}, {"s": "q:rn_seolbaek", "t": "서강 어르신 가신 뒤로 처음 드는 겨울잠이에요. 제가 맹약 패를 지니고 처음 맞는 겨울이고요."}, {"s": null, "t": "곁에서 짐을 부리던 여장수가 눈을 털며 다가왔다. 맹의 호송대장이었다."}, {"s": "north_league:yeo", "t": "짐은 다 올렸다. 그런데 길목에 뇌각 산군 두 마리가 자리를 잡았다. 포효할 때마다 바위 틈에서 낙뢰가 솟아. 잠든 노인들이 깨면 봄까지 못 버틴다."}, {"s": "north_league:yeo", "t": "그리고 하나 더. 올해는 맹주께서도 겨울잠에 드신다."}, {"s": "q:rn_seolbaek", "t": "맹주님이요? 한 번도 그러신 적이 없는데요."}, {"s": "north_league:yeo", "t": "그러니까 걱정이지. 산군부터 치워 다오. 이야기는 그다음에."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_north2', 2, '형의 패 앞에서', '뇌각 산군을(를) 물리친다', '{"at": ["thunder_peak"], "tasks": [{"t": "win", "m": ["m_thunder"], "n": 2}]}'::jsonb, '[{"s": null, "t": "산군이 쓰러지자 산마루가 고요해졌다. 맹약지 초막 안에서 맹주 석진악이 고찰에서 옮겨 온 패 하나를 닦고 있었다. 석진후의 패였다."}, {"s": "north_league:seok", "t": "형님 패를 올해만 여기 두려 한다. 형님도 겨울잠 한 번 못 자 보고 얼음 속에 서 계셨으니."}, {"s": "north_league:seok", "t": "……오른 어깨가 시리다. 형님이 남던 그날 얼음 인장 앞에서 다친 자리다. 서른 해를 모른 척했는데 올해는 말을 안 듣는군."}, {"s": null, "t": "나는 맹주가 겨울잠에 드는 동안 맹은 누가 이끄느냐고 물었다."}, {"s": "north_league:yeo", "t": "길은 내가 지키고, 고찰은 수좌가 지킨다. 맹주가 없다고 무너질 맹이면 진작 무너졌다."}, {"s": "q:rn_seolbaek", "t": "눈집이 너무 차요. 노인들 몸으로는 겨울을 못 나요. 서강 어르신은 눈집 바닥에 영핵을 묻어 온기를 돌리셨대요."}, {"s": "q:rn_seolbaek", "t": "이 산 뇌맥에서 응축 영핵을 두 덩이만 캐다 주세요. 맹주님 눈집이랑 맹우들 눈집 바닥에 나눠 묻을게요."}]'::jsonb, '{"xp": 1241}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_north2', 3, '잠들지 못하는 맹주', '응축 영핵을(를) 모은다', '{"at": ["thunder_peak"], "tasks": [{"t": "gather", "items": ["spirit_core"], "r": ["thunder_peak"], "n": 2}]}'::jsonb, '[{"s": null, "t": "영핵을 묻은 눈집 바닥에서 은은한 온기가 올라왔다. 노병들은 하나둘 코를 골기 시작했다."}, {"s": null, "t": "맹주의 눈집만 조용하지 않았다. 석진악은 눈을 뜬 채 누워 천장의 얼음만 보고 있었다."}, {"s": "north_league:seok", "t": "눈을 감으면 형님이 문을 두드리는 소리가 들린다. 그래서 서른 해 동안 겨울잠을 마다했지."}, {"s": "north_league:yeo", "t": "맹주께서 처음으로 약한 소리를 하시는군."}, {"s": "north_league:seok", "t": "약한 소리가 아니라 늙은 소리다, 운비."}, {"s": "q:rn_seolbaek", "t": "안신탕을 드시면 꿈 없이 주무실 수 있어요. 의원들이 그러는데 마음 졸이는 사람한테 제일이래요."}, {"s": null, "t": "나는 맹주와 맹우들 몫으로 안신탕 두 그릇을 달이겠다고 했다."}]'::jsonb, '{"xp": 1241}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_north2', 4, '뒤에 선 사람', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["thunder_peak"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 2}], "give": {"calm_brew": 2}}'::jsonb, '[{"s": null, "t": "석진악은 안신탕을 받아 들고도 한참 마시지 않았다. 설백이 맹약 패를 품에서 꺼내 맹주의 머리맡에 놓았다."}, {"s": "q:rn_seolbaek", "t": "맹주님. 눈을 감는 자는 뒤에 선 사람을 못 지킨다고 하셨지요."}, {"s": "q:rn_seolbaek", "t": "이번 겨울은 제가 뒤에 서겠습니다. 문을 두드리는 소리가 나면 제가 대답하겠습니다. 그러니 눈 감으셔도 됩니다."}, {"s": null, "t": "석진악은 설백을 오래 바라보다가 안신탕을 단숨에 비웠다."}, {"s": "north_league:seok", "t": "서강 형님 말이 맞았다. 뒤에 선 사람을 믿고 감으라더니."}, {"s": null, "t": "맹주의 숨이 고르게 잦아들었다. 여운비가 눈집 문 앞에 털가죽을 덧대었다."}, {"s": "north_league:yeo", "t": "맹주를 재운 사람은 맹에서 네가 처음이다. 봄까지 산마루를 부탁한다."}, {"s": null, "t": "그날 밤 산마루에 눈이 쌓였다. 설백은 맹약 패를 품고 초막 앞에 앉아 밤을 새웠다. 두드리는 소리는 들리지 않았다."}]'::jsonb, '{"xp": 1241, "gil": 101, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
