insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_gull_wedding', 1, '안 닫히는 갑문', '안 닫히는 갑문', '{"at": ["tide_gate"]}'::jsonb, '[{"s": null, "t": "만조의 갑문 꼭대기에서 갈매기 두 마리가 서로 깃을 다듬어 주고 있었다. 그 아래 쇠문은 한 뼘쯤 열린 채 멈춰 있었다."}, {"s": "q:sx_boksu", "t": "저것들 때문이야. 문을 닫으려고 바퀴를 돌리면 둥지가 짓눌리거든. 그러면 저 암놈이 내 머리를 쪼아."}, {"s": null, "t": "복수의 갓에는 정말로 쪼인 구멍이 여러 개 나 있었다."}, {"s": "q:sx_maehwa", "t": "우리 영감은 문을 그냥 닫으면 될 걸, 둥지 걱정에 사흘째 못 닫고 있어요."}, {"s": "q:sx_boksu", "t": "닫으면 알이 깨지잖아! 아직 알도 안 낳았지만, 낳을 거잖아."}, {"s": null, "t": "나는 둥지를 다른 데로 옮겨 주면 되지 않느냐고 했다."}, {"s": "q:sx_boksu", "t": "나도 그 생각은 했지. 그런데 소금 갈매기는 갈대로 짠 둥지만 쓴다더라. 수향 갈대 여섯 단을 베어 오게. 내가 새 둥지를 엮어 보지."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_gull_wedding', 2, '신랑 노릇', '수향 갈대을(를) 모은다', '{"at": ["tide_gate"], "tasks": [{"t": "gather", "items": ["river_reed"], "r": ["tide_gate"], "n": 6}]}'::jsonb, '[{"s": null, "t": "복수는 투덜대면서도 굵은 손으로 갈대를 꼼꼼히 엮었다. 둥지는 금세 바구니만 하게 둥그렇게 완성되었다."}, {"s": "q:sx_maehwa", "t": "우리 혼례 때 꽃가마는 저렇게 정성 들여 안 만들었으면서."}, {"s": "q:sx_boksu", "t": "그땐 내가 만든 게 아니잖아."}, {"s": null, "t": "그때 바다 쪽에서 하얀 갈매기 떼가 시끄럽게 몰려왔다. 갑문 꼭대기의 수컷을 에워싸고 마구 울어 댔다."}, {"s": "q:sx_maehwa", "t": "어머, 저 암놈 노리는 수놈들이네요. 혼례 날 신부 뺏으러 온 거예요."}, {"s": "q:sx_boksu", "t": "남의 혼례를 망치러 와? 저런 고얀 것들!"}, {"s": "q:sx_boksu", "t": "조사원, 저 떼거리 좀 쫓아 주게. 다치게는 말고. 하객 노릇이나 하라고 해."}]'::jsonb, '{"xp": 1241}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_gull_wedding', 3, '둥지 놓을 자리', '소금 갈매기 떼을(를) 물리친다', '{"at": ["tide_gate"], "tasks": [{"t": "win", "m": ["r71_tide_2"], "n": 4}]}'::jsonb, '[{"s": null, "t": "몰려왔던 떼가 바다로 흩어지자 갑문 꼭대기의 한 쌍은 나란히 앉아 숨을 골랐다."}, {"s": "q:sx_maehwa", "t": "이제 둥지만 옮기면 되겠네요. 그런데 어디에 놓아요?"}, {"s": "q:sx_boksu", "t": "바람이 덜 불고, 물이 안 튀고, 문 바퀴하고는 멀고, 해는 잘 들고……"}, {"s": "q:sx_maehwa", "t": "그런 데가 있으면 우리가 먼저 살겠어요."}, {"s": null, "t": "복수가 새 둥지를 들고 갈매기에게 다가가자, 암컷이 다시 갓을 쪼려 했다. 복수는 갓을 벗어 둥지 옆에 내려놓고 물러섰다."}, {"s": "q:sx_boksu", "t": "조사원, 갑문 둘레를 한번 살펴봐 주게. 저 까다로운 신부가 마음에 들어 할 만한 데가 있나."}]'::jsonb, '{"xp": 1241}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_gull_wedding', 4, '갓 속의 알', '만조의 갑문을(를) 살핀다', '{"at": ["tide_gate"], "tasks": [{"t": "search", "r": ["tide_gate"], "n": 2}]}'::jsonb, '[{"s": null, "t": "갑문 둘레를 돌아보고 왔을 때, 갈매기 한 쌍은 이미 자리를 정해 두고 있었다."}, {"s": null, "t": "새로 엮은 갈대 둥지가 아니었다. 복수가 벗어 둔 갓이었다. 암컷이 갓 속에 들어앉아 꿈쩍도 하지 않았다."}, {"s": "q:sx_boksu", "t": "그건 내 갓이야! 장날에 쓰는 갓이라고!"}, {"s": "q:sx_maehwa", "t": "영감, 갓 하나 새로 사요. 신부가 골랐잖아요."}, {"s": null, "t": "복수는 한참 입을 우물거리다가 갓을 둥지째 들어 갑문 망루 처마 밑으로 옮겼다. 그리고 갈대 둥지는 그 갓 위에 지붕처럼 덮어 주었다."}, {"s": null, "t": "쇠문은 그날 밤 끼익 소리를 내며 끝까지 닫혔다. 만조의 물이 문 앞에서 멈추었다."}, {"s": "q:sx_maehwa", "t": "영감, 기억나요? 우리도 이 갑문 위에서 혼례 올렸잖아요. 그때 갈매기들이 하도 울어서 하객 말소리가 하나도 안 들렸는데."}, {"s": "q:sx_boksu", "t": "……그때 그놈들 손주들이겠지."}, {"s": null, "t": "사흘 뒤 갑문에서 소식이 왔다. 갓 속에 알이 두 개 생겼다고 했다. 복수는 이제 망루에 올라갈 때마다 갓 대신 수건을 머리에 쓰고 다닌다고 했다."}]'::jsonb, '{"xp": 1241, "gil": 101, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
