on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_s_suchil' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_suchil', 1, '만조에 떠밀려 온 배', '만조에 떠밀려 온 배', '{"at": ["tide_gate"]}'::jsonb, '[{"s": null, "t": "만조의 갑문 아래 물목에 낡은 나룻배 한 척이 걸려 있었다. 배 옆구리에는 다 지워진 글씨로 「구룡」 두 글자가 남아 있었다."}, {"s": null, "t": "그 앞에서 지팡이를 짚은 노인이 배를 쓰다듬고 있었다. 구룡 폐수로에서 흑잉어를 구워 주던 그 수문지기였다."}, {"s": "q:dh_suchil", "t": "자네 왔나. 그새 다섯 해가 갔구먼. 내가 그랬지, 내일도 기다릴 거라고."}, {"s": "q:dh_suchil", "t": "그런데 정말 왔다네. 수문 닫히기 전날 마지막으로 나간 배야. 우리 수돌이가 노를 잡았지."}, {"s": null, "t": "나는 배 안을 들여다보았다. 배는 비어 있었다. 노 하나만 노걸이에 얌전히 걸려 있었다."}, {"s": null, "t": "물이 차오르자 배 밑에서 검은 손들이 뱃전을 붙잡고 올라왔다. 만조를 타고 들어온 물귀신들이었다."}, {"s": "q:dh_suchil", "t": "이놈들이 여기까지 배를 끌고 왔나 보이. 고맙기는 한데 배를 도로 끌고 갈 셈이야. 좀 떼어 주게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_suchil', 2, '두 그릇', '밀물 수귀을(를) 물리친다', '{"at": ["tide_gate"], "tasks": [{"t": "win", "m": ["r71_tide_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "수귀들이 물 밑으로 가라앉자 배가 조용히 흔들리다 멈추었다. 염수칠은 노를 내려 한참 손바닥으로 문질렀다."}, {"s": "q:dh_suchil", "t": "노에 손때가 그대로야. 이놈이 노를 쥘 때 꼭 엄지를 위로 올렸거든."}, {"s": null, "t": "나는 아들이 어디로 갔는지 아느냐고 물었다. 염수칠은 고개를 저었다."}, {"s": "q:dh_suchil", "t": "몰라. 배가 왔으면 됐지. 이십 년을 넘게 저녁마다 수돌아, 밥 먹어라, 하고 불렀다네. 대답은 없었어도."}, {"s": "q:dh_suchil", "t": "배가 왔으니 저녁상을 차려야지. 오늘은 두 그릇이야."}, {"s": "q:dh_suchil", "t": "여기 물목에서 고기 두 마리만 낚아 주겠나. 바닷물이라 흑잉어는 없겠지만, 저녁 무렵엔 우럭이 곧잘 문다더군."}]'::jsonb, '{"xp": 1241}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_suchil', 3, '헤매지 않게', '만조의 갑문에서 낚시를 한다', '{"at": ["tide_gate"], "tasks": [{"t": "fish", "r": ["tide_gate"], "n": 2}]}'::jsonb, '[{"s": null, "t": "염수칠은 떨리는 손으로 생선을 굽고 그릇 두 개에 나눠 담았다. 한 그릇은 뱃머리에 올려 두었다."}, {"s": null, "t": "해가 지자 갑문 아래가 금세 캄캄해졌다. 뱃머리의 그릇이 어둠 속에 묻혀 보이지 않았다."}, {"s": "q:dh_suchil", "t": "이래서는 안 되지. 배만 오고 사람은 길을 잃으면 어쩌나."}, {"s": "q:dh_suchil", "t": "내가 늘 그랬잖나. 누가 지키고 있어야 혹시 배가 와도 헤매지 않는다고."}, {"s": "q:dh_suchil", "t": "등잔 두 개만 지어 주게. 하나는 뱃머리에, 하나는 갑문 기둥에 걸 걸세. 황지에 등롱 어유만 있으면 된다더군."}]'::jsonb, '{"xp": 1241}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_suchil', 4, '밥 식었다', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["tide_gate"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 2}], "give": {"fish_oil_lamp": 2}}'::jsonb, '[{"s": null, "t": "뱃머리와 갑문 기둥에 등잔을 걸자 물목에 노란 길 하나가 생겼다. 물결이 그 빛을 따라 잔잔하게 흔들렸다."}, {"s": null, "t": "염수칠은 갑문 계단에 앉아 제 그릇을 비웠다. 뱃머리의 그릇은 김이 다 빠지도록 그대로였다."}, {"s": null, "t": "밤이 깊었을 때 배가 아주 조금 기울었다. 누가 뱃전에 걸터앉는 것처럼. 노걸이의 노가 엄지를 위로 올린 쪽으로 한 번 돌아갔다."}, {"s": "q:sx_sudol", "t": "아버지."}, {"s": "q:dh_suchil", "t": "……늦었구나. 밥 식었다."}, {"s": null, "t": "그 말 뒤로는 아무 소리도 없었다. 염수칠은 등잔 심지를 돋우고 다시 자리에 앉았다."}, {"s": "q:dh_suchil", "t": "이제 기다릴 게 하나 줄었구먼. 그래도 내일도 불 켜 둘 걸세. 저놈은 저녁을 늦게 먹는 버릇이 있거든."}]'::jsonb, '{"xp": 1241, "gil": 101, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
