on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_tide_pulley' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_tide_pulley', 1, '연장을 넘기는 날', '연장을 넘기는 날', '{"at": ["tide_gate"]}'::jsonb, '[{"s": null, "t": "갑문 둑 위에서 늙은 목수가 연장 궤짝을 손녀 앞에 밀어 놓고 있었다. 손녀는 궤짝에 손을 대지 않았다."}, {"s": "q:sx_ganseok", "t": "이제 네 거다. 나는 손이 떨려서 대패가 안 잡혀."}, {"s": "q:sx_mulsae", "t": "할아버지, 저는 도르래를 혼자 깎아 본 적이 한 번도 없어요. 늘 옆에서 잡아 드리기만 했잖아요."}, {"s": "q:sx_ganseok", "t": "잡아 봤으면 됐지. 깎는 건 손이 알아."}, {"s": null, "t": "나는 물새에게 무엇부터 하면 되느냐고 물었다."}, {"s": "q:sx_mulsae", "t": "큰 만조 전에 낡은 바퀴를 갈아야 해요. 바닷물을 먹어도 안 썩는 나무가 있어야 하는데……."}, {"s": "q:sx_ganseok", "t": "강화 부적목. 갑문 둑 나무 더미를 뒤지면 두어 토막은 나온다. 조사원, 우리 애 대신 좀 찾아 주게. 이 애는 아직 둑 끝까지 가는 것도 무서워해."}, {"s": "q:sx_mulsae", "t": "안 무서워요!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_tide_pulley', 2, '쇠사슬을 끊는 집게', '강화 부적목을(를) 모은다', '{"at": ["tide_gate"], "tasks": [{"t": "gather", "items": ["reinforced_lumber"], "r": ["tide_gate"], "n": 2}]}'::jsonb, '[{"s": null, "t": "강화 부적목을 안고 돌아오니, 도르래 쇠사슬이 끼익 소리를 내며 흔들리고 있었다. 사슬 마디마다 커다란 게가 매달려 집게질을 했다."}, {"s": "q:sx_mulsae", "t": "저것들이 또 왔어요! 사슬을 끊어 놓으면 갑문이 반만 닫혀요."}, {"s": "q:sx_ganseok", "t": "해마다 이맘때 올라오는 도르래 집게다. 내가 젊을 땐 장대로 쳐서 떨궜는데."}, {"s": null, "t": "간석이 장대를 집어 들다가 허리를 짚고 주저앉았다. 물새가 얼른 그 장대를 빼앗았다."}, {"s": "q:sx_mulsae", "t": "할아버지는 앉아 계세요. 제가…… 아니, 조사원님이 해 주실 거예요."}, {"s": "q:sx_ganseok", "t": "그새 남한테 미루는 것부터 배웠구먼."}, {"s": "q:sx_ganseok", "t": "조사원, 사슬에 붙은 놈 셋만 떨궈 주게. 셋이 우두머리 노릇을 해서, 셋만 내려가면 나머지는 저절로 물로 들어가."}]'::jsonb, '{"xp": 1241}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_tide_pulley', 3, '대패를 쥔 손', '도르래 집게을(를) 물리친다', '{"at": ["tide_gate"], "tasks": [{"t": "win", "m": ["r71_tide_3"], "n": 3}]}'::jsonb, '[{"s": null, "t": "마지막 집게가 물로 떨어지자 사슬이 조용해졌다. 물새는 강화 부적목 앞에 앉아 대패를 쥐었다가 내려놓기를 몇 번이나 되풀이했다."}, {"s": "q:sx_mulsae", "t": "할아버지가 한 번만 먼저 깎아 보여 주시면 안 돼요?"}, {"s": "q:sx_ganseok", "t": "안 된다. 내가 손을 대면 내 도르래지 네 도르래냐."}, {"s": "q:sx_mulsae", "t": "틀리면요? 큰 만조에 바퀴가 쪼개지면요?"}, {"s": "q:sx_ganseok", "t": "그럼 다시 깎아. 나는 처음 바퀴를 네 번 쪼갰다."}, {"s": null, "t": "물새가 눈을 크게 떴다. 그런 이야기는 처음 듣는다는 얼굴이었다."}, {"s": "q:sx_ganseok", "t": "조사원, 나무를 결대로 켜서 가공 부적목으로 세 토막만 만들어 주게. 그다음 깎는 건 이 애 몫이야. 거기까진 남이 거들어도 흉이 아니지."}]'::jsonb, '{"xp": 1241}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_tide_pulley', 4, '바퀴살 하나', '가공 부적목을(를) 만든다, 가공 부적목을(를) 넘긴다', '{"at": ["tide_gate"], "tasks": [{"t": "craft", "items": ["lumber"], "n": 3}], "give": {"lumber": 3}}'::jsonb, '[{"s": null, "t": "물새는 밤새 바퀴를 깎았다. 새벽녘에 낡은 바퀴를 떼어 내자, 그 바퀴살 하나에 서툴게 새긴 새 그림이 보였다."}, {"s": "q:sx_mulsae", "t": "이게 뭐예요? 할아버지가 그림도 새기셨어요?"}, {"s": "q:sx_ganseok", "t": "내가 그렸으면 그렇게 못 그렸겠지."}, {"s": "q:sx_ganseok", "t": "네가 일곱 살 때 내 무릎에 앉아서 끌을 쥐고 놓질 않았어. 그 바퀴살 하나는 네가 깎은 거다. 사십 년 돈 바퀴 가운데 열두 해를 그 살이 버텼어."}, {"s": "q:sx_mulsae", "t": "……."}, {"s": null, "t": "밀물이 들어오자 새 도르래가 길게 울며 갑문 날개를 들어 올렸다. 소리가 낡은 바퀴와 똑같았다."}, {"s": "q:sx_ganseok", "t": "들었냐. 손이 안다니까."}, {"s": null, "t": "물새는 낡은 바퀴에서 새 그림이 새겨진 살 하나를 빼내어 품에 넣었다. 그리고 새 바퀴살에 작은 새를 한 마리 더 새겼다."}]'::jsonb, '{"xp": 1241, "gil": 101, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
