delete from public.world_quest_steps where quest_id = 'sq110_f_river' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_river', 1, '갑문 아래의 독', '갑문 아래의 독', '{"at": ["tide_gate"]}'::jsonb, '[{"s": null, "t": "만조의 갑문 위에서 청파가 물속을 내려다보고 있었다. 잠수꾼 옷 대신 뱃사람 옷을 입고 있었다."}, {"s": "q:sn_cheongpa", "t": "이제 깊이 들어가지 않습니다. 대신 갑문 물길을 맡았어요. 동생과 한 약속이니까요."}, {"s": "q:sn_cheongpa", "t": "요즘 갑문 아래에 해초 독해파리가 끓어서 연맹 배가 못 지나갑니다. 촉수에 스치면 몸이 굳어요."}, {"s": "q:sn_cheongpa", "t": "저 혼자 걷어 내기엔 숫자가 많습니다. 세 무리만 쳐 주십시오."}, {"s": null, "t": "나는 갑문 난간에 걸린 낡은 장부 상자를 보았다. 연맹의 매듭이 묶여 있었다."}, {"s": "q:sn_cheongpa", "t": "연맹 뱃길 장부 사본입니다. 갑문을 지나는 배는 다 여기 적혀요. 나중에 보여 드리지요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_river', 2, '「물제비」', '해초 독해파리을(를) 물리친다', '{"at": ["tide_gate"], "tasks": [{"t": "win", "m": ["r71_tide_4"], "n": 3}]}'::jsonb, '[{"s": null, "t": "독해파리가 흩어진 물 밑에 배 한 척의 이물이 박혀 있었다. 썩은 판자에 「물제비」라는 글씨가 남아 있었다."}, {"s": "q:sn_cheongpa", "t": "……물제비. 아버지 배입니다. 서른 해 전에 갑문을 나가서 안 돌아왔어요."}, {"s": null, "t": "청파가 장부 사본을 펼쳤다. 물제비 줄은 떠난 날만 적혀 있고, 돌아온 날 칸은 비어 있었다."}, {"s": "q:sn_cheongpa", "t": "연맹은 안 돌아온 배를 「가라앉음」이라고 적지 않습니다. 칸을 비워 둡니다. 어릴 땐 그게 미웠어요. 아무도 끝을 말해 주지 않으니까."}, {"s": "q:sn_cheongpa", "t": "옛 뱃사람들 말이 있습니다. 연맹 사람이 수귀가 되면 비늘에 연맹 매듭 무늬가 돋는다고요."}, {"s": "q:sn_cheongpa", "t": "갑문 돌에 붙은 수귀 비늘을 세 장만 떼어 주십시오. 아버지 배 사람들이 수귀가 되었는지 알고 싶습니다."}]'::jsonb, '{"xp": 1333}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_river', 3, '비워 둔 까닭', '수귀 비늘을(를) 모은다', '{"at": ["tide_gate"], "tasks": [{"t": "gather", "items": ["drowned_scale"], "r": ["tide_gate"], "n": 3}]}'::jsonb, '[{"s": null, "t": "비늘 세 장 어디에도 매듭 무늬는 없었다. 청파는 비늘을 오래 만지작거렸다."}, {"s": null, "t": "갑문 계단을 따라 장부를 든 여인이 올라왔다. 말보다 걸음이 빨랐다."}, {"s": "river_alliance:maehyang", "t": "청파 씨가 물제비 칸을 채우겠다고 했다면서요. 그래서 원본을 들고 왔어요."}, {"s": "river_alliance:maehyang", "t": "돌아온 날 칸을 비워 두면 그 배는 아직 오는 중이에요. 오는 중인 사람은 이름이 잊히지 않아요. 누군가는 갑문에서 그 배를 기다리니까요."}, {"s": "river_alliance:maehyang", "t": "그래서 수귀가 안 된 거예요. 장사는 거짓말을 안 하는 게 제일 남는 장사라지만, 이 칸만은 거짓말이 아니라 기다림이에요."}, {"s": "q:sn_cheongpa", "t": "그럼 흑파 칸도요."}, {"s": "river_alliance:maehyang", "t": "그 칸은 가족이 정해요. 채우든 비우든."}, {"s": "q:sn_cheongpa", "t": "……아버지는 만조 때면 이 갑문에서 낚싯줄을 드리우셨습니다. 배가 들어오면 제일 먼저 보려고요. 저도 한번 그래 보고 싶습니다. 같이 드리워 주시겠습니까."}]'::jsonb, '{"xp": 1333}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_river', 4, '기다리는 사람', '만조의 갑문에서 낚시를 한다', '{"at": ["tide_gate"], "tasks": [{"t": "fish", "r": ["tide_gate"], "n": 2}]}'::jsonb, '[{"s": null, "t": "물이 차오르자 갑문 너머 물안개 속에서 등불 하나가 흔들렸다. 등불 아래로 작은 배의 그림자가 스쳐 갔다가 사라졌다."}, {"s": "q:sn_cheongpa", "t": "아버지 배는 저렇게 작았군요. 어릴 땐 집채만 해 보였는데."}, {"s": null, "t": "청파는 붓을 들어 물제비 줄에 가져갔다. 그러나 돌아온 날 칸은 건드리지 않았다."}, {"s": null, "t": "청파는 그 옆 여백에 한 줄을 적었다. 「기다리는 사람: 청파」. 흑파의 줄에도 같은 글을 적었다."}, {"s": "river_alliance:maehyang", "t": "그런 칸은 장부에 처음 생기네요."}, {"s": "q:sn_cheongpa", "t": "끝은 말하지 않겠습니다. 대신 누가 기다리는지는 적어 두겠습니다. 제가 없어도 누가 이어 기다리게요."}, {"s": "river_alliance:maehyang", "t": "그럼 사본마다 그 칸을 만들어 둘게요. 셈은 제가 할 테니 기다리는 건 청파 씨가 하세요."}]'::jsonb, '{"xp": 1333, "gil": 105, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
