values ('sq110_s_eunsil', 'side', '제작·적월 제단터', '흰 달의 제자', '흰 달로 약을 달이는 노파가 제자를 찾는다', 'crimson_altar', 25, '{sq_red_moon_fort_2}'::text[], null, 1142, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_s_eunsil' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_eunsil', 1, '제자를 구하는 약방', '제자를 구하는 약방', '{"at": ["crimson_altar"]}'::jsonb, '[{"s": null, "t": "적월 제단터 한쪽에 천막이 쳐져 있었다. 천막 안에는 다친 교도들이 줄지어 누워 있었고, 허리 굽은 노파가 그 사이를 오가며 약을 먹이고 있었다."}, {"s": "q:rn_eunsil", "t": "야행국 사람 아닌가. 네 해 전에 흰 달빛으로 정수를 뽑아 준 그 손이구먼."}, {"s": "q:rn_eunsil", "t": "제단 의식이 잦아지면서 다치는 놈이 늘었어. 월식성 약방에서 여기까지 오가자니 내 다리가 버티질 못해."}, {"s": "q:rn_eunsil", "t": "그래서 제자를 하나 들이려는데, 하겠다는 놈이 이 계집아이 하나뿐이야."}, {"s": "q:sx_hongdan", "t": "저 할 수 있어요! 약 이름도 벌써 다섯 개나 외웠어요. 안신탕, 청심환, 영초 차, 그리고…… 그리고 붉은 달 정수요!"}, {"s": "q:rn_eunsil", "t": "그런 약은 없다. 흰 달이라고 몇 번을 말해."}, {"s": "q:rn_eunsil", "t": "조사원, 이 아이 시험 좀 같이 봐 주게. 먼저 약재부터. 제단 돌 틈에 푸르게 고인 요기 결정을 세 덩이 모아 오게. 이 아이가 그걸 알아보는지 보자고."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_eunsil', 2, '첫 번째 시험', '요기 결정을(를) 모은다', '{"at": ["crimson_altar"], "tasks": [{"t": "gather", "items": ["spirit_dust"], "r": ["crimson_altar"], "n": 3}]}'::jsonb, '[{"s": null, "t": "요기 결정을 늘어놓자 홍단이 눈을 반짝이며 하나를 집어 들었다. 노파가 홍단에게 어느 것이 제일 좋은지 골라 보라고 했다."}, {"s": "q:sx_hongdan", "t": "이거요! 제일 크고 제일 빨개요."}, {"s": "q:rn_eunsil", "t": "틀렸다. 붉은 건 제단 피를 먹은 거야. 약에 넣으면 잠을 더 못 자."}, {"s": null, "t": "홍단은 입술을 깨물더니 이번에는 가장 작고 푸르스름한 조각을 골랐다. 노파가 아무 말 없이 고개를 한 번 끄덕였다."}, {"s": null, "t": "그때 천막 위로 날갯짓 소리가 몰려왔다. 붉은 달을 따라다니는 박쥐 떼가 약 냄새를 맡고 내려온 것이었다."}, {"s": "q:rn_eunsil", "t": "저놈들이 천막을 찢으면 누운 놈들이 다 깨. 조사원, 좀 쫓아 주게. 홍단이 너는 환자 곁에 있어."}]'::jsonb, '{"xp": 1333}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_eunsil', 3, '두 번째 시험', '핏달 박쥐을(를) 물리친다', '{"at": ["crimson_altar"], "tasks": [{"t": "win", "m": ["r71_altar_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "박쥐를 쫓고 돌아오니 홍단이 누운 교도의 이마에 젖은 천을 얹고 있었다. 손이 떨리지 않았다."}, {"s": "q:sx_hongdan", "t": "이 오라버니가 아까부터 붉은 달이 온다고 헛소리를 해요. 할머니, 무서워서 그러는 거죠?"}, {"s": "q:rn_eunsil", "t": "그래. 붉은 달을 너무 오래 본 놈들은 꿈에서도 달을 봐. 그래서 안신탕을 먹이는 게야."}, {"s": "q:rn_eunsil", "t": "마지막 시험이다. 조사원이 안신탕을 세 그릇 달일 테니, 홍단이 너는 옆에서 불만 봐라. 불이 세면 약이 쓰고, 약하면 맹탕이야."}, {"s": "q:sx_hongdan", "t": "불만요? 불은 제일 쉬운데요."}, {"s": "q:rn_eunsil", "t": "제일 쉬운 걸 끝까지 하는 놈이 약쟁이가 되는 게야."}]'::jsonb, '{"xp": 1333}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_eunsil', 4, '흰 달 약방', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["crimson_altar"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 3}], "give": {"calm_brew": 3}}'::jsonb, '[{"s": null, "t": "홍단은 안신탕이 다 될 때까지 한 번도 자리를 뜨지 않았다. 볼에 그을음이 묻은 줄도 몰랐다."}, {"s": null, "t": "안신탕을 먹은 교도들의 숨이 하나둘 고르게 바뀌었다. 헛소리를 하던 교도도 조용히 잠들었다."}, {"s": "q:rn_eunsil", "t": "불 조절이 괜찮구먼. 내일부터 약방 문 열 때 와. 늦으면 쫓아낸다."}, {"s": "q:sx_hongdan", "t": "정말요? 그럼 저 이제 흰 달 약방 제자예요?"}, {"s": "q:rn_eunsil", "t": "쉿. 교령 앞에서는 그냥 약방 심부름꾼이라고 해라. 흰 달 소리 하면 너도 나도 끝이야."}, {"s": null, "t": "나는 은실에게 약방이 오래 열려 있겠다고 말했다. 은실이 콧방귀를 뀌었다."}, {"s": "q:rn_eunsil", "t": "내가 아니라 저 아이가 열어 두겠지. 그러니 야행국은 이제 저 아이한테 약초를 갖다 주시게."}]'::jsonb, '{"xp": 1333, "gil": 105, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
