values ('sq110_star_cookoff', 'side', '제작·무극 관성대', '관성대 요리 겨루기', '별빛구이 원조를 두고 다투는 두 관측관', 'star_observatory', 25, '{}'::text[], null, 1143, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_star_cookoff' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_star_cookoff', 1, '원조는 누구인가', '원조는 누구인가', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "관성대 부엌 앞에서 관측관 둘이 국자를 하나씩 들고 서로를 노려보고 있었다."}, {"s": "q:sx_mangseong", "t": "별빛구이는 내가 처음 구웠소. 북두의 일곱째 별이 기울던 밤이었지."}, {"s": "q:sx_yuseong", "t": "거짓말! 그날 밤 생선 뒤집은 건 나야. 넌 옆에서 별만 셌잖아."}, {"s": "q:sx_mangseong", "t": "별을 세며 뒤집는 때를 잰 것이 곧 요리요."}, {"s": null, "t": "둘은 동시에 나를 돌아보았다. 지나가던 조사원이 심사를 맡으면 공정하다는 것이었다. 나는 무엇으로 겨루느냐고 물었다."}, {"s": "q:sx_yuseong", "t": "청새치 별빛구이! 성하 청새치가 있어야 돼. 별빛 벼랑 아래로 맑은 밤에만 올라오는 놈이야. 흐린 날엔 줄을 백 번 내려도 소용없어."}, {"s": "q:sx_mangseong", "t": "우리 둘은 이 다툼 때문에 벼랑에 함께 서지 않기로 맹세했소. 그러니 조사원이 줄을 드리워 주시오."}, {"s": "q:sx_yuseong", "t": "맹세는 얘가 혼자 한 거고!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_star_cookoff', 2, '국자 두 자루', '무극 관성대에서 낚시를 한다', '{"at": ["star_observatory"], "tasks": [{"t": "fish", "r": ["star_observatory"], "n": 3}]}'::jsonb, '[{"s": null, "t": "낚시를 마치고 돌아오니 부엌에 숯불이 두 군데 피어 있었다. 둘은 서로의 화로를 등지고 앉아 있었다."}, {"s": "q:sx_mangseong", "t": "청새치를 낚았다면 한 판은 벌일 수 있겠구려. 빈손이었대도 서운해하지 마오. 그 녀석은 별이 맑은 밤에만, 그것도 몇 밤에 한 번 문다오. 나는 서른 해 동안 일곱 번 보았소."}, {"s": "q:sx_yuseong", "t": "비법은 영초 차야. 굽다가 차를 끼얹어야 껍질에서 별빛이 돌아."}, {"s": "q:sx_mangseong", "t": "차를 끼얹는 건 내 비법이오!"}, {"s": "q:sx_yuseong", "t": "그 차, 원래 내가 마시던 거거든!"}, {"s": null, "t": "둘이 동시에 자기 비법을 외치는 바람에 나는 아무것도 알아듣지 못했다. 다만 숯과 영초 차가 있어야 한다는 것만은 알았다."}, {"s": "q:sx_mangseong", "t": "공정하려면 심사관이 손수 한 번 구워 보아야 하오. 그래야 누구 맛이 원조인지 가릴 혀가 생기지. 청새치가 아직이면 맑은 밤을 골라 벼랑에 다시 서 보시오."}, {"s": "q:sx_yuseong", "t": "그 말은 맞아. 구워 와 봐. 내 걸 먹고 나면 네 건 숯덩이로 보일 거야."}]'::jsonb, '{"xp": 1333}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_star_cookoff', 3, '같은 맛', '청새치 별빛구이을(를) 만든다, 청새치 별빛구이을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["marlin_grill"], "n": 1}], "give": {"marlin_grill": 1}}'::jsonb, '[{"s": null, "t": "내가 구운 별빛구이를 가운데 두고, 둘도 제 것을 한 접시씩 내놓았다. 나는 세 접시를 차례로 맛보았다."}, {"s": null, "t": "세 접시는 맛이 똑같았다. 껍질이 한쪽만 조금 탄 것까지 같았다."}, {"s": "q:sx_yuseong", "t": "……왜 너도 한쪽을 태워?"}, {"s": "q:sx_mangseong", "t": "그대야말로. 그쪽을 태워야 제맛이라고 배웠소."}, {"s": "q:sx_yuseong", "t": "누구한테?"}, {"s": "q:sx_mangseong", "t": "……삼십 년 전, 첫 관측을 하던 밤에 생선을 태운 신참 둘이 있었지."}, {"s": null, "t": "둘이 동시에 입을 다물었다. 부엌이 한참 조용했다."}, {"s": "q:sx_yuseong", "t": "그럼 판정이 안 나잖아! 조사원, 셋째 그릇! 아예 다른 걸로 와서 우리 둘을 다 이겨 봐. 영맥 약선탕 같은 거."}, {"s": "q:sx_mangseong", "t": "좋소. 둘 다 지면 둘 다 원조가 아닌 것이니, 아무도 억울하지 않겠구려."}]'::jsonb, '{"xp": 1333}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_star_cookoff', 4, '원조의 자리', '영맥 약선탕을(를) 만든다, 영맥 약선탕을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["bark_stew"], "n": 1}], "give": {"bark_stew": 1}}'::jsonb, '[{"s": null, "t": "영맥 약선탕을 내려놓자 둘은 말없이 한 그릇씩 비웠다. 그리고 동시에 빈 그릇을 내밀었다."}, {"s": "q:sx_mangseong", "t": "졌소."}, {"s": "q:sx_yuseong", "t": "나도 졌어. 분하지만 맛있어."}, {"s": null, "t": "나는 그럼 별빛구이의 원조는 누구로 할 것이냐고 물었다."}, {"s": "q:sx_mangseong", "t": "관측 일지에 적어 두겠소. 「별빛구이, 그날 밤 생선을 태운 신참 둘」이라고."}, {"s": "q:sx_yuseong", "t": "이름 순서는 내가 먼저야."}, {"s": "q:sx_mangseong", "t": "별자리는 북에서 남으로 읽는 법이오. 내 자리가 북쪽이지."}, {"s": null, "t": "둘은 다시 다투기 시작했다. 그런데 이번엔 한 화로 앞에 나란히 앉아서였다."}, {"s": null, "t": "다음 날 관성대 부엌 벽에 새 차림표가 붙었다. 맨 위 칸에 「영맥 약선탕 — 심사관 원조」라고 적혀 있었고, 그 아래에 작은 글씨로 「인정 못 함」이 두 번 적혀 있었다."}]'::jsonb, '{"xp": 1333, "gil": 105, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
