values ('cq110_paint_2', 'side', '연계·무명 화공의 그림', '압수된 초상', '봉인고에 압수된 초상들이 서로를 부른다', 'seal_vault', 26, '{cq110_paint_1}'::text[], null, 1144, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'cq110_paint_2' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_2', 1, '요물로 적힌 그림', '요물로 적힌 그림', '{"at": ["seal_vault"]}'::jsonb, '[{"s": null, "t": "봉인고 문 앞에서 담채가 창고지기와 마주 서 있었다. 소림이 나를 보고 달려왔다."}, {"s": "q:sx_sorim", "t": "조사원님! 뿌리에서 그린 광부 아저씨 그림 기억하시죠? 그날부터 스승님 그림들이 밤마다 소리를 냈어요. 사람들이 무섭다고 신고해서, 봉인고에서 그림을 전부 거둬 갔어요."}, {"s": "q:sx_mugyeom", "t": "규정입니다. 밤에 소리를 내고, 얼굴이 돌아가는 화폭은 요물로 적어 봉인고에 넣게 되어 있습니다."}, {"s": "q:sx_damchae", "t": "그 안에 있는 사람들은 요물이 아니오. 이름이 남은 사람들이오."}, {"s": "q:sx_mugyeom", "t": "그렇다 해도 지금은 꺼내 드릴 수 없습니다. 그림을 넣은 칸 둘레에 저주 인형 무리가 몰려들었습니다. 얼굴 있는 것을 좋아하는 놈들이라 화폭에 달라붙어 떨어지지 않습니다."}, {"s": "q:sx_mugyeom", "t": "조사원께서 그 무리를 치워 주신다면, 반출 여부는 그다음에 검토하겠습니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_2', 2, '빈 액자 하나', '저주 인형 무리을(를) 물리친다', '{"at": ["seal_vault"], "tasks": [{"t": "win", "m": ["r71_vault_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "인형 무리를 치운 칸 안에 담채의 그림들이 줄지어 세워져 있었다. 그림 속 얼굴들이 모두 같은 쪽을 보고 있었다. 봉인고 문 쪽이었다."}, {"s": "q:sx_sorim", "t": "원래는 다 앞을 보고 있었어요. 다들 나가고 싶은가 봐요."}, {"s": null, "t": "맨 끝 화폭 하나가 비어 있었다. 사람이 서 있던 자리에 먹 자국만 희미하게 남아 있었다."}, {"s": "q:sx_mugyeom", "t": "그 화폭은 사흘 전부터 비어 있었습니다. 기록에는 「여인 하나, 머리에 흰 끈」으로 적혀 있습니다."}, {"s": "q:sx_damchae", "t": "봉인고 안으로 들어간 거요. 저 사람은 여기 들어온 압수물 가운데 제 물건을 찾고 있을 게요."}, {"s": "q:sx_mugyeom", "t": "봉인고 안을 돌아다니게 둘 수는 없습니다. 봉인 먹으로 화폭을 다시 묶겠습니다."}, {"s": "q:sx_damchae", "t": "묶지 마시오. 그 먹으로 내가 다시 그리겠소. 봉인 먹은 번지지 않고 오래가오. 그 먹으로 그리면 선이 칼처럼 서고, 흰 끈의 결까지……. 세 개만 구해 주시오."}]'::jsonb, '{"xp": 1428}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_2', 3, '묶는 먹, 그리는 먹', '봉인 먹을(를) 모은다', '{"at": ["seal_vault"], "tasks": [{"t": "gather", "items": ["sealing_ink"], "r": ["seal_vault"], "n": 3}]}'::jsonb, '[{"s": null, "t": "담채는 봉인 먹으로 빈 화폭 앞에 앉았다. 붓을 대자마자 손이 빨라졌고, 입에서 끊임없이 말이 흘러나왔다."}, {"s": "q:sx_damchae", "t": "머리끈은 흰색이오. 흰색은 칠하는 게 아니라 남겨 두는 거요. 남겨 둔 자리가 끈이 되고, 끈이 묶은 머리가 얼굴을 만들고……."}, {"s": null, "t": "여인이 화폭에 다시 그려지는 동안, 봉인고 안쪽 어딘가에서 흐느끼는 소리가 들리다 멎었다."}, {"s": "q:sx_sorim", "t": "조사원님. 봉인 먹으로 그리니까 그림이 꼭 봉인 같아요. 그리는 게 아니라 묶는 것 같아요."}, {"s": "q:sx_sorim", "t": "스승님은 사람들을 남겨 주는 걸까요, 가둬 두는 걸까요."}, {"s": "q:sx_mugyeom", "t": "반출은 허가합니다. 다만 규정상 화폭마다 정화 부적을 붙여야 합니다. 두 장이면 칸 하나 몫은 됩니다."}]'::jsonb, '{"xp": 1428}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_2', 4, '스승님이 잊는 것', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["seal_vault"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "정화 부적을 붙인 화폭들이 봉인고 밖으로 나왔다. 그림 속 얼굴들은 이제 다시 앞을 보고 있었다."}, {"s": "q:sx_mugyeom", "t": "반출 완료입니다. 다음에 또 소리가 나면 이번엔 태워야 합니다. 그것도 규정입니다."}, {"s": "q:sx_damchae", "t": "……고맙소."}, {"s": null, "t": "담채가 화폭을 수레에 싣는 동안, 소림이 낮은 목소리로 말을 꺼냈다."}, {"s": "q:sx_sorim", "t": "조사원님, 아무한테도 말 안 했는데요. 스승님이 요새 제 이름을 한 번씩 못 부르세요. 「얘야」 하고 부르시다가 한참 있다 「소림아」 하세요."}, {"s": "q:sx_sorim", "t": "사람 얼굴도 그리지 않으면 기억을 못 하신대요. 그래서 밤마다 그리시는 거래요. 남의 이름을 남기려고 그리는 줄 알았는데, 어쩌면 스승님이 잊지 않으려고 그리시는 건지도 몰라요."}, {"s": "q:sx_sorim", "t": "그리고 스승님은 그림에 이름을 안 쓰세요. 한 번도요. 그래서 사람들이 스승님을 「무명 화공」이라고 불러요."}, {"s": null, "t": "수레 쪽에서 담채가 소림을 불렀다. 이번에는 이름을 바로 불렀다. 소림은 안도한 얼굴로 뛰어갔다."}]'::jsonb, '{"xp": 1428, "gil": 109, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
