delete from public.world_quest_steps where quest_id = 'sq110_f_mandate' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_mandate', 1, '빈 하루', '빈 하루', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "무극 관성대의 서고에서 서하람이 두꺼운 관측 기록을 펼쳐 놓고 있었다. 눈 밑이 거뭇했다."}, {"s": "q:r71_seoharam", "t": "왔네요. 약속대로 알려 주려고 했는데, 대답 대신 질문이 하나 더 생겼어요."}, {"s": "q:r71_seoharam", "t": "천명원은 하루도 빠짐없이 예언을 적어요. 그런데 딱 하루, 「이날 예언하지 않음」이라고만 적힌 날이 있어요."}, {"s": "q:r71_seoharam", "t": "혜성이 낙하지에 떨어진 날이에요. 그날 밤 하늘은 기록 어디에도 없어요."}, {"s": null, "t": "나는 그날 밤 하늘을 알 길이 있느냐고 물었다."}, {"s": "q:r71_seoharam", "t": "백옥 천문탑의 관측 거울들이요. 거울은 본 것을 잊지 않아요. 그런데 거울에 맺힌 별 그림자가 천문 거울귀가 되어 버렸어요."}, {"s": "q:r71_seoharam", "t": "백옥 천문탑에서 거울귀 세 마리만 깨 주세요. 조각에 그날 밤이 남아 있을지도 몰라요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_mandate', 2, '별 하나가 내려온 밤', '천문 거울귀을(를) 물리친다', '{"at": ["star_observatory"], "tasks": [{"t": "win", "m": ["x_white_tower_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "거울귀의 조각을 관성대 탁자에 늘어놓자 조각마다 같은 밤하늘이 비쳤다. 별 하나가 다른 별들보다 낮게, 땅 쪽으로 기울어 있었다."}, {"s": "q:r71_seoharam", "t": "이 별이에요. 별쇠 무늬에 하나 더 있던 그 별."}, {"s": "q:r71_seoharam", "t": "그런데 이상해요. 이 별은 혜성 꼬리가 아니라 관성대 쪽으로 내려오고 있어요."}, {"s": null, "t": "나는 조각만으로는 별이 어디에 내려앉았는지 모르겠다고 했다."}, {"s": "q:r71_seoharam", "t": "그래서 별모래가 필요해요. 성진사를 조각 위에 뿌리면 그 별이 가리키는 쪽으로 모래알이 늘어서요."}, {"s": "q:r71_seoharam", "t": "혜성 낙하지에서 성진사 세 줌만 거둬 와 주세요. 같은 혜성에서 나온 모래라야 해요."}]'::jsonb, '{"xp": 1428}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_mandate', 3, '아기 울음', '성진사을(를) 모은다', '{"at": ["star_observatory"], "tasks": [{"t": "gather", "items": ["star_sand"], "r": ["comet_crater"], "n": 3}]}'::jsonb, '[{"s": null, "t": "성진사를 뿌리자 모래알이 일제히 한쪽으로 늘어섰다. 모래알이 가리킨 곳은 관성대 안쪽의 낡은 수습 관측생 방이었다."}, {"s": "q:r71_seoharam", "t": "저기는 제가 어릴 때 지내던 방이에요. 저는 아기 때 관성대에 들어왔거든요."}, {"s": null, "t": "하품 소리와 함께 졸린 얼굴의 여인이 계단을 내려왔다. 수석 관측관이었다."}, {"s": "mandate_court:seo", "t": "아… 그 기록을 찾았구나. 그날 밤 나는 당번이었어. 태사령께서 그날만은 하늘을 보지 말라고 하셨지."}, {"s": "mandate_court:seo", "t": "그래서 별은 못 봤어. 대신 수습생 방 쪽에서 아기 울음을 들었지."}, {"s": "q:r71_seoharam", "t": "……그 아기가 누군지는요."}, {"s": "mandate_court:seo", "t": "그건 내가 말할 게 아니야. 성도를 다 펼치면 알 수도 있겠지. 혼천의를 돌리려면 영력이 많이 들어. 영기환 두 알은 있어야 해."}]'::jsonb, '{"xp": 1428}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_mandate', 4, '결론은 쓰지 마라', '영기환을(를) 만든다, 영기환을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["spirit_qi_pill"], "n": 2}], "give": {"spirit_qi_pill": 2}}'::jsonb, '[{"s": null, "t": "서하람이 영기환을 삼키고 혼천의에 손을 얹었다. 그날 밤하늘이 관성대 천장 가득 펼쳐졌다. 낮게 기운 별 하나가 그 한가운데에서 깜빡였다."}, {"s": null, "t": "등 뒤에서 지팡이 소리가 났다. 늙은 태사령이 천장을 올려다보고 있었다."}, {"s": "mandate_court:hahu", "t": "그날 우리는 한 아이의 별을 읽었다. 읽은 것을 입 밖에 내면, 그 아이는 그 별대로 살아야 했다."}, {"s": "mandate_court:hahu", "t": "본 것을 다 말하지 않는 것, 그것이 첫 번째 계율이다. 그래서 그날은 예언하지 않았다."}, {"s": "q:r71_seoharam", "t": "태사령님. 그 아이가 저인가요."}, {"s": null, "t": "태사령은 대답하지 않았다. 그 곁에서 기록을 품은 사관이 붓을 내려놓았다."}, {"s": "mandate_court:mun", "t": "기록은 정확하다. 결론은 쓰지 마라."}, {"s": null, "t": "서하람은 오래 천장을 올려다보다가 제 공책을 펼쳤다. 공책에 이렇게 적었다. 「이날, 나는 내가 고른 별을 보았다.」"}, {"s": "q:r71_seoharam", "t": "더 묻지 않을게요. 대답을 들으면 그 대답대로 살아야 할 것 같아서요."}]'::jsonb, '{"xp": 1428, "gil": 109, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
