values ('sq110_weeping_mirror', 'side', '전투·봉인고', '울음 새는 거울', '밤마다 다른 봉인관의 얼굴로 우는 압수물 거울', 'seal_vault', 26, '{}'::text[], null, 1146, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_weeping_mirror' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_weeping_mirror', 1, '밤마다 우는 압수물', '밤마다 우는 압수물', '{"at": ["seal_vault"]}'::jsonb, '[{"s": null, "t": "봉인고 문 앞에 등불 하나가 걸려 있었다. 등불 아래에서 봉인관 하나가 장부를 넘기고 있었다."}, {"s": "q:sx_mogyeon", "t": "야행국에서 보냈소? 다행이오. 여기 사람들은 이제 밤 당번을 서려 하지 않소."}, {"s": "q:sx_mogyeon", "t": "압수물 가운데 거울이 하나 있는데, 밤마다 우오. 그것까지는 견딜 만했지."}, {"s": "q:sx_mogyeon", "t": "우는 얼굴이 매번 다르오. 그리고 그 얼굴이 하나같이 봉인관이오. 여기서 당번을 서던 사람들 말이오."}, {"s": null, "t": "나는 그 사람들이 지금 어디 있느냐고 물었다."}, {"s": "q:sx_mogyeon", "t": "그걸 묻는 사람이 없어서 내가 묻고 있소. 봉인고 안을 좀 살펴 주시오. 울음이 어느 창고에서 새는지부터 알아야겠소."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_weeping_mirror', 2, '창고 안의 얼굴들', '봉인고을(를) 살핀다', '{"at": ["seal_vault"], "tasks": [{"t": "search", "r": ["seal_vault"], "n": 3}]}'::jsonb, '[{"s": null, "t": "울음은 거울 창고에서 새어 나왔다. 봉인 천이 반쯤 벗겨진 거울 하나가 벽에 기대 서 있었다."}, {"s": null, "t": "거울 속에서 처음 보는 얼굴이 울고 있었다. 눈을 깜빡이자 다른 얼굴이 되었고, 또 깜빡이자 또 다른 얼굴이 되었다."}, {"s": "q:sx_mogyeon", "t": "……공 선배. 저건 남 선배고. 저건 내 앞 당번이던 사람이오."}, {"s": "q:sx_mogyeon", "t": "다들 이 거울을 맡았던 사람들이오. 맡은 지 한 해를 못 넘기고 하나씩 보이지 않게 되었지."}, {"s": null, "t": "거울 표면이 물결처럼 일렁이더니, 울던 얼굴이 웃는 얼굴로 바뀌었다. 거울이 천을 마저 벗고 벽에서 걸어 나왔다."}, {"s": "q:sx_mogyeon", "t": "비친 대로 되돌려 치는 놈이오. 조심하시오. {직업:호위=방패에 비친 제 모습이 먼저 덤벼들 것이오/월궁=화살을 쏘면 화살이 거꾸로 돌아올 것이오/퇴마=진언을 외면 거울이 그 진언을 따라 욀 것이오/의무=다친 데를 보이면 그 상처를 그대로 베껴 올 것이오/봉인=봉인 부적을 들이대면 부적까지 비춰 버릴 것이오/암영=그림자로 숨어도 거울 속엔 그대 그림자가 남을 것이오}."}]'::jsonb, '{"xp": 1428}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_weeping_mirror', 3, '마지막 얼굴', '울음 새는 거울을(를) 물리친다', '{"at": ["seal_vault"], "tasks": [{"t": "win", "m": ["r71_vault_3"], "n": 1}]}'::jsonb, '[{"s": null, "t": "거울이 깨지며 바닥에 흩어졌다. 그런데 조각 하나하나에서 아직도 울음이 새어 나왔다."}, {"s": "q:sx_mogyeon", "t": "깨진 것으로는 안 끝나는구려. 조각마다 결계를 덧대어 다시 묶어야 하오."}, {"s": null, "t": "목연이 조각을 하나씩 주워 들여다보았다. 조각마다 아까 본 봉인관의 얼굴이 하나씩 담겨 있었다."}, {"s": null, "t": "목연이 마지막 조각을 들고 고개를 갸웃했다."}, {"s": "q:sx_mogyeon", "t": "이 사람은 누구요? 처음 보는 얼굴이오."}, {"s": null, "t": "조각 속에서 우는 얼굴은 바로 목연의 얼굴이었다. 그런데 목연이 든 조각 앞에 그가 서 있는데도, 조각에는 그의 모습이 비치지 않았다."}, {"s": null, "t": "나는 아무 말도 하지 않았다. 목연은 조각을 품에 넣고 장부를 다시 끼었다."}, {"s": "q:sx_mogyeon", "t": "봉인고 안쪽 단지 줄에 결계 파편이 흩어져 있을 것이오. 세 조각만 모아 주시오. 조각들을 다 묶어야 오늘 밤 당번을 마칠 수 있소."}]'::jsonb, '{"xp": 1428}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_weeping_mirror', 4, '내일 당번', '결계 파편을(를) 모은다', '{"at": ["seal_vault"], "tasks": [{"t": "gather", "items": ["ward_fragment"], "r": ["seal_vault"], "n": 3}]}'::jsonb, '[{"s": null, "t": "결계 파편을 덧대자 거울 조각들이 하나씩 조용해졌다. 목연의 품에 든 조각 하나만 마지막까지 작게 흐느꼈다."}, {"s": "q:sx_mogyeon", "t": "수고했소. 이제 이 창고도 조용하겠구려."}, {"s": null, "t": "나는 당번 장부를 보여 달라고 했다. 목연은 선선히 장부를 펼쳐 주었다."}, {"s": null, "t": "장부 맨 앞장에는 거울이 들어온 날이 적혀 있었다. 스물세 해 전이었다. 그날 밤 당번 칸에 목연의 이름이 있었다."}, {"s": null, "t": "그 뒤로 스물세 해 동안, 밤 당번 칸은 하루도 빠짐없이 목연의 이름으로 채워져 있었다. 글씨가 날마다 조금씩 달랐다."}, {"s": "q:sx_mogyeon", "t": "내 이름을 날마다 적어 주는 사람이 있어서 내가 아직 여기 있나 보오. 누가 적는지는 나도 모르오."}, {"s": "q:sx_mogyeon", "t": "그 사람이 그만 적고 싶어지면, 나도 그만 서겠지."}, {"s": null, "t": "다음 날 아침 봉인고를 나서다가 당번판을 보았다. 오늘 밤 칸에 먹이 마르지 않은 글씨로 목연의 이름이 적혀 있었다. 봉인고 사람 누구도 자기가 적었다고 하지 않았다."}]'::jsonb, '{"xp": 1428, "gil": 109, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
