values ('sq110_s_chorong', 'side', '전투·봉인고', '막내가 이끄는 호송대', '막내 초롱이 처음으로 호송대장이 되었다', 'seal_vault', 27, '{sq_jade_pass_2}'::text[], null, 1147, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_s_chorong' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_chorong', 1, '첫 호송', '첫 호송', '{"at": ["seal_vault"]}'::jsonb, '[{"s": null, "t": "봉인고 문 앞에 수레 세 대가 줄지어 서 있었다. 맨 앞 수레에 녹슨 등롱 하나가 걸려 있었다. 등롱에는 「청등」 두 글자가 남아 있었다."}, {"s": "q:rn_chorong", "t": "조사원님! 저 기억하세요? 귀신 얘기만 하던 막내요. 여섯 해 지났어요. 이제는 막내가 아니라 대장이에요. 이번이 처음이긴 하지만요."}, {"s": null, "t": "나는 여운비 대장은 어디 있느냐고 물었다."}, {"s": "q:rn_chorong", "t": "대장님은 관문에서 쉬고 계세요. 이번엔 저 혼자 해 보래요. 압수물을 북령에서 봉인고까지 나르는 일이요."}, {"s": "q:sx_bau", "t": "대, 대장님. 수레에서 또 소리가 나요. 바늘 긁는 소리요."}, {"s": "q:rn_chorong", "t": "바우야, 그건 그냥 바퀴 소리야. 대장은 겁먹으면 안 되는 거야."}, {"s": null, "t": "그 순간 수레 덮개가 들썩이더니 헝겊 인형들이 바늘을 들고 쏟아져 나왔다. 초롱이 내 뒤로 쏙 숨었다."}, {"s": "q:rn_chorong", "t": "바퀴 소리가 아니었네요! 조사원님, 부탁해요!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_chorong', 2, '대장의 일', '저주 인형 무리을(를) 물리친다', '{"at": ["seal_vault"], "tasks": [{"t": "win", "m": ["r71_vault_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "인형들이 흩어지자 초롱은 내 등 뒤에서 슬그머니 나와 옷매무새를 고쳤다. 바우가 그런 초롱을 존경하는 눈으로 올려다보았다."}, {"s": "q:sx_bau", "t": "대장님, 방금 조사원님 뒤로 숨으신 거 작전이었죠?"}, {"s": "q:rn_chorong", "t": "……당연하지. 대장은 앞에서 다 보고 있어야 하니까. 뒤에서."}, {"s": null, "t": "나는 웃음을 참으며 덮개가 찢어진 수레를 가리켰다. 압수물 함의 봉인이 반쯤 풀려 있었다."}, {"s": "q:rn_chorong", "t": "봉인을 다시 그어야 봉인고에서 받아 준대요. 봉인 먹이 있어야 하는데, 우리 짐에는 없어요."}, {"s": "q:rn_chorong", "t": "봉인고 안쪽 함 더미랑 문서 더미에 봉인 먹이 흘러 있대요. 세 개만 모아 주세요. 바우야, 너는 수레 지켜."}, {"s": "q:sx_bau", "t": "저 혼자요?"}, {"s": "q:rn_chorong", "t": "등롱 걸어 놨잖아. 그게 있으면 괜찮아. 나도 그렇게 배웠어."}]'::jsonb, '{"xp": 1526}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_chorong', 3, '등롱을 든 아이', '봉인 먹을(를) 모은다', '{"at": ["seal_vault"], "tasks": [{"t": "gather", "items": ["sealing_ink"], "r": ["seal_vault"], "n": 3}]}'::jsonb, '[{"s": null, "t": "봉인 먹을 들고 돌아오니 바우가 청등 등롱을 두 손으로 꼭 쥐고 수레 앞에 서 있었다. 다리는 떨렸지만 자리를 뜨지 않았다."}, {"s": "q:sx_bau", "t": "대장님, 저 안 도망갔어요. 인형이 한 번 더 들썩였는데 등롱을 비추니까 가만히 있었어요."}, {"s": "q:rn_chorong", "t": "……잘했어. 진짜로."}, {"s": null, "t": "초롱은 바우의 머리를 한 번 쓰다듬었다. 여섯 해 전 여운비가 초롱에게 하던 손짓과 똑같았다."}, {"s": "q:rn_chorong", "t": "봉인은 이걸로 그으면 되고, 봉인고에 넘길 때 함마다 정화 부적을 붙여야 한대요. 안 붙이면 접수를 안 해 준대요."}, {"s": "q:rn_chorong", "t": "조사원님, 정화 부적 두 장만 지어 주세요. 저는 그동안 바우한테 봉인 긋는 법을 가르칠게요. 저도 어제 배웠지만요."}]'::jsonb, '{"xp": 1526}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_chorong', 4, '대장님', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["seal_vault"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "정화 부적을 붙인 함들이 하나씩 봉인고 안으로 들어갔다. 봉인관이 장부에 도장을 찍고 초롱에게 접수증을 내주었다."}, {"s": "q:rn_chorong", "t": "받았어요! 한 상자도 안 잃었어요! ……인형 몇 개가 도망가긴 했지만 그건 조사원님이 잡았으니까 안 잃은 거죠?"}, {"s": null, "t": "나는 안 잃은 것으로 치자고 했다. 초롱이 접수증을 가슴에 꼭 안았다."}, {"s": "q:sx_bau", "t": "대장님, 다음 호송 때도 제가 등롱 들어도 돼요?"}, {"s": "q:rn_chorong", "t": "안 돼. 등롱은 대장이 드는 거야."}, {"s": "q:sx_bau", "t": "그럼 저 언제 대장 돼요?"}, {"s": "q:rn_chorong", "t": "네가 귀신 얘기 그만할 때."}, {"s": null, "t": "돌아가는 길에 초롱은 바우에게 잔도의 푸른 등불 이야기를 처음부터 끝까지 들려주었다. 바우는 덜덜 떨면서도 끝까지 들었고, 초롱은 그 이야기를 아주 즐겁게 했다."}]'::jsonb, '{"xp": 1526, "gil": 113, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
