insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_black_tide_lamps', 1, '돌아오지 않은 배 셋', '돌아오지 않은 배 셋', '{"at": ["black_tide_rift"]}'::jsonb, '[{"s": null, "t": "균열 가장자리 바위에 늙은 여인이 앉아 검은 물을 내려다보고 있었다. 무릎 위에 빈 등잔 셋이 놓여 있었다."}, {"s": "q:sx_bongnim", "t": "서른 해 전 이맘때 배 셋이 이 균열로 들어갔어. 하나도 안 나왔지."}, {"s": "q:sx_bongnim", "t": "해마다 등을 띄웠는데, 올해는 기름이 없어. 기름 낼 고기도 이제 내 손으로는 못 낚아."}, {"s": null, "t": "나는 어떤 고기가 필요하냐고 물었다."}, {"s": "q:sx_bongnim", "t": "초롱아귀. 머리에 초롱을 단 놈. 아니면 먹장어라도 돼. 둘 다 이 물 밑에 사니까, 줄 몇 번 내려 보면 걸릴 거야."}, {"s": "q:sx_bongnim", "t": "우리 영감이 늘 그랬어. 이 균열 고기는 사람을 기다렸다가 문다고."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_black_tide_lamps', 2, '기름 짜기', '흑조 균열에서 낚시를 한다', '{"at": ["black_tide_rift"], "tasks": [{"t": "fish", "r": ["black_tide_rift"], "n": 3}]}'::jsonb, '[{"s": null, "t": "낚은 고기를 내려놓자 복림이 손끝으로 비늘을 쓸어 보았다. 손이 많이 떨렸다."}, {"s": "q:sx_bongnim", "t": "기름은 자네가 짜 주게. 나는 칼을 잡으면 영감 생각이 나서 손이 안 움직여."}, {"s": "q:sx_bongnim", "t": "초롱아귀는 초롱만 짜면 되고, 먹장어는 두 마리를 짜야 한 병이 나와. 등롱 어유 두 병이면 등잔 셋은 밝혀."}, {"s": null, "t": "나는 다른 집 식구들은 오지 않느냐고 물었다."}, {"s": "q:sx_bongnim", "t": "다 떠났어. 서른 해야. 남은 건 나 하나."}, {"s": "q:sx_bongnim", "t": "처음엔 열한 집이 같이 등을 띄웠어. 해마다 한 집씩 안 오더라."}]'::jsonb, '{"xp": 1627}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_black_tide_lamps', 3, '열한 개의 이름', '등롱 어유을(를) 만든다, 등롱 어유을(를) 넘긴다', '{"at": ["black_tide_rift"], "tasks": [{"t": "craft", "items": ["lantern_oil"], "n": 2}], "give": {"lantern_oil": 2}}'::jsonb, '[{"s": null, "t": "등롱 어유 두 병을 건네자 복림이 품에서 붓을 꺼냈다. 붓끝이 다 닳아 있었다."}, {"s": "q:sx_bongnim", "t": "등에는 이름을 적어야 해. 그래야 물 밑에서 제 등인 줄 알고 따라 올라오지."}, {"s": "q:sx_bongnim", "t": "배 셋에 열한 사람이 탔어. 그 이름을 다 기억하는 사람이 이제 나밖에 없어. 그래서 내가 적어."}, {"s": null, "t": "복림은 막힘 없이 이름을 불렀다. 뱃머리 잡던 사람, 그물 던지던 사람, 그해 처음 배에 오른 열다섯 살 아이까지 열한 이름이 모두 나왔다."}, {"s": null, "t": "마지막에 부른 이름이 복림의 남편이었다. 그 이름을 부를 때만 목소리가 조금 낮아졌다."}, {"s": "q:sx_bongnim", "t": "등잔 셋을 만들어 주게. 배 하나에 하나씩. 기름을 잘 먹여서, 균열 바닥까지 꺼지지 않게."}]'::jsonb, '{"xp": 1627}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_black_tide_lamps', 4, '열두 번째 이름', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["black_tide_rift"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 3}], "give": {"fish_oil_lamp": 3}}'::jsonb, '[{"s": null, "t": "복림은 등잔 셋에 열한 이름을 나눠 적었다. 그런데 셋째 등잔 끝에 한 줄을 비워 두었다."}, {"s": null, "t": "나는 그 자리는 누구 것이냐고 물었다."}, {"s": "q:sx_bongnim", "t": "내 자리야. 자네가 적어 줘."}, {"s": "q:sx_bongnim", "t": "내가 가고 나면 나 대신 등 띄워 줄 사람이 없잖아. 그럼 영감이 물 밑에서 나를 못 알아볼 거야. 미리 적어 두면, 이 등 따라 내려갈 때 같이 갈 수 있겠지."}, {"s": null, "t": "나는 복림이 불러 주는 대로 그 이름을 적었다. 복림은 그 글씨를 오래 들여다보더니 고개를 끄덕였다."}, {"s": "q:sx_bongnim", "t": "글씨 곱네. 영감이 질투하겠어."}, {"s": null, "t": "등잔 셋이 검은 물결 위로 천천히 흘러갔다. 균열 한가운데서 등불이 하나씩 물 밑으로 가라앉았다."}, {"s": null, "t": "마지막 등이 가라앉고 한참 뒤, 깊은 곳에서 작은 불빛 하나가 잠깐 올라왔다가 다시 내려갔다. 복림은 그쪽을 보지 않고 일어섰다. 내년에도 오겠다고 했다."}]'::jsonb, '{"xp": 1627, "gil": 117, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
