values ('sq110_dragon_soup', 'side', '제작·흑조 균열', '흑룡 어보탕', '이 탕을 먹고 죽는 게 소원이라는 미식가', 'black_tide_rift', 28, '{}'::text[], null, 1149, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_dragon_soup' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_dragon_soup', 1, '죽기 전 소원', '죽기 전 소원', '{"at": ["black_tide_rift"]}'::jsonb, '[{"s": null, "t": "균열 어귀 바위에 상다리가 부러질 듯한 밥상이 차려져 있었다. 노인 하나가 그 앞에 앉아 숟가락으로 상을 두드리고 있었다."}, {"s": "q:sx_matbong", "t": "오, 젊은이! 내 소원을 들어주러 왔구려."}, {"s": "q:sx_matbong", "t": "이 맛봉, 팔도의 진미를 다 맛보았으나 단 하나를 못 먹었소. 흑룡 어보탕! 그 탕 한 그릇을 먹고 눈을 감는 것이 평생 소원이오."}, {"s": "q:sx_dolbok", "t": "할아버지, 그 말씀 올해만 스무 번째예요."}, {"s": "q:sx_matbong", "t": "스무 번 말했으면 스무 번 진심인 게지."}, {"s": null, "t": "나는 정말 먹고 나면 눈을 감을 셈이냐고 물었다. 돌복이 내 소매를 슬쩍 잡아당겼다."}, {"s": "q:sx_dolbok", "t": "걱정 마세요. 우리 할아버지는 밥상 앞에서 한 번도 진심이었던 적이 없어요."}, {"s": "q:sx_matbong", "t": "탕에는 봉연 흑룡어가 들어가오. 피안개 짙은 날 이 물 밑에서 딱 한 번 몸을 드러낸다지. 우선 줄부터 몇 번 드리워 물맛을 보시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_dragon_soup', 2, '게 떼의 밥상 습격', '흑조 균열에서 낚시를 한다', '{"at": ["black_tide_rift"], "tasks": [{"t": "fish", "r": ["black_tide_rift"], "n": 2}]}'::jsonb, '[{"s": null, "t": "낚시를 마치고 돌아오니 밥상 위가 시꺼멨다. 검은 게 떼가 반찬 그릇마다 집게를 넣고 있었다."}, {"s": "q:sx_matbong", "t": "이놈들! 그건 서른 해 묵은 간장이란 말이오!"}, {"s": "q:sx_dolbok", "t": "할아버지가 균열 앞에 밥상을 차리니까 그렇잖아요. 날마다 게한테 밥 주는 거예요."}, {"s": "q:sx_matbong", "t": "진미를 기다리는 자는 진미가 사는 곳에서 기다리는 법이오."}, {"s": null, "t": "게 한 마리가 맛봉의 숟가락을 물고 달아났다. 맛봉이 벌떡 일어나더니 그대로 다시 앉았다. 무릎이 안 따라 준다고 했다."}, {"s": "q:sx_dolbok", "t": "조사원님, 상 위에 올라온 놈들만 좀 치워 주세요. 저 숟가락이 할아버지 보물이에요."}]'::jsonb, '{"xp": 1627}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_dragon_soup', 3, '흑룡어는 오늘도 없다', '검은 게 떼을(를) 물리친다', '{"at": ["black_tide_rift"], "tasks": [{"t": "win", "m": ["x_black_tide_rift_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "게를 쫓아내자 돌복이 숟가락을 닦아 할아버지 손에 쥐여 주었다. 맛봉은 숟가락을 품에 꼭 안고 물 쪽을 기웃거렸다."}, {"s": "q:sx_matbong", "t": "그래, 흑룡어는 낚였소?"}, {"s": null, "t": "나는 바구니를 내밀었다. 걸려 올라온 것은 눈 없는 먹장어뿐이었다."}, {"s": "q:sx_matbong", "t": "이런 것은 진미가 아니오. 흑조 먹장어는 이 균열에서 아무 날이나 무는 놈이오. 아무 날이나 무는 고기에 무슨 격이 있겠소."}, {"s": "q:sx_dolbok", "t": "할아버지, 오늘 하늘 보세요. 피안개는커녕 구름도 없어요. 흑룡어 기다리다가 진짜로 굶어서 눈 감으시겠어요."}, {"s": null, "t": "돌복이 나를 밥상 뒤로 끌고 갔다."}, {"s": "q:sx_dolbok", "t": "조사원님, 그 먹장어 구워 주세요. 구우면 기름이 지글지글해서 냄새가 끝내줘요. 할아버지는 냄새에 약하세요. 아무 말 말고 상에 그냥 올려 두시면 돼요."}]'::jsonb, '{"xp": 1627}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_dragon_soup', 4, '새 소원', '먹장어 구이을(를) 만든다, 먹장어 구이을(를) 넘긴다', '{"at": ["black_tide_rift"], "tasks": [{"t": "craft", "items": ["hagfish_grill"], "n": 1}], "give": {"hagfish_grill": 1}}'::jsonb, '[{"s": null, "t": "먹장어 구이를 상 귀퉁이에 내려놓자 기름 타는 냄새가 균열 어귀에 퍼졌다. 맛봉은 고개를 돌린 채 코만 실룩였다."}, {"s": "q:sx_matbong", "t": "나는 안 먹소. 흑룡 어보탕 말고는 입에 대지 않기로 했소."}, {"s": null, "t": "돌복이 아무 말 없이 젓가락을 상 위에 놓았다. 맛봉의 손이 젓가락 쪽으로 슬금슬금 움직였다."}, {"s": "q:sx_matbong", "t": "……맛만 보는 것이오. 진미를 아는 자는 진미 아닌 것도 알아야 하니까."}, {"s": null, "t": "맛봉은 맛만 본다면서 한 접시를 다 비웠다. 마지막 한 점은 숟가락으로 긁어 먹었다."}, {"s": "q:sx_matbong", "t": "……안 되겠소."}, {"s": "q:sx_dolbok", "t": "할아버지?"}, {"s": "q:sx_matbong", "t": "아무 날이나 무는 고기가 이렇게 맛있으면, 흑룡어는 대체 얼마나 맛있단 말이오! 그걸 먹기 전에는 죽을 수가 없소. 아니, 이 구이를 한 접시 더 먹기 전에도 못 죽겠소."}, {"s": "q:sx_matbong", "t": "젊은이, 새 소원이 생겼소. 먹장어 구이를 날마다 한 접시씩 먹다가, 피안개 끼는 날 흑룡 어보탕을 먹고 눈을 감는 것이오."}, {"s": "q:sx_dolbok", "t": "그럼 피안개 끼는 날만 숨겨 드리면 되겠네요."}, {"s": null, "t": "돌복이 크게 한숨을 쉬었다. 그런데 그 한숨 끝에 웃음이 섞여 있었다."}]'::jsonb, '{"xp": 1627, "gil": 117, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
