delete from public.world_quest_steps where quest_id = 'sq110_f_lotus2' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_lotus2', 1, '젖어 드는 장부고', '젖어 드는 장부고', '{"at": ["under_root"]}'::jsonb, '[{"s": null, "t": "지맥의 뿌리 가장 깊은 갱도 끝에 돌문 하나가 있었다. 반석과 구슬이 문 앞에서 흘러내리는 물줄기를 바라보고 있었다."}, {"s": "q:bl_banseok", "t": "여기가 회원 장부를 두는 장부고요. 바깥사람한테 보여 주는 건 처음이오."}, {"s": "black_lotus:guseul", "t": "딱, 딱. 보여 준 게 아니라 일손을 빌린 거예요. 장부엔 그렇게 적을게요."}, {"s": "black_lotus:guseul", "t": "보름 전부터 수맥이 장부고 쪽으로 틀어졌어요. 물에 깃든 수맥귀들이 벽 틈으로 스며들어요. 장부가 젖으면 먹이 번지고, 먹이 번지면 이름이 흐려져요."}, {"s": null, "t": "돌문 아래로 스며든 물이 검게 물들어 있었다. 먹이 풀린 물이었다."}, {"s": "q:bl_banseok", "t": "회원 셋이 벌써 제 호칭을 듣고도 늦게 돌아보오. 수맥귀부터 몰아내 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_lotus2', 2, '돌아온 열셋째', '지하 수맥귀을(를) 물리친다', '{"at": ["under_root"], "tasks": [{"t": "win", "m": ["x_under_root_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "수맥귀가 흩어지자 장부고 안의 서가가 드러났다. 아래 칸 장부들이 물을 먹어 부풀어 있었다."}, {"s": null, "t": "맨 위 칸에는 검은 끈으로 몇 겹이나 묶인 장부 한 권이 따로 놓여 있었다. 구슬은 그 장부에서 눈을 돌렸다."}, {"s": "black_lotus:guseul", "t": "저건 회주님 장부예요. 저도 펼쳐 본 적 없어요. 건드리지 마세요."}, {"s": null, "t": "그때 갱도 쪽에서 낯선 사내가 들어왔다. 회원의 검은 띠를 매지 않은 사내였다."}, {"s": "q:sx_deuksu", "t": "반석 형님. 열셋째일세. 아니, 이제 득수지."}, {"s": "q:bl_banseok", "t": "득수. 이름을 되찾아 장가간다고 나간 녀석이 여긴 왜 왔나."}, {"s": "q:sx_deuksu", "t": "집사람이 지난겨울에 갔네. 아이도 없고. 바깥에선 이제 아무도 내 이름을 안 부르네. 이름이 다시 맡겨 달라고 우는 것 같아서 왔어."}, {"s": "black_lotus:guseul", "t": "다시 맡기려면 적을 먹부터 있어야겠네요. 젖은 장부도 다 고쳐 써야 하고요. 뿌리 사이에서 먹정을 세 덩이만 캐다 주세요."}]'::jsonb, '{"xp": 1627}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_lotus2', 3, '맡기면 빚이 생긴다', '먹정을(를) 모은다', '{"at": ["under_root"], "tasks": [{"t": "gather", "items": ["inkstone"], "r": ["under_root"], "n": 3}]}'::jsonb, '[{"s": null, "t": "구슬은 먹정을 갈아 번진 이름들을 한 줄씩 고쳐 썼다. 득수의 차례가 오자 붓을 멈췄다."}, {"s": "black_lotus:guseul", "t": "득수 씨. 다시 맡기면 다시 빚이 생겨요. 이자도 붙고요. 그 빚 때문에 나가셨잖아요."}, {"s": "q:sx_deuksu", "t": "아네. 빚이 있어도 불러 주는 사람이 있는 게 낫네."}, {"s": "q:bl_banseok", "t": "내가 불러 주겠다. 열셋째라고."}, {"s": "q:sx_deuksu", "t": "형님, 그건 호칭이지 이름이 아니잖나."}, {"s": null, "t": "반석이 말을 잇지 못했다. 그때 장부고 벽 너머에서 무언가가 긁는 소리가 났다. 맨 위 칸의 검은 끈 장부가 저 혼자 떨렸다."}, {"s": null, "t": "갱도 어둠 속에서 검은 옷의 사람이 걸어 나왔다. 반석과 구슬이 동시에 고개를 숙였다."}, {"s": "black_lotus:mumyeong", "t": "물길을 튼 것은 뿌리 속에 숨은 놈이다. 내 장부 냄새를 맡고 벽을 갉아 왔지. 내 이름을 노리는 것이다."}, {"s": "black_lotus:mumyeong", "t": "조사원. 값은 장부에 적어 두마. 뿌리 속 매복자를 끊어 다오."}]'::jsonb, '{"xp": 1627}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_lotus2', 4, '아는 사람 칸', '뿌리 속 매복자을(를) 물리친다', '{"at": ["under_root"], "tasks": [{"t": "win", "m": ["regional_under_root_guardian"], "n": 1}]}'::jsonb, '[{"s": null, "t": "매복자가 쓰러지자 장부고 벽을 타고 흐르던 물이 멎었다. 회주는 검은 끈 장부를 끈 하나 풀지 않은 채 다시 맨 위 칸에 올려놓았다."}, {"s": "black_lotus:mumyeong", "t": "나는 이름을 팔았다고들 하지. 판 게 아니다. 맡겨 둔 것이다. 맡긴 것을 지키는 게 이 회의 일이다."}, {"s": "black_lotus:mumyeong", "t": "득수. 다시 맡기지 마라. 대신 구슬, 장부 끝에 칸을 하나 더 내라. 맡긴 사람이 아니라 회가 아는 사람을 적는 칸이다."}, {"s": "black_lotus:guseul", "t": "아는 사람 칸이요? 빚도 이자도 없는 칸은 처음인데요."}, {"s": "black_lotus:mumyeong", "t": "그러니 셈은 필요 없다. 그 칸에 적힌 이름은 해마다 회원들이 돌아가며 한 번씩 소리 내어 부른다."}, {"s": null, "t": "구슬이 붓을 들어 새 칸 첫 줄에 득수의 이름을 적었다. 반석이 그 이름을 소리 내어 불렀다. 호칭이 아니었다."}, {"s": "q:sx_deuksu", "t": "……예, 형님."}, {"s": "black_lotus:mumyeong", "t": "흑련회는 이름을 사고판다고들 한다. 틀린 말은 아니다. 다만 우리는 값을 받고도 잊지는 않는다."}, {"s": null, "t": "회주는 그 말을 남기고 갱도 어둠 속으로 돌아갔다. 그날 장부고 문에는 처음으로 빗장이 아닌 등잔이 걸렸다."}]'::jsonb, '{"xp": 1627, "gil": 117, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
