values ('sq110_s_byeolsun', 'side', '제작·흑조 균열', '대답한 등대', '그날 대답하듯 깜빡인 다른 등대', 'black_tide_rift', 28, '{sq_nine_lighthouse_1}'::text[], null, 1151, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_s_byeolsun' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_byeolsun', 1, '대답이 끊긴 불', '대답이 끊긴 불', '{"at": ["black_tide_rift"]}'::jsonb, '[{"s": null, "t": "흑조 균열 어귀 바위에 작은 거룻배 한 척이 매여 있었다. 뱃전에 앉은 처녀가 빈 등잔을 무릎에 올려놓고 균열 안쪽을 노려보고 있었다."}, {"s": "q:sn_byeolsun", "t": "조사원님! 저 별순이에요. 구등대 군도 끝섬에서 같이 등대 불을 켰던. 벌써 여섯 해 됐어요. 이제는 제가 끝섬 등대지기예요."}, {"s": "q:sn_byeolsun", "t": "그날 밤 멀리서 다른 불 하나가 대답하듯 깜빡였던 거 기억하세요? 그 뒤로 제가 불을 켤 때마다 꼭 한 번씩 깜빡였어요. 여섯 해 동안 하루도 안 빠지고요."}, {"s": "q:sn_byeolsun", "t": "그런데 보름 전부터 대답이 없어요. 불이 보이던 쪽을 재어 보니 이 균열이에요."}, {"s": null, "t": "나는 군도에 그런 등대가 또 있느냐고 물었다."}, {"s": "q:sn_byeolsun", "t": "없어요. 군도 등대는 아홉 개뿐이고 다 제가 알아요. 배도 안 들어오는 균열에 누가 불을 켜겠어요."}, {"s": "q:sn_byeolsun", "t": "균열 안을 같이 좀 살펴봐 주세요. 높은 바위나 불 피운 자국이 어딘가 있을 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_byeolsun', 2, '바위 위의 등막', '흑조 균열을(를) 살핀다', '{"at": ["black_tide_rift"], "tasks": [{"t": "search", "r": ["black_tide_rift"], "n": 3}]}'::jsonb, '[{"s": null, "t": "균열 물이 거꾸로 꺾이는 자리 바로 앞에 바위 하나가 솟아 있었다. 꼭대기에 돌을 쌓아 지은 작은 등막이 있었다."}, {"s": null, "t": "등막 안에는 빈 기름 항아리 여럿과 꺼진 등잔, 심지 자르는 가위 하나가 놓여 있었다. 벽에는 칼로 그은 금이 빼곡했다."}, {"s": "q:sn_byeolsun", "t": "이 가위, 아버지 거예요. 손잡이에 감긴 끈, 제가 어릴 때 감아 드린 거예요."}, {"s": "q:sn_byeolsun", "t": "이 금은 날짜 세는 금이에요. 아버지는 늘 이렇게 셌어요. 넷은 세로로 긋고, 다섯째는 가로로."}, {"s": null, "t": "금은 여섯 해 치를 훌쩍 넘게 그어져 있었다. 마지막 금은 보름 전쯤에서 멈춰 있었다."}, {"s": null, "t": "그때 바위 아래 검은 물이 부풀어 올랐다. 촉수 여럿이 등막 쪽으로 뻗어 올라왔다."}, {"s": "q:sn_byeolsun", "t": "불이 꺼진 뒤로 이것들이 바위까지 올라오나 봐요. 쫓아 주세요. 저는 등막을 지킬게요."}]'::jsonb, '{"xp": 1627}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_byeolsun', 3, '바위틈의 기침', '검은 물결 촉수을(를) 물리친다', '{"at": ["black_tide_rift"], "tasks": [{"t": "win", "m": ["g_black_tide_rift"], "n": 3}]}'::jsonb, '[{"s": null, "t": "촉수들이 물 밑으로 물러나자 바위 아래 틈에서 마른기침 소리가 났다. 별순이 등잔을 내려놓고 바위를 미끄러져 내려갔다."}, {"s": null, "t": "틈 안에 수염이 하얗게 센 사내 하나가 웅크리고 있었다. 기름에 전 손에 빈 기름병을 쥐고 있었다."}, {"s": "q:sn_byeolsun", "t": "아버지!"}, {"s": "q:sx_seokgu", "t": "……별순이냐. 끝섬 불은. 불은 켜져 있느냐."}, {"s": "q:sn_byeolsun", "t": "켜져 있어요. 여섯 해 동안 하루도 안 껐어요. 그런데 아버지는 왜 여기 계셨어요. 왜 안 오셨어요."}, {"s": "q:sx_seokgu", "t": "불을 켜면 저것들이 온다. 그래서 내가 여기서 먼저 켰다. 여기 불이 밝으면 저것들이 이리로 몰리고, 끝섬 배는 무사하니까."}, {"s": "q:sx_seokgu", "t": "보름 전에 기름이 떨어졌다. 기름 낼 고기를 낚으러 내려갔다가 저것들한테 쫓겨 이 틈에 숨었지."}, {"s": "q:sx_seokgu", "t": "자네가 우리 애 불을 같이 켜 준 사람인가. 얘기는 나중에 하세. 불부터 켜 주게. 어유 등잔 둘이면 되네. 바람에 하나가 꺼져도 하나는 남게."}]'::jsonb, '{"xp": 1627}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_byeolsun', 4, '서로 깜빡이는 불', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["black_tide_rift"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 2}], "give": {"fish_oil_lamp": 2}}'::jsonb, '[{"s": null, "t": "등막에 어유 등잔 둘을 걸자 균열 어귀가 환해졌다. 검은 물 밑에서 무언가가 불빛을 따라 바위 쪽으로 몰려드는 기척이 났다. 군도 쪽 바다는 고요했다."}, {"s": "q:sx_seokgu", "t": "그날 끝섬 등대에서 불을 끄려던 것은 내가 아니다. 떠나면서 벗어 두고 온 내 옷을 저것들이 뒤집어쓴 게지. 불 냄새가 밴 옷이니."}, {"s": "q:sn_byeolsun", "t": "알아요. 아버지는 불을 미워한 적이 없잖아요."}, {"s": "q:sn_byeolsun", "t": "이제 집에 가세요. 여기 불은 제가 맡을게요. 사흘에 한 번씩 배 저어 와서 기름을 채우면 돼요."}, {"s": "q:sx_seokgu", "t": "등대지기가 하나면 불 둘을 어찌 다 지키느냐."}, {"s": "q:sn_byeolsun", "t": "그러니까 아버지가 끝섬 불을 지키세요. 저는 이쪽 불을 지킬게요. 밤마다 서로 깜빡여 주면 되잖아요."}, {"s": null, "t": "석구는 한참 딸을 바라보다가 처음으로 웃었다. 나는 석구를 태우고 끝섬 쪽으로 노를 저었다."}, {"s": null, "t": "균열을 다 벗어났을 때 뒤에서 불 하나가 깜빡였다. 뱃머리에 앉은 석구가 손에 든 등잔을 들어 올려, 한 번 깜빡여 대답했다."}]'::jsonb, '{"xp": 1627, "gil": 117, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
