insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yunpal', 1, '숲을 떠난 약사', '숲을 떠난 약사', '{"at": ["seal_vault"]}'::jsonb, '[{"s": null, "t": "봉인고 거울 창고 앞에 약 보따리를 멘 사내가 서성이고 있었다. 귀죽림에서 나무꾼들의 독을 빼 주던 떠돌이 약사였다."}, {"s": "q:dh_yunpal", "t": "허, 자네로구먼. 일곱 해 만인가. 숲을 못 떠난다던 놈이 여기까지 왔으니 우습지."}, {"s": "q:sx_gomyeong", "t": "내가 불렀소. 지난달 귀죽림에서 거두어 온 압수 거울이 하나 있는데, 밤마다 우는 얼굴이 비치오."}, {"s": "q:sx_gomyeong", "t": "그 얼굴이 이 약사 양반과 꼭 닮았소. 그래서 수소문해 모셔 왔지."}, {"s": "q:dh_yunpal", "t": "닮은 게 아니야. 내 동생이야. 윤구."}, {"s": null, "t": "육윤팔이 동생의 이름을 소리 내어 말하는 것은 처음 들었다. 일곱 해 전 그는 「못 살린 놈」이라고만 했다."}, {"s": "q:sx_gomyeong", "t": "거울 창고 안이 요즘 이상하오. 창고마다 압수 거울이 서로를 비추며 우오. 그 거울이 어디 있는지부터 찾아 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yunpal', 2, '형을 부르는 입', '봉인고을(를) 살핀다', '{"at": ["seal_vault"], "tasks": [{"t": "search", "r": ["seal_vault"], "n": 3}]}'::jsonb, '[{"s": null, "t": "거울 창고 맨 안쪽에 대나무 틀을 두른 거울 하나가 서 있었다. 봉인 천은 이미 바닥에 떨어져 있었다."}, {"s": null, "t": "거울 속에 앳된 사내의 얼굴이 비쳤다. 입술이 파랗게 질려 있었고, 소리 없이 같은 말을 되풀이하고 있었다. 입 모양은 「형」이었다."}, {"s": "q:dh_yunpal", "t": "윤구야."}, {"s": null, "t": "육윤팔이 한 걸음 다가서자 거울 속 얼굴이 육윤팔의 얼굴로 바뀌었다. 그러고는 육윤팔이 웃은 적 없는 모양으로 웃었다."}, {"s": "q:sx_gomyeong", "t": "물러서시오. 저 거울은 비친 사람을 흉내 내오. 동생 얼굴을 미끼로 형을 끌어당기는 거요."}, {"s": "q:dh_yunpal", "t": "알아. 알면서도 다리가 가네."}, {"s": null, "t": "거울이 틀째 바닥을 긁으며 앞으로 나왔다. 거울 속의 육윤팔이 손을 뻗었다. {직업:호위=방패를 들자 거울 속에도 똑같은 방패가 들렸다/월궁=활을 겨누자 거울 속에서도 화살 끝이 나를 겨누었다/퇴마=방울을 흔들자 거울 속 방울이 한 박자 늦게 따라 울었다/의무=약낭을 여는 손이 거울 속에서 거꾸로 움직였다/봉인=부적을 꺼내자 거울 속 부적의 글자가 뒤집혀 있었다/암영=그림자 속으로 몸을 숨겨도 거울 속에는 내 모습이 그대로 남아 있었다}."}]'::jsonb, '{"xp": 1627}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yunpal', 3, '그때 지었어야 할 약', '울음 새는 거울을(를) 물리친다', '{"at": ["seal_vault"], "tasks": [{"t": "win", "m": ["r71_vault_3"], "n": 1}]}'::jsonb, '[{"s": null, "t": "거울이 깨지며 대나무 틀이 부러졌다. 바닥에 흩어진 조각마다 윤구의 얼굴이 하나씩 담겨 있었다. 이번에는 웃지 않고 울고 있었다."}, {"s": "q:dh_yunpal", "t": "저 거울이 숲에서 윤구 얼굴을 주워 간 게야. 내가 이름을 안 불러 주니 얼굴만 남아 떠돌았던 거지."}, {"s": "q:dh_yunpal", "t": "일곱 해를, 아니 그보다 훨씬 오래, 「못 살린 놈」이라고만 했어. 이름을 부르면 내가 틀린 처방이 떠올라서."}, {"s": "q:sx_gomyeong", "t": "조각들을 그냥 두면 다시 하나로 붙으려 할 것이오. 편히 보낼 방도가 있겠소?"}, {"s": "q:dh_yunpal", "t": "그날 윤구한테 독을 빼는 약만 먹였어. 기운을 붙잡아 줄 약을 같이 먹였어야 했는데. 그게 내가 틀린 처방이야."}, {"s": "q:dh_yunpal", "t": "조사원, 청심환 세 알만 지어 주게. 그날 지었어야 할 약을 이제라도 놓아 주고 싶네."}]'::jsonb, '{"xp": 1627}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yunpal', 4, '윤구야', '청심환을(를) 만든다, 청심환을(를) 넘긴다', '{"at": ["seal_vault"], "tasks": [{"t": "craft", "items": ["tonic"], "n": 3}], "give": {"tonic": 3}}'::jsonb, '[{"s": null, "t": "육윤팔은 거울 조각을 하나씩 주워 흰 천 위에 모으고, 그 앞에 청심환 세 알을 나란히 놓았다."}, {"s": "q:dh_yunpal", "t": "윤구야. 형이 늦었다. 이번엔 처방 안 틀렸다."}, {"s": null, "t": "조각 속 얼굴들이 하나씩 울음을 그쳤다. 마지막 조각 속의 윤구가 입술을 움직였다. 소리는 없었지만, 이번에는 「형」이 아니었다. 「됐어」였다."}, {"s": null, "t": "조각들은 그 뒤로 아무것도 비추지 않는 평범한 유리가 되었다."}, {"s": "q:sx_gomyeong", "t": "이 조각들은 압수 장부에서 빼 두겠소. 가져가시오."}, {"s": "q:dh_yunpal", "t": "아니. 여기 두게. 나는 이제 이름을 부를 수 있으니, 얼굴은 없어도 돼."}, {"s": "q:dh_yunpal", "t": "숲으로 돌아가야겠네. 물린 놈들이 기다려. 이제는 못 떠나서가 아니라, 가고 싶어서 가는 걸세."}, {"s": null, "t": "봉인고를 나서며 육윤팔은 길모퉁이를 돌 때마다 낮은 목소리로 동생의 이름을 한 번씩 불렀다."}]'::jsonb, '{"xp": 1627, "gil": 117, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
