values ('cq110_pack_4', 'side', '연계·아버지의 등짐', '아버지가 마지막으로 판 것', '아버지의 마지막 흔적이 균열로 이어진다', 'black_tide_rift', 29, '{cq110_pack_3}'::text[], null, 1153, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'cq110_pack_4' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_4', 1, '장부를 낚아챈 손', '장부를 낚아챈 손', '{"at": ["black_tide_rift"]}'::jsonb, '[{"s": null, "t": "흑조 균열 어귀에는 검은 물이 바위틈마다 고여, 숨을 쉬듯 부풀었다 가라앉았다."}, {"s": "q:sx_haesol", "t": "장부 마지막 줄이에요. 「흑조 균열 어귀. 판 것: 원령재 세 줌. 받은 것: 안신탕 두 첩.」 그 아래는 글씨가 번져서 못 읽겠어요."}, {"s": "q:sx_dodam", "t": "안신탕이면 제가 어릴 때 먹던 약이에요! 제가 밤마다 경기를 했대요. 누나가 그랬어요."}, {"s": null, "t": "그때 바위 뒤에서 누군가 해솔의 손에서 장부를 낚아챘다. 비단 두루마기 자락이 펄럭였다."}, {"s": "q:sx_mogap", "t": "진작 팔았으면 좋았을 것을. 이름이 이만큼 적힌 장부면 적월교 쪽에서 값을 넉넉히 쳐 준다오."}, {"s": "q:sx_haesol", "t": "돌려줘요!"}, {"s": null, "t": "모갑은 균열 안쪽으로 뛰어 들어갔다. 몇 걸음 못 가서 검은 물결이 일어나며 촉수가 그의 발목을 휘감았다."}, {"s": null, "t": "누가 말릴 새도 없이 도담이 그 뒤를 쫓아 뛰어들었다."}, {"s": "q:sx_haesol", "t": "도담아!"}, {"s": "q:sx_haesol", "t": "조사원, 촉수부터 끊어 주세요. 제발요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_4', 2, '장부를 끌어안은 아이', '검은 물결 촉수을(를) 물리친다', '{"at": ["black_tide_rift"], "tasks": [{"t": "win", "m": ["g_black_tide_rift"], "n": 3}]}'::jsonb, '[{"s": null, "t": "마지막 촉수가 끊기자 검은 물이 바위틈으로 빨려 들어갔다. 도담은 장부를 품에 안은 채 바위 위에 쓰러져 있었다. 팔뚝에 검은 자국이 길게 나 있었다."}, {"s": "q:sx_dodam", "t": "누나…… 장부 안 젖었어요. 제가 꼭 안고 있었어요."}, {"s": "q:sx_haesol", "t": "바보야, 지금 장부가 문제야?"}, {"s": null, "t": "해솔은 동생을 끌어안고 한참 놓지 않았다."}, {"s": null, "t": "모갑은 젖은 두루마기를 끌어안고 덜덜 떨고 있었다. 촉수가 감겼던 발목이 검게 타 있었다."}, {"s": null, "t": "바위 뒤에서 지팡이를 짚은 노인이 나왔다. 노인은 도담의 팔을 보고, 오누이의 등짐을 보더니 눈이 커졌다."}, {"s": "q:sx_geomsoe", "t": "그 등짐. 내가 다섯 해 전에 너희 집으로 부친 것이다."}, {"s": "q:sx_geomsoe", "t": "얘기는 나중에 하자. 작은놈 팔에 요기가 들었어. 안신탕을 달여야 하는데 약재가 모자란다."}, {"s": "q:sx_geomsoe", "t": "균열 안쪽에 쌓인 원령재 세 줌을 가져오면 내 약재와 바꿔 주마. 너희 아비하고도 그렇게 바꿨다."}]'::jsonb, '{"xp": 1732}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_4', 3, '아버지가 판 것', '원령재을(를) 모은다', '{"at": ["black_tide_rift"], "tasks": [{"t": "gather", "items": ["ghost_ash"], "r": ["black_tide_rift"], "n": 3}]}'::jsonb, '[{"s": null, "t": "원령재를 받은 검쇠는 약재 꾸러미를 풀어 놓고, 불 앞에 앉아 천천히 이야기를 꺼냈다."}, {"s": "q:sx_geomsoe", "t": "너희 아비는 원령재를 캐러 균열 안까지 들어갔다. 집에 있는 작은놈이 밤마다 경기를 한다고, 안신탕을 꼭 보내야 한다고."}, {"s": "q:sx_geomsoe", "t": "나올 때는 요기를 너무 먹었더구나. 내가 이름을 물었더니 한참을 생각하더라. 제 이름을."}, {"s": "q:sx_geomsoe", "t": "그러고는 등짐을 벗어 내게 맡겼다. 이름이 흐려지는 사람이 남의 이름이 적힌 장부를 들고 다니면 안 된다고. 약 두 첩과 같이 집으로 부쳐 달라고."}, {"s": "q:sx_geomsoe", "t": "그 사람은 이름이 흐려진 사람들을 싣고 가는 섬 배를 탔다. 그 뒤로는 나도 모른다."}, {"s": null, "t": "해솔은 장부를 꼭 쥔 채 아무 말도 하지 못했다."}, {"s": null, "t": "모갑이 다리를 절며 다가와 무릎을 꿇었다. 손에 장부 한 쪽을 펴 들고 있었다."}, {"s": "q:sx_mogap", "t": "……여기 내 이름이 있소. 「모갑. 흉년 쌀 서 말. 형편 펴지면 갚을 것.」 내가 굶을 때 그 등짐장수가 준 쌀이오. 이름을 묻길래 빚 문서인 줄 알고 쌀만 받아 달아났지."}, {"s": "q:sx_mogap", "t": "나는 그 장부를 팔아넘기려 했소. 내 이름까지 같이. 발목이 타는 것쯤은 싼 값이오."}, {"s": "q:sx_haesol", "t": "쌀 서 말은 나중에 갚으세요. 지금은 안신탕이 먼저예요. 조사원, 두 첩만 같이 달여 주세요."}]'::jsonb, '{"xp": 1732}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_4', 4, '남겨 둔 한 첩', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["black_tide_rift"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 2}], "give": {"calm_brew": 2}}'::jsonb, '[{"s": null, "t": "안신탕 한 첩을 마신 도담은 금세 잠이 들었다. 팔의 검은 자국이 조금씩 옅어졌다."}, {"s": "q:sx_haesol", "t": "남은 한 첩은 아버지 몫으로 둘래요. 아버지가 도담이한테 보내신 것처럼요."}, {"s": null, "t": "모갑은 쌀 서 말 값이라며 전대를 내밀었다. 해솔이 고개를 젓자, 모갑은 장부의 제 줄 옆에 제 손으로 「아직 못 갚음」이라고 적었다."}, {"s": "q:sx_mogap", "t": "갚을 때까지 내 이름은 이 장부에 묶여 있겠지. 그편이 낫소."}, {"s": null, "t": "모갑은 발을 절며 균열을 떠났다. 다시 돌아보지 않았다."}, {"s": "q:sx_geomsoe", "t": "섬 배가 닿는 곳은 아무나 못 간다. 구중 봉연 너머라더라."}, {"s": null, "t": "해솔은 잠든 도담의 머리를 무릎에 올리고 장부의 맨 끝 쪽을 오래 들여다보았다. 번진 글씨 아래에서 처음 보는 한 줄이 희미하게 비쳤다."}, {"s": "q:sx_haesol", "t": "「내 이름은……」 여기서 끊겼어요. 아버지가 자기 이름을 적다가 마신 거예요."}, {"s": "q:sx_haesol", "t": "도담이가 일어나면 섬으로 가요. 이번에는 받을 게 아니라 드릴 게 있어요."}]'::jsonb, '{"xp": 1732, "gil": 121, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
