insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_redmoon2', 1, '묘지기가 된 문지기', '묘지기가 된 문지기', '{"at": ["crimson_altar"]}'::jsonb, '[{"s": null, "t": "적월 제단터 바깥 돌무덤 사이에서 탁무가 빗자루로 붉은 모래를 쓸고 있었다. 성문 창 대신 빗자루를 들고 있었다."}, {"s": "q:rn_takmu", "t": "대호법께서 내린 벌이다. 문지기 자리를 내놓고 제단터 묘역을 지키라고 하셨다. ……내가 이 자리를 달라고 했다."}, {"s": "q:rn_takmu", "t": "여기 묻힌 건 서약 때 이름을 바친 교도들의 빈 무덤이다. 아무도 안 찾는다. 그래서 누가 지켜야 했다."}, {"s": null, "t": "경파가 물동이를 지고 돌무덤 사이로 걸어왔다. 걸음이 전보다 단단했다."}, {"s": "q:sx_gyeongpa", "t": "조사원. 대호법께서 수련을 마치면 이 묘역에 물을 붓고 오라 하셨소. 덕분에 날마다 탁무 형님 잔소리를 듣소."}, {"s": "q:rn_takmu", "t": "그런데 이상한 일이 있다. 월식이 드는 밤마다 누가 바깥 돌무덤에 밥 한 그릇을 놓고 간다. 교도는 아니다. 교도라면 제단 안쪽에 놓겠지."}, {"s": "q:rn_takmu", "t": "묘지기는 누가 오가는지 알아야 한다. 제단터를 좀 훑어 다오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_redmoon2', 2, '바깥 돌 앞의 아낙', '적월 제단터을(를) 살핀다', '{"at": ["crimson_altar"], "tasks": [{"t": "search", "r": ["crimson_altar"], "n": 2}]}'::jsonb, '[{"s": null, "t": "바깥 돌무덤 하나 앞에 쉰 남짓한 아낙이 앉아 있었다. 밥그릇을 내려놓고 돌에 묻은 모래를 손바닥으로 닦고 있었다."}, {"s": null, "t": "아낙은 경파를 보더니 숨을 멈추었다. 경파는 아낙을 알아보지 못했다."}, {"s": "q:sx_chunhwa", "t": "……크게 자랐구려."}, {"s": "q:rn_takmu", "t": "춘화 아주머니. 교를 떠난 사람은 교도와 말을 섞지 않는 게 법이오."}, {"s": "q:sx_chunhwa", "t": "알고 있소. 그래서 스무 해 동안 바깥 돌까지만 왔지요."}, {"s": "q:sx_gyeongpa", "t": "형님, 이분이 누구시오."}, {"s": null, "t": "탁무가 대답하기 전에 붉은 모래가 발밑에서 솟구쳤다. 모래 속에 숨어 있던 그림자들이 춘화의 밥그릇을 향해 덮쳐 왔다."}, {"s": "q:rn_takmu", "t": "월식 밤이면 모래 그림자가 제사 음식을 노린다. 아주머니를 지켜 다오. 묘역 안에서는 내가 법이다."}]'::jsonb, '{"xp": 1732}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_redmoon2', 3, '바치지 않은 이름', '핏빛 모래 그림자을(를) 물리친다', '{"at": ["crimson_altar"], "tasks": [{"t": "win", "m": ["r71_altar_4"], "n": 3}]}'::jsonb, '[{"s": null, "t": "그림자가 흩어진 뒤, 춘화는 엎어진 밥그릇을 바로 세웠다. 그리고 경파를 보지 않은 채 돌에 대고 말했다."}, {"s": "q:sx_chunhwa", "t": "스무 해 전 월식에 제 지아비가 숨을 거뒀지요. 그때 제사장이 지아비 이름을 서약에 바치자 했소. 이름을 바치면 그 사람이 달 곁에 간다고."}, {"s": "q:sx_chunhwa", "t": "나는 싫었소. 내 지아비 이름은 내가 부르고 싶었지요. 그래서 아이를 두고 교를 떠났소. 아이 이름만은 교에서 지켜 주겠다 하길래."}, {"s": "q:sx_gyeongpa", "t": "……어머니."}, {"s": null, "t": "춘화는 대답하지 못하고 고개만 끄덕였다."}, {"s": "q:sx_chunhwa", "t": "그런데 그 제사장이 죽어서도 제단을 떠나지 않소. 붉은 달을 거울처럼 들고, 그 안에 바치지 못한 이름들을 붙들고 있다오. 지아비 이름도 거기 있소. 월식마다 그게 보여서 여기 오는 거요."}, {"s": null, "t": "제단 안쪽에서 무거운 발소리가 났다. 대호법이었다."}, {"s": "red_moon_cult:sama", "t": "그 제사장은 내 스승이었다. 교리를 지킨다며 남의 이름을 쥐고 놓지 않았지. 이제 놓아줄 때다."}, {"s": "red_moon_cult:sama", "t": "경파, 네 아비 이름이다. 네가 가서 찾아와라. 야행국, 이 녀석 곁에 서 다오."}]'::jsonb, '{"xp": 1732}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_redmoon2', 4, '묘지기는 적지 않는다', '월식 제사장귀을(를) 물리친다', '{"at": ["crimson_altar"], "tasks": [{"t": "win", "m": ["r71_altar_5"], "n": 1}]}'::jsonb, '[{"s": null, "t": "제사장귀가 쓰러지자 그 손에 들린 붉은 달 거울이 금 가며 갈라졌다. 갈라진 틈에서 붉은 빛줄기들이 흩어져 나왔다."}, {"s": null, "t": "춘화가 그 빛 하나를 보고 이름 하나를 불렀다. 처음 듣는 이름이었다. 바람이 한 번 돌무덤 사이를 지나갔다."}, {"s": "q:sx_gyeongpa", "t": "아버지 이름이 그거였소? 나는 한 번도 몰랐소."}, {"s": "q:sx_chunhwa", "t": "이제 알았으니 됐소. 그 이름은 이제 둘이서 부르면 되지요."}, {"s": "red_moon_cult:sama", "t": "교를 떠난 사람은 교도와 말을 섞지 않는다. 그 법은 그대로 둔다."}, {"s": null, "t": "경파의 얼굴이 굳었다. 탁무가 빗자루를 고쳐 쥐며 헛기침을 했다."}, {"s": "q:rn_takmu", "t": "바깥 돌무덤까지는 내 묘역입니다, 대호법. 묘지기는 누가 오가는지 기록하지 않습니다."}, {"s": "red_moon_cult:sama", "t": "……그런가. 나는 묘역 일은 모른다."}, {"s": null, "t": "대호법은 붉은 장포를 끌며 제단 안으로 돌아갔다. 그날부터 월식 밤마다 바깥 돌무덤 앞에는 밥그릇이 두 개 놓였다."}]'::jsonb, '{"xp": 1732, "gil": 121, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
