delete from public.world_quest_steps where quest_id = 'sq110_f_south2' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_south2', 1, '신호를 보낸 배', '신호를 보낸 배', '{"at": ["black_tide_rift"]}'::jsonb, '[{"s": null, "t": "흑조 균열 가장자리 검은 물 위에 낡은 뱃집 한 척이 묶여 있었다. 뱃머리에 바닷불 등대 쪽으로 세 번 깜빡이던 그 등잔이 매달려 있었다."}, {"s": "q:sx_pungdeok", "t": "그날 대답한 배가 이 배요. 해비 할미 배지라. 할미는 남명이 무너지기 전에 태어난 마지막 사람이오."}, {"s": null, "t": "아랑 곁에 한쪽 소매가 빈 노장이 서 있었다. 그 뒤로 무녀 하나가 따라왔다."}, {"s": "southern_remnant:jang", "t": "마지막 백성을 뵈러 왔다. 장수가 백성을 뵙는 데 쉰 해가 걸렸구나."}, {"s": null, "t": "뱃집 안에서 아주 늙은 할미가 기어 나왔다. 할미는 노장을 보고도 놀라지 않았다."}, {"s": "q:sx_haebi", "t": "장군이 왔구려. 나라가 아직 있는 줄 알면 어쩌나 했소."}, {"s": "q:sx_haebi", "t": "저 물 밑에 우리 마을 사람들이 있소. 밤마다 이름을 불렀는데 요새는 내가 이름을 자꾸 잊소. 잊은 이름부터 원령이 되어 배를 두드리오."}, {"s": "q:sx_haebi", "t": "잊은 건 내 탓이오. 두드리는 것들 좀 쉬게 해 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_south2', 2, '노래가 된 이름', '심해 원령을(를) 물리친다', '{"at": ["black_tide_rift"], "tasks": [{"t": "win", "m": ["x_black_tide_rift_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "원령들이 검은 물속으로 가라앉자 뱃집이 조용해졌다. 할미는 뱃전에 기대 숨을 골랐다."}, {"s": "southern_remnant:soi", "t": "할머님, 잊으신 이름은 소녀가 노래로 엮어 드리리다. 노래가 되면 잊어도 입이 기억하더이다."}, {"s": "q:sx_haebi", "t": "무녀 아가씨, 이름이 생각나야 엮지. 나는 얼굴만 생각나오. 웃던 거, 그물 던지던 거."}, {"s": "southern_remnant:soi", "t": "그럼 얼굴을 노래하오리다. 이름은 원령이 남긴 재가 알 것이외다."}, {"s": null, "t": "나는 원령재가 무엇을 아느냐고 물었다."}, {"s": "southern_remnant:soi", "t": "원령이 흩어지며 남긴 재에는 마지막으로 불린 이름이 묻어 있다 하더이다. 그 재를 태우면 이름이 한 번 소리가 되지요."}, {"s": "southern_remnant:jang", "t": "균열 바위틈에 원령재가 쌓여 있다. 세 줌만 모아 다오. 내 남은 팔로는 바위를 못 탄다."}]'::jsonb, '{"xp": 1732}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_south2', 3, '끝난 나라', '원령재을(를) 모은다', '{"at": ["black_tide_rift"], "tasks": [{"t": "gather", "items": ["ghost_ash"], "r": ["black_tide_rift"], "n": 3}]}'::jsonb, '[{"s": null, "t": "소이가 원령재를 등잔불에 한 줌씩 뿌렸다. 재가 탈 때마다 작은 소리가 났다. 할미는 그 소리를 듣고 이름을 하나씩 따라 불렀다."}, {"s": "q:sx_haebi", "t": "맞소, 그 이름이오. 갯바위 집 막내. ……그 이름은 우리 언니요."}, {"s": "southern_remnant:jang", "t": "할머님. 남명회는 불이 있는 한 나라는 끝나지 않는다고 믿어 왔소."}, {"s": "q:sx_haebi", "t": "장군. 나라는 끝났소. 그날 밤에 끝났소. 나는 봤소."}, {"s": null, "t": "노장의 얼굴이 굳었다. 아랑이 불씨 항아리를 꼭 끌어안았다."}, {"s": "q:sx_haebi", "t": "그래도 사람은 남았지라. 장군도 남았고, 저 불 지키는 아가씨도, 이 늙은이도. 끝난 걸 끝났다 하고, 남은 걸 남았다 하면 되오."}, {"s": "q:sx_haebi", "t": "이름 다 불렀으니 이제 물 밑 사람들을 보내 주고 싶소. 정화 부적 두 장만 지어 주시오. 물에 띄우게."}]'::jsonb, '{"xp": 1732}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_south2', 4, '남은 사람의 나라', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["black_tide_rift"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "할미가 정화 부적 두 장을 검은 물에 띄웠다. 부적이 물살을 따라 흘러가자 균열 아래에서 희미한 빛이 하나둘 떠올랐다가 흩어졌다."}, {"s": "southern_remnant:soi", "t": "그대들 얼굴은 소녀가 노래로 지니고 가리다. 가시오, 편히."}, {"s": null, "t": "노장 장무현이 뱃전에 한쪽 무릎을 꿇었다. 남은 한 팔로 할미의 손을 받쳐 들었다."}, {"s": "southern_remnant:jang", "t": "나라를 지키지 못한 장수가 마지막 백성께 절을 올리오."}, {"s": "q:sx_haebi", "t": "일어나시오. 나라는 못 지켰어도 사람은 지켰잖소. 그거면 됐지라."}, {"s": "q:r71_arang", "t": "할머니, 잔불촌으로 오세요. 고개 불도 있고 바다 불도 있어요. 할머니 자리도 있어요."}, {"s": "q:sx_haebi", "t": "뭍은 멀미가 나서 싫소. 대신 이 배를 잔불촌 아래 나루에 묶어 주구려. 밤마다 고개 불이 보이게."}, {"s": "q:sx_pungdeok", "t": "노는 내가 젓겠소."}, {"s": null, "t": "그날부터 남명회 사람들은 「나라가 끝나지 않는다」는 말 대신 「사람이 남았다」고 인사했다. 노장이 처음 그렇게 말했다."}]'::jsonb, '{"xp": 1732, "gil": 121, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
