insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_last_depot', 1, '무너진 움막', '무너진 움막', '{"at": ["black_tide_rift"]}'::jsonb, '[{"s": null, "t": "균열 아래로 내려가는 길목에 무너진 움막이 하나 있었다. 노인 하나가 쓰러진 기둥 사이에서 보따리를 하나씩 꺼내고 있었다."}, {"s": "q:sx_deokbo", "t": "어이, 거기 조사원. 봉연 가는 길인가? 아직이면 다행이고."}, {"s": "q:sx_deokbo", "t": "여기가 내 보급소야. 봉연 쪽으로 내려가는 사람들한테 건량 한 봉지씩 몰래 쥐여 주던 데지. 정청에서 시킨 일은 아니고."}, {"s": "q:sx_deokbo", "t": "엊그제 균열이 크게 한 번 울더니 이 꼴이 됐어. 쟁여 둔 건량이 다 묻혔고."}, {"s": null, "t": "나는 무엇을 도우면 되느냐고 물었다."}, {"s": "q:sx_deokbo", "t": "건량부터 다시 채워야지. 균열 가장자리 물자 더미를 뒤지면 지나간 사람들이 흘린 노정 건량이 나와. 네 봉지만 모아 주게. 오늘 밤에도 누가 내려갈지 모르니까."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_last_depot', 2, '기둥 아래의 벽', '노정 건량을(를) 모은다', '{"at": ["black_tide_rift"], "tasks": [{"t": "gather", "items": ["travel_ration"], "r": ["black_tide_rift"], "n": 4}]}'::jsonb, '[{"s": null, "t": "건량을 내려놓자 덕보는 봉지마다 매듭을 다시 묶었다. 그 손놀림이 몹시 익숙했다."}, {"s": null, "t": "움막 안쪽 벽은 무너지지 않고 서 있었다. 벽에는 이름이 빼곡했다. 이름 옆마다 먹으로 찍은 점이 하나씩 있었다."}, {"s": "q:sx_deokbo", "t": "건량 받아 간 사람들이 적고 간 거야. 점은 돌아온 사람이 다시 와서 찍은 거고."}, {"s": "q:sx_deokbo", "t": "점 찍으러 오는 날엔 내가 국을 끓여. 그 맛에 이 짓을 하지."}, {"s": null, "t": "그때 균열 밑에서 땅이 다시 울렸다. 검은 물 위로 거대한 것이 등을 내밀었다."}, {"s": "q:sx_deokbo", "t": "저놈이야. 저게 꿈틀대서 움막이 무너졌어. 저게 저기 있으면 아무도 이 길로 못 내려가."}]'::jsonb, '{"xp": 1732}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_last_depot', 3, '점 없는 이름', '균열을 삼킨 자을(를) 물리친다', '{"at": ["black_tide_rift"], "tasks": [{"t": "win", "m": ["regional_black_tide_rift_guardian"], "n": 1}]}'::jsonb, '[{"s": null, "t": "균열을 삼킨 자가 가라앉자 물살이 잠시 바로 흘렀다. 덕보는 벽 앞에 서서 이름을 하나씩 손가락으로 짚고 있었다."}, {"s": null, "t": "벽 맨 위, 가장 오래된 이름 옆에만 점이 없었다."}, {"s": null, "t": "나는 그 이름이 누구냐고 물었다."}, {"s": "q:sx_deokbo", "t": "우리 아들. 첫 봉지를 쥐여 준 게 그 애야. 그다음부터 그냥 아무한테나 쥐여 주게 됐지."}, {"s": "q:sx_deokbo", "t": "그 애 옆에 점이 없는 건 괜찮아. 다른 이름들 옆에 점이 찍히면 돼. 그게 그 애 몫이야."}, {"s": null, "t": "덕보가 손을 털고 돌아섰다."}, {"s": "q:sx_deokbo", "t": "움막을 다시 올리려면 기둥 밑에 원령재를 섞어 발라야 해. 균열 놈들이 원령 냄새를 싫어하거든. 이 둘레에 쌓인 원령재 세 줌만 걷어 다 주게."}]'::jsonb, '{"xp": 1732}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_last_depot', 4, '점 찍으러 오게', '원령재을(를) 모은다', '{"at": ["black_tide_rift"], "tasks": [{"t": "gather", "items": ["ghost_ash"], "r": ["black_tide_rift"], "n": 3}]}'::jsonb, '[{"s": null, "t": "원령재를 섞은 흙으로 기둥을 세우자 움막이 다시 섰다. 덕보는 새 선반에 건량 봉지를 가지런히 올렸다."}, {"s": "q:sx_deokbo", "t": "됐네. 오늘 밤 내려가는 사람도 빈손으로는 안 가겠어."}, {"s": null, "t": "덕보가 붓을 내밀었다. 벽 아래 빈자리를 가리켰다."}, {"s": "q:sx_deokbo", "t": "자네도 적고 가. 봉연까지 가든 안 가든, 이 길로 내려가는 사람이면 적어야 해."}, {"s": null, "t": "나는 벽에 이름을 적었다. 덕보가 건량 한 봉지를 내 손에 쥐여 주었다."}, {"s": "q:sx_deokbo", "t": "이건 정청 물건 아니야. 내 것이니 꼭 갚아. 갚는 법은 하나야. 돌아와서 그 옆에 점 찍는 거."}, {"s": "q:sx_deokbo", "t": "그날은 국을 끓여 놓을게. 자네 몫으로 한 그릇, 그리고 우리 아들 몫으로 한 그릇."}, {"s": null, "t": "움막을 나서는데 등 뒤에서 덕보가 흥얼거렸다. 오늘 밤 내려갈 누군가를 위해 벌써 물을 올리고 있었다."}]'::jsonb, '{"xp": 1732, "gil": 121, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
