on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'cq110_paint_3' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_3', 1, '문 앞의 화공', '문 앞의 화공', '{"at": ["sealed_abyss"]}'::jsonb, '[{"s": null, "t": "구중 봉연의 검은 물가에 담채가 화판을 세우고 앉아 있었다. 소림은 그 뒤에서 등불을 들고 떨고 있었다."}, {"s": "q:sx_sorim", "t": "조사원님, 오셨어요. 봉인고에서 그림을 찾아 온 뒤로 스승님이 여기 오겠다고 고집하셨어요. 잊힌 이름들이 흘러드는 곳이라고요."}, {"s": "q:sx_damchae", "t": "여기서는 얼굴이 보이오. 물결마다 얼굴이 떠올랐다 가라앉소. 아무도 그려 준 적 없는 얼굴들이오."}, {"s": "q:sx_sorim", "t": "저한테는 아무것도 안 보여요. 그냥 검은 물뿐이에요."}, {"s": null, "t": "등불 빛을 보고 천장 쪽에서 날개 소리가 몰려왔다. 박쥐 떼가 화판 위를 맴돌았다."}, {"s": "q:sx_damchae", "t": "그것들을 좀 쫓아 주시오. 붓 끝이 흔들리오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_3', 2, '떠오른 화폭', '봉연 박쥐 떼을(를) 물리친다', '{"at": ["sealed_abyss"], "tasks": [{"t": "win", "m": ["x_sealed_abyss_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "박쥐 떼가 날아드는 통에 담채의 화폭 하나가 검은 물에 떨어졌다. 소림이 비명을 질렀다."}, {"s": null, "t": "그런데 화폭은 가라앉지 않았다. 물 위로 천천히 떠올랐고, 건져 보니 한 방울도 젖어 있지 않았다."}, {"s": null, "t": "화폭 속 사람들이 모두 두 손을 들어 종이 안쪽에서 물을 밀어내고 있었다. 이를 악문 얼굴이었다."}, {"s": "q:sx_damchae", "t": "보시오. 저들이 그림을 지키고 있소. 이 그림이 저들의 집이오. 집을 잃지 않으려고…… 아니, 아니오. 집이 저들을 놓지 않는 것일 수도 있소. 어느 쪽이든 아름답소. 저 손가락 마디를 보시오. 저건 내가 그린 게 아니오. 저들이 스스로 힘을 준 거요."}, {"s": "q:sx_sorim", "t": "스승님, 무서워요. 그만 가요."}, {"s": "q:sx_damchae", "t": "아직이오. 저 너머를 그려야 하오. 그런데 이 물가 기운이 화폭을 갉소. 결계 파편 세 조각만 구해 주시오. 화판 네 귀에 박아 두면 물기가 못 넘어오오."}]'::jsonb, '{"xp": 1840}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_3', 3, '잠들지 않는 손', '결계 파편을(를) 모은다', '{"at": ["sealed_abyss"], "tasks": [{"t": "gather", "items": ["ward_fragment"], "r": ["sealed_abyss"], "n": 3}]}'::jsonb, '[{"s": null, "t": "결계 파편을 박은 화판 앞에서 담채는 사흘 밤을 내리 그렸다. 화폭에는 검은 물과, 그 위로 떠오르는 수많은 얼굴이 채워져 갔다."}, {"s": null, "t": "셋째 날 새벽, 소림이 나를 화판 뒤로 끌고 갔다. 담채의 손이 붓을 쥔 채 떨리고 있었다. 손끝이 먹으로 새까맸다."}, {"s": "q:sx_sorim", "t": "사흘 동안 한숨도 안 주무셨어요. 말을 걸어도 대답을 안 하세요. 아까는 저를 보고 「누구요」 하셨어요."}, {"s": "q:sx_damchae", "t": "하나만 더…… 하나만 더 그리면 되오. 저 얼굴이 아직 덜 떠올랐소."}, {"s": "q:sx_sorim", "t": "억지로라도 재워 드려야 해요. 안신탕 두 그릇만 지어 주세요. 한 그릇으로는 스승님이 안 넘어가세요."}]'::jsonb, '{"xp": 1840}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_3', 4, '그린 적 없는 얼굴', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["sealed_abyss"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 2}], "give": {"calm_brew": 2}}'::jsonb, '[{"s": null, "t": "안신탕을 마신 담채는 붓을 놓기 싫다는 듯 손을 쥔 채 잠들었다. 소림이 담채의 어깨에 겉옷을 덮었다."}, {"s": null, "t": "소림은 등불을 들어 완성된 화폭을 비추었다. 검은 물 위로 떠오른 얼굴이 백은 넘어 보였다."}, {"s": "q:sx_sorim", "t": "조사원님, 여기요. 오른쪽 아래."}, {"s": null, "t": "얼굴들 사이에 낯익은 얼굴이 하나 있었다. 지금 내 옆에서 잠든 사람의 얼굴이었다."}, {"s": "q:sx_sorim", "t": "스승님은 자기 얼굴을 그린 적이 한 번도 없어요. 거울도 잘 안 보세요. 그런데 이건 누가 그렸을까요."}, {"s": null, "t": "나는 그 얼굴이 물 위로 떠오르는 것인지, 물 밑으로 가라앉는 것인지 가늠할 수 없었다."}, {"s": "q:sx_sorim", "t": "스승님이 깨시면 귀허도로 가자고 하실 거예요. 바깥에서 이름이 지워진 사람들이 사는 섬이라고, 거기 얼굴이 제일 많다고요."}, {"s": "q:sx_sorim", "t": "저는 따라갈 거예요. 조사원님도 와 주세요. 저 혼자서는 스승님을 못 붙잡을 것 같아요."}]'::jsonb, '{"xp": 1840, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
