insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_mark', 1, '거꾸로 흐르는 물', '거꾸로 흐르는 물', '{"at": ["sealed_abyss"]}'::jsonb, '[{"s": null, "t": "구중 봉연 바깥 문 아래로 검은 물길 하나가 땅속으로 흘러들고 있었다. 물가에 늙은 뱃사람 하나가 장대를 들고 서서 물 위를 노려보고 있었다."}, {"s": "q:sx_geonjimi", "t": "정청 사람이구먼. 여기까지 오는 조사원은 드문데."}, {"s": "q:sx_geonjimi", "t": "나는 이 물가에서 떠내려오는 걸 건지는 사람이야. 다들 건짐이라고 부르지."}, {"s": null, "t": "나는 물이 땅속으로 흘러 들어가는데 무엇이 떠내려오느냐고 물었다."}, {"s": "q:sx_geonjimi", "t": "평소엔 안 오지. 그런데 봉연이 숨을 쉴 때가 있어. 사흘이나 나흘에 한 번, 문이 흔들리면 물이 거꾸로 밀려 올라와. 그때 저 아래서 별것이 다 올라온다고."}, {"s": "q:sx_geonjimi", "t": "그래서 물막이에 그물을 쳐 뒀는데, 봉연 박쥐 떼가 그 위에 둥지를 틀었어. 그물코를 다 물어뜯어 놨지."}, {"s": "q:sx_geonjimi", "t": "지난번 숨 때 뭔가 큼직한 게 그물에 걸렸는데, 박쥐들 때문에 다가가지를 못하고 있어. 저것들 좀 쫓아 줘."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_mark', 2, '그물에 걸린 판자', '봉연 박쥐 떼을(를) 물리친다', '{"at": ["sealed_abyss"], "tasks": [{"t": "win", "m": ["x_sealed_abyss_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "박쥐 떼를 쫓고 물막이에 다가가자, 찢어진 그물에 나뭇조각 하나가 반쯤 걸려 있었다. 배 옆구리를 뜯어낸 듯한 판자였다."}, {"s": null, "t": "판자 한가운데에 칼끝으로 새긴 표식이 있었다. 정청 조사원들이 지나간 길목에 남기는 표식이었다. 나도 처음 길을 나설 때 배운 모양이었다."}, {"s": "q:sx_geonjimi", "t": "거 봐. 조사원 표식이지? 저 아래서 올라온 거야."}, {"s": null, "t": "판자를 끌어 올리려 하자, 그물코가 끊어지며 판자가 물 쪽으로 미끄러졌다. 물살이 벌써 아래로 당기고 있었다."}, {"s": "q:sx_geonjimi", "t": "놔두면 다음 숨 전에 도로 끌려가. 그물코를 다시 엮어야 해."}, {"s": "q:sx_geonjimi", "t": "봉인이 깨진 조각을 그물코에 꿰면 물에 뜬 요기를 붙들어. 판자에도 요기가 잔뜩 배었으니 같이 붙들릴 거야."}, {"s": "q:sx_geonjimi", "t": "봉연 안쪽 무너진 봉인 틈에 결계 파편이 흩어져 있어. 세 조각만 주워 와."}]'::jsonb, '{"xp": 1840}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_mark', 3, '물 끝, 사람 있음', '결계 파편을(를) 모은다', '{"at": ["sealed_abyss"], "tasks": [{"t": "gather", "items": ["ward_fragment"], "r": ["sealed_abyss"], "n": 3}]}'::jsonb, '[{"s": null, "t": "결계 파편을 꿴 그물이 판자를 붙들었다. 건짐이와 함께 판자를 물가로 끌어 올렸다."}, {"s": null, "t": "표식 아래에 작은 글씨가 새겨져 있었다. 흔들리는 배 위에서 새겼을 텐데도 글씨가 반듯했다."}, {"s": null, "t": "「물 끝, 마을. 등불 있음. 사람 있음.」"}, {"s": null, "t": "나뭇결 틈에 푸른 비늘 한 조각이 박혀 있었다. 물고기 비늘이라기엔 너무 컸다."}, {"s": "q:sx_geonjimi", "t": "몇 해 전에도 이런 걸 하나 건져서 정청에 갖다준 적이 있어. 표식 옆에 새긴 번호를 서리가 명부에서 찾아봤는데, 그 줄엔 먹 거둔 자국만 남았다더군."}, {"s": "q:sx_geonjimi", "t": "그 뒤로 정청은 이런 건 갖다주지 말래. 아무 데도 적을 데가 없다고."}, {"s": null, "t": "나는 물 끝이 어디냐고 물었다. 건짐이는 고개를 저었다."}, {"s": "q:sx_geonjimi", "t": "봉연 아래로 내려간 배가 돌아온 적은 없어. 그런데 등불이 있다고 적었으면, 거기도 밤이 있다는 거겠지."}, {"s": "q:sx_geonjimi", "t": "등불이 있다는 말에는 등불로 답하는 법이야. 어유 등잔 하나 만들어 와. 다음 숨이 끝나고 물이 다시 내려갈 때 띄워 보내자고."}]'::jsonb, '{"xp": 1840}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_mark', 4, '답장', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["sealed_abyss"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 1}], "give": {"fish_oil_lamp": 1}}'::jsonb, '[{"s": null, "t": "이튿날 밤, 봉연이 숨을 쉬었다. 문이 낮게 울리고 물이 한 번 거꾸로 부풀었다가 다시 땅속으로 빨려 내려갔다."}, {"s": null, "t": "건짐이가 어유 등잔에 불을 붙여 판자 위에 올렸다. 판자는 등잔을 싣고 물살을 따라 천천히 어둠 속으로 들어갔다."}, {"s": null, "t": "등불은 점점 작아졌다. 마침내 깜빡이는 점 하나가 되었다가 보이지 않게 되었다."}, {"s": "q:sx_geonjimi", "t": "갔네."}, {"s": null, "t": "한참 뒤, 물길 저 아래 아주 먼 곳에서 무언가 한 번 깜빡였다. 물에 비친 등잔불이 남은 것인지, 다른 불빛인지는 알 수 없었다."}, {"s": "q:sx_geonjimi", "t": "봤어? ……아니, 못 봤다고 해 둬. 정청에 적을 데도 없는 걸 봤다고 해 봐야 뭐 하겠어."}, {"s": null, "t": "건짐이는 장대를 어깨에 걸쳤다. 그러고는 판자에서 떼어 둔 푸른 비늘을 내 손에 쥐여 주었다."}, {"s": "q:sx_geonjimi", "t": "이건 자네가 갖고 있어. 언젠가 물 끝에 가거든, 이걸 떨군 사람한테 돌려주라고."}]'::jsonb, '{"xp": 1840, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
