delete from public.world_quest_steps where quest_id = 'sq110_f_river2' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_river2', 1, '서른 해 만의 인양', '서른 해 만의 인양', '{"at": ["tide_gate"]}'::jsonb, '[{"s": null, "t": "만조의 갑문 도르래 아래로 굵은 쇠사슬이 물속까지 늘어져 있었다. 청파가 사슬을 붙든 채 물 밑을 가리켰다."}, {"s": "q:sn_cheongpa", "t": "도방께서 물제비를 건져 올리자고 하셨습니다. 서른 해 묵은 배를요."}, {"s": null, "t": "갑문 계단에서 웃는 얼굴의 여인이 손짓했다. 수향연맹의 도방이었다."}, {"s": "river_alliance:jin", "t": "연맹은 약속을 어기지 않아요. 물제비가 떠날 때 연맹은 「돌아오면 품삯을 치른다」고 적었어요. 서른 해째 못 치렀죠. 배라도 들어와야 셈을 끝내요."}, {"s": null, "t": "청파 뒤로 허리 굽은 노파가 바구니를 이고 서 있었다. 노파는 물 밑을 한 번도 보지 않았다."}, {"s": "q:sx_ondeok", "t": "건지든 말든 맘대로 해라. 나는 밥이나 지으러 왔다."}, {"s": "q:sn_cheongpa", "t": "어머니예요. 아버지 배 얘기만 나오면 저러세요."}, {"s": "q:sn_cheongpa", "t": "그런데 도르래 사슬마다 도르래 집게가 붙어서 사슬을 끊고 있습니다. 세 마리만 떼어 주십시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_river2', 2, '끊어진 도르래', '도르래 집게을(를) 물리친다', '{"at": ["tide_gate"], "tasks": [{"t": "win", "m": ["r71_tide_3"], "n": 3}]}'::jsonb, '[{"s": null, "t": "집게를 떼어 내자 사슬이 팽팽히 당겨졌다. 그 순간 낡은 도르래 바퀴가 우지끈 소리를 내며 금이 갔다."}, {"s": "river_alliance:maehyang", "t": "저 바퀴로는 배 무게를 못 버텨요. 갑문을 처음 지을 때 깎은 거라 장부에 값도 안 남았어요."}, {"s": "q:sx_ondeok", "t": "그 바퀴, 네 아비가 갈아 끼우자고 하던 거다. 다음 항해 다녀와서 하자더니."}, {"s": null, "t": "온덕은 그 말만 하고 다시 쌀을 씻었다. 청파가 어머니 등을 한참 보았다."}, {"s": "q:sn_cheongpa", "t": "그럼 오늘 아버지 대신 갈아 끼우겠습니다."}, {"s": "river_alliance:jin", "t": "도르래 바퀴는 강화 부적목으로 깎아야 바닷물에 안 썩어요. 갑문 둑 위에 몇 그루 있어요. 두 토막만 베어 와요."}]'::jsonb, '{"xp": 1840}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_river2', 3, '들어오는 배', '강화 부적목을(를) 모은다', '{"at": ["tide_gate"], "tasks": [{"t": "gather", "items": ["reinforced_lumber"], "r": ["tide_gate"], "n": 2}]}'::jsonb, '[{"s": null, "t": "새 도르래 바퀴가 돌기 시작하자 물 밑에서 물제비가 천천히 떠올랐다. 갑판에 조개껍데기가 덕지덕지 붙어 있었지만 이물의 글씨는 또렷했다."}, {"s": null, "t": "쌀을 씻던 온덕의 손이 멈췄다. 온덕은 바구니를 내려놓고 처음으로 물가에 섰다."}, {"s": "q:sx_ondeok", "t": "……저 사람, 키도 손바닥만 한 배를 타고 나가면서 큰소리는."}, {"s": "river_alliance:maehyang", "t": "연맹에선 배가 들어오면 갑문에 등을 두 개 걸어요. 하나는 배를 위해, 하나는 기다린 사람을 위해."}, {"s": "river_alliance:jin", "t": "서른 해 동안 그 등을 못 걸었네요. 오늘은 걸어야죠."}, {"s": null, "t": "나는 어유 등잔 두 개를 짓겠다고 했다. 청파가 고개를 숙였다."}]'::jsonb, '{"xp": 1840}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_river2', 4, '손수 쓰는 이름', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["tide_gate"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 2}], "give": {"fish_oil_lamp": 2}}'::jsonb, '[{"s": null, "t": "갑문 양쪽에 어유 등잔이 하나씩 걸렸다. 매향이 장부 원본을 펼쳐 물제비 줄을 가리켰다. 돌아온 날 칸은 여전히 비어 있었다."}, {"s": "river_alliance:maehyang", "t": "이 칸은 가족이 채워요. 「가라앉음」도, 「돌아옴」도."}, {"s": null, "t": "청파가 붓을 들려고 하자 온덕이 그 붓을 빼앗았다. 온덕은 서툰 손으로 오래 한 자씩 적었다. 「돌아옴. 맞은 사람: 온덕」. 그 곁에 지아비의 이름도 적었다."}, {"s": "q:sx_ondeok", "t": "서른 해 동안 갑문 쪽으로는 고개도 안 돌렸다. 기다린다고 하면 정말 안 올까 봐."}, {"s": "q:sx_ondeok", "t": "이제 됐다. 왔으니 됐다."}, {"s": "river_alliance:jin", "t": "물제비 사람들 품삯은 오늘 치러요. 이자는 연맹이 서른 해 기다린 값으로 쳐서 얹을게요."}, {"s": "river_alliance:maehyang", "t": "흑파 씨 칸은 어떻게 할까요."}, {"s": "q:sn_cheongpa", "t": "그대로 두겠습니다. 그 애는 아직 수궁 문 앞에 서 있으니까요. 기다리는 사람 칸에 어머니 이름을 하나 더 적어 주십시오."}, {"s": null, "t": "그날 밤 온덕이 지은 밥은 물제비 갑판 위에 차려졌다. 갑문의 두 등잔은 새벽까지 꺼지지 않았다."}]'::jsonb, '{"xp": 1840, "gil": 125, "items": {"spirit_qi_pill": 2, "travel_ration": 2}}'::jsonb)
