insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_office', 1, '봉인함 하나', '봉인함 하나', '{"at": ["seal_vault"]}'::jsonb, '[{"s": null, "t": "봉인고 문 앞에서 문수가 봉인함 하나를 두 팔로 끌어안고 서 있었다. 정청 처마에서 부적을 붙이던 때보다 키가 한 뼘 자라 있었다."}, {"s": "q:dh_munsu", "t": "조사원님! 여기서 뵈니까 반갑네요. 저 혼자 왔으면 문 앞에서 돌아갔을 거예요."}, {"s": "q:dh_munsu", "t": "올해 명부 정리 목록이에요. 서리들은 「먹 거두기」라고 해요. 봉인고 서고에 넣어 두면 날을 받아 거둔대요."}, {"s": "q:dh_munsu", "t": "저는 이 일이 뭔지 올봄에야 알았어요. 오래된 이름을 장부에서 거둬들이는 거래요. 거둔 이름은 아무에게도 안 묶이고요."}, {"s": null, "t": "문수가 함을 내려놓자 함 틈으로 검은 손가락 몇 개가 꿈틀거리며 비어져 나왔다."}, {"s": "q:dh_munsu", "t": "으악! 이거예요, 이거! 봉인고 가는 길 내내 함에서 이런 손이 기어 나와서 목록을 붙잡아요."}, {"s": "q:dh_munsu", "t": "서고까지 가는 길에 있는 손들 좀 치워 주세요. 저는 함을 꼭 끌어안고 있을게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_office', 2, '번진 글자', '함에서 기어 나온 손을(를) 물리친다', '{"at": ["seal_vault"], "tasks": [{"t": "win", "m": ["r71_vault_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "손들이 흩어지자 문수가 함을 열어 목록을 확인했다. 마지막 손이 긁고 간 자리에 먹이 번져 있었다."}, {"s": "q:dh_munsu", "t": "어떡해요. 이름이 몇 줄 번졌어요. 목록은 또박또박 읽혀야 한다고 감찰관님이 몇 번이나 말씀하셨는데."}, {"s": null, "t": "나는 번진 줄을 다시 적으면 되지 않느냐고 물었다."}, {"s": "q:dh_munsu", "t": "봉인고에 들이는 글은 봉인 먹으로 써야 해요. 보통 먹은 이 안에서 사흘이면 흐려진대요."}, {"s": null, "t": "문수는 번진 줄을 손끝으로 쓸어 보았다. 손끝에 묻어나는 먹이 아직 축축했다."}, {"s": "q:dh_munsu", "t": "봉인고 안에서 봉인 먹을 세 개만 구해 주세요. 제가 다시 쓸게요. ……이번엔 손 안 떨게요."}]'::jsonb, '{"xp": 1951}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_office', 3, '처마 밑의 이름들', '봉인 먹을(를) 모은다', '{"at": ["seal_vault"], "tasks": [{"t": "gather", "items": ["sealing_ink"], "r": ["seal_vault"], "n": 3}]}'::jsonb, '[{"s": null, "t": "문수는 봉인 먹을 갈아 번진 줄을 한 자씩 다시 적었다. 그러다 붓이 멈췄다."}, {"s": "q:dh_munsu", "t": "조사원님, 이 이름들요. 정청 처마 부적 뒤에 적혀 있던 옛 서리들 이름이에요. 붙인 날짜까지 똑같아요."}, {"s": "q:dh_munsu", "t": "그분들이 「우리가 여기 있었다」고 적어 둔 걸, 제가 거두라고 옮겨 적고 있었어요."}, {"s": null, "t": "서고 안쪽에서 늙은 서리 하나가 등잔을 들고 나왔다."}, {"s": "q:sx_nosong", "t": "처음 목록을 나르는 서리는 다 거기서 붓을 멈추오. 나도 그랬소."}, {"s": "q:sx_nosong", "t": "정청이 모질어서 거두는 게 아니오. 이름을 다 붙들고 있으면 영이 너무 많아져서 명줄이 서로 엉키오. 그러다 산 사람 명줄까지 조이지. 서고에도 끝이 있고."}, {"s": "q:dh_munsu", "t": "그럼 이 끝은 어디예요."}, {"s": "q:sx_nosong", "t": "목록은 서고 맨 끝 칸에 넣소. 나도 그 칸이 어디 붙었는지 가끔 헷갈리오. 같이 좀 찾아 주시오."}]'::jsonb, '{"xp": 1951}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_office', 4, '백 년 뒤의 칸', '봉인고을(를) 살핀다', '{"at": ["seal_vault"], "tasks": [{"t": "search", "r": ["seal_vault"], "n": 2}]}'::jsonb, '[{"s": null, "t": "서고 맨 끝 칸은 생각보다 작았다. 칸마다 해가 적혀 있었고, 올해 칸 옆으로 아직 해를 적지 않은 빈 칸이 끝없이 이어져 있었다."}, {"s": "q:dh_munsu", "t": "언젠가 제 이름도 여기 들어오겠네요."}, {"s": "q:sx_nosong", "t": "내 이름이 먼저 들어올 거요. 서두르지 마시오."}, {"s": null, "t": "문수는 목록을 올해 칸에 넣었다. 그러고는 품에서 새 정화 부적 몇 장을 꺼내 바닥에 펼쳤다."}, {"s": "q:dh_munsu", "t": "명부에서 거두는 건 제가 못 막아요. 그래도 처마 부적 뒤에 적는 건 명부가 아니잖아요."}, {"s": null, "t": "문수는 옛 서리들의 이름을 한 사람씩 소리 내어 읽고, 부적 뒷면에 옮겨 적었다. 나도 그 이름들을 따라 불렀다."}, {"s": "q:sx_nosong", "t": "그건 명부가 아니니 거둘 것도 없겠구려. ……나는 아무것도 못 봤소."}, {"s": "q:dh_munsu", "t": "돌아가면 정청 처마에 붙일 거예요. 백 년 뒤에 누가 떼어 보면, 그 사람이 또 불러 주겠죠."}]'::jsonb, '{"xp": 1951, "gil": 129, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
