values ('sq110_first_market', 'side', '제작·반요촌', '반요촌 첫 장날', '반요들이 처음으로 장을 연다', 'banyo_village', 31, '{mq_nine_gates}'::text[], null, 1161, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_first_market' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_first_market', 1, '장을 연다', '장을 연다', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "반요촌 한가운데 빈터에 좌판 여섯 개가 놓여 있었다. 좌판마다 아무것도 없었다."}, {"s": "q:sx_sangsoe", "t": "왔구나, 바깥 손님! 오늘이 반요촌 첫 장날이야. 섬에 들어온 뒤로 처음 여는 장이지."}, {"s": "q:sx_sangsoe", "t": "문제가 셋 있어. 팔 게 없고, 살 사람이 없고, 값을 어떻게 매기는지 아무도 몰라."}, {"s": "q:sx_maru", "t": "넷이에요. 상쇠 아저씨는 셈도 못 해요."}, {"s": "q:sx_sangsoe", "t": "넷은 말 안 해도 되는 거였어!"}, {"s": null, "t": "나는 우선 무엇을 팔 생각이냐고 물었다."}, {"s": "q:sx_sangsoe", "t": "정화 부적! 몸에 밴 요기를 걷어 내는 거. 우리한텐 늘 모자란 물건이라 다들 탐낼 거야. 두 장만 만들어 줘. 좌판이 비어 있으면 장이 아니라 그냥 빈터잖아."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_first_market', 2, '값 매기기', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "부적 두 장을 좌판에 올리자 상쇠가 그 앞에서 한참 팔짱을 끼고 서 있었다."}, {"s": "q:sx_sangsoe", "t": "한 장에 일 전."}, {"s": "q:sx_maru", "t": "재료값이 그것보다 열 배는 더 들어요."}, {"s": "q:sx_sangsoe", "t": "그럼 만 전!"}, {"s": "q:sx_maru", "t": "그럼 아무도 못 사요. 이 섬에서 만 전 있는 사람은 없어요."}, {"s": "q:sx_sangsoe", "t": "그럼 일 전하고 만 전 사이 어딘가로 해!"}, {"s": null, "t": "마루가 나를 올려다보며 작게 한숨을 쉬었다. 열 살 아이의 한숨치고는 깊었다."}, {"s": "q:sx_maru", "t": "조사원님, 부적만 있으면 장이 너무 쓸쓸해요. 풍년 노리개를 하나 엮어서 맨 앞 좌판에 걸고 싶어요. 갈대숲에서 갈대 영사 네 타래만 걷어다 주실래요?"}]'::jsonb, '{"xp": 1951}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_first_market', 3, '손님이 없다', '갈대 영사을(를) 모은다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 4}]}'::jsonb, '[{"s": null, "t": "갈대 영사를 들고 돌아오니, 좌판 앞에 마을 사람들이 줄을 서 있었다. 그런데 다들 손에 아무것도 들고 있지 않았다."}, {"s": "q:sx_sangsoe", "t": "손님은 생겼는데 다들 돈이 없어. 우리끼리 사고팔려니 우리 돈이 다 같은 주머니에서 나와."}, {"s": "q:sx_maru", "t": "그리고 다들 부적을 살 생각이 없어요. 구경하러 왔대요. 장날이 뭔지 보고 싶대요."}, {"s": null, "t": "줄 선 사람들은 빈 좌판을 신기한 듯 들여다보았다. 한 노인은 좌판을 손바닥으로 쓸어 보고는 고개를 끄덕였다. 장이 열리는 걸 몇 해 만에 본다고 했다."}, {"s": "q:sx_sangsoe", "t": "그래서 생각했지. 값을 돈으로 안 받아."}, {"s": "q:sx_maru", "t": "무엇으로 받을지는 아직 못 정했대요."}, {"s": "q:sx_sangsoe", "t": "노리개부터 엮어! 노리개가 걸리면 생각이 날 거야. 영사에 반요 비늘을 꿰어 반요촌 풍년 노리개 하나만 엮어 줘."}]'::jsonb, '{"xp": 1951}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_first_market', 4, '이름값', '반요촌 풍년 노리개을(를) 만든다, 반요촌 풍년 노리개을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["n6_plenty"], "n": 1}], "give": {"n6_plenty": 1}}'::jsonb, '[{"s": null, "t": "풍년 노리개를 맨 앞 좌판에 걸자 비늘이 등불을 받아 반짝였다. 줄 선 사람들이 한꺼번에 「아」 하고 소리를 냈다."}, {"s": "q:sx_sangsoe", "t": "정했다! 오늘 장의 값은 이름값이야."}, {"s": "q:sx_sangsoe", "t": "물건을 사려면, 판 사람의 이름을 불러 줘야 해. 바깥 이름이든 섬 이름이든 하나만."}, {"s": "q:sx_maru", "t": "그럼 부적 한 장에 이름 한 번이에요?"}, {"s": "q:sx_sangsoe", "t": "그렇지! 셈하기도 쉽잖아."}, {"s": null, "t": "줄 선 사람들이 하나씩 좌판 앞으로 나와 상쇠의 이름을 불렀다. 상쇠는 이름이 불릴 때마다 대답하고, 부적을 손톱만큼씩 찢어 손등에 붙여 주었다. 두 장으로 마을 사람 모두에게 돌아갔다."}, {"s": null, "t": "마지막으로 내 차례가 왔다. 나는 노리개를 가리키고 마루의 이름을 불렀다."}, {"s": "q:sx_maru", "t": "……바깥 사람이 제 이름 불러 준 거 처음이에요."}, {"s": null, "t": "마루는 노리개를 내 손에 쥐여 주려다가 도로 좌판에 걸었다. 다음 장날에도 맨 앞에 걸어 두어야 손님이 온다고 했다."}, {"s": "q:sx_sangsoe", "t": "마루야, 오늘 번 거 셈해 봐."}, {"s": "q:sx_maru", "t": "이름 서른한 번이요. 아저씨가 스물아홉 번, 제가 한 번, 그리고 아저씨가 혼잣말로 아저씨 이름을 한 번 불렀어요."}, {"s": "q:sx_sangsoe", "t": "그것도 쳐줘!"}]'::jsonb, '{"xp": 1951, "gil": 129, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
