delete from public.world_quest_steps where quest_id = 'sq110_reed_name' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_reed_name', 1, '반쪽 이름', '반쪽 이름', '{"at": ["ash_reeds"]}'::jsonb, '[{"s": null, "t": "갈대숲 어귀에서 아낙 하나가 바람에 귀를 기울이고 있었다. 손등에 회색 비늘이 돋아 있었다."}, {"s": "q:sx_hojeong", "t": "들리세요? 바람이 불 때마다 갈대가 「석」 하고 불러요."}, {"s": "q:sx_hojeong", "t": "우리 집 양반 이름이에요. 석규. 반요촌 문패에 바깥 이름이랑 섬 이름을 같이 적어 뒀는데, 두 이름이 다 흐려지더니 지난봄에 갈대숲으로 걸어 들어갔어요."}, {"s": "q:sx_hojeong", "t": "이름을 다 잃으면 요괴가 된대요. 그다음엔 이름 대신 갈래로 불린다고요."}, {"s": null, "t": "나는 갈대가 왜 앞 글자만 부르느냐고 물었다."}, {"s": "q:sx_hojeong", "t": "저도 몰라요. 저는 그 사람 이름을 아직 다 기억하는데, 제가 불러도 갈대는 「석」까지만 따라 해요."}, {"s": "q:sx_hojeong", "t": "그 사람이 어디쯤 있는지만이라도 알고 싶어요. 갈대숲을 좀 살펴 주시겠어요?"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_reed_name', 2, '물귀신의 길', '잿빛 갈대숲을(를) 살핀다', '{"at": ["ash_reeds"], "tasks": [{"t": "search", "r": ["ash_reeds"], "n": 3}]}'::jsonb, '[{"s": null, "t": "갈대숲 안쪽에서 갈대가 한 방향으로 누워 있었다. 누운 갈대 끝마다 물이 고여 있었다. 무언가 갈대를 엮어 길을 낸 자국이었다."}, {"s": null, "t": "돌아와 그 말을 전하자 호정 뒤에서 여자아이 하나가 고개를 내밀었다."}, {"s": "q:sx_gyusun", "t": "거기 아빠 있어? 나도 갈래."}, {"s": "q:sx_hojeong", "t": "규순아, 너는 안 돼. 그 길목에 갈대 물귀신이 들끓는대."}, {"s": "q:sx_gyusun", "t": "그럼 조사원님이 물귀신 치워 주면 되잖아."}, {"s": null, "t": "호정이 나를 보며 고개를 숙였다. 말리지 못하겠다는 얼굴이었다."}, {"s": "q:sx_hojeong", "t": "길목에 있는 것들만 쫓아 주세요. 끝까지 가는 건, 그다음에 정할게요."}]'::jsonb, '{"xp": 1951}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_reed_name', 3, '갈대 엮인 것', '갈대 물귀신을(를) 물리친다', '{"at": ["ash_reeds"], "tasks": [{"t": "win", "m": ["gw_reed_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "물귀신이 흩어지자 갈대 길 끝에 사람 꼴을 한 것이 서 있었다. 온몸에 갈대를 엮어 감고, 그 갈대로 어깨와 팔과 얼굴을 겨우 지키고 있었다."}, {"s": "q:sx_gyusun", "t": "아빠!"}, {"s": null, "t": "갈대 엮인 것이 고개를 돌렸다. 그러나 규순을 보고도 알아보지 못했다. 갈대 사이로 독기 섞인 숨이 새어 나왔다."}, {"s": "q:sx_hojeong", "t": "석규 씨. 석규 씨, 나예요."}, {"s": null, "t": "갈대 엮인 것이 「석」 하고 따라 말했다. 그 뒤가 나오지 않았다. 갈대가 다시 바람도 없이 「석」 하고 울었다."}, {"s": "q:sx_hojeong", "t": "이제 저 사람은 이름으로 안 불려요. 갈대 엮인 요인. 마을에서는 그렇게 불러요."}, {"s": "q:sx_hojeong", "t": "저 사람을 편히 보내 주세요. 사람 꼴을 지키느라 저렇게 갈대를 감고 있는 게, 보는 저보다 저 사람이 더 아플 거예요."}]'::jsonb, '{"xp": 1951}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_reed_name', 4, '뒷글자', '갈대 엮인 요인을(를) 물리친다', '{"at": ["ash_reeds"], "tasks": [{"t": "win", "m": ["gw_reed_4"], "n": 1}]}'::jsonb, '[{"s": null, "t": "갈대 엮인 요인이 무릎을 꿇자 감고 있던 갈대가 하나씩 풀렸다. 그 안에는 거의 아무것도 남아 있지 않았다."}, {"s": null, "t": "규순이 호정의 손을 뿌리치고 달려가 그 앞에 섰다."}, {"s": "q:sx_gyusun", "t": "아빠, 나 규순이야. 아빠가 지어 준 이름. 아빠 이름 뒷글자 떼어서 지어 줬다며."}, {"s": null, "t": "갈대가 일제히 숨을 죽였다. 요인이 고개를 들었다. 그리고 처음으로 「규」 하고 말했다."}, {"s": null, "t": "「석」, 「규」. 갈대가 두 글자를 이어서 불렀다. 반쪽은 갈대숲에, 반쪽은 딸의 이름에 남아 있었던 것이다."}, {"s": "q:sx_hojeong", "t": "……그래서 갈대가 앞 글자만 불렀구나. 뒷글자는 늘 우리 집에 있었네."}, {"s": null, "t": "요인이 규순을 향해 손을 뻗다가, 닿기 전에 갈대 부스러기가 되어 바람에 흩어졌다."}, {"s": null, "t": "마을로 돌아오는 길에 바람이 한 번 불었다. 갈대가 「석」이 아니라 「규순아」 하고 불렀다. 규순이 돌아보며 대답했다."}]'::jsonb, '{"xp": 1951, "gil": 129, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
