values ('sq110_s_chaeun', 'side', '낚시·흑조 균열', '빚 갚는 배', '흑련회가 정말 빚을 받으러 왔다', 'black_tide_rift', 31, '{sq_black_tide_rift_2,mq_nine_gates}'::text[], null, 1163, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_s_chaeun' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_chaeun', 1, '빚쟁이가 왔다', '빚쟁이가 왔다', '{"at": ["black_tide_rift"]}'::jsonb, '[{"s": null, "t": "균열 가장자리 바위 위에서 누군가 주판을 머리 위로 치켜든 채 떨고 있었다. 바위 아래에서는 검은 게 떼가 그가 타고 온 작은 배를 새까맣게 뒤덮고 있었다."}, {"s": "q:sx_yeolhan", "t": "거기 지나가는 분! 흑련회 수금꾼 열한째요. 이름이 아니라 호칭이니 묻지 마시오. 저 게들 좀, 저 게들 좀……!"}, {"s": null, "t": "바위 뒤에서 낯익은 여인이 느긋하게 걸어 나왔다. 채운이었다. 소매의 흑련 문양은 그새 더 바래 있었다."}, {"s": "q:bl_chaeun", "t": "어, 너구나. 다섯 해 만이네. 마침 잘 왔어. 빚 받으러 온 사람이 저 꼴이야."}, {"s": "q:sx_yeolhan", "t": "웃을 일이 아니오! 배 한 척, 짐 한 배, 다섯 해 이자까지. 장부지기께서 오늘은 꼭 받아 오라 하셨소."}, {"s": "q:bl_chaeun", "t": "갚는다니까. 그런데 네가 게밥이 되면 누구한테 갚아."}, {"s": "q:bl_chaeun", "t": "조사원, 저 배에 붙은 검은 게 떼부터 좀 떼어 줘. 네 번쯤 치우면 될 거야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_chaeun', 2, '맞지 않는 셈', '검은 게 떼을(를) 물리친다', '{"at": ["black_tide_rift"], "tasks": [{"t": "win", "m": ["x_black_tide_rift_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "게 떼가 흩어지자 열한째가 바위에서 미끄러져 내려와 제 배를 끌어안았다. 작고 낡았지만 단단한 배였다."}, {"s": "q:bl_chaeun", "t": "좋은 배네. 노도 멀쩡하고."}, {"s": "q:sx_yeolhan", "t": "내 배요. 아니, 회의 배요. 자, 이제 셈을 합시다. 무엇으로 갚겠소?"}, {"s": "q:bl_chaeun", "t": "고기로 갚지. 이 균열 고기는 바깥에서 값을 잘 쳐주잖아."}, {"s": null, "t": "열한째가 주판알을 한참 튕겼다. 튕길수록 얼굴이 하얘졌다."}, {"s": "q:sx_yeolhan", "t": "흑조 먹장어로 치면 사천 마리, 심연 초롱아귀로 쳐도 팔백 마리요. 선장이 평생 낚아도 모자라오."}, {"s": "q:bl_chaeun", "t": "누가 다 낚는댔어. 고기는 물길을 보려고 낚는 거야. 균열 고기는 바로 흐르는 물로만 다니거든. 어디서 무는지 보면 배 띄울 길이 보여."}, {"s": "q:bl_chaeun", "t": "조사원, 세 번만 던져 줘. 내 손은 노 잡으려고 아껴 둬야 해서."}]'::jsonb, '{"xp": 1951}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_chaeun', 3, '상환 방식', '흑조 균열에서 낚시를 한다', '{"at": ["black_tide_rift"], "tasks": [{"t": "fish", "r": ["black_tide_rift"], "n": 3}]}'::jsonb, '[{"s": null, "t": "고기는 세 번 다 균열 왼쪽 가장자리에서 물었다. 채운은 그쪽 물살을 한참 보더니 고개를 끄덕였다."}, {"s": "q:bl_chaeun", "t": "저기다. 저 물길이면 거꾸로 안 뒤집히고 빠져나갈 수 있어."}, {"s": "q:sx_yeolhan", "t": "빠져나간다니, 어디로 말이오? 빚은 어쩌고?"}, {"s": "q:bl_chaeun", "t": "배 한 척을 빚졌으니 배 한 척 띄워서 갚을 거야. 회 짐을 다시 나르는 거지. 한 배 나를 때마다 장부에서 한 줄씩 지워."}, {"s": "q:sx_yeolhan", "t": "배가 어디 있소?"}, {"s": null, "t": "채운은 말없이 열한째의 배를 손바닥으로 툭툭 두드렸다. 열한째가 주판을 떨어뜨렸다."}, {"s": "q:sx_yeolhan", "t": "이건 빚 받으러 온 배요! 빚 받으러 온 배로 빚을 갚는 법이 어디 있소!"}, {"s": "q:bl_chaeun", "t": "여기 있지. 그리고 첫 뱃길이니 먹을 것도 실어야 해. 조사원, 노정 건량 세 개만 챙겨 줘. 둘이 사흘은 버틸 거야."}, {"s": "q:sx_yeolhan", "t": "둘? 둘이라니, 나도 타란 말이오?"}]'::jsonb, '{"xp": 1951}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_chaeun', 4, '열셋째', '노정 건량을(를) 넘긴다', '{"at": ["black_tide_rift"], "give": {"travel_ration": 3}}'::jsonb, '[{"s": null, "t": "건량을 배에 싣자 채운이 품에서 종이 한 장을 꺼냈다. 새로 적은 선원 명부였다."}, {"s": null, "t": "맨 위부터 열두 이름이 적혀 있었다. 돌쇠, 막동, 끝순이……. 다섯 해 전 이 균열에서 보낸 선원들이었다."}, {"s": "q:bl_chaeun", "t": "배는 새로 띄워도 명부는 이어 써야지. 애들 밑에 네가 들어가."}, {"s": "q:sx_yeolhan", "t": "나는 이름을 회에 맡겨 둔 사람이오. 적을 이름이 없소."}, {"s": "q:bl_chaeun", "t": "그럼 열셋째라고 적지. 호칭 하나 더 생겼다 치고."}, {"s": null, "t": "열한째는 한참 명부를 내려다보다가, 떨어뜨린 주판을 주워 품에 넣었다."}, {"s": "q:sx_yeolhan", "t": "……장부에는 「상환 방식: 뱃일, 선원 한 명 차출」이라고 적겠소. 차출된 게 나라는 말은 안 적을 거요."}, {"s": "q:bl_chaeun", "t": "마음대로 해. 노는 네가 저어."}, {"s": null, "t": "작은 배가 균열 왼쪽 물길로 미끄러져 나갔다. 열한째의 비명이 한참 들리다가, 어느새 노 젓는 소리로 바뀌었다."}]'::jsonb, '{"xp": 1951, "gil": 129, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
