insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_analyst', 1, '다시 깜빡이는 등', '다시 깜빡이는 등', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "서린의 등이 또 깜빡이고 있었다. 이번에는 불빛이 깜빡일 때마다 색이 조금씩 바랬다."}, {"s": "q:dh_ilsu", "t": "이번엔 길을 잃은 게 아니야. 등 색이 바래는 건 이름이 흐려진다는 거야."}, {"s": "q:dh_ilsu", "t": "흑조 균열에 들어갔대. 그 검은 물 근처에 오래 있으면 요기가 스며. 제 이름이 남의 이름처럼 들리기 시작한다더라."}, {"s": "q:dh_ilsu", "t": "그 녀석이 떠나기 전에 칼을 맡기고 갔어. 이거 봐."}, {"s": null, "t": "마일수가 단도 한 자루를 내밀었다. 손잡이에도, 칼날에도 이름 한 자 새겨져 있지 않았다."}, {"s": "q:dh_ilsu", "t": "암영 칼에는 이름을 안 새기지. 누구 칼인지 알면 쫓기니까. 그런데 이젠 그 칼을 들고 가서 그 녀석이 누군지 알려 줘야 할 것 같아. 균열 근처를 뒤져서 찾아."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_analyst', 2, '검은 물가', '흑조 균열을(를) 살핀다', '{"at": ["black_tide_rift"], "tasks": [{"t": "search", "r": ["black_tide_rift"], "n": 3}]}'::jsonb, '[{"s": null, "t": "균열 물가 바위 위에 서린이 앉아 있었다. 검은 물결만 바라보고 있었다. 내가 이름을 불러도 한참 뒤에야 고개를 돌렸다."}, {"s": "q:sx_seorin", "t": "…누구 이름이었지, 그게."}, {"s": null, "t": "나는 그것이 그의 이름이라고 말해 주었다. 서린은 대답 대신 물가 쪽을 가리켰다. 검은 껍데기의 게들이 바위를 기어올라 우리를 에워싸고 있었다."}, {"s": "q:sx_seorin", "t": "저것들이 밤마다 올라와. 칼이 없어서 피하기만 했다."}, {"s": null, "t": "나는 맡아 온 단도를 서린 손에 쥐여 주었다. 그는 칼을 쥐는 법만은 잊지 않고 있었다."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_analyst', 3, '물 밑의 손님', '검은 게 떼을(를) 물리친다', '{"at": ["black_tide_rift"], "tasks": [{"t": "win", "m": ["x_black_tide_rift_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "게 떼가 물러가자 서린이 칼날을 내려다보았다. 아무것도 새겨지지 않은 칼날에 제 얼굴이 비쳤다."}, {"s": "q:sx_seorin", "t": "이름 없는 칼이 좋다고 생각했다. 아무도 나를 못 쫓으니까."}, {"s": "q:sx_seorin", "t": "그런데 이제는 나도 나를 못 쫓겠다."}, {"s": null, "t": "검은 물 위로 흐릿한 형체들이 떠올랐다. 균열 바닥에 가라앉은 원령들이 이름을 잃어 가는 사람의 기척을 따라 올라오고 있었다."}, {"s": null, "t": "저것들 곁에 오래 있으면 서린의 요기도 깊어질 것이었다. 정화 부적으로 그의 요기를 덜어 내고, 원령들을 물 밑으로 돌려보내야 했다."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_analyst', 4, '이름은 등에', '심해 원령을(를) 물리친다, 정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "win", "m": ["x_black_tide_rift_2"], "n": 2}, {"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 1}}'::jsonb, '[{"s": null, "t": "정화 부적을 태우자 서린의 눈빛이 조금 맑아졌다. 나는 그를 데리고 야시장까지 돌아왔다."}, {"s": null, "t": "등롱 가게에 들어서자 서린의 등이 깜빡임을 멈추었다. 바랬던 색이 천천히 돌아왔다. 등에는 마일수가 처음 써 준 그대로 그의 이름이 적혀 있었다."}, {"s": "q:sx_seorin", "t": "…서린. 그래, 서린이었다."}, {"s": "q:dh_ilsu", "t": "그래서 내가 등에 이름을 쓰라고 하는 거야. 칼에는 이름이 없어도 돼. 이름은 등이 지켜 주니까."}, {"s": null, "t": "서린은 단도를 칼집에 꽂았다. 끝내 칼날에는 아무것도 새기지 않았다."}, {"s": "q:sx_seorin", "t": "칼은 이름 없이 둔다. 대신 돌아올 데를 안다."}, {"s": null, "t": "서린은 내 등 아래로 가서 붓을 들었다. 내 이름 옆에 작은 칼자국 하나를 그렸다. 따라오라는 암영의 표시였다."}, {"s": "q:dh_ilsu", "t": "앞으로 네 등이 깜빡이면, 저 녀석이 제일 먼저 찾으러 가겠다는 거야."}]'::jsonb, '{"xp": 2065, "gil": 133, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
