insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_artificer', 1, '낯익은 매듭', '낯익은 매듭', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "반요촌 들머리, 갈대로 엮은 문 앞에 손등에 비늘 무늬가 돋은 사내가 낡은 방패를 끼고 서 있었다."}, {"s": "q:sx_galbaram", "t": "…그 칼집 매듭. 서문 호위대 것이로군."}, {"s": "q:sx_galbaram", "t": "섬 밖에서 그 매듭을 매는 놈이 아직 있나. 탁대근이라는 늙은이도 아직 살아 있고?"}, {"s": null, "t": "나는 탁대근이 서문 폐성을 지키고 있다고 했다. 사내는 한참 갈대숲 쪽만 바라보았다."}, {"s": "q:sx_galbaram", "t": "그래. 그 다리로도 버티는구먼."}, {"s": "q:sx_galbaram", "t": "밤마다 갈대 물귀신이 물가에 나온 아이들 발목을 잡아끌어. 나 혼자는 문을 비울 수가 없어. 네가 물가를 좀 맡아 다오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_artificer', 2, '문패에 적힌 이름', '갈대 물귀신을(를) 물리친다', '{"at": ["banyo_village"], "tasks": [{"t": "win", "m": ["gw_reed_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "문지기의 문패에는 이름이 하나뿐이었다. 섬에 와서 얻은 이름, 갈바람이었다. 옆에 있어야 할 바깥 이름 자리는 비어 있었다."}, {"s": "q:sx_galbaram", "t": "바깥 이름은 밤마다 조금씩 흐려진다. 아이들이 갈바람이라고 불러 주니 그쪽으로는 돌아보지."}, {"s": "q:sx_galbaram", "t": "서문이 무너진 밤에 나는 부적을 셋째로 긋던 놈이었다. 앞에서 그 늙은이가 맞는 동안 끝까지 그었지. 대신 요기가 손으로 들어왔다."}, {"s": "q:sx_galbaram", "t": "이 방패도 이제 오래 못 든다. 끈이 삭았고, 손도 예전 같지 않아."}, {"s": "q:sx_galbaram", "t": "갈대숲에서 갈대 영사를 거둬 오너라. 그걸로 끈을 꼬면 비늘 돋은 손에도 미끄러지지 않는다. 오가는 길에 잿빛 백로 떼가 덤비거든 쫓아 버리고."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_artificer', 3, '끈을 꼬는 손', '갈대 영사을(를) 모은다, 잿빛 백로 떼을(를) 물리친다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 4}, {"t": "win", "m": ["gw_reed_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "갈바람은 문 앞에 앉아 갈대 영사로 방패 끈을 꼬았다. 손가락이 자꾸 떨려 실이 엉켰다."}, {"s": "q:sx_galbaram", "t": "손이 내 말을 안 듣는다. 요문이 손끝까지 올라온 탓이야."}, {"s": null, "t": "나는 끈의 한쪽 끝을 잡아 주었다. 갈바람은 말없이 나머지를 꼬았다."}, {"s": "q:sx_galbaram", "t": "방패는 마지막까지 서 있는 놈이 드는 거다. 내가 쓰러지면 이 문에는 아무도 없어."}, {"s": "q:sx_galbaram", "t": "정화 부적을 손등에 붙이면 한동안 손이 돌아온다더라. 두 장만 지어 다오. 하나는 내 손에, 하나는 문 안 아이들 몫이다."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_artificer', 4, '두 이름', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "부적을 붙인 손으로 갈바람이 새 끈을 단 방패를 들어 올렸다. 이번에는 손이 떨리지 않았다."}, {"s": "q:sx_galbaram", "t": "됐다. 이 정도면 몇 해는 더 든다."}, {"s": null, "t": "갈바람은 붓을 들어 탁대근에게 보낼 편지 끝에 이름을 적다가 멈추었다. 한참 뒤에야 비어 있던 바깥 이름을 써 넣었다. 석주였다."}, {"s": "q:sx_galbaram", "t": "그 늙은이가 그 이름으로 불러 줄 테니, 적어 둬야지. 안 그러면 그 이름은 이 섬에서 아무도 모른다."}, {"s": null, "t": "그리고 문패의 빈자리에도 같은 이름을 새겼다. 갈바람 옆에 석주."}, {"s": null, "t": "문 안에서 아이들이 갈바람을 불렀다. 사내는 돌아보았다. 나는 시험 삼아 석주라고 불러 보았다. 사내는 그쪽으로도 돌아보았다."}, {"s": "q:sx_galbaram", "t": "편지는 네가 전해라. 그리고 그 늙은이한테 말해. 셋째는 아직 문 앞에 서 있다고."}]'::jsonb, '{"xp": 2065, "gil": 133, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
