insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_exorcist', 1, '방울을 빌려주는 밤', '방울을 빌려주는 밤', '{"at": ["shrine_ruins"]}'::jsonb, '[{"s": null, "t": "가을은 촛대 앞에 앉아 제 방울을 꼭 쥐고 있었다. 무언가 결심한 얼굴이었다."}, {"s": "q:dh_gaeul", "t": "퇴마관님, 귀허도에 거꾸로 선 사당이 있대요. 거기선 진언을 바로 외면 거꾸로 들린대요. 그래서 거기 퇴마관들은 다 졌대요."}, {"s": "q:dh_gaeul", "t": "저도 같이 갈래요. 이 방울이 있는 데면 저도 있을 수 있어요. 방울을 빌려 드릴게요."}, {"s": null, "t": "나는 섬에서는 잃어버린 것들이 귀허 쪽으로 흘러간다고 했다. 가을도 휩쓸려 갈지 몰랐다."}, {"s": "q:dh_gaeul", "t": "알아요. 그래서 꼭 쥐고 있어 줘요. 퇴마관님이 제 이름을 부르면 저는 안 떠내려가요."}, {"s": null, "t": "나는 가을의 방울을 받아 품에 넣었다. 방울 속에서 작은 목소리가 들렸다."}, {"s": "q:dh_gaeul", "t": "사당 안을 먼저 돌아봐요. 소리가 어디로 빠져나가는지 들어 봐야 해요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_exorcist', 2, '아래로 흐르는 연기', '거꾸로 선 사당을(를) 살핀다', '{"at": ["inverted_shrine"], "tasks": [{"t": "search", "r": ["inverted_shrine"], "n": 3}]}'::jsonb, '[{"s": null, "t": "사당은 지붕이 땅에 박히고 주춧돌이 하늘을 향해 있었다. 내가 진언을 외자 소리가 위로 올라가지 않고 발밑으로 가라앉았다."}, {"s": "q:dh_gaeul", "t": "들었어요? 소리가 다 땅 밑으로 가요. 땅 밑에 뭐가 있어서 삼키고 있어요."}, {"s": null, "t": "바닥 틈에서 연기가 거꾸로 흘러내렸다. 연기를 따라 뒤집힌 향로들이 기어 다녔다. 향로가 연기를 뿜을 때마다 내 진언이 목에서 막혔다."}, {"s": null, "t": "방울이 품 안에서 작게 떨었다. 가을이 겁을 먹은 것 같았다. 나는 방울을 쥔 손에 힘을 주었다."}, {"s": "q:dh_gaeul", "t": "저 향로들이 진언을 끊어요. 먼저 치워요. 제가 방울 소리로 길을 잡을게요."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_exorcist', 3, '종에 새긴 이름', '뒤집힌 향로귀을(를) 물리친다', '{"at": ["inverted_shrine"], "tasks": [{"t": "win", "m": ["gw_shrine_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "향로가 사라지자 땅 밑에서 종소리가 들렸다. 거꾸로 매달린 범종이 소리를 삼키며 천천히 흔들리고 있었다."}, {"s": "q:dh_gaeul", "t": "저 종이에요. 소리를 거꾸로 먹고 있어요. 종 테두리에 뭐가 적혀 있어요."}, {"s": null, "t": "종 테두리에는 종지기의 이름이 새겨져 있었다. 글자도 거꾸로 새겨져 있어서 바로 읽으면 뜻이 없는 소리였다."}, {"s": "q:dh_gaeul", "t": "여기선 다 거꾸로잖아요. 이름도 끝 글자부터 불러야 들릴 거예요. 진언도 끝 줄부터요."}, {"s": null, "t": "나는 정화 부적에 진언을 끝 줄부터 거꾸로 적어 넣기로 했다. 종을 멈추려면 부적이 둘은 있어야 했다."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_exorcist', 4, '바로 들리는 이름', '정화 부적을(를) 만든다, 거꾸로 선 범종귀을(를) 물리친다, 정화 부적을(를) 넘긴다', '{"at": ["shrine_ruins"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}, {"t": "win", "m": ["gw_shrine_5"], "n": 1}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "거꾸로 외는 진언이 종에 닿자 종이 처음으로 바른 소리를 냈다. 나는 종지기의 이름을 끝 글자부터 불렀다. 종이 멈추고, 테두리의 글자가 바로 섰다."}, {"s": null, "t": "범종귀는 무너지기 전에 아주 잠깐 흔들림을 멈추었다. 바로 선 제 이름 쪽으로 돌아보듯이."}, {"s": null, "t": "돌아오는 뱃길 내내 방울이 조금씩 귀허 쪽으로 끌렸다. 그때마다 나는 가을의 이름을 불렀다. 방울은 다시 내 품으로 돌아왔다."}, {"s": null, "t": "폐쇄 사당에 닿아 방울을 돌려주자 가을이 촛대 앞에 또렷하게 나타났다."}, {"s": "q:dh_gaeul", "t": "열네 번이요. 퇴마관님이 제 이름을 부른 거요. 다 셌어요."}, {"s": "q:dh_gaeul", "t": "그 종지기 아저씨, 이름을 거꾸로 새긴 건 일부러였을 거예요. 거꾸로 선 데서도 누가 바로 불러 주길 바랐던 거예요."}, {"s": "q:dh_gaeul", "t": "진언은 끝 줄부터 외워도 되는구나. 마음만 바로 서 있으면요. 저도 그거 외워 둘래요."}]'::jsonb, '{"xp": 2065, "gil": 133, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
