insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_medic', 1, '줄 그은 이름', '줄 그은 이름', '{"at": ["lantern_market"]}'::jsonb, '[{"s": null, "t": "고분이 외상 장부 첫째 권의 맨 앞쪽을 펴 놓고 있었다. 종이가 누렇게 바래 있었다."}, {"s": "q:dh_gopun", "t": "이거 봐. 서른 해 전에 내가 줄 그은 이름이야. 요기가 깊어져서 섬으로 실려 간 사람이지."}, {"s": "q:dh_gopun", "t": "그런데 반요촌에서 이 사람이 살아 있다는 소식이 왔어. 줄을 잘못 그은 거야."}, {"s": "q:dh_gopun", "t": "그 섬엔 약방이 없다지. 자네가 왕진을 좀 가 줘. 이 늙은이는 배를 못 타."}, {"s": "q:dh_gopun", "t": "섬 사람들 요문 자리엔 정화 부적이 제일 잘 들어. 세 장 지어 가. 그리고 이 장부도 가져가."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_medic', 2, '섬의 이름', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 3}], "give": {"ward_talisman": 3}}'::jsonb, '[{"s": null, "t": "반요촌 끝집에서 부엉이처럼 눈이 둥근 노인이 나를 맞았다. 목덜미까지 요문이 덮여 있었다."}, {"s": "q:sx_solbueong", "t": "약방에서 오셨습니까. 바깥에서 약이 오다니, 서른 해 만입니다."}, {"s": null, "t": "나는 노인의 요문 자리에 정화 부적을 붙여 주었다. 노인은 오래 참았던 숨을 내쉬었다."}, {"s": "q:sx_solbueong", "t": "여기서는 솔부엉이라고 불립니다. 섬에 와서 얻은 이름입니다. 바깥 이름은… 요즘은 잘 떠오르지 않습니다."}, {"s": "q:sx_solbueong", "t": "저보다 아이들이 걱정입니다. 갈대숲 물가에서 놀다가 물귀신에게 홀린 아이들이 밤마다 물을 토합니다. 물가에 그것들이 너무 많습니다."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_medic', 3, '아이들의 밤', '갈대 물귀신을(를) 물리친다', '{"at": ["banyo_village"], "tasks": [{"t": "win", "m": ["gw_reed_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "물가가 조용해졌다. 하지만 홀렸던 아이들은 여전히 밤마다 깨어 울었다. 물속에서 누가 이름을 불렀다고 했다."}, {"s": "q:sx_solbueong", "t": "물귀신은 이름을 반쯤 부르다 맙니다. 그래서 아이들이 제 이름을 반만 듣고 깹니다."}, {"s": null, "t": "나는 아이들 맥을 짚었다. 열은 없었다. 마음이 놀라 몸이 쉬지 못하고 있었다."}, {"s": null, "t": "고분이라면 안신탕을 달였을 것이다. 나는 아이들 수를 세었다. 넷이었다."}, {"s": "q:sx_solbueong", "t": "약을 지으시는 동안 저는 아이들 이름을 불러 주겠습니다. 끝까지, 반만이 아니라요."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_medic', 4, '줄을 지우는 법', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["lantern_market"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 4}], "give": {"calm_brew": 4}}'::jsonb, '[{"s": null, "t": "아이들은 안신탕을 먹고 아침까지 잤다. 나는 떠나기 전 노인에게 고분의 장부를 보여 주었다. 노인은 줄 그어진 이름을 오래 들여다보다가, 그 옆에 떨리는 글씨로 「아직 있음」이라고 적었다."}, {"s": null, "t": "나는 야시장으로 돌아와 장부를 고분에게 돌려주었다."}, {"s": "q:dh_gopun", "t": "…차복이. 이 녀석, 살아 있었구먼."}, {"s": null, "t": "할멈이 그 이름을 소리 내어 부르는 것은 서른 해 만이라고 했다."}, {"s": "q:dh_gopun", "t": "줄 그은 걸 지우는 건 처음이야. 먹은 못 지우니까, 이렇게 옆에 적는 수밖에 없지."}, {"s": null, "t": "할멈은 그 이름을 첫째 권에서 둘째 권으로 옮겨 적었다. 아직 갚을 사람들의 장부였다."}, {"s": "q:dh_gopun", "t": "섬에 또 가거든 전해. 약값은 안 받는다고. 그러니 오래 갚으라고."}, {"s": "q:dh_gopun", "t": "왕진은 약을 주러 가는 게 아니야. 아직 거기 있다고 알려 주러 가는 거지. 자네가 그걸 했어."}]'::jsonb, '{"xp": 2065, "gil": 133, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
