insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_scout', 1, '휘는 화살', '휘는 화살', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "반요촌 나루에 위소라가 서 있었다. 섬까지 건너온 것이 믿기지 않았다."}, {"s": "q:dh_sora", "t": "놀랐어요? 사수가 섬 하나 못 건너면 안 되죠."}, {"s": "q:dh_sora", "t": "그런데 여긴 이상해요. 갈대숲 쪽으로 쏘면 화살이 다 한쪽으로 휘어요. 바람이 늘 같은 데로 불어요."}, {"s": null, "t": "위소라가 화살 한 대를 쏘았다. 화살은 곧게 날아가다가 섬 깊은 쪽, 귀허가 있는 쪽으로 꺾여 사라졌다."}, {"s": "q:dh_sora", "t": "바람을 모르면 아무것도 못 맞혀요. 잿빛 갈대숲을 몇 번 돌아요. 갈대가 어느 쪽으로 눕는지, 어디서 바람이 꺾이는지 읽어 와요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_scout', 2, '떠난 쪽으로 부는 바람', '잿빛 갈대숲을(를) 살핀다', '{"at": ["ash_reeds"], "tasks": [{"t": "search", "r": ["ash_reeds"], "n": 3}]}'::jsonb, '[{"s": null, "t": "갈대는 어디서나 귀허 쪽으로 누워 있었다. 갈대 사이에 떨어진 깃털도, 물 위의 재도 모두 그쪽으로 흘러갔다."}, {"s": "q:dh_sora", "t": "반요촌 사람들이 그랬어요. 여기 바람은 잃어버린 것 쪽으로 분대요."}, {"s": "q:dh_sora", "t": "그럼 이 바람을 아는 깃을 달아야 해요. 이 바람 속에서 사는 새 깃털이요."}, {"s": null, "t": "갈대숲 위로 잿빛 깃의 새 떼가 낮게 날았다. 바람을 거스르지 않고, 바람을 타고 방향을 틀었다."}, {"s": "q:dh_sora", "t": "잿빛 백로 떼예요. 저것들이 떨어뜨린 깃이면 돼요. 쫓아내면서 깃을 주워 와요."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_scout', 3, '깃을 매는 실', '잿빛 백로 떼을(를) 물리친다', '{"at": ["ash_reeds"], "tasks": [{"t": "win", "m": ["gw_reed_2"], "n": 4}]}'::jsonb, '[{"s": null, "t": "나는 백로 떼가 흩어진 자리에서 잿빛 깃을 한 줌 주워 왔다. 위소라는 깃을 하나씩 빛에 비추어 보고 골랐다."}, {"s": "q:dh_sora", "t": "좋아요. 결이 다 한 방향이에요."}, {"s": "q:dh_sora", "t": "그런데 보통 실로 매면 바람에 깃이 돌아가요. 이 섬 것으로 매야 이 섬 바람을 버텨요."}, {"s": null, "t": "나는 갈대 영사를 쓰면 어떠냐고 물었다. 위소라가 고개를 끄덕였다."}, {"s": "q:dh_sora", "t": "그거예요. 갈대에서 잣는 빛나는 실. 넉넉히 거둬 와요. 셋은 제가 깃 매는 데 쓸게요."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_scout', 4, '바람에 맡기는 화살', '갈대 영사을(를) 모은다, 갈대 영사을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 4}], "give": {"reed_silk": 3}}'::jsonb, '[{"s": null, "t": "위소라가 갈대 영사로 잿빛 깃을 맨 화살을 쏘았다. 화살은 바람을 타고 휘었다가, 바람 끝에서 다시 곧게 펴져 과녁 한가운데 꽂혔다."}, {"s": "q:dh_sora", "t": "바람을 이기려고 하면 안 돼요. 읽고, 타고, 끝에서 고치는 거예요."}, {"s": null, "t": "위소라는 화살 세 대를 더 꺼냈다. 화살대마다 사람 이름이 하나씩 새겨져 있었다. 그믐에 돌아오지 않은 순찰조의 이름이었다."}, {"s": "q:dh_sora", "t": "이 바람이 잃어버린 쪽으로 분다면, 이 화살들도 그 사람들한테 닿겠죠."}, {"s": null, "t": "위소라는 세 대를 차례로 바람에 맡겨 쏘았다. 화살은 귀허 쪽으로 멀리, 아주 멀리 날아갔다."}, {"s": "q:dh_sora", "t": "이름을 적어 보냈으니까 길은 안 잃을 거예요."}, {"s": "q:dh_sora", "t": "남은 깃은 당신 거예요. 언젠가 당신이 바람 쪽으로 쏠 일이 생기면 쓰세요. …그런 일은 없으면 좋겠지만요."}]'::jsonb, '{"xp": 2065, "gil": 133, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
