insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_sealmaster', 1, '돌아오지 않은 열쇠', '돌아오지 않은 열쇠', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "출납관 자리에 낯선 사람이 앉아 있었다. 책상은 그대로였다. 붓걸이와 벼루도 윤도한이 쓰던 그대로였다."}, {"s": "q:sx_hanbi", "t": "봉인술사님이시죠. 전 출납관님 장부에 자주 나오는 이름이라 바로 알았어요."}, {"s": "q:sx_hanbi", "t": "장부를 넘겨받아 맞추는데, 봉인고 열쇠 하나가 빠져 있어요. 열 해 전에 전 출납관님이 직접 내어 가셨고, 돌려놓은 기록이 없어요."}, {"s": "q:sx_hanbi", "t": "서랍 안에서 쪽지 하나가 나왔어요. 「봉연 앞, 결계함」. 그것뿐이에요."}, {"s": "q:sx_hanbi", "t": "구중 봉연은 제가 갈 수 있는 곳이 아니에요. 대신 가 주세요. 문 앞 어딘가에 결계함이 있을 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_sealmaster', 2, '결계함', '구중 봉연을(를) 살핀다', '{"at": ["sealed_abyss"], "tasks": [{"t": "search", "r": ["sealed_abyss"], "n": 3}]}'::jsonb, '[{"s": null, "t": "첫째 문 그늘 아래, 바위틈에 작은 함 하나가 박혀 있었다. 함은 겹겹의 결계로 묶여 있었다. 매듭 하나하나가 장부 글씨처럼 반듯했다."}, {"s": null, "t": "이렇게 묶은 사람을 나는 한 명밖에 알지 못했다."}, {"s": null, "t": "함 주위의 바위에는 거울 같은 얼굴들이 박혀 있었다. 함에 손을 뻗자 거울 얼굴들이 내 모습을 비추며 일어섰다."}, {"s": null, "t": "거울귀들은 비친 모습을 빼앗아 결계 앞에 세웠다. 내 모습을 한 것이 함을 가로막았다."}, {"s": null, "t": "저것들을 묶어 두지 않으면 함에 손을 댈 수 없었다. 나는 먼저 거울부터 깨기로 했다."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_sealmaster', 3, '푸는 쪽이 어려운 매듭', '봉연 거울귀을(를) 물리친다', '{"at": ["sealed_abyss"], "tasks": [{"t": "win", "m": ["x_sealed_abyss_2"], "n": 2}]}'::jsonb, '[{"s": null, "t": "거울귀를 걷어 내자 함의 결계가 드러났다. 함부로 끊으면 함째로 부서지게 묶여 있었다."}, {"s": null, "t": "봉인은 묶는 쪽보다 푸는 쪽이 쉽다고 했다. 이 매듭은 아니었다. 풀 사람이 시간을 들이도록 일부러 그렇게 묶은 것이었다."}, {"s": null, "t": "바깥을 먼저 단단히 묶어야 안쪽 매듭을 하나씩 풀 수 있었다. 봉연 바닥에 흩어진 결계 파편과 문틈에 맺힌 응축 영핵이면 함 둘레에 새 결계를 칠 수 있었다."}, {"s": null, "t": "문틈 너머에서 무언가 숨을 고르는 소리가 났다. 이름을 부르는 소리가 아니라, 이름을 삼키는 소리였다."}, {"s": null, "t": "나는 파편을 주우며 그 소리를 듣지 않으려고 애썼다."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('jq3_sealmaster', 4, '열쇠를 맡기는 글', '결계 파편을(를) 모은다, 응축 영핵을(를) 모은다', '{"at": ["hq_yard"], "tasks": [{"t": "gather", "items": ["ward_fragment"], "r": ["sealed_abyss"], "n": 3}, {"t": "gather", "items": ["spirit_core"], "r": ["sealed_abyss"], "n": 1}]}'::jsonb, '[{"s": null, "t": "새 결계로 함 둘레를 묶고 안쪽 매듭을 하나씩 풀었다. 함 안에는 녹슨 열쇠 하나와 접힌 출납 쪽지가 들어 있었다. 나는 둘을 들고 정청으로 돌아왔다."}, {"s": null, "t": "한비가 쪽지를 펴서 소리 내어 읽었다. 윤도한의 글씨였다."}, {"s": null, "t": "「봉인고 열쇠 하나. 내어 감. 돌려놓지 않음. 이 열쇠는 출납 장부가 아니라 봉인술사에게 맡긴다. 이 매듭을 끝까지 푼 사람이면, 묶는 일이 무엇인지 아는 사람이다.」"}, {"s": "q:sx_hanbi", "t": "…전 출납관님은 처음부터 누가 찾으러 올 줄 아셨나 봐요."}, {"s": "q:sx_hanbi", "t": "이 칸을 어떻게 적어야 할지 모르겠어요. 돌려놓은 것도 아니고, 잃어버린 것도 아니니까요."}, {"s": null, "t": "나는 「맡음」이라고 적으면 되지 않겠느냐고 했다. 한비는 붓을 들고 한참 망설이다가 그렇게 적었다. 그리고 그 옆에 내 이름을 또박또박 끝까지 눌러 적었다."}, {"s": "q:sx_hanbi", "t": "이제 이 칸은 맞아요. 열쇠는 봉인술사님이 지켜 주세요. 장부는 제가 지킬게요."}]'::jsonb, '{"xp": 2065, "gil": 133, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
