delete from public.world_quest_steps where quest_id = 'sq110_f_mandate2' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_mandate2', 1, '탑을 떠난 제자', '탑을 떠난 제자', '{"at": ["white_tower"]}'::jsonb, '[{"s": null, "t": "백옥 천문탑 아래에서 서하람이 꼭대기를 올려다보고 있었다. 꼭대기 창마다 희미한 등불이 흔들렸다."}, {"s": "q:r71_seoharam", "t": "더 묻지 않겠다고 했는데, 대답이 저를 먼저 찾아왔어요."}, {"s": "q:r71_seoharam", "t": "그날 밤 그 별을 읽은 관측관이 한 사람 더 있었대요. 태사령님의 제자였는데, 예언을 감추는 건 별을 배신하는 거라며 천명원을 떠났대요."}, {"s": "q:r71_seoharam", "t": "그 사람은 이 탑 꼭대기에 올라가 그날 읽은 예언을 끝까지 쥐고 있다가 죽었어요. 지금은 원령이 되어 탑 꼭대기를 지킨대요."}, {"s": null, "t": "곁에서 늘 졸린 얼굴이던 수석 관측관이 이번만은 눈을 똑바로 뜨고 있었다."}, {"s": "mandate_court:seo", "t": "그 사람은 내 동기였어. 별을 누구보다 사랑했지. 그래서 별에 적힌 걸 사람이 바꾸는 걸 못 견뎠어."}, {"s": "q:r71_seoharam", "t": "그 사람이 쥔 예언이 제 별 이야기라면, 제가 직접 들어야 할 것 같아요. 꼭대기까지 같이 가 줄래요?"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_mandate2', 2, '쥐고 있던 종이', '탑 꼭대기 원령을(를) 물리친다', '{"at": ["white_tower"], "tasks": [{"t": "win", "m": ["regional_white_tower_guardian"], "n": 1}]}'::jsonb, '[{"s": null, "t": "원령이 무너지며 손에 쥐고 있던 누런 종이 한 장을 떨어뜨렸다. 종이에는 성도 한 장과 짧은 글 한 줄이 적혀 있었다."}, {"s": null, "t": "글은 반쯤 바래 읽을 수 없었다. 성도 위의 낮게 기운 별 하나만 또렷했다."}, {"s": "q:r71_seoharam", "t": "글자가 바랬어요. 끝까지 쥐고 있었는데도요."}, {"s": "mandate_court:seo", "t": "별모래로 성도를 덮으면 그 별이 무엇을 가리켰는지 다시 보일 거야. 낙하지 모래가 아니라 이 탑에 내려앉은 모래여야 해. 그날 밤 이 탑에서 읽었으니까."}, {"s": null, "t": "서하람은 종이를 품에 넣지 못하고 두 손으로 받쳐 들고만 있었다."}, {"s": "mandate_court:seo", "t": "탑 둘레 처마에 성진사가 쌓여 있어. 세 줌만 모아 줘."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_mandate2', 3, '엄마가 지어 준 성', '성진사을(를) 모은다', '{"at": ["white_tower"], "tasks": [{"t": "gather", "items": ["star_sand"], "r": ["white_tower"], "n": 3}]}'::jsonb, '[{"s": null, "t": "성진사를 성도 위에 뿌리자 모래알이 별 둘레로 모여 바랜 글자를 다시 그렸다. 「이 별은 예언을 깨뜨린다.」"}, {"s": "q:r71_seoharam", "t": "……예언을 깨뜨린다고요?"}, {"s": "mandate_court:seo", "t": "그 별은 처음부터 읽은 대로 가지 않는 별이었던 거야. 그러니 예언을 해도 소용이 없었지. 태사령께서는 그걸 아시고 입을 다무셨고, 그 사람은 그걸 못 받아들였고."}, {"s": "q:r71_seoharam", "t": "수석님은 그날 아기 울음을 들었다고 하셨죠. 그 아기를 누가 키웠어요?"}, {"s": null, "t": "서이연은 한참 하품도 하지 않고 서 있다가 작게 웃었다."}, {"s": "mandate_court:seo", "t": "졸린 수습생이 키웠지. 성도 없이 들어온 아기라 제 성을 붙여 줬어. 서씨로."}, {"s": null, "t": "서하람이 입을 열었다가 닫았다. 탑 아래에서 지팡이 소리가 올라왔다."}, {"s": "mandate_court:seo", "t": "태사령께서 오시네. 혼천의를 다시 돌리시겠대. 이번엔 이 탑의 혼천의라 영력이 더 들어. 영기환 두 알만 지어 줘."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_mandate2', 4, '결론을 쓰는 날', '영기환을(를) 만든다, 영기환을(를) 넘긴다', '{"at": ["white_tower"], "tasks": [{"t": "craft", "items": ["spirit_qi_pill"], "n": 2}], "give": {"spirit_qi_pill": 2}}'::jsonb, '[{"s": null, "t": "탑 꼭대기의 혼천의가 돌자 그날 밤하늘이 다시 펼쳐졌다. 낮게 기운 별은 이번에는 어느 별자리에도 묶이지 않고 제 길로 흘러갔다."}, {"s": "mandate_court:hahu", "t": "그 아이의 별은 읽을 수 없었다. 읽을 수 없는 것을 예언이라 적으면 거짓이 된다. 그래서 적지 않았다."}, {"s": "mandate_court:hahu", "t": "제자는 그것을 별을 배신한 것이라 했다. 나는 그 아이를 지킨 것이라 여겼다. 둘 다 맞았을 것이다."}, {"s": null, "t": "태사령은 원령이 남긴 종이를 접어 서하람의 손에 쥐여 주었다. 그 곁에서 기밀 사관이 기록을 펼쳤다."}, {"s": "mandate_court:mun", "t": "기록은 정확하다. 결론은 쓰지 마라. ……그것이 사관의 법이다. 그러나 이 줄은 사관의 기록이 아니다."}, {"s": null, "t": "문서진이 붓을 서하람에게 내밀었다. 서하람은 「이날 예언하지 않음」 옆에 한 줄을 더 적었다."}, {"s": null, "t": "「그 별은 관측관이 되었다. 이름은 서하람.」"}, {"s": "mandate_court:seo", "t": "아… 이제 좀 자도 되겠다."}, {"s": "q:r71_seoharam", "t": "주무세요, 어머니. 오늘 밤 별은 제가 볼게요."}]'::jsonb, '{"xp": 2065, "gil": 133, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
