on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_s_somae' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_somae', 1, '갈대에 걸린 붉은 천', '갈대에 걸린 붉은 천', '{"at": ["ash_reeds"]}'::jsonb, '[{"s": null, "t": "잿빛 갈대숲 물가에서 붉은 천 조각 하나가 갈대 끝에 걸려 나부꼈다. 그 아래 진흙에 여자 하나가 허리까지 잠겨 있었다. 갈대 뿌리가 발목을 감고 있었다."}, {"s": "q:r71_somae", "t": "……당겨 주세요. 아, 잠깐. 당신, 그 조사원이죠. 붉은 달 아래서 만난."}, {"s": null, "t": "나는 소매를 진흙에서 끌어 올렸다. 소매는 한참 숨을 골랐다. 붉은 소매 끝으로 손목의 인두 자국이 비쳤는데, 그 둘레로 거무스름한 무늬가 번져 있었다."}, {"s": "q:r71_somae", "t": "네 해 만이에요. 그때 말했죠, 다시 도망칠 거라고. 정말 도망쳤어요. 교단 추격꾼을 피해서, 섬으로 가는 배에 숨어 탔어요."}, {"s": "q:r71_somae", "t": "여기로 오면 바깥 명부에서 「잔여 없음」으로 지워진대요. 지워진 사람은 교단도 못 찾아요. 도망치기엔 이만한 데가 없죠."}, {"s": "q:r71_somae", "t": "그런데 이 물가 것들이 밤마다 나를 끌어당겨요. 갈대 물귀신이요. 세 마리만 쫓아 주세요. 오늘은 할 일이 있어서 끌려가면 안 되거든요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_somae', 2, '풀려 가는 글자', '갈대 물귀신을(를) 물리친다', '{"at": ["ash_reeds"], "tasks": [{"t": "win", "m": ["gw_reed_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "물귀신이 흩어지자 갈대숲이 조용해졌다. 소매가 소매 안쪽을 뒤집어 보였다. 안감에 붉은 실로 이름 둘이 수놓여 있었는데, 하나는 실이 거의 풀려 있었다."}, {"s": "q:r71_somae", "t": "하나는 동생 이름, 하나는 내 이름이에요. 요즘은 아침에 일어나면 내 이름이 먼저 떠오르지 않아요. 이걸 보고서야 알아요."}, {"s": null, "t": "나는 풀린 쪽이 누구 이름이냐고 물었다."}, {"s": "q:r71_somae", "t": "내 거요. 다행이죠. 연이 것은 아직 멀쩡하니까."}, {"s": "q:r71_somae", "t": "언니가 대신 기억하겠다고 했잖아요. 그런데 내가 나를 잊으면, 연이를 기억하던 사람도 같이 없어지는 거예요. 그게 무서워요."}, {"s": "q:r71_somae", "t": "바깥 실로는 안 돼요. 여기 요기를 먹으면 금방 삭아요. 이 숲 갈대 속에서 뽑는 갈대 영사는 요기를 머금어도 안 끊어진대요. 세 타래만 모아다 주세요. 다시 수놓을게요."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_somae', 3, '떨리는 바늘', '갈대 영사을(를) 모은다', '{"at": ["ash_reeds"], "tasks": [{"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 3}]}'::jsonb, '[{"s": null, "t": "소매는 갈대 영사를 바늘에 꿰려다 몇 번이나 놓쳤다. 손끝이 떨렸고, 눈동자가 이따금 초점을 잃었다."}, {"s": "q:r71_somae", "t": "미안해요. 수를 놓으려고만 하면 머릿속이 갈대밭처럼 수런거려요. 무슨 글자를 놓으려 했는지 자꾸 잊어버려요."}, {"s": null, "t": "나는 수를 놓는 동안 그 이름을 소리 내어 불러 주겠다고 했다. 소매가 놀란 얼굴로 나를 보았다."}, {"s": "q:r71_somae", "t": "……그래 줄래요? 그럼 연이 이름부터 불러 주세요. 내 건 그다음에요."}, {"s": "q:r71_somae", "t": "그 전에 마음부터 가라앉혀야겠어요. 반요촌 사람들이 안신탕을 마시면 머리가 맑아진다고 했어요."}, {"s": "q:r71_somae", "t": "두 그릇만 달여 주세요. 하나는 첫 땀 뜰 때, 하나는 마지막 땀 뜰 때."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_somae', 4, '뒤를 돌아보며', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["ash_reeds"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 2}], "give": {"calm_brew": 2}}'::jsonb, '[{"s": null, "t": "안신탕을 한 모금 마신 소매가 바늘을 들었다. 내가 「연이」 하고 부르자 바늘이 천을 한 땀 지나갔다."}, {"s": null, "t": "「소매」 하고 부르자 소매는 한 박자 늦게 고개를 들었다. 그리고 웃었다. 둘째 그릇을 비웠을 때 안감에는 두 이름이 나란히 단단하게 박혀 있었다."}, {"s": "q:r71_somae", "t": "다 됐다. 이제 아침마다 이걸 보면 돼요."}, {"s": "q:r71_somae", "t": "도망친 끝이 여기였네요. 더 갈 데가 없어요. 앞에는 바다밖에 없으니까."}, {"s": "q:r71_somae", "t": "그래서 이제 그만 도망치려고요. 반요촌에 가서 문패를 하나 달 거예요. 바깥 이름하고 섬 이름을 같이 적는다던데, 나는 셋 적을래요. 내 거, 연이 거, 섬에서 지을 거."}, {"s": null, "t": "나는 섬 이름은 무엇으로 지을 거냐고 물었다."}, {"s": "q:r71_somae", "t": "아직 몰라요. 이름을 지으면 불러 줄 사람이 있어야 하니까, 다음에 오면 제일 먼저 알려 줄게요."}, {"s": null, "t": "소매는 갈대숲을 나서다 한 번 뒤를 돌아보았다. 붉은 천 조각이 아직 갈대 끝에 걸려 나부끼고 있었다. 소매는 그것을 떼어 가지 않고 그대로 두었다."}]'::jsonb, '{"xp": 2065, "gil": 133, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
