insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_spinning_child', 1, '갈대 손가락', '갈대 손가락', '{"at": ["ash_reeds"]}'::jsonb, '[{"s": null, "t": "갈대숲 어귀 바위에 아이 하나가 앉아 실을 잣고 있었다. 손가락이 갈대 줄기처럼 가늘고 길어서, 실을 감을 때마다 마디가 사각사각 소리를 냈다."}, {"s": "q:sx_garak", "t": "아, 바깥 사람이다! 제 손 보지 마세요. 아니, 봐도 돼요. 그 대신 제 실 보세요."}, {"s": "q:sx_garak", "t": "이거 갈대 영사로 자은 거예요. 섬에서 제일 가늘어요. 솔래 아주머니가 그랬어요."}, {"s": null, "t": "나는 손가락이 왜 그렇게 기냐고 물었다."}, {"s": "q:sx_garak", "t": "작년 겨울부터 자랐어요. 근데 괜찮아요. 실을 천 바퀴 자으면 사람 손으로 돌아온대요."}, {"s": "q:sx_garak", "t": "지금 삼백 바퀴요. 아니, 삼백열두 바퀴. 근데 갈대 영사가 다 떨어졌어요. 안쪽에 많은데, 저 혼자 들어가면 아주머니한테 혼나요."}, {"s": "q:sx_garak", "t": "여섯 타래만 걷어다 주세요. 다 자으면 제일 먼저 보여 드릴게요. 약속해요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_spinning_child', 2, '실 도둑', '갈대 영사을(를) 모은다', '{"at": ["ash_reeds"], "tasks": [{"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 6}]}'::jsonb, '[{"s": null, "t": "갈대 영사를 건네자 아이는 바로 물레를 돌렸다. 은빛 실이 길게 뽑혀 나왔다."}, {"s": null, "t": "그때 머리 위에서 날개 소리가 났다. 재를 뒤집어쓴 백로 떼가 내려와 말려 둔 실타래를 부리로 물고 갈대 위로 날아갔다."}, {"s": "q:sx_garak", "t": "아아! 제 실! 그거 사백 바퀴째 거예요!"}, {"s": "q:sx_sollae", "t": "가락아, 또 혼자 나왔니."}, {"s": null, "t": "갈대 사이에서 바구니를 든 아낙이 나왔다. 손등에 회색 비늘이 촘촘했다."}, {"s": "q:sx_sollae", "t": "저 백로들이 가락이 실로 둥지를 짓는단다. 질긴 실인 줄은 저것들도 아는 거지."}, {"s": "q:sx_sollae", "t": "미안하지만 백로 떼를 좀 쫓아 주게. 둥지까지 헐 건 없고, 물고 간 실만 떨구게 하면 돼."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_spinning_child', 3, '걸리는 바퀴', '잿빛 백로 떼을(를) 물리친다', '{"at": ["ash_reeds"], "tasks": [{"t": "win", "m": ["gw_reed_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "백로들이 떨군 실타래를 주워 오자, 아이가 그것을 끌어안고 한참 냄새를 맡았다."}, {"s": "q:sx_garak", "t": "갈대 냄새 나요. 제 실 맞아요."}, {"s": "q:sx_garak", "t": "근데 물레가 자꾸 걸려요. 손가락이 길어서, 가락바퀴를 돌리면 손가락까지 같이 감겨요."}, {"s": "q:sx_sollae", "t": "바퀴를 미끄러운 걸로 갈면 덜 걸릴 게다. 물가 채집터에 수귀 비늘이 떨어져 있지. 그걸 겹쳐 박으면 바퀴가 물처럼 돌아."}, {"s": "q:sx_garak", "t": "비늘이요? 그거 박으면 제 손등에도 비늘 나요?"}, {"s": "q:sx_sollae", "t": "안 난다. 바퀴에 박는 거야, 바퀴에."}, {"s": "q:sx_garak", "t": "그럼 세 개만요. 크고 반짝이는 걸로요."}]'::jsonb, '{"xp": 2065}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_spinning_child', 4, '천 바퀴', '수귀 비늘을(를) 모은다', '{"at": ["ash_reeds"], "tasks": [{"t": "gather", "items": ["drowned_scale"], "r": ["ash_reeds"], "n": 3}]}'::jsonb, '[{"s": null, "t": "솔래가 비늘 세 장을 가락바퀴에 겹쳐 박았다. 아이가 물레를 돌리자 바퀴가 소리도 없이 돌았고, 실이 아까보다 곱절은 빨리 뽑혀 나왔다."}, {"s": "q:sx_garak", "t": "구백구십팔, 구백구십구…… 천!"}, {"s": null, "t": "아이가 두 손을 번쩍 들었다. 손가락은 여전히 갈대처럼 길었다."}, {"s": "q:sx_garak", "t": "……."}, {"s": "q:sx_sollae", "t": "가락아. 그 말, 아주머니가 지어낸 거야. 네가 울기만 해서, 뭐라도 손에 쥐여 주려고."}, {"s": "q:sx_garak", "t": "알아요."}, {"s": null, "t": "솔래가 바구니를 떨어뜨릴 뻔했다."}, {"s": "q:sx_garak", "t": "저번에 아주머니가 묵호 할아버지한테 하는 말 들었어요. 그래도 실 잣는 거 좋아요. 손가락이 길어서 제가 섬에서 제일 잘 자아요."}, {"s": null, "t": "아이는 막 자은 실을 한 뼘 끊어 내 손목에 감고 매듭을 지었다. 매듭이 아주 작고 단단했다."}, {"s": "q:sx_garak", "t": "이거 천 바퀴째 실이에요. 바깥에 나가면 자랑하세요. 섬에 실 제일 잘 잣는 애가 있다고요."}, {"s": null, "t": "솔래는 아이의 긴 손가락을 한참 쥐고 있다가, 고개를 돌려 눈가를 훔쳤다."}]'::jsonb, '{"xp": 2065, "gil": 133, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
