insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_5', 1, '날마다 오는 손님', '날마다 오는 손님', '{"at": ["ash_reeds"]}'::jsonb, '[{"s": null, "t": "잿빛 갈대숲은 바람이 불 때마다 사람 목소리 같은 소리를 냈다. 도담은 팔에 남은 옅은 자국을 소매로 가리고 앞장서 걸었다."}, {"s": "q:sx_dodam", "t": "누나, 섬에 오니까 장부가 무거워진 것 같아요."}, {"s": "q:sx_haesol", "t": "기분 탓이야. ……나도 그래."}, {"s": null, "t": "갈대숲 어귀에서 빈 문패를 등에 진 사내가 오누이를 불러 세웠다."}, {"s": "q:sx_solmoe", "t": "반요촌에 가시는 길이에요? 저는 문패장이 솔뫼예요. 혹시 등짐장수세요?"}, {"s": "q:sx_solmoe", "t": "저희 마을 장에 날마다 나와서 「이름을 사러 왔소」 하는 손님이 있어요. 그 손님도 등짐장수예요. 빈 등짐 틀만 메고 다니고요."}, {"s": null, "t": "해솔의 손에서 장부가 미끄러질 뻔했다."}, {"s": "q:sx_solmoe", "t": "그 손님은 해 질 녘마다 이 숲에 와서 갈대 영사를 뜯어요. 등짐 끈을 엮는다면서, 엮다가 엮는 법을 잊고 도로 풀어요. 오늘은 아직 안 왔네요."}, {"s": "q:sx_haesol", "t": "그분 대신 갈대 영사를 모아 드리고 싶어요. 조사원, 같이 뜯어 주세요. 네 묶음이면 끈 하나는 엮을 거예요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_5', 2, '빈 등짐 틀', '갈대 영사을(를) 모은다', '{"at": ["ash_reeds"], "tasks": [{"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 4}]}'::jsonb, '[{"s": null, "t": "갈대 영사를 다발로 묶을 무렵, 숲 안쪽에서 바스락 소리가 났다. 빈 등짐 틀을 멘 사내가 비척비척 걸어 나왔다. 손등과 목덜미에 갈대 잎 같은 요문이 돋아 있었다."}, {"s": "q:sx_banyo_deung", "t": "이름…… 이름 사러 왔소. 이름 파는 데가 어디요."}, {"s": null, "t": "도담이 입을 벌렸다가 다물었다. 해솔은 한 걸음도 움직이지 못했다."}, {"s": "q:sx_banyo_deung", "t": "갈대. 갈대 뜯으러 왔소. 끈을 엮어야 하오. 아이들한테…… 아이들한테 뭘 보내야 하는데."}, {"s": null, "t": "사내가 갈대 영사 다발 쪽으로 손을 뻗었다. 그 순간 물가 갈대 사이에서 젖은 손들이 일어나 사내의 발목을 붙잡았다."}, {"s": "q:sx_solmoe", "t": "갈대 물귀신이에요! 저 손님은 날마다 저것들한테 끌려갈 뻔해요."}, {"s": "q:sx_dodam", "t": "아버지!"}, {"s": "q:sx_haesol", "t": "조사원, 저분 좀 지켜 주세요!"}]'::jsonb, '{"xp": 2182}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_5', 3, '알아보지 못하는 얼굴', '갈대 물귀신을(를) 물리친다', '{"at": ["ash_reeds"], "tasks": [{"t": "win", "m": ["gw_reed_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "물귀신들이 갈대 아래로 가라앉았다. 사내는 진흙에 주저앉아 오누이를 멀뚱히 올려다보았다."}, {"s": "q:sx_banyo_deung", "t": "고맙소. 누구시오."}, {"s": "q:sx_dodam", "t": "저 도담이에요. 아버지가 안신탕 보내 준 도담이요."}, {"s": "q:sx_banyo_deung", "t": "도담. 도담…… 좋은 이름이오. 그 이름 파시오? 나는 이름이 없어서."}, {"s": null, "t": "도담이 울음을 터뜨렸다. 해솔은 동생을 끌어당겨 제 등 뒤에 세웠다."}, {"s": "q:sx_solmoe", "t": "반요는 스스로는 이름을 떠올리지 못해요. 누가 불러 줘야 잠깐 돌아와요. 그런데 이 손님 이름은 아무도 몰라서, 여태 아무도 불러 드리지 못했어요."}, {"s": "q:sx_haesol", "t": "저는 알아요."}, {"s": "q:sx_haesol", "t": "그런데 지금 부르면 요기에 눌려서 못 들으실 거예요. 조사원, 정화 부적 두 장만 만들어 주세요. 반요촌으로 모시고 가서 요기를 걷어 낸 다음에 부를게요."}]'::jsonb, '{"xp": 2182}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_pack_5', 4, '아버지의 이름', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "반요촌 솔뫼의 마당에서 정화 부적 두 장을 사내의 어깨와 등짐 틀에 붙였다. 갈대 잎 같은 요문이 조금 가라앉았다."}, {"s": null, "t": "해솔은 장부의 맨 끝 쪽, 아버지가 적다 만 줄을 사내 앞에 펴 놓았다. 그리고 숨을 한 번 고르고 불렀다."}, {"s": "q:sx_haesol", "t": "윤보. 등짐장수 윤보. 아버지."}, {"s": null, "t": "사내가 천천히 고개를 들었다. 한 박자 늦게, 그러나 분명히 돌아보았다."}, {"s": "q:sx_banyo_deung", "t": "……해솔이냐. 키가 컸구나. 도담이는 이제 경기 안 하냐."}, {"s": "q:sx_dodam", "t": "안 해요! 하나도 안 해요!"}, {"s": "q:sx_banyo_deung", "t": "장부는…… 받으러 다녔냐. 다 받았냐."}, {"s": "q:sx_haesol", "t": "받을 건 받고, 안 받을 건 안 받았어요. 아버지가 적어 두신 대로요."}, {"s": null, "t": "사내는 웃으려다가 눈빛이 다시 흐려졌다. 부르기 전의 얼굴로 돌아가며 「이름 사러 왔소」 하고 중얼거렸다."}, {"s": null, "t": "해솔은 울지 않았다. 아버지가 적다 만 줄 끝에 제 손으로 마저 적었다. 「윤보. 외상: 이름 하나. 갚는 법: 날마다 불러 줄 것.」 솔뫼는 그 이름을 문패에 새겨 사내의 집 앞에 걸어 주었다."}, {"s": "q:sx_dodam", "t": "누나, 그럼 우리가 날마다 와서 받아 가면 돼요. 이름값."}, {"s": "q:sx_haesol", "t": "응. 평생 받자."}]'::jsonb, '{"xp": 2182, "gil": 137, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
