delete from public.world_quest_steps where quest_id = 'sq110_hanging_boys' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_hanging_boys', 1, '처마 밑의 부탁', '처마 밑의 부탁', '{"at": ["inverted_shrine"]}'::jsonb, '[{"s": null, "t": "거꾸로 선 사당은 처마가 발밑에 묻혀 있었다. 천장 쪽으로 솟은 서까래마다 작은 그림자가 하나씩 거꾸로 매달려, 바람도 없이 흔들렸다."}, {"s": "q:sx_dongja", "t": "거기 누구 있어요? 바로 세워 주세요. 머리에 피가 몰려요."}, {"s": "q:sx_dongja", "t": "바로 세워 주세요. 바로 세워 주세요."}, {"s": null, "t": "내가 그쪽으로 손을 뻗자, 등 뒤에서 마른 손이 내 소매를 붙잡았다. 목탁을 든 늙은 반요였다."}, {"s": "q:sx_jeongnyeo", "t": "손대지 마시오. 저 소리에 대답도 하지 마시오."}, {"s": "q:sx_jeongnyeo", "t": "나는 이 사당의 공양주요. 저 아이들은 저렇게 매달려 있어야 하오. 까닭을 말해도 믿지 않을 테니, 먼저 사당을 한 바퀴 돌아보고 오시오."}, {"s": "q:sx_jeongnyeo", "t": "위만 보지 말고, 발밑도 보시오. 무엇이 찍혀 있는지."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_hanging_boys', 2, '얼굴 없는 아이들', '거꾸로 선 사당을(를) 살핀다', '{"at": ["inverted_shrine"], "tasks": [{"t": "search", "r": ["inverted_shrine"], "n": 3}]}'::jsonb, '[{"s": null, "t": "사당 바닥 곳곳에 작은 맨발 자국이 찍혀 있었다. 발자국은 대웅전 뒤편 기둥 앞에서 끊겼다. 거기서부터는 기둥을 거꾸로 기어오른 손자국이었다."}, {"s": null, "t": "대웅전 천장에도 아이 혼들이 매달려 있었다. 이 아이들은 얼굴이 있어야 할 자리가 하얗게 비어 있었고, 쉬지 않고 목탁을 두드렸다."}, {"s": "q:sx_jeongnyeo", "t": "보았소. 누군가 한 번 바로 세워 준 아이들이오."}, {"s": "q:sx_jeongnyeo", "t": "이 사당에서는 기도가 거꾸로 이루어지오. 기억해 달라 빌면 잊히지. 그런데 몸까지 거꾸로 매달고 빌면, 두 번 뒤집혀 바로 이루어지오."}, {"s": "q:sx_jeongnyeo", "t": "처마의 아이들은 바깥의 어미가 저를 잊지 않기를 빌고 있소. 바로 세우면 기도가 다시 뒤집혀, 얼굴부터 떨어져 나가고 이름이 지워지오."}, {"s": "q:sx_jeongnyeo", "t": "저 아이들은 버릇처럼 도로 기어올라 매달렸지만, 이제 빌 것이 없소. 사람만 보면 목탁으로 내려치지. 셋이오. 편히 보내 주시오."}, {"s": "q:sx_dongja", "t": "바로 세워 주세요. 바로 세워 주세요."}]'::jsonb, '{"xp": 2182}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_hanging_boys', 3, '목소리의 주인', '거꾸로 매달린 동자을(를) 물리친다', '{"at": ["inverted_shrine"], "tasks": [{"t": "win", "m": ["gw_shrine_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "얼굴 없는 아이들이 흩어지자 목탁 소리가 멎었다. 그런데 부탁하는 소리는 멎지 않았다."}, {"s": "q:sx_dongja", "t": "바로 세워 주세요. 머리에 피가 몰려요."}, {"s": null, "t": "나는 처마의 아이들을 올려다보았다. 아이들은 눈을 감은 채 입을 꼭 다물고 있었다. 소리는 위가 아니라 마당 아래쪽에서 올라오고 있었다."}, {"s": "q:sx_jeongnyeo", "t": "이제 알겠소. 처마의 아이들은 한 번도 말한 적이 없소. 빌고 있는 아이가 입을 열 리가 있겠소."}, {"s": "q:sx_jeongnyeo", "t": "저 소리는 마당의 나한이 내는 것이오. 머리를 잃은 석상이지. 아이들이 바로 서서 얼굴이 떨어지면, 그것을 주워 제 목 위에 얹으려 하오."}, {"s": null, "t": "마당 한가운데서 머리 없는 석상이 거꾸로 걸어 나왔다. 빈 목 구멍에서 아이 목소리가 새어 나왔다."}, {"s": "q:sx_dongja", "t": "바로 세워 주세요. 바로 세워 주세요."}, {"s": "q:sx_jeongnyeo", "t": "저것을 부수어 주시오. 그래야 아이들이 마저 빌 수 있소."}]'::jsonb, '{"xp": 2182}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_hanging_boys', 4, '거꾸로 선 사람', '목 없는 나한을(를) 물리친다', '{"at": ["inverted_shrine"], "tasks": [{"t": "win", "m": ["gw_shrine_3"], "n": 1}]}'::jsonb, '[{"s": null, "t": "나한의 돌 몸이 무너지자 빈 목 구멍에서 하얀 얼굴 몇 개가 굴러 나왔다. 얼굴들은 바닥에 닿기 전에 연기처럼 흩어졌다."}, {"s": "q:sx_jeongnyeo", "t": "저 얼굴들도 이제 쉬겠구려."}, {"s": null, "t": "공양주가 처마 아래로 가서 목탁을 한 번 쳤다. 매달린 아이들이 일제히 조금씩 흔들렸다. 바람은 없었다."}, {"s": "q:sx_jeongnyeo", "t": "고맙소. 바깥에서 온 사람은 대개 아이들을 바로 세우고 가오. 착한 사람일수록 그러지."}, {"s": null, "t": "사당을 나서려는데, 처마 끝에서 처음 듣는 작은 목소리가 들렸다. 「조사원님, 고마워요. 그런데 조사원님은 왜 거꾸로 서 계세요?」"}, {"s": null, "t": "돌아보니 아이들은 모두 눈을 감고 있었다. 공양주는 대답 대신 목탁을 한 번 더 쳤다."}, {"s": null, "t": "일주문을 나와서야 발밑을 내려다보았다. 내 그림자가 발에서부터 하늘 쪽으로 뻗어 있었다."}]'::jsonb, '{"xp": 2182, "gil": 137, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
