insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeohwi', 1, '비어 있던 줄', '비어 있던 줄', '{"at": ["inverted_shrine"]}'::jsonb, '[{"s": null, "t": "거꾸로 선 사당 처마 밑에서 낯익은 사관 하나가 고개를 젖힌 채 서 있었다. 가슴에 빈 책을 안고 있었다."}, {"s": "q:bl_yeohwi", "t": "그대구려. 무명 고도에서 종의 자취를 함께 밟던. 몇 해 만이오. 봉연의 문이 닫혔다는 소문을 듣고 이 늙은이도 섬까지 건너왔소."}, {"s": "q:bl_yeohwi", "t": "이 섬 반요들이 그러더이다. 이 사당 들보에 글씨가 거꾸로 적혀 있는데, 읽어 보면 모두 사람 이름이라고."}, {"s": null, "t": "여휘가 책 맨 끝 장을 펴 보였다. 「야행국 본부」까지만 적힌 그 줄이 여전히 비어 있었다."}, {"s": null, "t": "나는 그 줄의 나머지를 이제는 안다고 했다."}, {"s": "q:bl_yeohwi", "t": "아는 것과 적힌 것은 다르오. 그 사람이 어디에 무엇을 남겼는지 보고 나서 적겠소."}, {"s": "q:bl_yeohwi", "t": "사당 안은 어둡고 뒤틀려서 늙은 눈으로는 어디가 위인지도 모르겠소. 세 번쯤 둘러보며 글씨 있는 들보를 찾아 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeohwi', 2, '거꾸로 적힌 이름들', '거꾸로 선 사당을(를) 살핀다', '{"at": ["inverted_shrine"], "tasks": [{"t": "search", "r": ["inverted_shrine"], "n": 3}]}'::jsonb, '[{"s": null, "t": "들보는 발밑에 있었다. 사당이 뒤집혀 선 탓에 지붕이 발밑에, 마루가 머리 위에 있었다. 들보마다 작은 글씨가 거꾸로 빼곡했다."}, {"s": null, "t": "나는 허리를 굽혀 몇 줄을 읽었다. 모르는 이름들이었다. 다만 이름 앞마다 같은 두 글자가 붙어 있었다. 「고도」."}, {"s": "q:bl_yeohwi", "t": "……무명 고도 사람들이오. 그날 밤 내 책에서 지워진 이름들이오. 이 이름은 대장간 집 셋째, 이 이름은 우물가 떡집 할멈."}, {"s": "q:bl_yeohwi", "t": "누군가 성 큰길 홈에 눌어붙은 이름을 하나하나 베껴 여기 옮겨 둔 거요. 그것도 거꾸로."}, {"s": null, "t": "들보 둘레로 향 연기가 아래로 흘러내렸다. 연기 속에서 향로 몇이 혼자 굴러다니며 글씨 위에 연기를 덮었다."}, {"s": "q:bl_yeohwi", "t": "연기가 덮인 줄은 읽히지 않소. 저 향로들을 좀 치워 주시오."}]'::jsonb, '{"xp": 2182}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeohwi', 3, '거꾸로 적은 까닭', '뒤집힌 향로귀을(를) 물리친다', '{"at": ["inverted_shrine"], "tasks": [{"t": "win", "m": ["gw_shrine_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "향로가 깨지자 연기가 걷히고 마지막 들보가 드러났다. 그 끝에 다른 글씨보다 크고 반듯한 한 줄이 있었다."}, {"s": null, "t": "「적은 이 야행국 본부 출납관 윤도한. 고도 사람 사백열둘, 여기 맡겨 둠.」"}, {"s": "q:bl_yeohwi", "t": "지운 자리를 따라 내려왔던 그 사람이구려. 돌을 문지르던 손이, 이렇게 많이 적은 손이었소."}, {"s": "q:bl_yeohwi", "t": "거꾸로 적은 까닭도 알겠소. 해마다 먹을 거두는 손도 바로 적힌 글자만 읽어 가지. 뒤집힌 글자는 읽지 못하고 지나가는 게요."}, {"s": null, "t": "나는 이 이름들을 고도로 데려갈 수 있느냐고 물었다."}, {"s": "q:bl_yeohwi", "t": "데려가되 거꾸로인 채로 데려가야 하오. 바로 세우는 순간 다시 거둬질 테니."}, {"s": "q:bl_yeohwi", "t": "이 사당 나무는 결이 위아래로 뒤집힌 거꾸로 향목이오. 그 나무 판에 적으면 반듯하게 세워 두어도 거꾸로 적힌 셈이 되오. 사당 둘레에서 세 토막만 구해 주시오. 사백열둘이면 판 셋은 있어야 하오."}]'::jsonb, '{"xp": 2182}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_yeohwi', 4, '다 찬 줄', '거꾸로 향목을(를) 모은다', '{"at": ["inverted_shrine"], "tasks": [{"t": "gather", "items": ["inverted_incense"], "r": ["inverted_shrine"], "n": 3}]}'::jsonb, '[{"s": null, "t": "여휘는 사흘 밤을 들보 곁에 앉아 이름을 옮겨 적었다. 나는 그 곁에서 이름을 하나씩 소리 내어 읽어 주었다. 붓끝은 한 번도 떨리지 않았다."}, {"s": null, "t": "마지막 판까지 채운 여휘가 빈 책을 다시 폈다. 그리고 「야행국 본부」 뒤에 붓을 댔다."}, {"s": "q:bl_yeohwi", "t": "그 사람은 지금 어디 있소?"}, {"s": null, "t": "나는 그가 구중 봉연 아홉째 문 안쪽에서 빗장을 잡고 있다고 했다. 정청 장부에도 그 이름이 다시 적혔다고 했다."}, {"s": "q:bl_yeohwi", "t": "그럼 두 군데 적히는구려. 정청 장부에 한 번, 망한 나라 사관의 책에 한 번."}, {"s": null, "t": "여휘가 「출납관 윤도한」을 이어 적었다. 그 아래에 한 줄을 더 적었다. 「고도 사람 사백열둘의 이름을 맡아 준 이.」"}, {"s": "q:bl_yeohwi", "t": "이 줄은 이제 다 찼소. 그대가 채워 온 거요. 섬이 대신 들고 있다가 건네주었을 뿐이지."}, {"s": null, "t": "여휘는 향목 판 셋을 등에 지고 사당을 나섰다. 나서기 전에 마지막 들보를 향해 고개를 깊이 숙였다."}]'::jsonb, '{"xp": 2182, "gil": 137, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
