delete from public.world_quest_steps where quest_id = 'cq110_paint_4' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_4', 1, '거꾸로 걸린 그림', '거꾸로 걸린 그림', '{"at": ["inverted_shrine"]}'::jsonb, '[{"s": null, "t": "거꾸로 선 사당의 처마 아래에 담채의 화폭들이 거꾸로 매달려 있었다. 담채는 바닥에 화폭을 뒤집어 놓고 얼굴을 거꾸로 그리고 있었다."}, {"s": "q:sx_sorim", "t": "조사원님, 와 주셨네요. 봉연에서 깨신 뒤로 스승님이 정말 이 섬으로 오셨어요. 그리고 여기서는 거꾸로 그려야 바로 보인대요."}, {"s": "q:sx_damchae", "t": "이 사당에서는 위가 아래요. 똑바로 그리면 얼굴이 뒤집혀 보이오. 거꾸로 그려야 똑바로 서오."}, {"s": null, "t": "그때 사당 안쪽에서 종이 울렸다. 거꾸로 매달린 범종이 혼자 흔들리고 있었다."}, {"s": null, "t": "종소리가 울리자 처마의 화폭 속 얼굴들이 일제히 뒤집혔다. 소림이 머리를 감싸 쥐고 주저앉았다."}, {"s": "q:sx_sorim", "t": "조사원님……. 방금 스승님 이름이 생각이 안 났어요. 한순간이었는데, 머릿속이 하얘졌어요."}, {"s": "q:sx_damchae", "t": "저 종이오. 저 종이 울릴 때마다 그림 속 이름이 뒤집혀 쏟아지오. 그리고 듣는 이의 이름도 흔들리오. 저것부터 멈춰 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_4', 2, '잃어버린 것을 찾는 연기', '거꾸로 선 범종귀을(를) 물리친다', '{"at": ["inverted_shrine"], "tasks": [{"t": "win", "m": ["gw_shrine_5"], "n": 1}]}'::jsonb, '[{"s": null, "t": "범종이 바닥으로 떨어져 깨지자 사당 안이 조용해졌다. 화폭 속 얼굴들은 천천히 제자리로 돌아왔다."}, {"s": "q:sx_sorim", "t": "이제 생각나요. 다행이에요."}, {"s": null, "t": "담채는 대답하지 않고 자기 손을 내려다보고 있었다. 한참 뒤에야 낮은 목소리가 나왔다."}, {"s": "q:sx_damchae", "t": "……종소리를 들은 뒤로 내 얼굴이 떠오르지 않소. 남의 얼굴은 천 개도 그리는데, 내 얼굴은 한 번도 들여다본 적이 없으니 붙들 것도 없었던 게요."}, {"s": "q:sx_sorim", "t": "스승님……."}, {"s": "q:sx_damchae", "t": "이 사당에서는 향을 거꾸로 피우면 연기가 아래로 흘러 잃은 것을 찾아 준다 하오. 거꾸로 향목 네 토막만 구해 주시오. 내가 무엇을 잃었는지 보고 싶소."}]'::jsonb, '{"xp": 2303}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_4', 3, '연기가 멈춘 자리', '거꾸로 향목을(를) 모은다', '{"at": ["inverted_shrine"], "tasks": [{"t": "gather", "items": ["inverted_incense"], "r": ["inverted_shrine"], "n": 4}]}'::jsonb, '[{"s": null, "t": "담채가 향을 거꾸로 꽂아 불을 붙이자, 연기가 위가 아니라 아래로 흘렀다. 연기는 바닥을 기어 담채의 화폭들 쪽으로 갔다."}, {"s": null, "t": "연기는 지맥의 뿌리에서 그린 광부의 그림 앞에서 멈추었다. 광부 그림의 한 귀퉁이에 아주 작은 사람 하나가 거꾸로 그려져 있었다."}, {"s": null, "t": "소림이 그림을 뒤집었다. 거꾸로 그려진 작은 사람은 담채였다. 다른 그림들도 뒤집어 보니 귀퉁이마다 같은 사람이 있었다. 봉인고의 여인 곁에도, 봉연의 검은 물가에도."}, {"s": "q:sx_sorim", "t": "스승님, 이거 언제 그리셨어요?"}, {"s": "q:sx_damchae", "t": "그린 적 없소."}, {"s": null, "t": "담채의 목소리는 떨리지 않았다. 대신 손이 차갑게 식어 붓을 쥐지 못했다. 소림이 그 손을 두 손으로 감쌌다."}, {"s": "q:sx_sorim", "t": "손이 얼음장 같아요. 영력이 다 빠져나가신 것 같아요. 조사원님, 영기환 두 알만 지어 주세요."}]'::jsonb, '{"xp": 2303}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_4', 4, '붙든 쪽, 매달린 쪽', '영기환을(를) 만든다, 영기환을(를) 넘긴다', '{"at": ["inverted_shrine"], "tasks": [{"t": "craft", "items": ["spirit_qi_pill"], "n": 2}], "give": {"spirit_qi_pill": 2}}'::jsonb, '[{"s": null, "t": "영기환을 삼킨 담채의 손에 조금씩 핏기가 돌아왔다. 담채는 귀퉁이의 작은 사람들을 오래 들여다보았다."}, {"s": "q:sx_damchae", "t": "이제야 알겠소. 내가 저들을 붙든 줄 알았소. 그런데 저들이 나를 붙들고 있었소. 내가 잊히지 않게, 귀퉁이마다 나를 남겨 둔 거요."}, {"s": "q:sx_damchae", "t": "아니오. 어쩌면 내가 매달린 거겠지. 내 이름을 불러 줄 이가 없으니, 저들 곁에라도 끼어 있으려고."}, {"s": "q:sx_sorim", "t": "제가 있잖아요. 제가 불러 드리면 되잖아요."}, {"s": null, "t": "담채는 대답 대신 소림의 머리를 한 번 쓰다듬었다. 그리고 화구 상자를 닫았다."}, {"s": "q:sx_damchae", "t": "마지막 그림을 그려야겠소. 달 없는 저잣거리에 무월 비단이 있다 하오. 달빛이 한 번도 닿지 않은 비단이라, 그 위에 그린 것은 바래지 않는다 하오."}, {"s": null, "t": "소림이 나를 돌아보았다. 「마지막」이라는 말을 들은 얼굴이었다."}]'::jsonb, '{"xp": 2303, "gil": 141, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
