delete from public.world_quest_steps where quest_id = 'sq110_inverted_incense' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_inverted_incense', 1, '무엇을 잃었는지', '무엇을 잃었는지', '{"at": ["inverted_shrine"]}'::jsonb, '[{"s": null, "t": "사당 마당 구석에서 덩치 큰 반요 사내가 향로 앞에 쭈그려 앉아 있었다. 향이 꽂혀 있는데 연기가 나지 않았다."}, {"s": "q:sx_mangdol", "t": "저기요, 향 피울 줄 아세요? 거꾸로 피우면 잃은 걸 찾아 준대서 왔는데, 불이 안 붙어요."}, {"s": null, "t": "나는 무엇을 잃었느냐고 물었다."}, {"s": "q:sx_mangdol", "t": "그게…… 모르겠어요. 뭘 잃은 건 확실한데, 그게 뭔지가 생각이 안 나요. 그래서 향한테 물어보려고요."}, {"s": "q:sx_ihyang", "t": "거꾸로 피우는 향은 거꾸로 선 나무에서 나네."}, {"s": null, "t": "대들보 위에서 목소리가 내려왔다. 비녀를 거꾸로 꽂은 반요 여인이 들보에 걸터앉아 있었다."}, {"s": "q:sx_ihyang", "t": "나는 이 사당의 향지기 이향일세. 향목은 뿌리가 하늘에 달린 나무에서 베어야 하네. 다섯 토막이면 되네."}, {"s": "q:sx_ihyang", "t": "찾는 법은 쉽네. 위를 보며 걷게. 그러면 자네 발이 먼저 찾을 걸세."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_inverted_incense', 2, '아래로 흐르는 연기', '거꾸로 향목을(를) 모은다', '{"at": ["inverted_shrine"], "tasks": [{"t": "gather", "items": ["inverted_incense"], "r": ["inverted_shrine"], "n": 5}]}'::jsonb, '[{"s": null, "t": "향목에 불을 대자 연기가 위가 아니라 아래로 흘렀다. 연기는 바닥을 기어 마당 쪽으로 천천히 나아갔다."}, {"s": "q:sx_mangdol", "t": "움직여요! 따라가면 되는 거죠?"}, {"s": null, "t": "몇 걸음 따라가자 향로 하나가 데굴데굴 굴러 나와 길을 막았다. 그 향로에서도 연기가 아래로 흘렀다. 두 줄기 연기가 엉키더니 사방으로 흩어졌다."}, {"s": "q:sx_ihyang", "t": "연기가 연기를 만나면 길을 잃네. 사당의 향로귀들이 남의 연기를 먹고 사는 탓이지."}, {"s": "q:sx_ihyang", "t": "둘일세. 둘을 꺼야 연기가 한 줄기로 남네."}, {"s": "q:sx_mangdol", "t": "향로가 연기를 먹어요? 왜요?"}, {"s": "q:sx_ihyang", "t": "잃은 걸 찾아 주는 연기니까. 저것들은 무엇을 잃었는지 잊어버린 것들이라네. 자네처럼."}, {"s": null, "t": "망돌이 입을 다물었다."}]'::jsonb, '{"xp": 2303}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_inverted_incense', 3, '연기를 담는 주머니', '뒤집힌 향로귀을(를) 물리친다', '{"at": ["inverted_shrine"], "tasks": [{"t": "win", "m": ["gw_shrine_2"], "n": 2}]}'::jsonb, '[{"s": null, "t": "향로귀가 깨지자 연기가 다시 한 줄기로 모였다. 그러나 바람이 한 번 지나가자 연기는 금세 옅어졌다."}, {"s": "q:sx_ihyang", "t": "맨 연기는 오래 못 가네. 주머니에 담아야 하네. 거꾸로 향낭을 지어 보게. 향목을 넣고, 무월 비단으로 감싸고, 요인 혈정으로 입을 묶으면 되네."}, {"s": "q:sx_mangdol", "t": "제가 지으면 안 돼요? 손이 커서 다 터트릴 것 같긴 한데……."}, {"s": "q:sx_ihyang", "t": "잃은 사람은 제 길을 못 짓네. 남이 지어 줘야 하네."}, {"s": null, "t": "나는 왜 그래야 하느냐고 물었다."}, {"s": "q:sx_ihyang", "t": "자네는 제 그림자를 직접 밟아 본 적이 있나. 그런 것일세."}]'::jsonb, '{"xp": 2303}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_inverted_incense', 4, '발밑에 없는 것', '거꾸로 향낭을(를) 만든다, 거꾸로 향낭을(를) 넘긴다', '{"at": ["inverted_shrine"], "tasks": [{"t": "craft", "items": ["m6_purify"], "n": 1}], "give": {"m6_purify": 1}}'::jsonb, '[{"s": null, "t": "향낭을 열자 연기가 흘러나와 망돌의 발치에 고였다. 연기는 더 가지 않고 그의 발 둘레를 맴돌며, 무언가 있어야 할 자리를 동그랗게 비워 두었다."}, {"s": "q:sx_mangdol", "t": "여기요? 제 발이요? 발은 그대로 있는데요."}, {"s": null, "t": "그 빈자리를 보고서야 나는 알았다. 등불이 망돌을 비추는데, 발밑에 그림자가 없었다."}, {"s": "q:sx_mangdol", "t": "아. 아! 그림자! 그림자를 잃었어요! 언제부터 없었지?"}, {"s": "q:sx_ihyang", "t": "잃은 게 아닐세. 위를 보게."}, {"s": null, "t": "망돌이 고개를 들었다. 천장에 덩치 큰 그림자가 거꾸로 붙어 있었다. 망돌이 손을 흔들자 그림자도 손을 흔들었다."}, {"s": "q:sx_ihyang", "t": "이 사당에서는 그림자가 위로 떨어지네. 자네는 너무 오래 앉아 있었어. 그러고는 줄곧 아래만 보며 찾았으니 못 찾을 수밖에."}, {"s": "q:sx_mangdol", "t": "그럼 처음부터 말해 주시지요!"}, {"s": "q:sx_ihyang", "t": "말했네. 위를 보며 걸으라고."}, {"s": null, "t": "망돌은 그림자를 머리에 인 채 사당을 나갔다. 일주문을 넘자 그림자가 툭 떨어져 그의 발밑에 제대로 붙었다."}, {"s": null, "t": "나는 향낭을 돌려주려다 멈췄다. 들보 위에 앉은 향지기의 발밑에도, 천장에도, 그림자는 어디에도 없었다."}, {"s": "q:sx_ihyang", "t": "내 것은 찾지 말게. 나는 일부러 놓아 둔 것이니."}]'::jsonb, '{"xp": 2303, "gil": 141, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
