delete from public.world_quest_steps where quest_id = 'sq110_f_office2' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_office2', 1, '묶인 칼들', '묶인 칼들', '{"at": ["seal_vault"]}'::jsonb, '[{"s": null, "t": "봉인고 서고 맨 안쪽, 처음 보는 철문 앞에 문수와 노송이 서 있었다. 철문 틈으로 금줄이 비어져 나와 있었다."}, {"s": "q:dh_munsu", "t": "조사원님, 큰일 났어요. 봉인고 맨 처음 압수물이 깨어났대요. 깨어날 때마다 다른 봉인에 금이 가요."}, {"s": "q:sx_nosong", "t": "그게 무엇인지 적힌 기록이 없소. 봉인고를 처음 연 날 들어왔다는 것만 전해지지."}, {"s": "q:sx_nosong", "t": "그 앞을 금줄 감긴 요도들이 지키오. 금줄이 그대로 결계라 함부로 다가가면 칼이 먼저 뛰오."}, {"s": null, "t": "철문 뒤에서 무언가 긁히는 소리가 났다. 문수가 내 소매를 붙잡았다."}, {"s": "q:dh_munsu", "t": "감찰관님이 오시기 전에 길을 터 놓으래요. 저는 무서운데요, 그래도 따라갈게요. 서리가 기록을 해야 하니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_office2', 2, '기록 없는 상자', '금줄 감긴 요도을(를) 물리친다', '{"at": ["seal_vault"], "tasks": [{"t": "win", "m": ["r71_vault_4"], "n": 3}]}'::jsonb, '[{"s": null, "t": "요도들이 바닥에 떨어지자 철문 안쪽에 작은 나무 상자 하나가 드러났다. 상자 겉의 봉인 각인이 모두 닳아 있었다."}, {"s": null, "t": "차가운 얼굴의 감찰관이 철문 앞으로 걸어왔다. 상자를 한 번 보고 곧장 문수를 보았다."}, {"s": "night_office:han", "t": "기록에 없는 압수물이라. 기록에 없는 일은 일어나지 않은 일이다. 그러니 적어라."}, {"s": "q:dh_munsu", "t": "무엇인지 알아야 적죠, 감찰관님."}, {"s": "night_office:han", "t": "그러니 열어서 확인해라. 다만 각인이 닳은 채로 열면 무엇이 튀어나올지 모른다. 새 각인을 덧대고 열어라."}, {"s": "q:sx_nosong", "t": "봉인고 서가 사이에 각인판이 남아 있을 거요. 두 장이면 상자를 다시 묶을 수 있소."}]'::jsonb, '{"xp": 2426}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_office2', 3, '첫 서리의 고집', '각인판을(를) 모은다', '{"at": ["seal_vault"], "tasks": [{"t": "gather", "items": ["rune_plate"], "r": ["seal_vault"], "n": 2}]}'::jsonb, '[{"s": null, "t": "각인판을 덧대자 상자 뚜껑이 저절로 열렸다. 안에는 아이 손바닥만 한 명패 하나가 들어 있었다. 「가희」라는 두 글자가 또렷했다."}, {"s": null, "t": "노송이 명패 뒷면을 등잔에 비췄다. 작은 글씨가 빽빽했다."}, {"s": "q:sx_nosong", "t": "……정청 첫 서리의 글씨요. 「내 딸 가희. 명부 정리 목록에 올랐으나 차마 거두지 못한다. 이 이름은 내가 숨긴다.」"}, {"s": "q:sx_nosong", "t": "그래서 정청이 이름 자체를 압수했던 거요. 거둘 수도, 남길 수도 없으니 봉인고에 가둬 두고 기록을 지웠지."}, {"s": "q:dh_munsu", "t": "수백 년을 아무도 안 불렀으면, 이 이름은 어떻게 아직 남아 있어요?"}, {"s": "q:sx_nosong", "t": "명패가 기억하고 있었던 거요. 거두지 못한 미련이 봉인을 갉으면서."}, {"s": null, "t": "그때 명패에서 검은 기운이 솟구쳐 상자 위로 엉겼다. 수백 년 묵은 미련이 형체를 갖추고 있었다."}, {"s": "night_office:han", "t": "이게 봉인을 깨던 것이군. 이름이 아니라 미련이다. 조사원, 미련을 걷어 내라. 이름은 다치게 하지 말고."}]'::jsonb, '{"xp": 2426}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_f_office2', 4, '해마다 읽는 이름', '봉인고의 첫 압수물을(를) 물리친다', '{"at": ["seal_vault"], "tasks": [{"t": "win", "m": ["r71_vault_5"], "n": 1}]}'::jsonb, '[{"s": null, "t": "검은 기운이 걷히자 명패만 남았다. 문수가 두 손으로 명패를 받쳐 들었다. 철문 밖에서 느린 발소리가 들렸다."}, {"s": "night_office:baek", "t": "첫 서리 이야기는 나도 들은 적이 있네. 기록이 없어 옛말인 줄 알았지."}, {"s": "night_office:han", "t": "도제조님. 규정대로라면 이 이름은 수백 년 전에 거뒀어야 합니다."}, {"s": "night_office:baek", "t": "그렇지. 그리고 규정대로라면 기록에 없는 일은 일어나지 않은 일이지. 이제 적게. 일어난 일로."}, {"s": "night_office:baek", "t": "이 이름 하나는 거두지 않네. 봉인고 기록 맨 앞에 적고, 해마다 명부 정리 목록을 들여오는 서리가 이 이름을 먼저 소리 내어 읽게."}, {"s": "night_office:han", "t": "……예외를 하나 두면 다음 예외가 옵니다."}, {"s": "night_office:baek", "t": "그래서 하나만 두는 걸세. 우리가 무엇을 거두는지 잊지 않으려고."}, {"s": null, "t": "문수가 명패를 들고 그 이름을 소리 내어 불렀다. 오래 닫혀 있던 서고에 바람이 한 번 지나갔다."}, {"s": "q:dh_munsu", "t": "해마다 제가 읽을게요. 제가 못 하게 되면 다음 서리가 읽겠죠. 그 사람한테 이 얘기도 해 줄게요."}, {"s": "q:sx_nosong", "t": "등잔은 누가 지켜보지 않아도 타야 한다더니. 이 서고에도 등잔 하나가 생겼구려."}]'::jsonb, '{"xp": 2426, "gil": 145, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
