insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_ferryman_mask', 1, '나루의 밥그릇', '나루의 밥그릇', '{"at": ["ash_reeds"]}'::jsonb, '[{"s": null, "t": "갈대숲 안쪽, 물에 반쯤 잠긴 나루터에 밥 한 그릇과 물 한 사발이 놓여 있었다. 그 옆에서 반요 아낙이 쪼그려 앉아 물 쪽을 보고 있었다."}, {"s": "q:sx_galmi", "t": "쉿, 조금만 낮게 앉아 주세요. 사공 양반은 사람이 많으면 안 나와요."}, {"s": null, "t": "안개 속에서 낡은 나룻배가 미끄러져 왔다. 노를 쥔 망령은 얼굴이 있어야 할 자리가 물안개처럼 흐렸다. 배는 나루에 닿지 않고 멀찍이 멈춰 섰다."}, {"s": "q:sx_galmi", "t": "밤마다 저기까지 와요. 그런데 노를 안 저어요. 얼굴이 없으니까, 손님들이 보고 다 도망쳤대요."}, {"s": "q:sx_galmi", "t": "그래서 탈을 하나 지어 드리고 싶어요. 얼굴 대신 쓰시게요. 짓는 법은 알아요. 그런데 제 손이 이래서……."}, {"s": null, "t": "아낙의 손가락은 비늘에 덮여 구부러지지 않았다."}, {"s": "q:sx_galmi", "t": "탈 끈은 갈대 영사로 꼬아야 물에 안 풀려요. 세 타래만 걷어다 주실래요?"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_ferryman_mask', 2, '어떤 얼굴을', '갈대 영사을(를) 모은다', '{"at": ["ash_reeds"], "tasks": [{"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 3}]}'::jsonb, '[{"s": "q:sx_galmi", "t": "고마워요. 이만하면 끈은 넉넉해요."}, {"s": "q:sx_galmi", "t": "섬에서는 예부터 사공 탈이라는 걸 지었어요. 물에 빠진 사람한테 얼굴을 대신 씌워 보내던 탈이래요. 눈자위는 요인 혈정으로 그려요."}, {"s": null, "t": "나는 어떤 얼굴을 그려야 하느냐고 물었다."}, {"s": "q:sx_galmi", "t": "그게…… 저도 몰라요. 사공 양반 얼굴을 본 사람이 없으니까요."}, {"s": "q:sx_galmi", "t": "그냥 웃는 얼굴로 해 주세요. 손님이 무서워하지 않게요."}, {"s": null, "t": "갈미는 밥그릇을 물가로 조금 더 밀어 두었다. 배 위의 망령이 그쪽으로 몸을 기울였다가 다시 멈췄다."}]'::jsonb, '{"xp": 2426}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_ferryman_mask', 3, '탈을 쓴 사공', '사공 탈을(를) 만든다, 사공 탈을(를) 넘긴다', '{"at": ["ash_reeds"], "tasks": [{"t": "craft", "items": ["k6_ghost"], "n": 1}], "give": {"k6_ghost": 1}}'::jsonb, '[{"s": null, "t": "다 지은 탈을 건네자 갈미가 끈을 한 번 더 단단히 매었다. 그러고는 탈을 물 위에 띄워 배 쪽으로 밀어 보냈다."}, {"s": null, "t": "탈은 물살을 타고 천천히 흘러가 뱃전에 닿았다. 망령은 그것을 오래 내려다보다가, 흐린 얼굴 위에 가만히 썼다."}, {"s": null, "t": "웃는 탈을 쓴 사공이 노를 들었다. 노가 물을 쳤다. 배가 처음으로 나루에 닿았다."}, {"s": "q:sx_galmi", "t": "……타요. 같이 타요. 얼른요."}, {"s": null, "t": "갈미가 내 소매를 끌었다. 배 바닥에는 낡은 낚싯대 두 자루가 놓여 있었다."}, {"s": "q:sx_galmi", "t": "사공 양반이 예전엔 손님을 태우면 물고기를 잡아 줬대요. 건너는 동안 심심하지 말라고요. 오늘은 우리가 잡아 드려요. 두 마리만요."}]'::jsonb, '{"xp": 2426}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_ferryman_mask', 4, '맡겨 둔 이름', '잿빛 갈대숲에서 낚시를 한다', '{"at": ["ash_reeds"], "tasks": [{"t": "fish", "r": ["ash_reeds"], "n": 2}]}'::jsonb, '[{"s": null, "t": "배는 갈대 사이를 느릿느릿 돌았다. 잡은 물고기를 뱃전에 올려 두자, 사공은 탈 쓴 얼굴을 그쪽으로 돌리고 한참 바라보았다."}, {"s": "q:sx_galmi", "t": "저 처음 섬에 왔을 때 이 배를 탔어요. 사공 양반이 뱃삯으로 이름 하나를 달라고 해서, 바깥 이름을 드렸어요."}, {"s": "q:sx_galmi", "t": "다들 큰일 난다고 했는데요, 저는 아직 요괴가 안 됐잖아요. 사공 양반이 그 이름을 잘 갖고 계신 거예요. 그 생각을 하면 밥을 안 드릴 수가 없어요."}, {"s": null, "t": "나는 그 이름을 돌려받고 싶지 않으냐고 물었다."}, {"s": "q:sx_galmi", "t": "이제는 갈미가 좋아요. 섬에서 지은 이름이에요. 문패에도 이것만 적었어요."}, {"s": null, "t": "배가 나루에 다시 닿았다. 갈미가 내리자, 사공이 노를 멈추고 아주 작게 무어라 불렀다. 사람 이름 같았다."}, {"s": null, "t": "갈미는 돌아보지 않았다. 맡긴 이름으로는 불려도 대답할 수 없다는 것을 나는 알고 있었다. 그래도 갈미는 웃고 있었다."}, {"s": null, "t": "사공은 탈을 쓴 채 다시 안개 속으로 노를 저어 갔다. 이번에는 같은 자리를 돌지 않았다."}]'::jsonb, '{"xp": 2426, "gil": 145, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
