delete from public.world_quest_steps where quest_id = 'sq110_s_soetdae' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_soetdae', 1, '아래로 타는 불', '아래로 타는 불', '{"at": ["inverted_shrine"]}'::jsonb, '[{"s": null, "t": "거꾸로 선 사당 마당에 낯익은 좌판이 펼쳐져 있었다. 등잔 수십 개가 줄지어 놓였는데, 불꽃이 모두 아래로 늘어져 타고 있었다."}, {"s": "q:r71_soetdae", "t": "구경만 할 거면 저리 비키쇼. 이 섬은 손님보다 구경꾼이……"}, {"s": "q:r71_soetdae", "t": "어, 당신이오? 등잔골에서 두꺼비 치워 준 그 조사원! 이 먼 데서 또 보는구려."}, {"s": null, "t": "나는 쇳대가 어떻게 귀허도까지 왔느냐고 물었다."}, {"s": "q:r71_soetdae", "t": "그 통행세 장부 말이오. 새 두목이 앉자마자 들이밀었더니 세를 반으로 깎더이다. 장사가 좀 되니 욕심이 나서, 밤이 제일 긴 데가 어디냐고 물었지. 다들 바다 건너 섬이라더구려."}, {"s": "q:r71_soetdae", "t": "와 보니 밤은 참 길더이다. 그런데 불이 거꾸로 타오. 심지 밑으로 불이 흘러서 기름 접시를 다 태워 먹지 뭐요."}, {"s": "q:r71_soetdae", "t": "게다가 뒤집힌 향로귀란 것들이 와서 내 불꽃을 제 연기 속으로 빨아 가오. 사흘 동안 등잔 하나도 못 팔았소. 저것들부터 좀 치워 주쇼."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_soetdae', 2, '거꾸로의 거꾸로', '뒤집힌 향로귀을(를) 물리친다', '{"at": ["inverted_shrine"], "tasks": [{"t": "win", "m": ["gw_shrine_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "향로귀가 쓰러지자 아래로 흐르던 연기가 걷혔다. 등잔 불꽃은 여전히 아래로 늘어져 있었다."}, {"s": "q:r71_soetdae", "t": "고맙소. 이제 빼앗기지는 않겠소. 그런데 불이 바로 서질 않으니 팔 수가 있어야지."}, {"s": null, "t": "쇳대는 한참 팔짱을 끼고 사당 처마를 올려다보았다. 처마도 기둥도 모두 거꾸로 서 있었다."}, {"s": "q:r71_soetdae", "t": "가만, 여기선 다 거꾸로란 말이지. 그럼 거꾸로 자란 나무로 받침을 깎으면 어떻소? 거꾸로의 거꾸로면 바로 서지 않겠소?"}, {"s": null, "t": "나는 그게 될지 모르겠다고 했다."}, {"s": "q:r71_soetdae", "t": "꾀가 아니라 셈이오. 빼기에 빼기를 하면 더하기 아니오."}, {"s": "q:r71_soetdae", "t": "이 사당 뒤편에 거꾸로 향목이 자란다더이다. 받침 세 개만 깎을 만큼 베어 와 주쇼."}]'::jsonb, '{"xp": 2426}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_soetdae', 3, '견본 두 개', '거꾸로 향목을(를) 모은다', '{"at": ["inverted_shrine"], "tasks": [{"t": "gather", "items": ["inverted_incense"], "r": ["inverted_shrine"], "n": 3}]}'::jsonb, '[{"s": null, "t": "쇳대가 거꾸로 향목으로 받침을 깎아 등잔 밑에 괴었다. 불꽃이 잠깐 흔들리더니, 천천히 위로 섰다."}, {"s": "q:r71_soetdae", "t": "섰다! 섰소! 보시오, 셈이 맞지 않소!"}, {"s": null, "t": "그런데 섬 바람이 한 번 불자 불꽃이 픽 꺼졌다. 다시 붙여도 또 꺼졌다."}, {"s": "q:r71_soetdae", "t": "……바깥 기름이라 이 섬 바람을 못 견디는구려. 섬 사람들은 생선 기름으로 켜는 어유 등잔을 쓴다 들었소."}, {"s": "q:r71_soetdae", "t": "어유 등잔 두 개만 만들어 주쇼. 견본으로 놓고 그대로 본떠 팔 테니. 값은 치르겠소."}, {"s": null, "t": "나는 값은 됐다고 했다."}, {"s": "q:r71_soetdae", "t": "안 되오. 공짜로 받으면 셈이 안 맞소. 장사꾼이 셈 안 맞는 물건을 좌판에 올리면 그날로 망하는 거요."}]'::jsonb, '{"xp": 2426}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_soetdae', 4, '둘째 덤', '어유 등잔을(를) 만든다, 어유 등잔을(를) 넘긴다', '{"at": ["inverted_shrine"], "tasks": [{"t": "craft", "items": ["fish_oil_lamp"], "n": 2}], "give": {"fish_oil_lamp": 2}}'::jsonb, '[{"s": null, "t": "쇳대는 어유 등잔 두 개를 거꾸로 향목 받침 위에 올려 좌판 맨 앞에 내놓았다. 섬 바람이 불어도 불꽃은 꺼지지 않고 꼿꼿이 섰다."}, {"s": null, "t": "저녁 무렵, 반요 아이 하나가 좌판 앞에 쭈뼛쭈뼛 섰다. 손바닥에 반요 비늘 한 닢을 올려 내밀었다. 섬에서는 그게 돈이었다."}, {"s": "q:r71_soetdae", "t": "첫 손님이구려. 하나 골라 보거라."}, {"s": null, "t": "아이가 등잔 하나를 고르자, 쇳대는 좌판에서 제일 좋은 심지를 골라 아이 손에 함께 쥐여 주었다."}, {"s": "q:r71_soetdae", "t": "심지는 덤이다. 이 섬에서 덤 받은 손님은 네가 처음이야."}, {"s": null, "t": "아이는 등잔을 두 손으로 받쳐 들고 사당 계단을 뛰어 내려갔다. 거꾸로 선 처마 밑으로 작은 불빛 하나가 멀어졌다."}, {"s": null, "t": "쇳대는 받은 비늘을 한참 들여다보더니 내 손바닥에 올려놓았다."}, {"s": "q:r71_soetdae", "t": "첫 손님 돈은 길잡이한테 주는 법이오. 그리고 이건 셈에 안 넣소. 덤이오. 당신은 두 번째 덤을 받은 사람이오. 처음도 당신이었고."}]'::jsonb, '{"xp": 2426, "gil": 145, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
