insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_memory_scale', 1, '헐값', '헐값', '{"at": ["moonless_market"]}'::jsonb, '[{"s": null, "t": "꺼진 청사초롱 아래, 떡 좌판 앞에서 반요 아낙이 시루를 붙들고 울상을 짓고 있었다. 시루 속 떡은 반쯤 설어 있었다."}, {"s": "q:sx_gopdan", "t": "떡 사러 왔으면 내일 오우. 오늘 떡은 망했어."}, {"s": "q:sx_gopdan", "t": "우리 어머니가 떡 찌던 법을 잊어버렸거든. 아니, 판 거지. 저 끝 골목 저울 장수한테."}, {"s": "q:sx_gopdan", "t": "급전이 필요해서 하루 치 기억만 달아 보자 했는데, 저울이 내 쪽으로 붕 떠오르더라고. 기억이 가볍다나. 그래서 헐값에 넘겼지."}, {"s": "q:sx_gopdan", "t": "그런데 이 골목 사람들이 다 똑같은 소리를 해. 하나같이 기억이 가볍다는 소리를 들었대. 이상하지 않수?"}, {"s": null, "t": "나는 그 저울을 한번 살펴보겠다고 했다."}, {"s": "q:sx_gopdan", "t": "그럼 저잣거리를 좀 돌아보고 오우. 저울 장수 좌판은 날마다 자리를 옮겨."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_memory_scale', 2, '속이 빈 추', '달 없는 저잣거리을(를) 살핀다', '{"at": ["moonless_market"], "tasks": [{"t": "search", "r": ["moonless_market"], "n": 3}]}'::jsonb, '[{"s": null, "t": "저잣거리 맨 끝 좌판에서 저울을 찾았다. 장수는 자리를 비웠고, 저울만 덩그러니 놓여 있었다."}, {"s": null, "t": "추를 들어 보니 이상하게 가벼웠다. 바닥을 비틀어 열자 속이 텅 비어 있었다. 대신 손님 쪽이 아닌 장수 쪽 접시 밑바닥에 망각 수정이 덕지덕지 붙어 있었다."}, {"s": "q:sx_gopdan", "t": "이것 봐! 제 쪽 접시에 남의 기억을 붙여 놓고, 우리 기억더러 가볍다고 했던 거야!"}, {"s": "q:sx_jeoul", "t": "손님, 남의 좌판에서 무얼 하시오."}, {"s": null, "t": "등 뒤에서 갓을 쓴 키 큰 그림자가 다가왔다. 그 뒤로 얼굴 없는 손님들이 우르르 따라왔다."}, {"s": "q:sx_jeoul", "t": "내 단골들이 손님을 마음에 들어 하지 않는구려. 단골들, 손님을 배웅해 드리시오."}, {"s": "q:sx_gopdan", "t": "저것들도 다 저놈한테 기억을 팔다가 제 얼굴까지 잊은 사람들이야. 너무 세게는 말고!"}]'::jsonb, '{"xp": 2553}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_memory_scale', 3, '장수의 저울질', '얼굴 없는 손님 떼을(를) 물리친다', '{"at": ["moonless_market"], "tasks": [{"t": "win", "m": ["gw_market_2"], "n": 4}]}'::jsonb, '[{"s": null, "t": "손님들이 흩어지자 장수는 저울을 품에 안고 뒷걸음질 쳤다."}, {"s": "q:sx_jeoul", "t": "억지 쓰지 마시오. 저울은 정직하오. 사람들이 스스로 가볍다고 믿었을 뿐이지."}, {"s": "q:sx_gopdan", "t": "그럼 네 기억도 한번 달아 보자. 네 저울이 정직하다며."}, {"s": null, "t": "나는 접시 밑의 수정을 떼어 내고 추를 바로 채워 저울에 걸었다. 장수가 움찔했다."}, {"s": "q:sx_jeoul", "t": "그건 아니 되오. 내 것은…… 내 것은 무겁소. 아주 무겁소."}, {"s": "q:sx_gopdan", "t": "무거우면 비싸게 쳐 주지. 올려 봐."}, {"s": "q:sx_jeoul", "t": "아니 된다 하지 않았소!"}, {"s": null, "t": "갓 아래에서 저울 접시 같은 손이 둘 튀어나왔다. 좌판이 엎어졌다."}]'::jsonb, '{"xp": 2553}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_memory_scale', 4, '빈 접시', '기억 저울 장수을(를) 물리친다', '{"at": ["moonless_market"], "tasks": [{"t": "win", "m": ["gw_market_3"], "n": 1}]}'::jsonb, '[{"s": null, "t": "장수가 쓰러지자 품에 안고 있던 저울이 굴러 나왔다. 흩어지는 장수의 몸에서 흘러나온 것들이 하나둘 접시에 올라앉았다. 장수 자신의 기억이었다."}, {"s": null, "t": "저울은 꿈쩍도 하지 않았다. 접시에 올라간 기억은 하나같이 깃털보다 가벼웠다."}, {"s": "q:sx_gopdan", "t": "……뭐야. 제 것은 무겁다더니."}, {"s": null, "t": "나는 수정 하나를 들어 보았다. 젊은 장수가 다른 저울 앞에 서 있었다. 저울 너머의 누군가가 「가볍구먼」 하고 웃었다. 장수가 처음으로 판 기억이었다."}, {"s": "q:sx_gopdan", "t": "저놈도 처음엔 속았구먼. 그래서 남을 속였고."}, {"s": "q:sx_gopdan", "t": "그래도 불쌍하단 소린 안 할 거야. 남의 어머니 떡을 훔쳐 간 놈이니."}, {"s": null, "t": "곱단은 흩어진 수정 가운데 하나를 골라 이마에 댔다. 그러고는 시루에 물을 다시 부었다."}, {"s": "q:sx_gopdan", "t": "됐다. 쌀은 한 번 더 불리고, 소금은 손가락 세 마디만큼. 우리 어머니는 시루에 대고 「잘 쪄져라」 하고 말을 걸었어. 그걸 잊고 있었네."}, {"s": null, "t": "곱단은 그 저울을 좌판 옆에 걸었다. 이제 그 저울로는 떡만 단다고 했다. 눈금 하나 속이지 않고."}, {"s": null, "t": "김이 오른 떡 한 덩이를 받아 들었다. 따뜻하고 묵직했다."}]'::jsonb, '{"xp": 2553, "gil": 149, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
