values ('sq110_s_haerang', 'side', '전투·달 없는 저잣거리', '빌려준 얼굴', '거울 속 또 하나의 얼굴이 저잣거리에서 팔리고 있다', 'moonless_market', 36, '{sq_glass_canyon_2,mq_nine_gates}'::text[], null, 1182, '[]'::jsonb, true, null, null)
