delete from public.world_quest_steps where quest_id = 'sq110_s_haerang' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_haerang', 1, '빈 거울', '빈 거울', '{"at": ["moonless_market"]}'::jsonb, '[{"s": null, "t": "달 없는 저잣거리 어귀, 등불 하나 없는 골목 끝에 보자기로 싼 둥근 것을 안은 여인이 서 있었다. 보자기 틈으로 유리 가장자리가 비쳤다."}, {"s": "q:rn_haerang", "t": "조사원님, 저예요. 유리협곡 해랑이요. 그 거울 기억하시죠. 가마 옆에 여덟 해를 걸어 두었어요."}, {"s": "q:rn_haerang", "t": "그런데 한 달 전부터 거울 속에 그 애가 없어요. 그냥 거울이 됐어요. 제 얼굴만 비쳐요."}, {"s": "q:rn_haerang", "t": "협곡에 들른 반요 등짐장수가 그랬어요. 섬 저잣거리에서 얼굴을 판다고. 그것도 제 얼굴이랑 똑같은 얼굴을요."}, {"s": null, "t": "그때 골목 저편에서 갓을 쓴 손님들이 줄지어 걸어왔다. 갓 아래가 하나같이 비어 있었다. 그런데 맨 앞 손님 하나에게는 얼굴이 있었다. 해랑과 똑같은 얼굴이었다."}, {"s": "q:rn_haerang", "t": "……저 애예요. 아니, 저 애 얼굴이에요. 웃는 것까지 그대로예요."}, {"s": null, "t": "얼굴 없는 손님들이 일제히 해랑 쪽으로 갓을 돌렸다. 같은 얼굴을 하나 더 가진 사람을 찾아낸 것 같았다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_haerang', 2, '얼굴 좌판', '얼굴 없는 손님 떼을(를) 물리친다', '{"at": ["moonless_market"], "tasks": [{"t": "win", "m": ["gw_market_2"], "n": 4}]}'::jsonb, '[{"s": null, "t": "손님들이 흩어지자 얼굴을 쓰고 있던 손님의 갓이 떨어졌다. 갓 아래에는 아무것도 없었고, 얼굴만 얇은 유리처럼 남아 바닥을 굴러갔다."}, {"s": null, "t": "얼굴은 골목 안쪽 좌판 앞에서 멈췄다. 좌판에는 탈처럼 생긴 얼굴들이 줄지어 걸려 있었다. 주인이 웃는 낯으로 그 얼굴을 집어 빈 고리에 걸었다."}, {"s": "q:sx_mojeon", "t": "손님, 남의 물건을 함부로 굴리시면 곤란하오. 이건 빌려 온 물건이라 고이 돌려주어야 하오."}, {"s": "q:rn_haerang", "t": "빌려 왔다고요? 그건 제 동생 얼굴이에요!"}, {"s": "q:sx_mojeon", "t": "압지요. 그 아가씨가 손수 내놓았으니. 거울 속에서 하루 한 번 얼굴을 빌려주고, 삯으로 망각 수정을 받아 갔소."}, {"s": null, "t": "나는 망각 수정이 무엇이냐고 물었다."}, {"s": "q:sx_mojeon", "t": "팔린 기억이 굳은 돌이오. 들여다보면 남의 기억이 보이지. 거울 속 아가씨는 그걸 모으더이다. 까닭은 묻지 않았소. 장사꾼은 값만 묻는 법이라."}, {"s": "q:sx_mojeon", "t": "얼굴을 도로 가져가시려면 그동안 치른 삯을 물어내시오. 망각 수정 셋. 이 저잣거리 바닥 어디에나 굴러다니니 줍기는 어렵지 않을 게요."}]'::jsonb, '{"xp": 2553}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_haerang', 3, '남의 기억', '망각 수정을(를) 모은다', '{"at": ["moonless_market"], "tasks": [{"t": "gather", "items": ["oblivion_crystal"], "r": ["moonless_market"], "n": 3}]}'::jsonb, '[{"s": null, "t": "망각 수정 셋을 내려놓자 모전은 웃는 낯 그대로 얼굴을 내주었다. 해랑은 얼굴을 받아 들다가 수정 하나를 들여다보고 손을 멈췄다."}, {"s": null, "t": "수정 안에서 낯선 사람이 낯선 마당을 쓸고 있었다. 다른 수정에서는 모르는 아이가 모르는 어머니를 부르고 있었다."}, {"s": "q:rn_haerang", "t": "그 애가 이걸 왜 모았는지 알겠어요. 거울 속에 오래 있으니까 제 기억이 바래 갔던 거예요. 남의 기억으로라도 빈자리를 채우려고 했나 봐요."}, {"s": "q:rn_haerang", "t": "그런데 남의 기억으로 채우면, 그 애는 그 애가 아니게 되잖아요."}, {"s": "q:sx_mojeon", "t": "그렇지요. 얼굴을 몇 번만 더 빌려줬으면 거울 속에는 남의 기억으로 꽉 찬 남이 앉아 있었을 게요. 나야 손해 볼 것 없소만."}, {"s": "q:rn_haerang", "t": "거울을 다시 닫아야 해요. 남의 기억이 스민 테두리를 씻고, 다시는 아무도 그 애 얼굴을 빌려 가지 못하게요. 정화 부적 두 장이면 테두리를 두를 수 있어요."}]'::jsonb, '{"xp": 2553}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_haerang', 4, '한 박자 늦게', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["moonless_market"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "해랑이 정화 부적을 거울 테두리에 두르고 얼굴을 거울에 댔다. 얼굴은 물에 잠기듯 유리 안으로 스며들었다."}, {"s": null, "t": "거울 속에 여자 하나가 앉아 있었다. 해랑과 똑같은 얼굴이었다. 그런데 해랑을 보고도 아무 표정이 없었다."}, {"s": "q:rn_haerang", "t": "해련아."}, {"s": null, "t": "거울 속 여자는 한 박자 늦게 고개를 돌렸다. 그리고 천천히, 협곡에서 보았던 그 얼굴로 웃었다."}, {"s": "q:rn_haerang", "t": "이제 네 이름은 내가 날마다 불러 줄게. 남의 기억 같은 거 모으지 마. 우리 기억은 내가 다 갖고 있으니까."}, {"s": null, "t": "해랑은 거울을 보자기로 단단히 싸서 품에 안았다. 우리가 골목을 나설 때 모전이 등 뒤에서 말했다."}, {"s": "q:sx_mojeon", "t": "또 오시오. 얼굴이 둘이면 하나쯤은 빌려줄 만하지 않소."}, {"s": null, "t": "돌아보니 좌판 맨 끝 빈 고리에 새 값표가 하나 걸려 있었다. 값표에는 해랑의 이름이 적혀 있었다."}]'::jsonb, '{"xp": 2553, "gil": 149, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
