insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_ink', 1, '먹을 삽니다', '먹을 삽니다', '{"at": ["moonless_market"]}'::jsonb, '[{"s": null, "t": "달 없는 저잣거리 끝자락에 처음 보는 좌판이 서 있었다. 검은 항아리 수십 개가 줄지어 놓였고, 항아리마다 아가리를 종이로 봉해 두었다."}, {"s": null, "t": "좌판 기둥에는 「먹을 삽니다」라고 적힌 나무패가 걸려 있었다. 파는 것이 아니라 산다는 글이었다."}, {"s": "q:sx_ilgopjjae", "t": "어서 오시오. 야행국 조사원이시구려. 바깥 손님은 오랜만이오."}, {"s": "q:sx_ilgopjjae", "t": "흑련회에서 이름 거둠꾼 노릇을 하는 사람이오. 회에서는 일곱째라고 부르지. 이름은 회에 맡겨 두었으니 그렇게만 불러 주시오."}, {"s": null, "t": "나는 항아리에 무엇이 들었느냐고 물었다. 일곱째는 항아리 하나를 손가락으로 톡 두드렸다. 안에서 무언가 출렁였다."}, {"s": "q:sx_ilgopjjae", "t": "먹이오. 먹귀가 마지막까지 붙들고 있던 먹. 이름이 거둬진 넋이 미련을 못 놓으면 먹귀가 되는데, 그것이 품고 있던 기억이 이 안에 고여 있소."}, {"s": "q:sx_ilgopjjae", "t": "우리 회는 그걸 거둬 맡아 두었다가, 찾는 사람에게 값을 받고 내주오. 판 게 아니라 맡겨 둔 것이니 셈이 깨끗하지."}, {"s": "q:sx_ilgopjjae", "t": "그런데 밤마다 얼굴 없는 손님들이 몰려와 항아리에 코를 박고 킁킁거리오. 냄새를 맡는 거요. 저것들한테는 이게 밥 냄새로 들리나 보오."}, {"s": "q:sx_ilgopjjae", "t": "손님 떼를 좀 흩어 주시오. 항아리 하나라도 깨지면 내 한 해 장사가 날아가오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_ink', 2, '남의 기억이라도', '얼굴 없는 손님 떼을(를) 물리친다', '{"at": ["moonless_market"], "tasks": [{"t": "win", "m": ["gw_market_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "손님 떼가 흩어진 뒤에도 항아리들은 한동안 달그락거렸다. 봉한 종이 너머로 웅얼거리는 소리가 새어 나왔다. 누군가 아이를 재우는 소리 같았다."}, {"s": null, "t": "갓을 깊이 눌러쓴 반요 노파 하나가 좌판 앞에 쪼그려 앉았다. 손바닥에 반요 비늘 세 닢을 올려 내밀었다."}, {"s": "q:sx_sotdeok", "t": "하나만 주게. 아무거나 하나만. 아무거나."}, {"s": "q:sx_ilgopjjae", "t": "할멈, 이건 바깥 나루에서 거둔 것들이오. 할멈 식구 것은 하나도 없소."}, {"s": "q:sx_sotdeok", "t": "알아. 알아. 내 것은 바깥에 두고 왔어. 아들 얼굴도 생각이 안 나."}, {"s": "q:sx_sotdeok", "t": "남의 기억이라도 품고 자면 덜 추워. 남의 아들이라도 꿈에 오면 반갑더라고."}, {"s": null, "t": "일곱째는 비늘을 세어 받고 작은 항아리 하나를 노파에게 안겨 주었다. 노파는 항아리를 갓난아이처럼 품고 어둠 속으로 사라졌다."}, {"s": null, "t": "나는 그 항아리가 어디서 왔느냐고 물었다."}, {"s": "q:sx_ilgopjjae", "t": "묵창 나루라는 데요. 비 대신 먹비가 내리는 곳이지. 우리 회 동료 하나가 먹비 내리는 나루 쪽으로 갔소. 요즘 거기서 나는 물건이 제일 좋거든."}, {"s": "q:sx_ilgopjjae", "t": "그나저나 이 저잣거리는 달이 없어서 먹이 가라앉질 않소. 망각 수정을 항아리 밑에 괴어 두면 좀 얌전해진다는데, 세 개만 구해다 주시오."}]'::jsonb, '{"xp": 2683}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_ink', 3, '금 간 항아리', '망각 수정을(를) 모은다', '{"at": ["moonless_market"], "tasks": [{"t": "gather", "items": ["oblivion_crystal"], "r": ["moonless_market"], "n": 3}]}'::jsonb, '[{"s": null, "t": "망각 수정을 괴자 항아리들이 하나둘 조용해졌다. 맨 끝의 큰 항아리 하나만 떨기를 멈추지 않았다."}, {"s": null, "t": "쩍, 소리와 함께 그 항아리 옆구리에 금이 갔다. 틈으로 검은 먹이 한 줄기 흘러나와 좌판 널빤지를 적셨다."}, {"s": null, "t": "먹이 번진 자리에서 여자 목소리가 났다. 누군가의 이름을 부르고 있었다. 같은 이름을, 대답이 올 때까지 기다리듯 천천히 되풀이했다."}, {"s": null, "t": "일곱째의 손이 잠깐 멈췄다. 정말 아주 잠깐이었다."}, {"s": null, "t": "나는 아는 이름이냐고 물었다."}, {"s": "q:sx_ilgopjjae", "t": "모르는 이름이오."}, {"s": "q:sx_ilgopjjae", "t": "……이런 건 값이 꽤 나가오. 이렇게 오래, 이렇게 또렷하게 부르는 먹은 드물거든."}, {"s": null, "t": "일곱째는 웃었다. 입꼬리만 올라간 웃음이었다."}, {"s": "q:sx_ilgopjjae", "t": "먹이 다 새기 전에 막아야겠소. 정화 부적 두 장이면 금을 덮을 수 있을 거요. 서둘러 주시오. 새는 먹은 값이 떨어지니까."}]'::jsonb, '{"xp": 2683}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_ink', 4, '안 파는 항아리', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["moonless_market"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "일곱째는 정화 부적 두 장을 엇갈려 붙여 금을 덮었다. 목소리가 부적 안쪽으로 잦아들었다. 마지막 한 번은 끝까지 다 부르지 못하고 끊겼다."}, {"s": null, "t": "일곱째는 그 항아리를 진열대에 올리지 않았다. 보따리에 싸서 제 등 뒤에 내려놓았다."}, {"s": null, "t": "나는 팔지 않을 거냐고 물었다."}, {"s": "q:sx_ilgopjjae", "t": "값을 못 매기겠소. 값을 못 매기는 물건은 파는 게 아니오. 장사꾼의 셈이 그렇소."}, {"s": "q:sx_ilgopjjae", "t": "조사원, 언젠가 묵창 나루에 가거든 비를 맞지 마시오. 거기는 먹비가 문패 글자를 지우고, 매어 둔 배의 이름까지 지운다더이다. 사람들이 아침마다 문패를 새로 쓴다지."}, {"s": "q:sx_ilgopjjae", "t": "그리고 거기 먹귀를 보거든…… 아니오. 그건 그때 가서 보시오."}, {"s": null, "t": "저잣거리를 떠나며 돌아보니, 좌판 앞에 얼굴 없는 손님들이 다시 줄지어 서 있었다. 이번에는 아무도 킁킁거리지 않았다. 다들 일곱째의 등 뒤 보따리 쪽을 향해 가만히 서 있을 뿐이었다."}, {"s": null, "t": "기둥에 걸린 「먹을 삽니다」 나무패의 글자가, 올 때보다 조금 흐려져 있었다."}]'::jsonb, '{"xp": 2683, "gil": 153, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
