delete from public.world_quest_steps where quest_id = 'sq110_moon_mourner' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_moon_mourner', 1, '꺼진 초롱', '꺼진 초롱', '{"at": ["moonless_market"]}'::jsonb, '[{"s": null, "t": "저잣거리의 청사초롱은 모두 꺼져 있었다. 노인 하나가 사다리를 오르내리며 그 초롱을 하나씩 닦고 있었다. 불은 켜지 않았다."}, {"s": "q:sx_bitnae", "t": "켜지도 않을 초롱을 왜 닦느냐고 묻고 싶은 얼굴이군."}, {"s": "q:sx_bitnae", "t": "이 거리에는 달이 없네. 그래서 초롱을 켜 봐야 불빛이 퍼지지를 않아. 그래도 닦아 두면, 달이 돌아오는 날 바로 켤 수 있지."}, {"s": null, "t": "나는 달이 어디로 갔느냐고 물었다."}, {"s": "q:sx_bitnae", "t": "팔렸네. 이 거리에선 무엇이든 팔리니까. 판 사람은 어느 상주였어. 어머니 장례를 치를 값이 없었다지."}, {"s": "q:sx_bitnae", "t": "그날 일은 나도 흐릿하네. 거리 사람들이 그날 밤 기억을 죄다 망각 수정으로 흘려 버렸거든. 수정 넷이면 그날 밤을 대강 이어 볼 수 있을 걸세."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_moon_mourner', 2, '그날 밤', '망각 수정을(를) 모은다', '{"at": ["moonless_market"], "tasks": [{"t": "gather", "items": ["oblivion_crystal"], "r": ["moonless_market"], "n": 4}]}'::jsonb, '[{"s": null, "t": "빛내가 수정 넷을 꺼진 초롱 안에 하나씩 넣었다. 불 없는 초롱 속에 흐린 그림이 떠올랐다."}, {"s": null, "t": "하얀 상복을 입은 사내가 빈 상여 앞에 서 있었다. 상여를 멜 사람도, 곡을 할 사람도 없었다. 사내는 한참 하늘을 올려다보다가 좌판 앞으로 걸어갔다."}, {"s": null, "t": "「값이 모자라오. 어머니 기억은 하나도 못 팔겠소. 그러니 저것을 가져가시오.」 사내가 가리킨 것은 달이었다."}, {"s": "q:sx_bitnae", "t": "그 값으로 상여꾼을 사고, 곡꾼을 사고, 등불을 샀지. 섬에서 그렇게 큰 장례는 처음이었네."}, {"s": "q:sx_bitnae", "t": "헌데 장례가 끝나도 그는 상복을 벗지 않았어. 지금도 거리 끝에서 상여 곁을 지키고 있네. 몸이 저잣거리만큼 커져서, 이제는 아무도 그를 이름으로 부르지 않아. 그저 「상주」라고들 하지."}, {"s": "q:sx_bitnae", "t": "사람이 이름 대신 제 노릇으로만 불리면, 이름은 이미 떠난 거라네. 그를 보내 주게. 상복째로라도."}]'::jsonb, '{"xp": 2683}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_moon_mourner', 3, '상여 곁', '달을 판 상주을(를) 물리친다', '{"at": ["moonless_market"], "tasks": [{"t": "win", "m": ["gw_market_5"], "n": 1}]}'::jsonb, '[{"s": "q:sx_sangju", "t": "조용히 하오. 어머니 주무시오."}, {"s": null, "t": "거대한 상주가 무너지며 빈 상여 위로 엎어졌다. 상복 자락이 거리를 덮었다."}, {"s": "q:sx_sangju", "t": "달이 있으면…… 어머니가 길을 찾아 떠나실 것 같았소. 그래서 팔았소. 장례 값은 핑계였소."}, {"s": "q:sx_sangju", "t": "어두우면 못 가시겠지. 못 가시면 내 곁에 계시겠지."}, {"s": null, "t": "상주의 몸이 흩어지고 나니, 상여 안에 희미한 영 하나가 앉아 있었다. 늙은 여인이었다. 여인은 흩어지는 아들 쪽으로 손을 뻗고 있었다."}, {"s": "q:sx_bitnae", "t": "어머니가 아직 계셨구먼. 아들이 날마다 불러 드린 덕이야."}, {"s": "q:sx_bitnae", "t": "이제 아들이 먼저 떠났으니 어머니가 길을 잃으시겠네. 수의를 덮어 드려야 해. 달 없는 밤에 짠 무월 비단이라야 이 거리에서 바래지 않네. 세 필만 구해 주게."}]'::jsonb, '{"xp": 2683}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_moon_mourner', 4, '달이라 부르기엔', '무월 비단을(를) 모은다', '{"at": ["moonless_market"], "tasks": [{"t": "gather", "items": ["moonless_silk"], "r": ["moonless_market"], "n": 3}]}'::jsonb, '[{"s": null, "t": "빛내와 함께 무월 비단을 펼쳐 상여를 덮었다. 비단이 어깨에 닿자, 여인의 영이 천천히 고개를 들었다."}, {"s": "q:sx_bitnae", "t": "할머니, 이름을 기억하시오? 나라도 불러 드리리다."}, {"s": null, "t": "여인은 고개를 저었다. 그리고 입술을 움직여 한 사람의 이름을 말했다. 아들의 이름이었다."}, {"s": "q:sx_bitnae", "t": "제 이름은 잊으시고, 스스로를 아들 이름으로 아시는구먼. 아무개 어미라고. 그것도 이름이지."}, {"s": "q:sx_bitnae", "t": "그럼 내가 그 이름으로 불러 드리겠네. 날마다, 초롱 닦을 때마다."}, {"s": null, "t": "빛내는 사다리를 올라 가장 높은 초롱에 불을 켰다. 처음으로 불빛이 퍼졌다. 아주 조금이었다."}, {"s": null, "t": "그날 밤 저잣거리 하늘 한쪽이 희미하게 밝았다. 달이라고 부르기에는 모자란 빛이었다."}, {"s": "q:sx_bitnae", "t": "그래도 길은 보이겠지. 가실 거면 가시고, 계실 거면 계시고."}, {"s": null, "t": "상여 위의 영은 어디로도 가지 않고, 그 빛 아래 오래 앉아 있었다."}]'::jsonb, '{"xp": 2683, "gil": 153, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
