insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_pawn_spider', 1, '기한은 다음 달 보름', '기한은 다음 달 보름', '{"at": ["moonless_market"]}'::jsonb, '[{"s": "q:sx_omok", "t": "거기 바깥 양반! 잘 만났소. 저 전당포 좀 혼내 주시오."}, {"s": null, "t": "갖바치 노릇을 한다는 반요 사내가 골목 끝의 시커먼 처마를 가리켰다. 처마 밑에 거미줄이 휘장처럼 드리워져 있었다."}, {"s": "q:sx_omok", "t": "저 안에 늙은 거미가 사는데, 뭐든 맡아 줘. 그런데 골목 사람들이 찾으러 가면 안 돌려준대! 내 왼쪽 신이 자꾸 없어지는 것도 저놈 짓이 틀림없어."}, {"s": "q:sx_geomi", "t": "돌려 드리지요. 기한이 차면."}, {"s": null, "t": "휘장 사이로 커다란 거미가 장부를 넘기며 나타났다."}, {"s": "q:sx_omok", "t": "기한이 언젠데?"}, {"s": "q:sx_geomi", "t": "장부를 보니 「다음 달 보름」이라 적혀 있구려."}, {"s": "q:sx_omok", "t": "여긴 달이 없잖아!"}, {"s": "q:sx_geomi", "t": "그러니 기한이 아직 안 찼지요."}, {"s": "q:sx_omok", "t": "들었소? 저렇게 말이 안 통해. 저놈은 한 대 맞으면 문 닫고 숨었다가 또 나와. 세 번은 혼내야 정신을 차릴 거요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_pawn_spider', 2, '서른 개의 짝신', '전당포 거미을(를) 물리친다', '{"at": ["moonless_market"], "tasks": [{"t": "win", "m": ["gw_market_4"], "n": 3}]}'::jsonb, '[{"s": "q:sx_geomi", "t": "그만, 그만 하시오. 오늘은 문을 닫겠소."}, {"s": "q:sx_omok", "t": "닫기 전에 장부 좀 보자!"}, {"s": null, "t": "거미가 마지못해 내민 장부를 펼쳤다. 서른 줄이 똑같았다. 「짝 잃은 신 한 짝」."}, {"s": null, "t": "거미줄 안쪽에는 정말로 신이 한 짝씩 서른 개, 줄에 매달려 대롱거리고 있었다. 모두 왼쪽 신이었다."}, {"s": null, "t": "나는 신을 왜 이렇게 모았느냐고 물었다."}, {"s": "q:sx_geomi", "t": "다리가 여덟이오. 남들은 신을 두 짝씩 신고 다니더구려. 나도 한번 신어 보고 싶었소."}, {"s": "q:sx_geomi", "t": "헌데 아무도 신을 팔지 않으니 맡아 둘 수밖에. 맡은 것은 기한까지 내 것이오."}, {"s": "q:sx_omok", "t": "그러니까 신이 갖고 싶어서 남의 신을 안 돌려준다 이거야?"}, {"s": "q:sx_omok", "t": "……좋아. 내가 갖바치요. 신을 지어 주면 다 돌려줄 텐가?"}, {"s": "q:sx_geomi", "t": "발소리가 안 나는 비단신이라면 생각해 보겠소."}, {"s": "q:sx_omok", "t": "무월 비단신이구먼. 재료가 없어서 나는 못 지어. 바깥 양반, 하나만 지어다 주시오. 내 이름 걸고 나중에 갚으리다."}]'::jsonb, '{"xp": 2683}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_pawn_spider', 3, '첫 신', '무월 비단신을(를) 만든다, 무월 비단신을(를) 넘긴다', '{"at": ["moonless_market"], "tasks": [{"t": "craft", "items": ["s6_swift"], "n": 1}], "give": {"s6_swift": 1}}'::jsonb, '[{"s": null, "t": "비단신을 내밀자 거미는 여덟 다리 가운데 하나를 조심스럽게 들어 신을 신었다. 몇 걸음 걸어 보더니 장부를 덮었다."}, {"s": "q:sx_geomi", "t": "발소리가 없구려. 좋소. 약속대로 돌려 드리지."}, {"s": null, "t": "거미가 줄을 끊자 왼쪽 신 서른 짝이 와르르 쏟아졌다."}, {"s": "q:sx_geomi", "t": "기한 전에 돌려 드리는 것은 처음이오. 장부에 뭐라 적어야 할지 모르겠구려."}, {"s": "q:sx_omok", "t": "「비단신 한 짝 받고 다 내줌」이라고 적어!"}, {"s": "q:sx_omok", "t": "자, 이제 주인을 찾아 줘야지. 저잣거리에 한 짝만 신고 다니는 놈들이 있을 거야. 두어 바퀴만 돌면 다 찾겠지."}, {"s": null, "t": "나는 신 서른 짝을 자루에 담아 짊어졌다. 생각보다 무거웠다."}]'::jsonb, '{"xp": 2683}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_pawn_spider', 4, '왼발의 주인', '달 없는 저잣거리을(를) 살핀다', '{"at": ["moonless_market"], "tasks": [{"t": "search", "r": ["moonless_market"], "n": 2}]}'::jsonb, '[{"s": null, "t": "저잣거리를 두 바퀴 돌았지만 신을 한 짝만 신은 사람은 아무도 없었다. 얼굴 없는 손님들은 모두 맨발이었다."}, {"s": null, "t": "오목에게 돌아가 자루를 내려놓았다. 오목은 신을 하나씩 들어 보더니 점점 얼굴이 붉어졌다."}, {"s": "q:sx_omok", "t": "……이거, 내 솜씨네."}, {"s": "q:sx_omok", "t": "이것도 내가 지은 거고. 이것도. 바닥 실땀이 꼭 내 것이야."}, {"s": null, "t": "나는 신을 맡긴 사람이 누구였느냐고 거미에게 물었다."}, {"s": "q:sx_geomi", "t": "장부를 보니 맡긴 이의 이름이 모두 「오목」이구려. 서른 번이오. 늘 술 냄새가 나셨지."}, {"s": "q:sx_omok", "t": "그런 건 진작 말했어야지!"}, {"s": "q:sx_geomi", "t": "묻지 않으셨소."}, {"s": null, "t": "오목은 신 서른 짝을 끌어안고 한참 말이 없었다. 그러더니 이튿날부터 오른쪽 신만 일곱 짝을 짓기 시작했다. 거미에게 줄 것이라고 했다."}, {"s": "q:sx_geomi", "t": "기한은 다음 달 보름으로 하겠소."}]'::jsonb, '{"xp": 2683, "gil": 153, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
