delete from public.world_quest_steps where quest_id = 'sq110_s_sapyeong' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_sapyeong', 1, '묶음으로 나온 지팡이', '묶음으로 나온 지팡이', '{"at": ["moonless_market"]}'::jsonb, '[{"s": null, "t": "저잣거리 한복판에서 모래 빛 두건을 쓴 사내가 땅바닥에 귀를 대고 엎드려 있었다. 지나가는 갓 쓴 손님들이 그를 비켜 돌아갔다."}, {"s": "q:rn_sapyeong", "t": "당신이구려. 적사 황무지에서 모래 매복귀를 끌어내 주던. 그새 열 해가 다 되었소."}, {"s": "q:rn_sapyeong", "t": "모래 소리를 듣던 귀로 이 바닥 소리를 듣고 있었소. 여기는 땅이 숨을 쉬지 않소. 대신 수군거리지."}, {"s": "q:rn_sapyeong", "t": "섬에 건너온 반요 순례자가 그러더이다. 이 저잣거리 좌판에 이름 새긴 지팡이가 한 묶음 나와 있다고. 황무지에서 길을 잃은 순례자들의 지팡이라고."}, {"s": null, "t": "나는 그 지팡이를 찾으러 바다를 건너왔느냐고 물었다."}, {"s": "q:rn_sapyeong", "t": "지팡이를 돌려보내는 게 길잡이 일이오. 길을 다 잃은 지팡이라도 마찬가지요."}, {"s": "q:rn_sapyeong", "t": "좌판이 어디 붙었는지는 모르겠소. 여기는 날마다 골목이 바뀐다 하오. 세 번쯤 돌아보며 찾아 주시오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_sapyeong', 2, '값이 붙은 이름', '달 없는 저잣거리을(를) 살핀다', '{"at": ["moonless_market"], "tasks": [{"t": "search", "r": ["moonless_market"], "n": 3}]}'::jsonb, '[{"s": null, "t": "좌판은 골목 그늘 맨 안쪽에 있었다. 주인 없는 좌판 위에 지팡이 수십 자루가 새끼줄로 묶여 있었다. 손때 묻은 손잡이마다 이름이 새겨져 있었다."}, {"s": null, "t": "지팡이마다 종이 값표가 붙어 있었다. 값은 글자가 아니라 얼룩 같았는데, 내가 바라볼 때마다 조금씩 모양이 바뀌었다."}, {"s": "q:rn_sapyeong", "t": "이름에 값을 매기고 있는 거요. 누가 사 갈지 보아 가며."}, {"s": null, "t": "좌판 그늘이 꿈틀거렸다. 그림자 몇이 지팡이 묶음 둘레를 기어 다니며 값표를 고쳐 붙이고 있었다."}, {"s": "q:rn_sapyeong", "t": "길잡이는 모래와 싸우지 않소. 그림자와도 싸우지 않지. 그러나 오늘도 당신이 있구려."}]'::jsonb, '{"xp": 2683}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_sapyeong', 3, '이름 밑의 이름', '값 매기는 그림자을(를) 물리친다', '{"at": ["moonless_market"], "tasks": [{"t": "win", "m": ["gw_market_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "그림자가 흩어지자 값표가 모두 하얗게 바랬다. 사평은 새끼줄을 풀고 지팡이를 하나씩 손끝으로 더듬었다."}, {"s": "q:rn_sapyeong", "t": "이 사람은 내가 스물 적에 잃었소. 이 사람은 서른둘에. 이 둘은 부부였는데, 하루 사이로 잃었지."}, {"s": null, "t": "사평은 지팡이마다 이름을 소리 내어 불렀다. 한 번도 막히지 않았다. 삼십 년 넘게 잃은 순례자를 하나도 잊지 않고 있었다."}, {"s": null, "t": "마지막 지팡이 앞에서 사평의 손이 멈췄다. 손잡이에 이름 둘이 새겨져 있었다. 위에는 깊고 반듯하게 「사평」, 그 밑에는 삐뚤삐뚤한 아이 글씨였다."}, {"s": "q:rn_sapyeong", "t": "내 지팡이요. 처음 잃은 아이에게 빌려주었지. 모래바람이 불던 날, 이걸 짚고 내 발자국을 따라오라 했는데."}, {"s": "q:rn_sapyeong", "t": "아이가 제 이름을 내 이름 밑에 새겼구려. 끝까지 따라오고 있었다는 뜻이오."}, {"s": "q:rn_sapyeong", "t": "모두 데려가겠소. 다만 이 저잣거리를 나설 때까지 그림자들 눈에 띄면 안 되오. 달빛 없이 짠 무월 비단에 싸면 빛을 머금지 않아 그림자가 못 본다 하오. 세 필만 구해 주시오."}]'::jsonb, '{"xp": 2683}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_sapyeong', 4, '둘이 걷는 발자국', '무월 비단을(를) 모은다', '{"at": ["moonless_market"], "tasks": [{"t": "gather", "items": ["moonless_silk"], "r": ["moonless_market"], "n": 3}]}'::jsonb, '[{"s": null, "t": "사평은 지팡이 묶음을 무월 비단으로 세 겹 싸서 등에 졌다. 비단에 싸인 지팡이들은 저잣거리 그늘 속에서 보이지 않았다."}, {"s": null, "t": "저잣거리를 나서는 동안 사평은 한 걸음마다 이름 하나씩을 낮게 불렀다. 마지막에 부른 것은 그 아이의 이름이었다."}, {"s": "q:rn_sapyeong", "t": "황무지로 돌아가 길이 갈라지는 자리마다 하나씩 꽂아 두겠소. 지팡이가 길을 가리키면 뒤에 오는 이가 덜 잃을 거요."}, {"s": null, "t": "나는 아이의 지팡이는 어떻게 할 거냐고 물었다."}, {"s": "q:rn_sapyeong", "t": "그건 내가 짚겠소. 길잡이는 지팡이를 짚지 않는 법이지만, 이제 늙었으니."}, {"s": null, "t": "저잣거리 어귀 진흙 바닥에 사평의 발자국이 찍혔다. 열 해 전보다 깊었다. 그 옆으로 지팡이 끝 자국이 나란히 따라갔다."}, {"s": "q:rn_sapyeong", "t": "이번엔 둘이 걷는 발자국이오."}]'::jsonb, '{"xp": 2683, "gil": 153, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
