insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_5', 1, '값을 묻는 그림자', '값을 묻는 그림자', '{"at": ["moonless_market"]}'::jsonb, '[{"s": null, "t": "달 없는 저잣거리는 등불 하나 없이도 붐볐다. 담채가 화폭을 펼치자 사방에서 그림자들이 고개를 돌렸다."}, {"s": "q:sx_sorim", "t": "조사원님, 사당에서 스승님이 마지막 그림을 그리겠다고 하셔서 여기까지 왔어요. 그런데 오자마자 이래요."}, {"s": "q:sx_eoreum", "t": "이보게 화공. 그 그림 얼마인가. 얼굴 하나에 이름 하나씩 들었으니, 여기선 제법 값이 나가겠어."}, {"s": "q:sx_damchae", "t": "팔 그림이 아니오."}, {"s": "q:sx_eoreum", "t": "여기는 값 없는 게 없는 데일세. 자네가 안 팔겠다 해도 저 그림자들이 알아서 값을 매기지. 매기고 나면 가져가고."}, {"s": null, "t": "그림자 몇이 화폭 쪽으로 손을 뻗었다. 손끝이 닿은 자리마다 얼굴 하나가 희미해졌다."}, {"s": "q:sx_sorim", "t": "그림이 흐려져요! 조사원님!"}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_5', 2, '서명 없는 그림', '값 매기는 그림자을(를) 물리친다', '{"at": ["moonless_market"], "tasks": [{"t": "win", "m": ["gw_market_1"], "n": 3}]}'::jsonb, '[{"s": null, "t": "그림자들이 물러가자 화폭의 얼굴들이 조금씩 되살아났다. 어름이 혀를 차며 다가왔다."}, {"s": "q:sx_eoreum", "t": "저것들이 물러가면서 뭐라던지 아나? 「서명 없는 그림은 값을 못 매긴다」더군. 누가 그렸는지 모르는 그림엔 값이 안 붙는 법이야."}, {"s": "q:sx_eoreum", "t": "그리고 이런 말도 했지. 「그린 자도 곧 값이 없어지겠군.」 이건 공짜로 알려 주는 걸세. 흔치 않은 일이야."}, {"s": null, "t": "담채는 아무 말 없이 화구 상자를 열었다. 소림이 담채의 소매를 잡았지만 담채는 그 손을 가만히 떼어 냈다."}, {"s": "q:sx_damchae", "t": "소림아, 걱정 마라. 그림을 그릴 뿐이오."}, {"s": "q:sx_damchae", "t": "조사원, 무월 비단 세 필만 구해 주시오. 이 저잣거리 어딘가에 쌓여 있을 거요. 마지막 그림은 크게 그려야 하오. 지금까지 그린 얼굴이 다 들어가야 하니."}]'::jsonb, '{"xp": 2817}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_5', 3, '비어 있던 한가운데', '무월 비단을(를) 모은다', '{"at": ["moonless_market"], "tasks": [{"t": "gather", "items": ["moonless_silk"], "r": ["moonless_market"], "n": 3}]}'::jsonb, '[{"s": null, "t": "담채는 무월 비단 세 필을 이어 붙이고 밤새 그렸다. 광부, 흰 끈의 여인, 검은 물 위의 얼굴들, 거꾸로 선 사당의 얼굴들. 지금까지 그린 모든 얼굴이 비단 위에 모였다."}, {"s": null, "t": "비단 한가운데만은 비어 있었다. 담채는 그 자리에 붓을 대지 않았다."}, {"s": null, "t": "새벽에 소림의 울음소리가 났다. 화판 앞에 붓 한 자루만 놓여 있었고, 담채는 어디에도 없었다."}, {"s": null, "t": "비단 한가운데에 사람 하나가 그려져 있었다. 등을 보인 채 얼굴들 사이로 걸어 들어가는 모습이었다. 얼굴들이 사방에서 그를 향해 손을 뻗고 있었다. 맞이하는 손인지 붙드는 손인지 알 수 없었다."}, {"s": "q:sx_sorim", "t": "스승님이 들어가셨어요. 그림 속으로요. 불러도 대답을 안 하세요."}, {"s": "q:sx_eoreum", "t": "이제 저 그림은 값을 따질 수가 없겠군. 그린 자가 그림 속에 있으니. 그래도 그림자들은 또 올 걸세. 값을 못 매기는 건 가져가도 되는 걸로 여기거든."}, {"s": "q:sx_sorim", "t": "그림이 요기에 상하지 않게 해야 해요. 조사원님, 정화 부적 두 장만 지어 주세요. 비단 위아래에 붙여 둘게요."}]'::jsonb, '{"xp": 2817}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('cq110_paint_5', 4, '처음 쓰는 이름', '정화 부적을(를) 만든다, 정화 부적을(를) 넘긴다', '{"at": ["moonless_market"], "tasks": [{"t": "craft", "items": ["ward_talisman"], "n": 2}], "give": {"ward_talisman": 2}}'::jsonb, '[{"s": null, "t": "소림은 정화 부적을 비단 위아래에 붙인 뒤, 바닥에 놓인 붓을 집어 들었다. 손이 떨렸다."}, {"s": "q:sx_sorim", "t": "스승님은 한 번도 그림에 이름을 안 쓰셨어요. 그래서 아무도 스승님 이름을 몰라요. 저만 알아요."}, {"s": "q:sx_sorim", "t": "제자가 스승님 이름을 함부로 부르는 건 버릇없는 일이지만요."}, {"s": null, "t": "소림은 비단 귀퉁이에 먹을 찍어 두 글자를 또박또박 적었다. 「담채」."}, {"s": "q:sx_sorim", "t": "담채 스승님. 담채 스승님!"}, {"s": null, "t": "나도 소림을 따라 그 이름을 불렀다. 저잣거리의 소음이 잠깐 멎은 것 같았다."}, {"s": null, "t": "비단 한가운데, 등을 보이고 걷던 사람이 한 번 고개를 돌렸다. 아주 잠깐이었다. 그리고 다시 얼굴들 사이로 걸어갔다. 그림 밖으로 나오지는 않았다."}, {"s": "q:sx_eoreum", "t": "……값이 붙었군. 이름이 적혔으니. 그래도 이건 내가 못 사겠네. 너무 비싸."}, {"s": "q:sx_sorim", "t": "이제 제가 그릴게요. 스승님이 못 다 그린 얼굴들이요. 다만 저는 그림마다 제 이름을 꼭 쓸 거예요. 스승님 이름도 같이요. 누가 묻거든, 이 얼굴들을 그린 사람이 있었다고 말해 줄 수 있게요."}, {"s": null, "t": "소림은 비단을 말아 등에 메고 저잣거리를 걸어 나갔다. 말린 비단 안쪽에서 붓이 종이를 스치는 소리가 아주 작게 났다."}]'::jsonb, '{"xp": 2817, "gil": 157, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('sq110_pearl_rod', 'side', '제작·귀허', '귀허 진주 낚싯대', '마지막으로 귀허에 줄을 드리우고 싶은 노인', 'gwiheo_core', 38, '{mq_nine_gates}'::text[], null, 1188, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_pearl_rod' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_pearl_rod', 1, '마지막 줄', '마지막 줄', '{"at": ["banyo_village"]}'::jsonb, '[{"s": null, "t": "반요촌 선창 끝에서 늙은 반요 하나가 낚싯대를 손질하고 있었다. 낚싯대는 가운데가 부러져 노끈으로 감겨 있었고, 영감의 손은 쉬지 않고 떨렸다."}, {"s": "q:sx_gaetdol", "t": "바깥 사람이구먼. 이 갯돌이 왕년에 바깥 바다에서 뭘 낚았는지 아나? 고래야, 고래. 세 마리."}, {"s": null, "t": "나는 고래를 낚싯대로 어떻게 낚았느냐고 물었다."}, {"s": "q:sx_gaetdol", "t": "그러니까 왕년이지. 따지지 말게."}, {"s": "q:sx_gaetdol", "t": "손이 이래서, 올겨울을 넘기면 줄도 못 맬 것 같아. 그 전에 꼭 한 번 귀허에 줄을 드리워 보고 싶네. 거기선 떠난 것이 돌아온다잖나."}, {"s": "q:sx_gaetdol", "t": "그런데 이 대로는 안 돼. 귀허 물살에 바늘이 녹아. 귀허 바닥에 깔린 흑철로 바늘과 봉돌을 떠야 버틴다네. 세 덩이만 캐다 주게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_pearl_rod', 2, '훈수', '귀허 흑철을(를) 모은다', '{"at": ["banyo_village"], "tasks": [{"t": "gather", "items": ["gwiheo_iron"], "r": ["gwiheo_core"], "n": 3}]}'::jsonb, '[{"s": "q:sx_gaetdol", "t": "오, 이 무게. 이거면 소용돌이 한가운데 떨어뜨려도 안 떠내려가겠어."}, {"s": null, "t": "영감은 흑철을 손바닥에 올려 이리저리 굴려 보다가, 떨리는 손가락으로 허공에 바늘 모양을 그려 보였다."}, {"s": "q:sx_gaetdol", "t": "대에는 갈대 영사를 꼬아 감고, 손잡이엔 귀허 진주를 박아야 하네. 진주는 귀허의 문지기가 품고 있다니 그게 좀 일이지. 그리고 봉연 흑룡어든 해룡 돗돔이든, 큰 놈 한 마리 기름을 먹여야 해. 흑룡어는 피안개 끼는 날, 돗돔은 바람 센 날에나 올라오니 날을 잘 골라야 하네. 귀허 물고기들이 그 냄새를 따라오거든."}, {"s": "q:sx_gaetdol", "t": "반요촌 공방에서 짓게. 나는 옆에서 훈수를 두지."}, {"s": null, "t": "나는 훈수만 두느냐고 물었다."}, {"s": "q:sx_gaetdol", "t": "손이 떨려서 바늘귀에 실도 못 꿰는데 어쩌겠나. 대신 훈수는 바깥 바다 제일이야."}]'::jsonb, '{"xp": 2817}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_pearl_rod', 3, '쥐지 못하는 손', '귀허 진주 낚싯대을(를) 만든다, 귀허 진주 낚싯대을(를) 넘긴다', '{"at": ["banyo_village"], "tasks": [{"t": "craft", "items": ["lt_rod_6"], "n": 1}], "give": {"lt_rod_6": 1}}'::jsonb, '[{"s": null, "t": "낚싯대가 다 되자 영감은 한참 말없이 그것을 쓰다듬었다. 진주가 박힌 손잡이가 어두운 데서 희게 빛났다."}, {"s": "q:sx_gaetdol", "t": "곱구먼. 내 평생 쥐어 본 대 중에 제일 고와."}, {"s": null, "t": "영감은 낚싯대를 쥐어 보려다 손을 거두었다. 손가락이 대를 감싸지 못하고 자꾸 미끄러졌다."}, {"s": "q:sx_gaetdol", "t": "……자네가 쥐게. 나는 옆에서 보겠네. 귀허 물가까지만 데려다주면 돼."}, {"s": "q:sx_gaetdol", "t": "세 번만 던져 주게. 세 번이면 뭐든 하나는 돌아올 거야."}, {"s": null, "t": "나는 무엇이 돌아오기를 바라느냐고 물었다."}, {"s": "q:sx_gaetdol", "t": "그건 낚아 봐야 알지. 낚시꾼이 미리 알면 재미없어."}]'::jsonb, '{"xp": 2817}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_pearl_rod', 4, '돌아온 것', '귀허에서 낚시를 한다', '{"at": ["gwiheo_core"], "tasks": [{"t": "fish", "r": ["gwiheo_core"], "n": 3}]}'::jsonb, '[{"s": null, "t": "세 번째로 줄을 당겼을 때 걸려 올라온 것은 물고기가 아니었다. 이끼가 잔뜩 낀 낡은 낚싯대 한 자루였다. 가운데가 부러져 있었다."}, {"s": "q:sx_gaetdol", "t": "……."}, {"s": null, "t": "영감이 그것을 받아 들고 이끼를 문질렀다. 손잡이에 칼로 새긴 글자가 반쯤 남아 있었다."}, {"s": "q:sx_gaetdol", "t": "섬에 건너오던 날, 배에서 이걸 바다에 던졌어. 바깥 이름을 새겨 둔 대라, 들고 있기가 싫어서."}, {"s": "q:sx_gaetdol", "t": "그런데 이놈이 여기까지 흘러와 있었구먼. 서른 해 동안."}, {"s": null, "t": "나는 손잡이의 글자를 읽어 주겠다고 했다. 영감은 고개를 저었다."}, {"s": "q:sx_gaetdol", "t": "안 읽어도 아네. 내 이름이야. 내가 버린 것도 바다는 안 버리고 갖고 있었다는 거, 그거면 됐어."}, {"s": "q:sx_gaetdol", "t": "고래 얘기는 거짓말이었네. 나는 평생 잔챙이만 낚았어. 그런데 오늘 건 고래보다 크구먼."}, {"s": null, "t": "영감은 옛 낚싯대를 품에 안고, 새 낚싯대는 내 손에 쥐여 주었다."}, {"s": "q:sx_gaetdol", "t": "그건 자네 거야. 내 손은 이걸로 충분해."}]'::jsonb, '{"xp": 2817, "gil": 157, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
