values ('sq110_s_eodu', 'side', '낚시·귀허', '아들을 낚는 줄', '떠난 것이 돌아오는 바다에 늙은 낚시꾼이 마지막 줄을 드리운다', 'gwiheo_core', 38, '{sq_black_tide_rift_1,mq_nine_gates}'::text[], null, 1189, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true, job_key = excluded.job_key;
delete from public.world_quest_steps where quest_id = 'sq110_s_eodu' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_eodu', 1, '녀석의 대', '녀석의 대', '{"at": ["gwiheo_core"]}'::jsonb, '[{"s": null, "t": "귀허 물가 바위에 늙은이 하나가 앉아 있었다. 손에 쥔 것은 부러진 대를 새 줄로 이은 낚싯대였다. 손잡이에 감긴 은가락지가 소용돌이 빛을 받아 희게 번득였다."}, {"s": "q:bl_eodu", "t": "왔구려. 흑조 균열에서 이 대를 건져 준 조사원. 그 뒤로 일곱 해, 균열 물에서 못 돌아간 것들을 건져서 하나씩 놓아주었소."}, {"s": "q:bl_eodu", "t": "그런데 녀석은 끝내 안 걸리더이다. 남쪽 바다에 빠진 것은 균열로 흘러오고, 균열에서도 못 돌아간 것은 결국 이리로 온다 하오. 떠난 것이 돌아오는 바다라지."}, {"s": null, "t": "나는 아드님을 낚으러 오셨느냐고 물었다."}, {"s": "q:bl_eodu", "t": "낚는다기보다 줄을 대 주러 왔소. 녀석이 잡고 올라올 줄."}, {"s": "q:bl_eodu", "t": "손이 더 떨려서 이제 던지지도 못하오. 녀석 대로 줄을 세 번 내려 주시오. 무엇이 무는지 보면 녀석이 어디쯤 있는지 알 거요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_eodu', 2, '남의 사슬', '귀허에서 낚시를 한다', '{"at": ["gwiheo_core"], "tasks": [{"t": "fish", "r": ["gwiheo_core"], "n": 3}]}'::jsonb, '[{"s": null, "t": "첫 줄에는 거꾸로 헤엄치는 물고기가 걸렸고, 둘째 줄에는 깨진 등잔 유리 한 조각이 걸려 나왔다. 유리 테에 남쪽 군도 등대의 표식이 찍혀 있었다."}, {"s": "q:bl_eodu", "t": "녀석 등대 것이오. 녀석이 날마다 닦던 유리요."}, {"s": null, "t": "셋째 줄은 바닥에 닿기도 전에 무언가에 걸려 팽팽해졌다. 당겨도 줄은 올라오지 않고, 물 밑에서 쇠 부딪는 소리만 올라왔다."}, {"s": null, "t": "줄을 타고 하얀 사슬이 물 위로 감겨 올라왔다. 사슬은 낚싯줄을 칭칭 감더니 물 밑으로 도로 끌어당겼다."}, {"s": "q:bl_eodu", "t": "녀석은 사슬 같은 걸 차 본 적이 없소. 남의 사슬이오. 돌아오는 것마다 감아 버린다더니, 내 줄까지 감는구려."}, {"s": "q:bl_eodu", "t": "줄이 끊어지기 전에 저것들 좀 떼어 주시오. 셋이오."}]'::jsonb, '{"xp": 2817}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_eodu', 3, '꽂아 둘 대', '흰 사슬 망령을(를) 물리친다', '{"at": ["gwiheo_core"], "tasks": [{"t": "win", "m": ["gw_core_2"], "n": 3}]}'::jsonb, '[{"s": null, "t": "사슬이 끊겨 흩어지자 줄이 가벼워졌다. 그런데 어두는 줄을 감지 않았다. 늘어진 줄을 손가락에 걸고 가만히 물살을 느꼈다."}, {"s": "q:bl_eodu", "t": "녀석은 아직 저 밑 어딘가에 있소. 그런데 나는 녀석이 올라올 때까지 여기 앉아 있을 수가 없구려. 손이 이렇고, 남은 날도 얼마 없소."}, {"s": "q:bl_eodu", "t": "그러니 내가 없어도 줄은 드리워져 있어야 하오. 이 대를 바위에 꽂아 두고 가겠소."}, {"s": null, "t": "나는 귀허 물살에 대가 버티겠느냐고 물었다."}, {"s": "q:bl_eodu", "t": "나무 대만으로는 못 버티지. 소용돌이 밑바닥의 흑철은 물에 녹지 않는다 하오. 그걸로 말뚝을 박고, 대를 감을 쇠테를 두르겠소."}, {"s": "q:bl_eodu", "t": "귀허 흑철 세 덩이만 건져다 주시오. 녀석 대가 내 손보다 오래 버티게."}]'::jsonb, '{"xp": 2817}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_s_eodu', 4, '두 번 짧게, 한 번 길게', '귀허 흑철을(를) 모은다', '{"at": ["gwiheo_core"], "tasks": [{"t": "gather", "items": ["gwiheo_iron"], "r": ["gwiheo_core"], "n": 3}]}'::jsonb, '[{"s": null, "t": "흑철 말뚝을 바위틈에 박고 낚싯대를 거기 묶었다. 은가락지 감긴 손잡이가 바다 쪽을 향했다. 줄은 소용돌이 한가운데로 곧게 내려갔다."}, {"s": null, "t": "어두는 대 곁에 앉아 오래 줄을 바라보았다. 소용돌이 소리만 들렸다."}, {"s": null, "t": "해가 질 무렵 줄이 움직였다. 두 번 짧게, 한 번 길게. 물고기가 무는 것과는 다른 떨림이었다."}, {"s": "q:bl_eodu", "t": "……녀석이 어릴 적에 하던 신호요. 물에서 놀다가 「아버지, 나 여기 있소」 할 때."}, {"s": null, "t": "나는 줄을 당겨 보겠느냐고 물었다. 어두는 고개를 저었다."}, {"s": "q:bl_eodu", "t": "당기면 끊어지오. 여기서는 놓아야 붙어 있소. 녀석이 제 손으로 잡고 올라오게 둡시다."}, {"s": "q:bl_eodu", "t": "나도 대답은 해야지. 우리 집안 매듭으로."}, {"s": null, "t": "어두는 떨리는 손으로 줄 위에 작은 매듭 하나를 지었다. 매듭은 줄을 타고 천천히 소용돌이 속으로 미끄러져 내려갔다."}, {"s": null, "t": "줄은 다시 떨리지 않았다. 어두는 그래도 한참을 일어나지 않았다. 일어날 때는 대를 두고, 빈손으로 물가를 떠났다."}]'::jsonb, '{"xp": 2817, "gil": 157, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
