insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_doorplate', 1, '갈대에 걸린 사람', '갈대에 걸린 사람', '{"at": ["ash_reeds"]}'::jsonb, '[{"s": null, "t": "잿빛 갈대숲 물가에서 반요 아낙 하나가 낫으로 갈대를 쳐 내고 있었다. 그 발치에 젖은 사내 하나가 갈대 뿌리에 반쯤 감긴 채 앉아 있었다."}, {"s": "q:sx_saeam", "t": "야행국 사람이지? 잘 왔어. 이 사람 좀 같이 봐 줘. 사흘 전에 물에 떠밀려 왔는데, 아직 반요촌까지도 못 데려갔어."}, {"s": null, "t": "사내는 품에 판자 한 쪽을 꼭 끌어안고 있었다. 문패였다. 나뭇결만 남고 글자는 한 획도 보이지 않았다."}, {"s": "q:sx_tteomilin", "t": "우리 나루에는…… 검은 비가 왔소. 먹비라 했지. 그 비를 맞으면 문패 글자가 지워지고, 배 이름도 지워졌소."}, {"s": "q:sx_tteomilin", "t": "그래서 아침마다 문패를 새로 썼소. 그런데 어느 아침에…… 무엇을 써야 할지 생각이 안 났소."}, {"s": "q:sx_tteomilin", "t": "물가에 앉아 그걸 생각하다가…… 눈을 뜨니 여기였소."}, {"s": "q:sx_saeam", "t": "이름을 물어봐도 몰라. 여기 오는 사람들이 다 그래."}, {"s": "q:sx_saeam", "t": "그런데 저것 좀 봐. 갈대 엮인 요인이 밤마다 이 사람 둘레를 맴돌아. 갈대로 사람 꼴을 엮어 입으려는 거야. 저대로 두면 이 사람도 저렇게 돼. 저것부터 쫓아 줘."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_doorplate', 2, '실로 꿰매는 이름', '갈대 엮인 요인을(를) 물리친다', '{"at": ["ash_reeds"], "tasks": [{"t": "win", "m": ["gw_reed_4"], "n": 1}]}'::jsonb, '[{"s": null, "t": "갈대 엮인 요인이 쓰러지자 몸을 감고 있던 갈대가 한 가닥씩 풀려 물에 떠내려갔다. 풀린 갈대 가운데 하나에 누군가 손톱으로 새긴 글자가 남아 있었다. 반쯤 지워져 읽을 수 없었다."}, {"s": null, "t": "사내는 그 갈대를 오래 내려다보았다. 그러고는 다시 제 문패를 끌어안았다."}, {"s": "q:sx_tteomilin", "t": "저것도…… 누군가의 문패였겠구려."}, {"s": "q:sx_saeam", "t": "그러니까 서둘러야 해. 먹으로 쓰면 또 지워지잖아. 반요촌에서는 지워질까 무서운 이름은 실로 꿰매."}, {"s": "q:sx_saeam", "t": "갈대 영사로 꿰매면 물에 젖어도 안 풀려. 판자에 바늘구멍을 내서 한 땀씩 박으면 돼."}, {"s": "q:sx_saeam", "t": "갈대숲 안쪽에 영사 고치가 잘 붙어. 세 타래만 거둬 와. 이 사람이 이름을 떠올리면 바로 꿰매게."}]'::jsonb, '{"xp": 2953}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_doorplate', 3, '감나무와 기둥', '갈대 영사을(를) 모은다', '{"at": ["ash_reeds"], "tasks": [{"t": "gather", "items": ["reed_silk"], "r": ["ash_reeds"], "n": 3}]}'::jsonb, '[{"s": null, "t": "새암이 바늘에 갈대 영사를 꿰어 들고 기다렸다. 사내는 문패를 무릎에 올려놓고 눈을 감았다."}, {"s": "q:sx_tteomilin", "t": "대문 옆에 감나무가 있었소. 기둥에는 키 잰 금이 그어져 있었고. 금이 해마다 하나씩 올라갔소."}, {"s": "q:sx_tteomilin", "t": "문패 글자는 세 자였소. 마지막 글자에 긴 획이 있었는데……"}, {"s": null, "t": "사내의 말이 거기서 끊겼다. 이가 딱딱 부딪쳤다. 이마를 짚어 보니 불덩이였다. 목덜미에서 비늘이 하나 더 돋아 있었다."}, {"s": "q:sx_saeam", "t": "요기가 올라오는 거야. 기억을 억지로 끌어올리면 꼭 이래."}, {"s": "q:sx_saeam", "t": "마음을 가라앉혀야 생각이 떠올라. 안신탕 두 그릇만 달여 줘. 한 그릇은 지금, 한 그릇은 자고 일어나서."}]'::jsonb, '{"xp": 2953}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_e_doorplate', 4, '아래 칸은 비워 두오', '안신탕을(를) 만든다, 안신탕을(를) 넘긴다', '{"at": ["ash_reeds"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 2}], "give": {"calm_brew": 2}}'::jsonb, '[{"s": null, "t": "안신탕을 마신 사내는 갈대 그늘에서 잠이 들었다. 자는 동안 누군가를 몇 번 불렀다. 깨어난 사내의 눈이 젖어 있었다."}, {"s": "q:sx_tteomilin", "t": "내 이름은…… 끝내 모르겠소. 그런데 그 애가 나를 부르던 소리는 생각이 났소. 「아버지」 하고."}, {"s": "q:sx_tteomilin", "t": "그 애 이름도 생각이 났소. 키 잰 금 옆에 늘 그 애 이름을 적었으니까."}, {"s": null, "t": "사내는 새암에게서 바늘을 받아, 문패에 딸의 이름을 한 땀씩 꿰맸다. 손이 떨려 땀이 고르지 않았다."}, {"s": "q:sx_tteomilin", "t": "이 집에 이 아이가 산다고 적어 두면, 그 애가 부를 때 내가 돌아볼 수 있을 거요."}, {"s": "q:sx_saeam", "t": "반요촌에선 문패에 이름을 둘 적어. 위에는 바깥 이름, 아래에는 섬에서 지은 이름. 아래 칸에 넣을 이름은 내가 하나 지어 줄까?"}, {"s": "q:sx_tteomilin", "t": "아니오. 아래 칸은 비워 두시오. 그 애가 언젠가 와서 적어 줄지도 모르니."}, {"s": null, "t": "새암은 더 묻지 않았다. 사내를 부축해 반요촌 쪽으로 걸어갔다. 사내의 품에서 갈대 영사로 꿰맨 글자 세 자가 반짝였다. 아래 칸은 비어 있었다."}]'::jsonb, '{"xp": 2953, "gil": 161, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
