insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_returning_wave', 1, '마중', '마중', '{"at": ["gwiheo_core"]}'::jsonb, '[{"s": null, "t": "귀허 물가에 노파 하나가 앉아 있었다. 파도가 밀려올 때마다 노파는 손을 들어 흔들었다. 파도는 사람 꼴로 일어섰다가 물가에 닿기 전에 부서졌다."}, {"s": "q:sx_majung", "t": "앉거라. 여기선 서 있으면 파도가 사람인 줄 알고 끌고 간다."}, {"s": "q:sx_majung", "t": "나는 날마다 여기서 파도를 마중한다. 귀허에선 떠난 것이 파도가 되어 돌아오거든. 잊힌 것, 놓친 것, 두고 온 것."}, {"s": "q:sx_majung", "t": "그런데 네가 온 뒤로 파도 하나가 자꾸 너를 부른다. 저것 봐라."}, {"s": null, "t": "밀려오는 물살 사이로 물로 된 사람 하나가 이쪽으로 손을 뻗고 있었다. 그 둘레에서 다른 파도귀들이 엉겨 붙어 그것을 도로 끌어당겼다."}, {"s": "q:sx_padogwi", "t": "거기 있구나. 많이 컸네."}, {"s": null, "t": "그 목소리를 알 것 같았다. 그런데 누구의 목소리인지는 떠오르지 않았다."}, {"s": "q:sx_majung", "t": "파도끼리 서로 붙잡고 있어서 물가까지 못 온다. 저 엉긴 것들을 좀 떼어 줘라. 넷이면 된다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_returning_wave', 2, '흰 사슬', '돌아오는 파도귀을(를) 물리친다', '{"at": ["gwiheo_core"], "tasks": [{"t": "win", "m": ["gw_core_1"], "n": 4}]}'::jsonb, '[{"s": null, "t": "엉겨 붙은 파도들이 흩어지자 그 파도귀가 조금 더 가까이 밀려왔다. 그러나 발목에서 하얀 사슬이 짤랑거렸다. 사슬 끝은 물속 깊이 이어져 있었다."}, {"s": "q:sx_padogwi", "t": "미안하다. 너한테 할 말이 있었는데, 이게 놓아주질 않네."}, {"s": "q:sx_majung", "t": "귀허로 끌려온 이들이 차던 사슬이다. 차던 사람은 흩어졌는데 사슬만 혼째 남아서, 돌아오는 것마다 감아 버린다."}, {"s": null, "t": "나는 파도귀에게 나를 어떻게 아느냐고 물었다."}, {"s": "q:sx_padogwi", "t": "어떻게 모르겠니. {직업:호위=무거운 칼을 메고 다니는 것까지 그대로인걸./월궁=활 쥐는 손 버릇까지 그대로인걸./퇴마=방울 흔드는 손 버릇까지 그대로인걸./의무=옷에 밴 약 냄새까지 그대로인걸./봉인=부적 접는 손 버릇까지 그대로인걸./암영=발소리 죽여 걷는 것까지 그대로인걸./*=걸음걸이까지 그대로인걸.}"}, {"s": null, "t": "그 말을 듣자 가슴 한쪽이 묵직해졌다. 그런데도 얼굴은 떠오르지 않았다."}, {"s": "q:sx_majung", "t": "사슬 망령이 둘 붙었다. 끊어 줘라."}]'::jsonb, '{"xp": 2953}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_returning_wave', 3, '되튕기는 말', '흰 사슬 망령을(를) 물리친다', '{"at": ["gwiheo_core"], "tasks": [{"t": "win", "m": ["gw_core_2"], "n": 2}]}'::jsonb, '[{"s": null, "t": "사슬이 끊어지자 파도귀가 물가 가까이까지 밀려왔다. 하지만 물가 바로 앞에서 물살이 뒤로 꺾였다. 거울 같은 몸을 한 것이 물속에서 일어나 길을 막고 있었다."}, {"s": "q:sx_majung", "t": "문지기다. 귀허 안쪽을 지키느라, 물가로 오는 것까지 다 막아 선다."}, {"s": "q:sx_padogwi", "t": "괜찮아. 여기서 말해도 돼."}, {"s": null, "t": "파도귀가 무언가 말했지만, 그 말은 문지기의 몸에 부딪혀 되튕겨 나갔다. 내 귀에 들린 것은 내 목소리뿐이었다."}, {"s": "q:sx_majung", "t": "저 앞에선 무슨 말이든 듣는 사람의 말로 되돌아온다. 저걸 넘어뜨려야 네가 그 말을 듣는다."}, {"s": "q:sx_majung", "t": "나는 서른 해를 여기 앉아 있었지만 문지기한테 덤빌 생각은 못 했다. 내 파도가 무슨 말을 할지 무서워서."}]'::jsonb, '{"xp": 2953}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('sq110_returning_wave', 4, '이번엔 네가', '귀허의 문지기을(를) 물리친다', '{"at": ["gwiheo_core"], "tasks": [{"t": "win", "m": ["gw_core_5"], "n": 1}]}'::jsonb, '[{"s": null, "t": "문지기의 거울 몸이 부서졌다. 조각들이 물 위로 흩어지며 저마다 다른 얼굴을 비췄다."}, {"s": null, "t": "파도귀가 마침내 물가에 닿았다. 물로 된 손이 내 발등을 덮었다. 차갑지 않았다."}, {"s": "q:sx_padogwi", "t": "늦었다. 밥 식었겠다."}, {"s": "q:sx_padogwi", "t": "다른 말을 하려고 했는데, 막상 보니까 이 말밖에 안 나오네."}, {"s": null, "t": "나는 당신이 누구냐고 물었다."}, {"s": "q:sx_padogwi", "t": "네가 모르면 나도 몰라. 나는 네가 두고 온 거니까."}, {"s": "q:sx_padogwi", "t": "그래도 괜찮아. 다 잊었으면 나는 파도도 못 됐어. 네가 아직 어딘가에 들고 있으니까 돌아온 거야."}, {"s": null, "t": "파도귀가 물러나기 시작했다. 나는 손을 뻗었지만 손가락 사이로 물만 빠져나갔다."}, {"s": "q:sx_padogwi", "t": "잘 가. 이번엔 네가 떠나는 쪽이야."}, {"s": null, "t": "그 파도는 다시 오지 않았다. 마중 할멈이 내 옆에 앉아, 아무것도 밀려오지 않는 바다를 향해 손을 흔들었다."}, {"s": "q:sx_majung", "t": "누군지 몰라도 마중은 할 수 있다. 내일 또 나와 봐라. 저쪽은 몰라도, 나는 나와 있을 테니."}]'::jsonb, '{"xp": 2953, "gil": 161, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
